		["{quest:1012}, taken alone"] = "{quest:1012}, aceptada en solitario",
		["{quest:1031}, taken alone"] = "{quest:1031}, aceptada en solitario",
		["{quest:95646}: the root core, inside"] = "{quest:95646}: el núcleo de raíz, adentro",
		["{quest:98815}: the hides, inside"] = "{quest:98815}: las pieles, adentro",
		["{quest:98824}: {npc:5387} stands in the {object:32356}, north-east of the {object:32372}."] = "{quest:98824}: {npc:5387} está en {object:32356}, al noreste de {object:32372}.",
		["{zone:1453} flight master"] = "Maestro de vuelo de {zone:1453}",
		["{zone:1455} priests"] = "Sacerdotes de {zone:1455}",
} end)()
t.guides["forever/alliance/07-thousand-needles"] = (function() return {
		["Back to {area:42}"] = "Regresa a {area:42}",
		["Below ground"] = "Bajo tierra",
		["Fly to {area:150}"] = "Vuela a {area:150}",
		["For {npc:1212} in {zone:1453}, in the next guide"] = "Para {npc:1212} en {zone:1453}, en la siguiente guía",
		["For {npc:482} in {zone:1453}, in the next guide"] = "Para {npc:482} en {zone:1453}, en la siguiente guía",
		["Head south-west from {area:42} to the ogre mound. {object:119} sits in the camp at its entrance; Splinter Fist ogres guard it. {npc:300} is inside the ogre mound's cave: go in by the cave mouth on the mound's west side."] = "Ve al suroeste desde {area:42} hasta el túmulo de los ogros. {object:119} está en el campamento de su entrada; lo vigilan ogros Puño Astillado. {npc:300} está dentro de la cueva del túmulo: entra por la boca de la cueva en el lado oeste del túmulo.",
		["Hearth back to {area:42} (bound at the start of this guide): {npc:311}'s camp is at the far west of {zone:1431}."] = "Usa la piedra de hogar para volver a {area:42} (vinculada al inicio de esta guía): el campamento de {npc:311} está en el extremo oeste de {zone:1431}.",
		["Inside"] = "Adentro",
		["Nightbane Dark Runners"] = "Sombracechadores Penumbría",
		["Nightbane Shadow Weavers"] = "Tejesombras Penumbría",
		["Nightbane Vile Fangs and Tainted Ones"] = "Colmillovil Penumbría y Corruptos",
		["Only if a {npc:272273} dropped {quest:96138}: right-click it"] = "Solo si un {npc:272273} soltó {quest:96138}: haz clic derecho en él",
		["The Dark Runners prowl the woods south of the road, west of {area:42}."] = "Los sombracechadores merodean por el bosque al sur del camino, al oeste de {area:42}.",
		["The Defias camp lies in the south-west of {zone:1431}, south of {area:94} near the {zone:1436} border. The strongbox stands among the tents."] = "El campamento Defias está en el suroeste de {zone:1431}, al sur de {area:94}, cerca de la frontera de {zone:1436}. La caja fuerte está entre las tiendas.",
		["The Plague Spreaders walk the northern half of the {area:492}. {npc:522}, an elite, wanders the graves: keep away from him.\nSkeletal Raiders, Healers and Warders hold the west part of the cemetery, just east of {npc:311}'s camp.\nCareful: The skeletons in the catacombs are packed close together, so you can easily pull extra mobs."] = "Los propagadores de peste recorren la mitad norte de {area:492}. {npc:522}, un élite, deambula entre las tumbas: mantente lejos de él.\nLos asaltantes, sanadores y celadores esqueléticos ocupan la parte oeste del cementerio, justo al este del campamento de {npc:311}.\nCuidado: Los esqueletos de las catacumbas están muy juntos, así que es fácil atraer enemigos de más.",
		["The grave stands among the skeletons at the cemetery's north-west corner, on the way to {npc:311}. Its quest and the next are talk-only, to {npc:268} and Commander Althea in {area:42}: level 35 quests, but no fight."] = "La tumba está entre los esqueletos de la esquina noroeste del cementerio, de camino a {npc:311}. Su misión y la siguiente son solo de hablar, con {npc:268} y la comandante Althea en {area:42}: misiones de nivel 35, pero sin pelear.",
		["The strongest worgen roam the woods south of {area:42}, west and south of the {area:121}.\nCareful: {spell:8282} lasts 10 minutes and adds 13 to each hit of physical damage you take.\nCareful: Some worgen outside the cave stand in groups, including one camp of four. To avoid adds, pull them one at a time from the raised ground next to the cave entrance.\nCareful: Gutspill, a level 32 abomination, walks these woods: let it pass."] = "Los huargen más fuertes recorren el bosque al sur de {area:42}, al oeste y al sur de {area:121}.\nCuidado: {spell:8282} dura 10 minutos y suma 13 a cada golpe de daño físico que recibes.\nCuidado: Algunos huargen de fuera de la cueva están en grupos, incluido un campamento de cuatro. Para no atraer de más, atráelos de a uno desde el terreno elevado junto a la entrada de la cueva.\nCuidado: Derramatripas, una abominación de nivel 32, recorre este bosque: déjala pasar.",
		["The worgen hold the woods of Brightwood, west of {area:42} and north of the road. Pull them one at a time."] = "Los huargos ocupan el bosque de la Arboleda del Destello, al oeste de {area:42} y al norte del camino. Atráelos de uno en uno.",
		["The {npc:511}"] = "{npc:511}",
		["The {npc:511} hides in the small crypt by the {area:121}, south of {area:42}. {npc:663}'s Nightbane Vile Fangs and Tainted Ones (level 29-31) roam the woods around it: they come at the end of this guide, a level later."] = "{npc:511} se esconde en la criptita junto a {area:121}, al sur de {area:42}. Los Colmillovil Penumbría y los Corruptos (nivel 29-31) de {npc:663} recorren el bosque a su alrededor: vienen al final de esta guía, un nivel después.",
		["Wait a moment, then speak with her again"] = "Espera un momento y vuelve a hablar con ella",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it."] = "No hiciste esto en la visita anterior de la ruta a esta zona: ahora va primero. Es rápido y abre las misiones que le siguen.",
		["{area:42} flight master"] = "Maestro de vuelo de {area:42}",
		["{area:492}: kill these as you meet them"] = "{area:492}: mata a estos según te los encuentres",
		["{area:93}: kill these as you meet them"] = "{area:93}: mata a estos según te los encuentres",
		["{item:1946}; inside"] = "{item:1946}; adentro",
		["{item:5947}; inside"] = "{item:5947}; adentro",
		["{npc:263}, in the town hall"] = "{npc:263}, en el ayuntamiento",
		["{npc:268}, in the house behind the town hall"] = "{npc:268}, en la casa detrás del ayuntamiento",
		["{npc:276}'s house stands at the east end of town, on the way to the flight master."] = "La casa de {npc:276} está en el extremo este del pueblo, de camino al maestro de vuelo.",
		["{npc:276}, inside"] = "{npc:276}, adentro",
		["{npc:311}'s Camp"] = "Campamento de {npc:311}",
		["{npc:661}, by {npc:633}'s house; inside"] = "{npc:661}, junto a la casa de {npc:633}; adentro",
		["{npc:663} and {npc:661}"] = "{npc:663} y {npc:661}",
		["{npc:663}, by the town hall"] = "{npc:663}, junto al ayuntamiento",
		["{npc:6790}, Scarlet Raven Tavern"] = "{npc:6790}, en la taberna",
		["{npc:840} walks around {area:42}: look inside the circle on the map"] = "{npc:840} recorre {area:42}: busca dentro del círculo del mapa",
		["{npc:840}, at the north entrance of town; walks around {area:42}: look inside the circle on the map"] = "{npc:840}, en la entrada norte del pueblo; recorre {area:42}: busca dentro del círculo del mapa",
		["{quest:377}, from your {area:717} run: {npc:270} is in the town hall, beside Commander Althea."] = "{quest:377}, de tu recorrido por {area:717}: {npc:270} está en el ayuntamiento, junto a la comandante Althea.",
} end)()
t.guides["forever/alliance/30-40/01-hillsbrad-foothills"] = (function() return {
		["A report for {object:2117}; inside"] = "Un informe para {object:2117}; adentro",
		["Back down the road to {area:205}: {npc:1075} wants the {object:147516} explosives under the far end of the span destroyed."] = "De vuelta por el camino hasta {area:205}: {npc:1075} quiere que destruyas los explosivos de {object:147516} que están bajo el otro extremo del puente.",
		["Back east along the road to the {area:1025}: {npc:270637} camps among the Fenrunners, just west of {npc:1244}. Then west again to Menethil for the boat."] = "De vuelta al este por el camino hasta {area:1025}: {npc:270637} acampa entre los correpantanos, justo al oeste de {npc:1244}. Luego otra vez al oeste a Menethil para el barco.",
		["Back over the span and down the road through {area:205} on the way south."] = "De vuelta por el puente y bajando por el camino a través de {area:205}, de camino al sur.",
		["Back south to Menethil: {npc:1217} stands in the {area:2104}."] = "De vuelta al sur a Menethil: {npc:1217} está en {area:2104}.",
		["Back to the same murlocs; not every one drops a head."] = "Regresa con los mismos múrlocs; no todos sueltan una cabeza.",
		["Beat {npc:4961} and his thugs: they give up"] = "Vence a {npc:4961} y a sus matones: se rinden",
		["Below ground"] = "Bajo tierra",
		["Boat to {area:271}"] = "Barco a {area:271}",
		["Cathedral of Light"] = "Cathedral of Light",
		["Daggerspine naga"] = "Nagas Espinadaga",
		["Druid training"] = "Instrucción de druida",
		["Ebenezer Rustlocke"] = "Ebenezer Herrumbra",
		["Farren"] = "Farren",
		["Fly to {area:1537}"] = "Vuela a {area:1537}",
		["Fly to {zone:1453}"] = "Vuela a {zone:1453}",
		["For {npc:1284} in {zone:1453}, at the end of this guide"] = "Para {npc:1284} en {zone:1453}, al final de esta guía",
		["For {npc:2916} in {zone:1455}, at the end of this guide"] = "Para {npc:2916} en {zone:1455}, al final de esta guía",
		["Inside"] = "Adentro",
		["Level 30 and 32 spells"] = "Hechizos de nivel 30 y 32",
		["Level 30.8"] = "Nivel 30.8",
		["Maddened Rotclaws roam the {area:1025} around {npc:1244}; one of them drops the flesh. {npc:1244} takes the quest only with {quest:98283}'s head too."] = "Los garrapodridas enloquecidos recorren {area:1025} alrededor de {npc:1244}; uno de ellos suelta la carne. {npc:1244} solo acepta la misión si también tienes la cabeza de {quest:98283}.",
		["Murloc heads"] = "Cabezas de múrloc",
		["North along the coast from Menethil to the wreck of the Intrepid: {npc:1160} (30) is aboard, and the locked strongbox sits in the wreck. Careful: {npc:270589}, a level 31-32 elite, roams the {zone:1437}: give it a wide berth."] = "Al norte por la costa desde Menethil hasta el naufragio de El Intrépido: el {npc:1160} (30) está a bordo, y la caja fuerte cerrada está en el naufragio. Cuidado: {npc:270589}, un élite de nivel 31-32, recorre {zone:1437}: mantente bien lejos.",
		["North along the road from {area:205} towards the {area:880}: Ebenezer Rustlocke's corpse lies under the span. Rustlocke's parchment goes back to {npc:1075}.\nTwo elite Dark Iron Saboteurs stand by the corpse inside the span: pull them one at a time, or loot the corpse and run out."] = "Al norte por el camino desde {area:205} hacia {area:880}: el cadáver de Ebenezer Rustlocke está debajo del puente. El pergamino de Rustlocke vuelve a {npc:1075}.\nDos saboteadores Hierro Negro élite están junto al cadáver, dentro del puente: atráelos de a uno, o saquea el cadáver y sal corriendo.",
		["North along the road to {area:205}. {npc:1071} and {npc:1075} stand together in the dwarves' camp on the east side of the road; the {object:147516} ruins west of it are full of elites."] = "Al norte por el camino hasta {area:205}. {npc:1071} y {npc:1075} están juntos en el campamento de los enanos, en el lado este del camino; las ruinas de {object:147516} al oeste están llenas de élites.",
		["North-east to the {area:1038}: {npc:271338} stands at the gates (use the {item:279996})."] = "Al noreste hasta {area:1038}: {npc:271338} está en las puertas (usa {item:279996}).",
		["Off the boat, walk up the pier into town: {npc:2711} and Lieutenant Farren stand by the inn, {npc:2430} upstairs, {npc:2382} east of it; the flight master is at the north end, {npc:2381} and {npc:2438} between her and the inn, Maleb in the town hall at the west side.\n{npc:2366} may not offer {quest:98463} on Forever: if she doesn't, skip it."] = "Al bajar del barco, sube por el muelle hasta el pueblo: {npc:2711} y el teniente Farren están junto a la posada, {npc:2430} arriba, {npc:2382} al este; la maestra de vuelo está en el extremo norte, {npc:2381} y {npc:2438} entre ella y la posada, y Maleb en el ayuntamiento, en el lado oeste.\nPuede que {npc:2366} no ofrezca {quest:98463} en Forever: si no lo hace, sáltala.",
		["On the top floor"] = "En el piso superior",
		["Over the {area:880}: the Dark Irons' cache of explosives sits by its Arathi end."] = "Cruza {area:880}: el alijo de explosivos de los Hierro Negro está junto a su extremo de Arathi.",
		["Razormaw nests"] = "Nidos Tajobuche",
		["Skipped {quest:474} and short of 30.8? Kill the Bluegill murlocs on the coast south of Menethil until level 30.8. Or, with a group, run the {area:133} dungeon or the {area:796} dungeon (Graveyard) instead."] = "¿Te saltaste {quest:474} y no llegas a 30.8? Mata múrlocs Branquiazul en la costa al sur de Menethil hasta el nivel 30.8. O, con un grupo, haz en su lugar la mazmorra {area:133} o la mazmorra {area:796} (Cementerio).",
		["Snapjaws"] = "Quijafortes",
		["South-east from Menethil to the Dragonmaw's {area:1036}: the first catapult stands on the way, and the {object:671518} lies in the camp."] = "Al sureste desde Menethil hasta {area:1036} de los Faucedraco: la primera catapulta está en el camino, y {object:671518} está en el campamento.",
		["The Perfect Razormaw Eggs for {quest:98246} lie in the raptors' nests in the hills around {quest:98283}."] = "Los huevos Tajobuche perfectos para {quest:98246} están en los nidos de los raptores, en las colinas alrededor de {quest:98283}.",
		["The Snapjaw turtles bask along the river east of {area:271}, south of {area:272} (Horde)."] = "Las tortugas Quijaforte toman el sol a lo largo del río al este de {area:271}, al sur de {area:272} (Horda).",
		["The Torn Fin murlocs crowd the {area:295}, south-west of {area:271}.\nCareful: One camp holds a tight cluster of Oracles that all aggro together."] = "Los múrlocs Rompeanca llenan {area:295}, al suroeste de {area:271}.\nCuidado: Un campamento tiene un grupo muy junto de oráculos que atacan todos a la vez.",
		["The cheese shop in the {object:2096}."] = "La quesería de {object:2096}.",
		["The naga hold the shore south-east of {area:271}."] = "Los nagas ocupan la costa al sureste de {area:271}.",
		["The root core from your {area:17732} run: {npc:1244} stands by the river, just east of {npc:270637}."] = "El núcleo de raíz de tu recorrido por {area:17732}: {npc:1244} está junto al río, justo al este de {npc:270637}.",
		["The whelps nest in the hills north-east of the {area:1036}; {quest:98283} prowls further north, and the Razormaw raptors hunt the highlands on the way north to {area:205}.\n{quest:98283} is elite: grouping up is advised."] = "Las crías anidan en las colinas al noreste de {area:1036}; {quest:98283} merodea más al norte, y los raptores Tajobuche cazan en las tierras altas de camino al norte hacia {area:205}.\n{quest:98283} es élite: se recomienda agruparse.",
		["The yetis live in the cave in the hills north of {area:271}.\nStay in the {area:277}: the cave further north has Mountain and Giant Yetis (32-34) in pairs and {npc:13602}, a level 36 elite."] = "Los yetis viven en la cueva de las colinas al norte de {area:271}.\nQuédate en {area:277}: la cueva más al norte tiene Yetis monteses y Yetis gigantes (32-34) en parejas y a {npc:13602}, un élite de nivel 36.",
		["The {item:270865} from your {area:17732} run: {npc:1077} is below ground in his dig, south of the road west."] = "{item:270865} de tu recorrido por {area:17732}: {npc:1077} está bajo tierra en su excavación, al sur del camino hacia el oeste.",
		["The {object:2704}"] = "{object:2704}",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. The {npc:271481} is held at the far west end of the {object:147516} ruins, past level 27-30 elite dwarves, and {npc:1364} (34, elite) can be among them. Lead it east out of the ruins, then hand it in to {npc:1072} in the camp. Skip it if you are alone."] = "Son enemigos élite: se recomienda agruparse, busca gente con quien hacerlo. {npc:271481} está retenido en el extremo oeste de las ruinas de {object:147516}, pasando enanos élite de nivel 27-30, y {npc:1364} (34, élite) puede estar entre ellos. Llévalo al este, fuera de las ruinas, y entrégalo a {npc:1072} en el campamento. Sáltalo si vas solo.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:2091} is a level 32 elite: most classes solo it at level 34, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nCareful: Shadowcasters stand on either side of him, and at least one is linked to him, so it joins when he is pulled. Non-elite centurions and captains are spread around his ring of tents."] = "Son enemigos élite: se recomienda agruparse, busca gente con quien hacerlo. {npc:2091} es un élite de nivel 32: la mayoría de las clases lo hacen solas a nivel 34, pero puede que necesites ayuda. Sáltalo si vas solo: la ruta te hace recuperar la experiencia matando enemigos.\nCuidado: Hay lanzasombras a ambos lados de él, y al menos uno está vinculado a él, así que se suma cuando lo atraes. Hay centuriones y capitanes no élite repartidos por su anillo de tiendas.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:271462}, {npc:271338}, {npc:271458} and {npc:271460} are level 32 elites, each called up by using the {item:279996} beside it. Skip them if you are alone. {npc:271462} stands in the south-eastern hills."] = "Son enemigos élite: se recomienda agruparse, busca gente con quien hacerlo. {npc:271462}, {npc:271338}, {npc:271458} y {npc:271460} son élites de nivel 32, y cada uno aparece al usar {item:279996} a su lado. Sáltalos si vas solo. {npc:271462} está en las colinas del sureste.",
		["Torn Fin murlocs"] = "Múrlocs Rompeanca",
		["Underwater"] = "Bajo el agua",
		["Use the {item:279386} at the {area:287} council."] = "Usa {item:279386} en el consejo de {area:287}.",
		["West along the road to Menethil."] = "Al oeste por el camino hasta Menethil.",
		["West from {area:271} to the {area:286} farms."] = "Al oeste desde {area:271} hasta las granjas de {area:286}.",
		["With {quest:98283}'s head and the flesh"] = "Con la cabeza de {quest:98283} y la carne",
		["Yeti cave"] = "Cueva de los yetis",
		["grind on {npc:1418}"] = "farmea {npc:1418}",
		["the same corpse"] = "el mismo cadáver",
		["{area:1038}: kill these as you meet them"] = "{area:1038}: mata a estos según te los encuentres",
		["{area:271} flight master"] = "Maestro de vuelo de {area:271}",
		["{area:287} council"] = "Consejo de {area:287}",
		["{item:2629}, from {npc:1160}"] = "{item:2629}, del {npc:1160}",
		["{item:3713}, from {npc:2381}"] = "{item:3713}, de {npc:2381}",
		["{npc:1075} again"] = "{npc:1075} otra vez",
		["{npc:1077}, below ground"] = "{npc:1077}, bajo tierra",
		["{npc:1077}: for {npc:5387} in {zone:1455}, at the end of this guide"] = "{npc:1077}: para {npc:5387} en {zone:1455}, al final de esta guía",
		["{npc:1356}, {npc:2916} and {npc:5637} stand in the {object:32356}, north-east of the flight master."] = "{npc:1356}, {npc:2916} y {npc:5637} están en {object:32356}, al noreste del maestro de vuelo.",
		["{npc:2094} stands by the docks; {npc:1239} sits in the {area:2104}, south of the keep."] = "{npc:2094} está junto a los muelles; el {npc:1239} está sentado en {area:2104}, al sur de la fortaleza.",
		["{npc:2104} stands on the top floor of {area:2103}: go up inside, the arrow cannot tell the floors apart."] = "{npc:2104} está en el piso de arriba de {area:2103}: sube por adentro, la flecha no distingue los pisos.",
		["{npc:2104}: for {npc:270637}, back east along the road"] = "{npc:2104}: para {npc:270637}, de vuelta al este por el camino",
		["{npc:2228}, inside"] = "{npc:2228}, adentro",
		["{npc:2382}: the lions come later"] = "{npc:2382}: los leones vienen después",
		["{npc:2430}, upstairs"] = "{npc:2430}, arriba",
		["{npc:2438} makes a yeti fur cloak for anyone who brings a {item:3719} ({skill:165}) and a {item:2997} ({skill:197}); no vendor sells either, so this step shows only when you carry both."] = "{npc:2438} hace una capa de piel de yeti para quien le traiga una {item:3719} ({skill:165}) y un {item:2997} ({skill:197}); ningún mercader vende ninguno de los dos, así que este paso solo aparece cuando llevas ambos.",
		["{npc:2438}, between the flight master and the inn: he wants a {item:3719} and a {item:2997} too"] = "{npc:2438}, entre el maestro de vuelo y la posada: también quiere una {item:3719} y un {item:2997}",
		["{npc:251493} stands north-west of the flight master, on the way north to the yeti cave.\n{quest:98059}: {npc:251493} hands you a {item:279386} for the {area:287} council, in the farms west of {area:271}."] = "{npc:251493} está al noroeste del maestro de vuelo, de camino al norte hacia la cueva de los yetis.\n{quest:98059}: {npc:251493} te da una {item:279386} para el consejo de {area:287}, en las granjas al oeste de {area:271}.",
		["{npc:2695}: for King Magni, on the same {zone:1455} stop"] = "{npc:2695}: para el rey Magni, en la misma parada de {zone:1455}",
		["{npc:2708} and {npc:4078} are in the {object:2164}; {npc:5081} south of the {object:2101}."] = "{npc:2708} y {npc:4078} están en {object:2164}; {npc:5081}, al sur de {object:2101}.",
		["{npc:2711}: his trail leads to Arathi"] = "{npc:2711}: su rastro lleva a Tierras Altas de Arathi",
		["{npc:271458} stands in the hills between the {area:1038} and {area:205} (use the {item:279996})."] = "{npc:271458} está en las colinas entre {area:1038} y {area:205} (usa {item:279996}).",
		["{npc:271460} stands in the ruins of {area:205} (use the {item:279996})."] = "{npc:271460} está en las ruinas de {area:205} (usa {item:279996}).",
		["{npc:4078}: the Saltstone Basilisks at the {area:2240} drop the scales, in the next guide"] = "{npc:4078}: los basiliscos Piedra de sal de {area:2240} sueltan las escamas, en la siguiente guía",
		["{npc:4455}, by the keep's door: for {quest:1132} in Theramore, in the next guide"] = "{npc:4455}, junto a la puerta del bastión: para {quest:1132} en Theramore, en la guía siguiente",
		["{npc:4961} waits in the Pig and Whistle tavern in {object:2100}; he and his two thugs fight you, but stop once beaten."] = "{npc:4961} espera en la taberna El Cerdo Borracho, en {object:2100}; él y sus dos matones pelean contigo, pero se detienen al ser derrotados.",
		["{object:2652}, inside"] = "{object:2652}, adentro",
		["{object:671518}: for {npc:2104}"] = "{object:671518}: para {npc:2104}",
		["{quest:98246}: the eggs"] = "{quest:98246}: los huevos",
		["{zone:1455} flight master"] = "Maestro de vuelo de {zone:1455}",
		["{zone:1455} has no druid trainer: {npc:5504} stands in {zone:1453}, north-west of the {object:2101}."] = "{zone:1455} no tiene instructor de druidas: {npc:5504} está en {zone:1453}, al noroeste de {object:2101}.",
} end)()
t.guides["forever/alliance/30-40/02-desolace"] = (function() return {
		["Boat to {area:17203}"] = "Barco al {area:17203}",
		["Escort {npc:5644}"] = "Escolta a {npc:5644}",
		["Fly to {area:442}"] = "Vuela a {area:442}",
		["Follow the road west past {area:460} (Horde) and south-west through the {area:465} into {zone:1443}; {area:608} stands at the top of the pass."] = "Sigue el camino hacia el oeste pasando por {area:460} (Horda) y hacia el suroeste por {area:465} hasta {zone:1443}; {area:608} está en lo alto del paso.",
		["For {npc:5638}, at the end of this guide"] = "Para {npc:5638}, al final de esta guía",
		["Her brother {npc:5643} (36) walks the fortress with the Burning Blade cultists (30-33): pull him alone. The {npc:13019} keeps the sceptre in the fortress's main building. {npc:5642} wants four of each kind of cultist on the way."] = "Su hermano {npc:5643} (36) recorre la fortaleza con los sectarios del Filo Ardiente (30-33): atráelo solo. {npc:13019} guarda el cetro en el edificio principal de la fortaleza. {npc:5642} quiere cuatro de cada tipo de sectario por el camino.",
		["Inside"] = "Adentro",
		["Lead {npc:5644} out of the fortress; she walks off once you are clear of it. {npc:5642} takes the turn-in at {area:608} at the end of the guide."] = "Saca a {npc:5644} de la fortaleza; se va por su cuenta una vez fuera. {npc:5642} recibe la entrega en {area:608} al final de la guía.",
		["Malem chest"] = "Cofre de los Malem",
		["Out of Thunder Axe Fortress"] = "Fuera de la Fortaleza del Hacha de Trueno",
		["Swim out to {area:2406} off the far northern tip: {object:177786} stands on the shore beside the {object:177673}. Open it with both keys; leave the statue alone."] = "Nada hasta {area:2406}, frente a la punta norte: {object:177786} está en la orilla junto a {object:177673}. Ábrelo con ambas llaves; no toques la estatua.",
		["The Hatefury satyrs hold the ruins of {area:603}, east of {area:608}.\nCareful: Hatefury Rogues spawn stealthed, and Hatefury Tricksters have a poison proc on their attacks."] = "Los sátiros Odio Feroz ocupan las ruinas de {area:603}, al este de {area:608}.\nCuidado: Los pícaros Odio Feroz aparecen en sigilo, y los embaucadores Odio Feroz envenenan con sus ataques.",
		["The chest lies in the ruins south-west of {area:608}."] = "El cofre está en las ruinas al suroeste de {area:608}.",
		["The wrecked ship lies just south-west of {npc:11863}'s tower; its chest sits beside {object:177787}."] = "El barco naufragado está justo al suroeste de la torre de {npc:11863}; su cofre está junto a {object:177787}.",
		["on an Aged, Dying or {npc:4702} in the graveyard; don't kill it"] = "en un kodo viejo, moribundo o {npc:4702} en el cementerio; no lo mates",
		["the tamed kodo, at {npc:11596}'s camp: talk to it, five times"] = "el kodo domado, en el campamento de {npc:11596}: habla con él, cinco veces",
		["{area:608} flight master"] = "Maestro de vuelo de {area:608}",
		["{item:15878}, from the Drysnap crabs"] = "{item:15878}, de los cangrejos Secachasquido",
		["{item:6767}; inside"] = "{item:6767}; adentro",
		["{npc:11596}'s camp is on the road south of {area:609}, by the {area:596}."] = "El campamento de {npc:11596} está en el camino al sur de {area:609}, junto a {area:596}.",
		["{npc:11863}'s tower stands on the hill west of {area:599}: take his quest first, the sceptre he wants is in the fortress."] = "La torre de {npc:11863} está en la colina al oeste de {area:599}: acepta primero su misión; el cetro que quiere está en la fortaleza.",
		["{npc:5396}, beside {npc:5752}"] = "{npc:5396}, junto a {npc:5752}",
		["{npc:5638}: the wreck's chest lies below {npc:11863}'s tower, on the way to {area:599}"] = "{npc:5638}: el cofre del naufragio está debajo de la torre de {npc:11863}, de camino a {area:599}",
		["{npc:5642}: the Burning Blade in {area:599}, where her search leads"] = "{npc:5642}: el Filo Ardiente en {area:599}, adonde lleva su búsqueda",
		["{npc:5643} and the Seer"] = "{npc:5643} y el vidente",
		["{npc:5644}, inside"] = "{npc:5644}, adentro",
		["{npc:5752}: the Kolkar are at the end of this guide"] = "{npc:5752}: los Kolkar están al final de esta guía",
		["{quest:5741}; on the top floor"] = "{quest:5741}; en el piso de arriba",
} end)()
t.guides["forever/alliance/30-40/03-ashenvale"] = (function() return {
		["Boat to {area:35}"] = "Barco a {area:35}",
		["Crystalized Scale, from the Saltstone Basilisks: eight for {npc:4078} in {zone:1453}"] = "Escama cristalizada, de los basiliscos Piedra de sal: ocho para {npc:4078} en {zone:1453}",
		["East through the canyons. {area:484}, a Horde camp with guards, sits on the mesa here: keep to the canyon floor and give the foot of its lifts a wide berth."] = "Al este por los cañones. {area:484}, un campamento de la Horda con guardias, está sobre la meseta: quédate en el fondo del cañón y mantente bien lejos de la base de sus elevadores.",
		["Fly to Theramore"] = "Vuela a Isla Theramore",
		["Fly to {area:150}"] = "Vuela a {area:150}",
		["Follow the canyons east to the salt flats. The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "Sigue los cañones al este hasta El Desierto de Sal. Los goblins y gnomos de {area:2240} son neutrales y dan misiones a ambas facciones.",
		["For {npc:1416} in {zone:1453}, after Stranglethorn"] = "Para {npc:1416} en {zone:1453}, después de Tuercespina",
		["For {quest:1132} in Theramore's inn, where this guide's boat goes"] = "Para {quest:1132} en la posada de Theramore, adonde va el barco de esta guía",
		["For {quest:5762} in Stranglethorn, later"] = "Para {quest:5762} en Tuercespina, más adelante",
		["From the raceway follow the road south out of the {area:439} into {zone:1446}."] = "Desde el circuito de carreras sigue el camino al sur saliendo de {area:439} hasta {zone:1446}.",
		["Inside"] = "Adentro",
		["Into {zone:1413}"] = "Hacia {zone:1413}",
		["Into {zone:1446}"] = "A {zone:1446}",
		["Lightforge Ingots"] = "Lingotes Forjaluz",
		["On the road south through the {zone:1413}, {npc:6244} camps east of the road, north-east of {area:378}; come in from the east and keep clear of the Horde guards."] = "En el camino al sur por {zone:1413}, {npc:6244} acampa al este del camino, al noreste de {area:378}; llega desde el este y mantente lejos de los guardias de la Horda.",
		["Tapoke Jahn (34) slips out of the tavern once you take {quest:1248}: stay close behind him. He turns on you outside, a friend joins him, and he gives up once badly hurt. If you lose him the quest fails: abandon it and take it again from {npc:4963}."] = "Tapoke Jahn (34) sale de la taberna en cuanto tomas {quest:1248}: síguelo de cerca. Afuera se vuelve contra ti, se le suma un amigo, y se rinde cuando está muy herido. Si lo pierdes, la misión fracasa: abandónala y vuelve a tomarla de {npc:4963}.",
		["The Bluegill murlocs on the beach south-west of Menethil carry the ingots."] = "Los múrlocs Branquiazul de la playa al suroeste de Menethil llevan los lingotes.",
		["The canyons east of {area:482}"] = "Los cañones al este de {area:482}",
		["The flight master stands by the gate of {area:514}; {npc:5083} and {npc:4964} are inside the citadel."] = "El maestro de vuelo está junto a la puerta de {area:514}; {npc:5083} y {npc:4964} están dentro de la ciudadela.",
		["The wreck of the Flying Osprey lies in the shallows south of the keep."] = "El naufragio del Flying Osprey está en los bajíos al sur del Castillo de Menethil.",
		["Theramore"] = "Theramore",
		["{area:2240}: kill these as you meet them"] = "{area:2240}: mata a estos según te los encuentres",
		["{area:976} flight master"] = "Maestro de vuelo de {area:976}",
		["{area:976} is a short walk down the road; keep to it. {npc:7823}, the Alliance flight master, stands inside the walls."] = "{area:976} queda a un paseo corto por el camino; no te salgas de él. {npc:7823}, la maestra de vuelo de la Alianza, está dentro de las murallas.",
		["{item:2702}; underwater"] = "{item:2702}; bajo el agua",
		["{item:5795}, from the Sparkleshell Tortoises"] = "{item:5795}, de las tortugas brillavalva",
		["{npc:1217} stands in the {area:2104}, south of the keep, where {npc:4963} and {npc:5082} wait too."] = "{npc:1217} está en {area:2104}, al sur del castillo, donde también esperan {npc:4963} y {npc:5082}.",
		["{npc:4454}: for Martek in the {zone:1418}, at the end of 30-40"] = "{npc:4454}: para Martek en {zone:1418}, al final de 30-40",
		["{npc:4455} stands by {area:2103}'s door, just north of the flight master."] = "{npc:4455} está junto a la puerta de {area:2103}, justo al norte del maestro de vuelo.",
		["{npc:4456}'s next errand goes to {area:415}, off this route: leave it."] = "El siguiente encargo de {npc:4456} va a {area:415}, fuera de esta ruta: déjalo.",
		["{npc:4964}, on the top floor"] = "{npc:4964}, en el piso de arriba",
		["{npc:5083}, on the top floor"] = "{npc:5083}, en el piso de arriba",
		["{quest:1132}, inside the inn in the north of town"] = "{quest:1132}, dentro de la posada en el norte del pueblo",
		["{quest:1132}: the wyverns are in {zone:1441}, later in this guide"] = "{quest:1132}: los dracos están en {zone:1441}, más adelante en esta guía",
		["{quest:1738}: in {zone:1440}, on the way to {zone:1443}"] = "{quest:1738}: en {zone:1440}, de camino a {zone:1443}",
		["{quest:65602}: the incubus, beside the succubus; the {item:190309} is near the {quest:1738}"] = "{quest:65602}: el íncubo, junto a la súcubo; {item:190309} está cerca de {quest:1738}",
		["{zone:1453} flight master"] = "Maestro de vuelo de {zone:1453}",
} end)()
t.guides["forever/alliance/30-40/04-stranglethorn-vale"] = (function() return {
		["Back east to Nesingwary's camp on the way north to the {area:99}."] = "De vuelta al este hasta el campamento de Nesingwary, de camino al norte hacia {area:99}.",
		["Back south past Nesingwary: Panthers and Stranglethorn Raptors run in the clearings west of the camp toward the coast; the elder tigers hold the hills south-west."] = "De vuelta al sur pasando a Nesingwary: las panteras y los raptores de Tuercespina corren por los claros al oeste del campamento hacia la costa; los tigres mayores ocupan las colinas del suroeste.",
		["Boat to {area:35}"] = "Barco a {area:35}",
		["Both roam the grass around the camp and along the road north."] = "Ambos deambulan por la hierba alrededor del campamento y a lo largo del camino al norte.",
		["Careful: Troll camps are close to the tiger area, and trolls can join a fight if you pull carelessly.\nCareful: The raptor nest has young raptors that join the fight when you attack the adults."] = "Cuidado: Hay campamentos de trols cerca de la zona de los tigres, y los trols pueden sumarse a la pelea si atraes sin cuidado.\nCuidado: El nido de raptores tiene raptores jóvenes que se suman a la pelea cuando atacas a los adultos.",
		["Class training"] = "Entrenamiento de clase",
		["Fly to {area:415}"] = "Vuela a {area:415}",
		["Fly to {area:467}"] = "Vuela a {area:467}",
		["Fly to {zone:1453}"] = "Vuela a {zone:1453}",
		["From {area:415} head north-west into the hills: the {quest:1738} is a glowing tree north of the road to {area:413}. If you took {quest:65602}, the {item:190309} lies in a house among the trees north of {area:413} (26.6,22.0). Then take the road west to Stonetalon."] = "Desde {area:415} ve al noroeste hacia las colinas: {quest:1738} es un árbol brillante al norte del camino a {area:413}. Si tomaste {quest:65602}, {item:190309} está en una casa entre los árboles al norte de {area:413} (26.6,22.0). Luego toma el camino al oeste hacia Sierra Espolón.",
		["Gluggle (37, rare) on the coast west of camp drops the {item:4614}: four levels over you, leave him unless you are grouped"] = "Gluggle (37, raro), en la costa al oeste del campamento, suelta {item:4614}: está cuatro niveles por encima de ti; déjalo a menos que vayas en grupo",
		["Level 33.2"] = "Nivel 33.2",
		["Panthers, raptors and elder tigers"] = "Panteras, raptores y tigres mayores",
		["River crocolisks"] = "Crocoliscos fluviales",
		["Stranglethorn Tigers"] = "Tigres de Tuercespina",
		["The Kurzen rebels hold the camp east of the {area:99}; work its outer edge, where Jungle Fighters and Medicine Men stand, and loot the supply crates by the tents. {quest:200}'s records lie in a hut on the compound's west side. Careful: Kurzen Elites and Witch Doctors (36) hold the compound's eastern half, by the cave: stay on its west side."] = "Los rebeldes de Kurzen ocupan el campamento al este de {area:99}; recorre su borde exterior, donde están los combatientes de la jungla y los curanderos, y saquea las cajas de suministros junto a las tiendas. Los registros de {quest:200} están en una choza del lado oeste del complejo. Cuidado: los élites y médicos brujos de Kurzen (36) ocupan la mitad este del complejo, junto a la cueva: quédate en su lado oeste.",
		["The adult tigers prowl the hills just south and west of the camp."] = "Los tigres adultos merodean por las colinas justo al sur y al oeste del campamento.",
		["The elder tigers come later, on the way back from the {area:99}"] = "Los tigres mayores vienen después, al regresar de {area:99}",
		["The elder tigers next are 34-35: short of 33.2? Keep on the Kurzen Jungle Fighters and Medicine Men around the compound's outer edge until level 33.2. Or, with a group, run the {area:796} dungeon (Library) instead."] = "Los tigres mayores que siguen son de nivel 34-35: ¿no llegas a 33.2? Sigue con los jíbaros y curanderos de Kurzen alrededor del borde exterior del complejo hasta el nivel 33.2. O, con un grupo, haz en su lugar el calabozo {area:796} (Biblioteca).",
		["The haunted island"] = "La isla embrujada",
		["The road to {area:608}"] = "El camino a {area:608}",
		["The strongbox is deeper in, by the cave: on the northern loop (04b)"] = "La caja fuerte está más adentro, junto a la cueva: en el circuito del norte (04b)",
		["Warlocks fly to {area:415} for the {quest:1738}, on the way west."] = "Los brujos vuelan a {area:415} por {quest:1738}, de camino al oeste.",
		["You know the {area:467} flight: it lands closer to {zone:1443} than {area:415} does. From the peak, follow the road south through the mountains to the {area:465}."] = "Conoces la ruta de vuelo a {area:467}: aterriza más cerca de {zone:1443} que {area:415}. Desde el pico, sigue el camino al sur por las montañas hasta {area:465}.",
		["Young tigers and panthers"] = "Tigres jóvenes y panteras",
		["Your level 34 ranks: the class trainers stand around the {object:2096}, {object:2100}, the Cathedral and the {object:2101}; {npc:5504}, the druid trainer, stands north-west of the {object:2101}. Shamans train in {zone:1455}, later in 30-40."] = "Tus rangos de nivel 34: los instructores de clase están alrededor de {object:2096}, {object:2100}, la Catedral y {object:2101}; {npc:5504}, el instructor de druidas, está al noroeste de {object:2101}. Los chamanes entrenan en {zone:1455}, más adelante en 30-40.",
		["grind on {npc:937}"] = "farmea {npc:937}",
		["keep it: the Lashtail Raptors come on the second loop (04b), around {npc:729}'s hill"] = "consérvala: los raptores colazote vienen en el segundo circuito (04b), alrededor de la colina de {npc:729}",
		["keep it: the Shadowmaw Panthers (37-38) wait for the 40-50 Stranglethorn guide"] = "consérvala: las panteras Faucesombría (37-38) quedan para la guía 40-50 de Tuercespina",
		["{area:101}: kill these as you meet them"] = "{area:101}: mata a estos según te los encuentres",
		["{area:35} flight master"] = "Maestro de vuelo de {area:35}",
		["{area:442} flight master"] = "Maestro de vuelo de {area:442}",
		["{item:190309}, north of {area:413}"] = "{item:190309}, al norte de {area:413}",
		["{item:2634}, from a {object:263} crate"] = "{item:2634}, de una caja de {object:263}",
		["{npc:2495}, by the bank; inside"] = "{npc:2495}, junto al banco; adentro",
		["{npc:2495}, inside"] = "{npc:2495}, adentro",
		["{npc:2495}: the Snapjaw Crocolisks, on the northern loop"] = "{npc:2495}: los crocoliscos Quijaforte, en el circuito del norte",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496}, en el piso de arriba de la taberna",
		["{npc:2496}: the water elementals rise around the haunted island, on the northern loop"] = "{npc:2496}: los elementales de agua surgen alrededor de la isla encantada, en el circuito del norte",
		["{npc:2498}, inside"] = "{npc:2498}, adentro",
		["{npc:2832}, in the {object:56910}; upstairs"] = "{npc:2832}, en {object:56910}; arriba",
		["{npc:4078} is in the {object:2164}, in the {object:2101}."] = "{npc:4078} está en {object:2164}, en {object:2101}.",
		["{npc:469}, in the hut"] = "{npc:469}, en la cabaña",
		["{npc:469}: {quest:200}'s records lie at the edge of {area:101}, next"] = "{npc:469}: los registros de {quest:200} están en el borde de {area:101}, lo siguiente",
		["{npc:6807}, {object:56910}; upstairs"] = "{npc:6807}, {object:56910}; arriba",
		["{npc:715}, from {zone:1441}"] = "{npc:715}, de {zone:1441}",
		["{npc:716} collects the {item:2755}: the pages drop from almost every humanoid in the jungle. Turn the pages into chapters as you go."] = "{npc:716} colecciona {item:2755}: las páginas las sueltan casi todos los humanoides de la jungla. Convierte las páginas en capítulos sobre la marcha.",
		["{npc:737}'s Bloodscalp ears wait for the second Stranglethorn loop: keep the quest."] = "Las orejas Cabellera Sangrienta de {npc:737} quedan para el segundo circuito de Tuercespina: conserva la misión.",
		["{npc:737}, in the tavern"] = "{npc:737}, en la taberna",
		["{npc:738}, at the foot of the path"] = "{npc:738}, al pie del sendero",
		["{npc:770}: for {npc:773} in {area:35}, later in this guide"] = "{npc:770}: para {npc:773} en {area:35}, más adelante en esta guía",
		["{npc:773}, from {npc:770}"] = "{npc:773}, de {npc:770}",
		["{npc:773}, upstairs"] = "{npc:773}, en el piso de arriba",
		["{object:287}, in the hut"] = "{object:287}, en la choza",
		["{object:661516}, a looted crate west of Nesingwary's camp: the Stolen Shipments lie in the Bloodscalp ruins on the coast, for the second Stranglethorn loop"] = "{object:661516}, una caja saqueada al oeste del campamento de Nesingwary: los envíos robados están en las ruinas Cabellera Sangrienta de la costa, para el segundo circuito de Tuercespina",
		["{quest:201}: just look around the hunters' camp"] = "{quest:201}: solo echa un vistazo al campamento de los cazadores",
		["{zone:1434}: kill these as you meet them"] = "{zone:1434}: mata a estos según te los encuentres",
} end)()
t.guides["forever/alliance/30-40/04b-stranglethorn-vale"] = (function() return {
		["\"Sea Wolf\" MacKinley, on the top floor"] = "MacKinley «Lobo de Mar», en el piso superior",
		["East to {area:101}: Herod's records lie in a hut on its west side."] = "Al este hacia {area:101}: los registros de Herod están en una choza en su lado oeste.",
		["Fly to {area:42}"] = "Vuela a {area:42}",
		["For Archmage Ansirem in {zone:1416}"] = "Para el archimago Ansirem en {zone:1416}",
		["For characters of 35 to 36, but several quests here are level 37-38: on purpose, for their experience. The water elementals are 36-37: pull them one at a time."] = "Para personajes de nivel 35 a 36, pero varias misiones de aquí son de nivel 37-38: a propósito, por su experiencia. Los elementales de agua son de nivel 36-37: atráelos de uno en uno.",
		["For {npc:4631} in {area:35}, at the end of this loop"] = "Para el {npc:4631} en {area:35}, al final de este recorrido",
		["From {zone:1431} take the road south; the camp sits in the hills west of the road."] = "Desde {zone:1431} toma el camino al sur; el campamento está en las colinas al oeste del camino.",
		["In the {object:2164}, if you still carry it"] = "En {object:2164}, si todavía lo llevas",
		["Into {zone:1434}"] = "A {zone:1434}",
		["North along the coast to the ruins on the hill: the last two tablets lie there. {npc:268992}, a goblin, is caged beside the third tablet: any Bloodscalp can drop his {item:277957}, then lead him out of the ruins. The Stolen Shipments lie at the ruins' east edge. Pick up Green Hills pages as they drop.\nCareful: the Bloodscalp Berserkers, Headhunters and Witch Doctors (36-37) hold the ruins' core: pull them one at a time."] = "Al norte por la costa hasta las ruinas de la colina: allí están las dos últimas tablillas. {npc:268992}, un goblin, está enjaulado junto a la tercera tablilla: cualquier Sangrapellejo puede soltar su {item:277957}; luego guíalo fuera de las ruinas. Los envíos robados están en el borde este de las ruinas. Recoge las páginas de Colinas Verdes a medida que caigan.\nCuidado: los rabiosos, cazadores de cabezas y médicos brujos Sangrapellejo (36-37) ocupan el centro de las ruinas: atráelos de uno en uno.",
		["North-east up the road to the {area:99}, then back south through the jungle."] = "Al noreste por el camino hacia el {area:99}, luego vuelve al sur a través de la jungla.",
		["Snapjaw Crocolisks"] = "Crocoliscos Quijaforte",
		["Snapjaw Crocolisks bask along the river in the middle of the jungle, on the way south to {area:35}."] = "Los crocoliscos Quijaforte toman sol a lo largo del río en medio de la jungla, de camino al sur hacia {area:35}.",
		["South along the road: the hunters' tents stand just west of it. {npc:717} and Hemet gave you these on the first loop: take them now only if you didn't."] = "Al sur por el camino: las tiendas de los cazadores están justo al oeste. {npc:717} y Hemet te las dieron en el primer circuito: tómalas ahora solo si no lo hiciste.",
		["The Lashtail raptors"] = "Los raptores colazote",
		["The haunted island lies just off the shore west of the second tablet: the Lesser Water Elementals rise from the water around it."] = "La isla embrujada está justo frente a la costa, al oeste de la segunda tablilla: los elementales de agua menores surgen del agua a su alrededor.",
		["The jungle ruins"] = "Las ruinas de la jungla",
		["The {area:102}"] = "Las {area:102}",
		["West across the jungle to the troll ruins: each holds one stone tablet of the troll legends, the first two in the ruins south-west of Nesingwary's camp, the last two on the hill in the north-west.\nCareful: the Saltscale murlocs on the shore near the second tablet are elite (35-37): swim to the tablet from the water and keep clear of them."] = "Al oeste a través de la jungla hacia las ruinas trol: cada una guarda una tablilla de piedra de las leyendas trol; las dos primeras en las ruinas al suroeste del campamento de Nesingwary, las dos últimas en la colina del noroeste.\nCuidado: los múrlocs Escamasal de la orilla cerca de la segunda tablilla son élite (35-37): nada hasta la tablilla desde el agua y mantente lejos de ellos.",
		["keep it: the Skullsplitter Witch Doctors (41-42) wait for the 40-50 Stranglethorn guide"] = "consérvala: los médicos brujos Machacacráneos (41-42) esperan a la guía de Tuercespina 40-50",
		["{item:2006}: {object:58}; underwater"] = "{item:2006}: {object:58}; bajo el agua",
		["{item:277957}, from the Bloodscalp trolls"] = "{item:277957}, de los trols Sangrapellejo",
		["{npc:218230}, a cook, is caged at the compound's western edge: take his quest now and keep it, his cage key and the fighter's uniform come on the 40-50 Stranglethorn guide, when the Subchiefs and Elites are your level. Headshrinkers stand deeper in the compound; the Commandos lurk stealthed around it and in the cave, and Herod's strongbox sits by the cave mouth. Pick up Green Hills pages as they drop.\nCareful: Kurzen Commandos are level 34-35, not elite, and often spawn stealthed; near death they use {spell:7964}. {npc:813}, an elite of 39-40, stands at the compound's north end: leave him be."] = "{npc:218230}, un cocinero, está enjaulado en el borde oeste del complejo: acepta su misión ahora y consérvala; la llave de su jaula y el uniforme de luchador vienen en la guía de Tuercespina 40-50, cuando los subjefes y élites sean de tu nivel. Los reductores de cabezas están más adentro del complejo; los comandos acechan en sigilo a su alrededor y en la cueva, y la caja fuerte de Herod está junto a la entrada de la cueva. Recoge las páginas de Colinas Verdes cuando caigan.\nCuidado: los comandos Kurzen son de nivel 34-35, no élite, y suelen aparecer en sigilo; cerca de la muerte usan {spell:7964}. {npc:813}, un élite de nivel 39-40, está en el extremo norte del complejo: déjalo en paz.",
		["{npc:218230}, in his cage"] = "{npc:218230}, en su jaula",
		["{npc:2495}, inside"] = "{npc:2495}, adentro",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496}, en el piso de arriba de la taberna",
		["{npc:2498}, inside"] = "{npc:2498}, adentro",
		["{npc:268992}, in his cage beside the third tablet"] = "{npc:268992}, en su jaula junto a la tercera tablilla",
		["{npc:4631}, on the docks"] = "{npc:4631}, en los muelles",
		["{npc:715}: the Jungle Stalkers come in 40-50"] = "{npc:715}: los acechadores de la selva vienen en 40-50",
		["{npc:733}: the Commandos and Headshrinkers fell in the compound"] = "{npc:733}: los comandos y reductores de cabezas caídos en el complejo",
		["{npc:737}, upstairs"] = "{npc:737}, en el piso de arriba",
		["{npc:773}, upstairs"] = "{npc:773}, en el piso de arriba",
		["{npc:773}, upstairs: this optional quest needs four {item:4278}. Mine Lesser Bloodstone Deposits in {zone:1417} with {skill:186} 75, or buy the ore at the Auction House or ask a miner friend. The kobolds do not drop it; skip this quest if you cannot get the ore."] = "{npc:773}, en el piso de arriba: esta misión opcional pide cuatro {item:4278}. Extrae de depósitos de sangrita inferior en {zone:1417} con {skill:186} 75, o compra el mineral en la casa de subastas o pídeselo a un amigo minero. Los kóbolds no lo sueltan; omite esta misión si no puedes conseguir el mineral.",
		["{npc:941}, below ground"] = "{npc:941}, bajo tierra",
		["{object:287}, upstairs"] = "{object:287}, arriba",
		["{object:288}, below ground"] = "{object:288}, bajo tierra",
		["{zone:1453} flight master"] = "Maestro de vuelo de {zone:1453}",
} end)()
t.guides["forever/alliance/30-40/05-arathi-highlands"] = (function() return {
		["A group stop: two level 40 water elementals ambush {npc:2768}'s escort, and the Daggerspine naga in the reef are 38-40, with Sorceresses among them. Grouping up is encouraged, look for people to do it with. Skip it if you are alone.\nSouth along the west coast to the goblins' cove; Lolo keeps watch on the rocks above it."] = "Parada de Grupo: dos elementales de agua de nivel 40 emboscan la escolta de {npc:2768}, y los naga Dorsodaga del arrecife son de nivel 38-40, con Hechiceras entre ellos. Se recomienda formar Grupo, busca gente con quien hacerlo. Omítelo si estás solo.\nAl sur por la costa oeste hasta la cala de los goblins; Lolo vigila desde las rocas de arriba.",
		["A {npc:2434} (37-38) lurks stealthed on the edge of {area:271}, and few players find him. Careful: he is a level or two over you; fight him only at full health, or leave him. His contract goes to {npc:2276}. Don't wait for him: the rest of this step doesn't need him."] = "Un {npc:2434} (37-38) acecha en sigilo en las afueras de {area:271}, y pocos jugadores lo encuentran. Cuidado: te supera por un Nivel o dos; enfréntalo solo con la salud completa, o déjalo. Su contrato es para {npc:2276}. No lo esperes: el resto de este Paso no lo necesita.",
		["Back out of the grate to Modera's camp on the lake shore."] = "Sal por la reja y regresa al campamento de Modera en la orilla del lago.",
		["Back west through {zone:1430} to {area:42}."] = "De vuelta al oeste por {zone:1430} hasta {area:42}.",
		["Below ground"] = "Bajo tierra",
		["Careful: Syndicate Spies and Assassins can be stealthed. Assassins also poison you.\nCareful: {npc:2306} (40) turns up in one spot at a time: the cellar of {area:280}'s inn, or one of the Syndicate tent camps north of the village. Leave him be."] = "Cuidado: los Espías y Asesinos de la Hermandad pueden estar en sigilo. Los Asesinos además te envenenan.\nCuidado: {npc:2306} (40) aparece en un solo lugar a la vez: el sótano de la Posada de {area:280}, o uno de los campamentos de tiendas de la Hermandad al norte del pueblo. Déjalo en paz.",
		["City of Dalaran"] = "Ciudad de Dalaran",
		["Crushridge ogres"] = "Ogros Aplastacresta",
		["East along the road to the {area:76}. The {quest:1389} are the glowing blue crystals among the Lost Ones' tents: click them. Any {npc:254797} counts for {npc:254775}, and the Lost One Fishermen on the sanctuary's west side carry {npc:254770}'s {item:258530}. {quest:1392} walks a long path through the ruins; his cudgel starts a quest for {npc:1776}. Don't wait for him.\nCareful: Noboru is level 39, two over you here: fight him only with a friend or from level 38; otherwise let him pass."] = "Al este por el camino hacia {area:76}. Los {quest:1389} son los cristales azules brillantes entre las tiendas de los Perdidos: haz clic en ellos. Cualquier {npc:254797} cuenta para {npc:254775}, y los pescadores Perdidos del lado oeste del santuario llevan el {item:258530} de {npc:254770}. {quest:1392} recorre un largo camino por las ruinas; su garrote inicia una misión para {npc:1776}. No lo esperes.\nCuidado: Noboru es de nivel 39, dos más que tú aquí: enfréntalo solo con un amigo o desde el nivel 38; si no, déjalo pasar.",
		["East from {quest:681} across the north of the Highlands; the shards glitter on the hill by the {area:333}, north of {area:314}."] = "Al este desde {quest:681}, por el norte de las Tierras Altas; los fragmentos brillan en la colina junto a {area:333}, al norte de {area:314}.",
		["Escort the professor up the hill to the cave above the cove and guard him while he works. Two level 40 water elementals ambush him there, and they are immune to frost. Hold them at the cave mouth, away from him: if the fight happens inside the cave, he joins in instead of working and more elementals keep coming."] = "Escolta al profesor colina arriba hasta la cueva sobre la cala y protégelo mientras trabaja. Dos elementales de agua de nivel 40 lo emboscan ahí, y son inmunes a la escarcha. Retenlos en la entrada de la cueva, lejos de él: si la pelea es dentro de la cueva, él se une en lugar de trabajar y siguen llegando más elementales.",
		["Fly to {area:144}"] = "Vuela a {area:144}",
		["Fly to {area:271}"] = "Vuela a {area:271}",
		["Fly to {area:42}"] = "Vuela a {area:42}",
		["Fly to {zone:1453}"] = "Vuela a {zone:1453}",
		["Follow the road north out of {area:271} into the mountains. Mountain lions roam the slopes; the Syndicate in {area:280} wear the signet rings."] = "Sigue el camino al norte, saliendo de {area:271}, hacia las montañas. Los leones de montaña rondan las laderas; la Hermandad de {area:280} lleva los anillos de sello.",
		["Follow the road north to the draenei of the {area:657}. {npc:254775} and {npc:254770} stand beside {npc:1776}: their Lost Ones are the ones you meet in the {area:76} anyway."] = "Sigue el camino al norte hasta los draenei de {area:657}. {npc:254775} y {npc:254770} están junto a {npc:1776}: sus Perdidos son los que encontrarás de todos modos en {area:76}.",
		["For your City of Dalaran run, next: the {npc:269127} wants the arcane remnants in the city thinned out and a mote from the heart of the disruption. {quest:92458} brings the {item:277507}, which opens the grate."] = "Para tu recorrido por Ciudad de Dalaran, lo siguiente: la {npc:269127} quiere que diezmes los restos arcanos de la ciudad y una mota del corazón de la perturbación. {quest:92458} trae {item:277507}, que abre la reja.",
		["For {npc:1356} in {zone:1455}, at the end of this guide"] = "Para {npc:1356} en {zone:1455}, al final de esta Guía",
		["For {npc:1440} in {zone:1453}: keep it"] = "Para {npc:1440} en {zone:1453}: guárdalo",
		["For {npc:2487} in {area:35}: keep it"] = "Para {npc:2487} en {area:35}: guárdalo",
		["For {npc:2542} in {area:35}: keep it"] = "Para {npc:2542} en {area:35}: guárdalo",
		["For {npc:2711} in {area:271}"] = "Para {npc:2711} en {area:271}",
		["From the Syndicate camp, follow the road east over {area:1057} to {area:320}."] = "Desde el campamento de la Hermandad, sigue el camino al este por {area:1057} hasta {area:320}.",
		["From {npc:2712}'s camp, a short way north-east to the {object:2691}, by the shards' hill north of {area:314}. The {object:2702}, where the three keys go, stands west of {area:320}.\nCareful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East."] = "Desde el campamento de {npc:2712}, un corto trecho al noreste hasta {object:2691}, junto a la colina de los fragmentos al norte de {area:314}. {object:2702}, donde van las tres llaves, está al oeste de {area:320}.\nCuidado: Cada piedra central está vigilada por unos tres elementales de nivel 39 más o menos que atacan juntos si haces clic en la piedra sin despejarlos: Exiliados ardientes en el Oeste, Exiliados tronadores en el Exterior, Éxilus coronadores en el Este.",
		["From {zone:1455} take the tunnel east through {zone:1426} into {zone:1432} and follow the road to {area:144}."] = "Desde {zone:1455} toma el túnel al este por {zone:1426} hasta {zone:1432} y sigue el camino hasta {area:144}.",
		["Hay Weevils crawl about the north end of {quest:681}'s farm: catch one with the tool from {npc:217412}'s {item:213565}."] = "Los gorgojos del heno andan por el extremo norte de la granja de {quest:681}: atrapa uno con la herramienta de {item:213565} de {npc:217412}.",
		["Lost Ones: Hunters, Muckdwellers, Seers and Riftseekers all count"] = "Perdidos: cuentan los Cazadores, Moradores del fango, Videntes y Buscafallas",
		["North out of {area:271} to the Syndicate camp on the Alterac border, west of {area:272} (Horde): its Footpads and Thieves are the Syndicate Maleb wants, and the documents lie in the camp. Then back to the road and east to Arathi.\nCareful: a few Syndicate Wizards (34-35) stand among the tents and cast from range: pull them one at a time."] = "Al norte, saliendo de {area:271}, hasta el campamento de la Hermandad en la frontera de Alterac, al oeste de {area:272} (Horda): sus Salteadores y Ladrones son la Hermandad que busca Maleb, y los documentos están en el campamento. Luego vuelve al camino y ve al este hacia Arathi.\nCuidado: unos cuantos Zahoríes de la Hermandad (34-35) están entre las tiendas y lanzan hechizos a distancia: atráelos de uno en uno.",
		["North-west of Watcher Biggs, {npc:255597} (level 34) waits by the road: lead him north to the {area:657}, on your way there. Stay close to him and clear what attacks him; if he falls, abandon the quest and go on."] = "Al noroeste del vigía Biggs, {npc:255597} (nivel 34) espera junto al camino: guíalo al norte hasta {area:657}, de camino allí. Mantente cerca de él y elimina lo que lo ataque; si muere, abandona la misión y sigue.",
		["North-west out of the Witherbark valley; {npc:2712} and {npc:2713} camp in the hills just north of {area:314}."] = "Al noroeste, saliendo del valle Secacorteza; {npc:2712} y {npc:2713} acampan en las colinas justo al norte de {area:314}.",
		["Off the flight, straight to the {area:271} inn. Then {npc:2276} and {npc:2277}, in the town hall, take the Syndicate camp's quests and send you north to {area:280}."] = "Al bajar del vuelo, ve directo a la Posada de {area:271}. Luego {npc:2276} y {npc:2277}, en el ayuntamiento, te dan las Misiones del campamento de la Hermandad y te envían al norte a {area:280}.",
		["Only if Gluggle gave you the pendant in Stranglethorn"] = "Solo si Gluggle te dio el colgante en Tuercespina",
		["Phizzlethorpe"] = "Fiseltor",
		["South down the road to {npc:5476}, on the way west out of the swamp."] = "Al sur por el camino hasta {npc:5476}, de camino al oeste para salir del pantano.",
		["South-east along the loch to the dig site."] = "Al sureste por la orilla del lago hasta la excavación.",
		["South-east through the hills: {npc:2793}, an ogre mage, holds the cave at the southern end of the Witherbark valley.\nCareful: {npc:2793} is level 39, a caster, one or two over you here: clear the cave mouth first, then pull him alone at full health."] = "Al sureste por las colinas: {npc:2793}, un ogro mago, ocupa la cueva en el extremo sur del valle Secacorteza.\nCuidado: {npc:2793} es de nivel 39, lanzador de hechizos, uno o dos por encima de ti aquí: despeja primero la entrada de la cueva y luego atráelo solo con la salud completa.",
		["South-west from {npc:2793}'s cave to the {area:880}: {npc:2696} stands on a broken section of the bridge; jump down to him from its north end. {quest:647} must reach {npc:2705} in {area:271} within 15 minutes: go straight back to {area:320} and fly to {area:271}."] = "Al suroeste desde la cueva de {npc:2793} hasta {area:880}: {npc:2696} está en un tramo roto del puente; salta hasta él desde su extremo norte. {quest:647} tiene que llegar a {npc:2705} en {area:271} en 15 minutos: vuelve directo a {area:320} y vuela a {area:271}.",
		["South-west to the Kirin Tor camp on the lake shore west of {area:279}, just over the border into {zone:1421}: the {npc:269127} stands there. Archmage Ansirem stands south-east of it, by the dome."] = "Al suroeste hasta el campamento del Kirin Tor en la orilla del lago al oeste de {area:279}, justo al cruzar la frontera de {zone:1421}: ahí está {npc:269127}. El archimago Ansirem está al sureste, junto a la cúpula.",
		["Stay with {npc:2713} while she sneaks into {area:314} and back; Horde orcs jump you on the way.\nCareful: Orcs that drop to low health run away. {npc:2713} follows them and can pull more mobs, so kill or slow runners fast."] = "Quédate con {npc:2713} mientras se infiltra en {area:314} y vuelve; los orcos de la Horda te asaltan por el camino.\nCuidado: Los orcos que quedan con poca salud huyen. {npc:2713} los sigue y puede atraer más enemigos, así que mata o ralentiza rápido a los que huyen.",
		["Syndicate camp"] = "Campamento de la Hermandad",
		["The City of Dalaran is a dungeon for a group of five at about level 28 to 33: at your level it goes quickly. Its way in is the sewer grate in the city's western wall, by the lake, 30 yards from Modera's camp.\nInside: the Seeking Remnants, Saturated Remnants and Mana Echoes are Modera's {quest:92457}; the {item:251961} for {quest:92458} drops inside too."] = "Ciudad de Dalaran es una mazmorra para un grupo de cinco de nivel 28 a 33 más o menos: a tu nivel se hace rápido. Su entrada es la reja de la alcantarilla en el muro oeste de la ciudad, junto al lago, a 30 m del campamento de Modera.\nAdentro: los restos buscadores, los restos saturados y los ecos de maná son para {quest:92457} de Modera; {item:251961} para {quest:92458} también cae adentro.",
		["The Crushridge ogres hold the hills north of {area:280}. Careful: Nagaz (40) stands far to the north-west by a worn wooden chest, with Syndicate guards: stay with the ogres.\nThe Crushridge Maulers, Mages, Enforcers and Warmongers (36-39) are elite; the Crushridge Ogres and Brutes (34-35) are not and drop the knucklebones too: pull one at a time, or group up."] = "Los ogros Aplastacresta ocupan las colinas al norte de {area:280}. Cuidado: Nagaz (40) está muy al noroeste junto a un cofre de madera gastado, con guardias de la Hermandad: quédate con los ogros.\nLos aplastadores, magos, déspotas y belicistas Aplastacresta (36-39) son élite; los ogros y brutos Aplastacresta (34-35) no, y también sueltan los nudillos: atráelos de a uno, o agrúpate.",
		["The Drywhisker kobolds dig in the gorge east of {area:321} (Horde); skirt the town to the north. They drop the Motes of Myzrael, not Krazek's ore. Lesser Bloodstone Deposits need {skill:186} 75: mine four ore, buy them at the Auction House, or ask a miner friend. The ore goal is optional; continue with Myzrael if you cannot get it. Careful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them."] = "Los kóbolds Mostacho Seco excavan en el desfiladero al este de {area:321} (Horda); rodea el pueblo por el norte. Sueltan las Motas de Myzrael, no el mineral de Krazek. Los depósitos de sangrita inferior requieren {skill:186} 75: extrae cuatro de mineral, cómpralos en la casa de subastas o pídeselos a un amigo minero. El objetivo del mineral es opcional; sigue con Myzrael si no puedes conseguirlo. Cuidado: todos los tipos de kóbold huyen en busca de ayuda cuando tienen poca salud (los kóbolds al 30%, los peritos y los cavadores al 15%), lo que puede atraer a más.",
		["The Syndicate hold the farm north-west of {area:320}.\nCareful: Syndicate Highwaymen are level 30-31 and can cast Sneak while out of combat, so they are often stealthed and hard to spot."] = "El Sindicato ocupa la granja al noroeste de {area:320}.\nCuidado: Los salteadores del Sindicato son de nivel 30-31 y pueden usar Sigilo fuera de combate, así que suelen estar ocultos y cuesta verlos.",
		["The courier walks the road from {area:314} west across the Highlands, as far as about 24,45, and back, with two guards: the arrow follows the road west until you meet him. Pull them off the road."] = "El mensajero recorre el camino desde {area:314} hacia el oeste a través de las Tierras Altas, hasta aproximadamente 24,45, y de regreso, con dos guardias: la flecha sigue el camino al oeste hasta que lo encuentres. Atráelos fuera del camino.",
		["The shards lie at the far end of {area:318}."] = "Los fragmentos están al fondo de {area:318}.",
		["The tomes lie in the ruined keep west of {area:280}; Argus Shadow Mages hold the ruins.\nCareful: Crushridge Warmongers call nearby allies within 15 yd once they fall below half health.\nThe Crushridge Maulers, Mages, Enforcers and Warmongers (36-39) are elite; the Crushridge Ogres and Brutes (34-35) are not and carry the tomes too: pull one at a time, or group up."] = "Los tomos están en el castillo en ruinas al oeste de {area:280}; los magos oscuros Argus ocupan las ruinas.\nCuidado: Los belicistas Aplastacresta piden ayuda a los aliados a menos de 15 m cuando bajan de la mitad de su salud.\nLos machacadores, magos, déspotas y belicistas Aplastacresta (36-39) son élite; los ogros y brutos Aplastacresta (34-35) no, y también llevan los tomos: atráelos de a uno, o agrúpate.",
		["The western swamp"] = "El pantano del oeste",
		["The wrecked caravan's chest lies at the north end of the {area:76}, beside {npc:5391}'s cage.\nCareful: The camp is full of Lost Ones around level 38. They stand in linked groups of 2-3, many are casters, and they respawn quickly."] = "El cofre de la caravana destrozada está en el extremo norte de {area:76}, junto a la jaula de {npc:5391}.\nCuidado: El campamento está lleno de perdidos de nivel 38 más o menos. Están en grupos vinculados de 2-3, muchos son lanzadores de hechizos, y reaparecen rápido.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:2417} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back.\n{npc:2417} walks from the arrow north-east through the ruins to about 40,47 and back: if he isn't at the arrow, follow his path."] = "Estos son enemigos élite: se recomienda agruparse, busca gente con quien hacerlo. {npc:2417} es un élite de nivel 40: la mayoría de las clases lo derrotan en solitario a nivel 42, pero quizá necesites ayuda. Sáltalo si vas solo: la ruta te hace recuperar la experiencia matando enemigos.\n{npc:2417} camina desde la flecha al noreste a través de las ruinas hasta aproximadamente 40,47 y de regreso: si no está en la flecha, sigue su recorrido.",
		["To {area:144}"] = "A {area:144}",
		["Tram to {zone:1455}"] = "Tranvía a {zone:1455}",
		["West along the road from {npc:5391}'s strongbox to the {area:657}."] = "Al oeste por el camino desde la caja fuerte de {npc:5391} hasta {area:657}.",
		["West along the road to {area:320}."] = "Al oeste por el camino hasta {area:320}.",
		["Young crocolisks, Sorrow Spinners and Swamp Jaguars all roam the swamp around the road."] = "Crocoliscos jóvenes, Hilapenas ({npc:858}) y Jaguares del pantano ({npc:767}) recorren el pantano alrededor del camino.",
		["from {quest:1392}: he walks a path through the ruins"] = "de {quest:1392}: recorre un camino por las ruinas",
		["{area:280}: kill these as you meet them"] = "{area:280}: mata a estos según te los encuentres",
		["{area:281}: kill these as you meet them"] = "{area:281}: mata a estos según te los encuentres",
		["{area:318}: kill these as you meet them"] = "{area:318}: mata a estos según te los encuentres",
		["{area:320} flight master"] = "Maestro de vuelo de {area:320}",
		["{area:328}: kill these as you meet them"] = "{area:328}: mata a estos según te los encuentres",
		["{area:35} flight master"] = "Maestro de vuelo de {area:35}",
		["{item:2321}, from {npc:2381}"] = "{item:2321}, de {npc:2381}",
		["{item:258530}, from a {npc:757}"] = "{item:258530}, de un {npc:757}",
		["{item:3658}: Crushridge ogres"] = "{item:3658}: ogros Aplastacresta",
		["{item:3659}: the {object:1760}, beside Muckrake (40, elite): get it with a group, or abandon {quest:540}; inside"] = "{item:3659}: {object:1760}, junto a Muckrake (40, élite): consíguelo con un grupo o abandona {quest:540}; adentro",
		["{item:4435} from {npc:2572}, {npc:2573} and {npc:2574}, by this stop"] = "{item:4435} de {npc:2572}, {npc:2573} y {npc:2574}, junto a esta parada",
		["{item:4492}; underwater"] = "{item:4492}; bajo el agua",
		["{item:4525}; below ground"] = "{item:4525}; bajo tierra",
		["{item:5040}; below ground"] = "{item:5040}; bajo tierra",
		["{item:6071}, the blue crystals by the tents"] = "{item:6071}, los cristales azules junto a las tiendas",
		["{npc:1141}, {area:17203} road"] = "{npc:1141}, camino de {area:17203}",
		["{npc:12336}, Cathedral of Light"] = "{npc:12336}, en la catedral",
		["{npc:1356}: for {npc:1344} in {zone:1432}, next"] = "{npc:1356}: para {npc:1344} en {zone:1432}, lo siguiente",
		["{npc:1440}, the Royal Library in the keep"] = "{npc:1440}, la biblioteca real del castillo",
		["{npc:1470}, below ground"] = "{npc:1470}, bajo tierra",
		["{npc:1776}: Noboru's cudgel"] = "{npc:1776}: el garrote de Noboru",
		["{npc:1776}: {npc:255597}'s escort"] = "{npc:1776}: la escolta de {npc:255597}",
		["{npc:1776}: {quest:93464}, for {npc:11863} in {zone:1443}, on the {zone:1443} guide at the end of 30-40"] = "{npc:1776}: {quest:93464}, para {npc:11863} en {zone:1443}, en la Guía de {zone:1443} al final de 30-40",
		["{npc:185335}, at the same circle"] = "{npc:185335}, en el mismo círculo",
		["{npc:217412}: three critters to catch in Arathi, {zone:1443} and Stranglethorn"] = "{npc:217412}: tres alimañas que atrapar en Arathi, {zone:1443} y Tuercespina",
		["{npc:2276}, inside"] = "{npc:2276}, adentro",
		["{npc:2276}: the signet rings are in {area:280}"] = "{npc:2276}: los anillos de sello están en {area:280}",
		["{npc:2434}, if you spot him"] = "{npc:2434}, si lo ves",
		["{npc:2438} stands between the flight master and the inn; {npc:2381} beside him sells {item:2321} if you have none."] = "{npc:2438} está entre el maestro de vuelo y la posada; {npc:2381}, a su lado, vende {item:2321} si no tienes.",
		["{npc:2595}, underwater"] = "{npc:2595}, bajo el agua",
		["{npc:2596}, underwater"] = "{npc:2596}, bajo el agua",
		["{npc:2705}, below ground"] = "{npc:2705}, bajo tierra",
		["{npc:2712} and {npc:2713}"] = "{npc:2712} y {npc:2713}",
		["{npc:2713}'s errand"] = "El encargo de {npc:2713}",
		["{npc:2789}: {npc:2793}'s cave, west past the {object:2689}"] = "{npc:2789}: la cueva de {npc:2793}, al oeste pasando {object:2689}",
		["{npc:5391} is caged at the north end of the sanctuary. Free him and keep him alive on the walk out; his strongbox waits by the road afterwards. Careful: on the walk out the camp's Lost One Riftseekers (37-38) and their pets, with the Lost Ones around them, turn on {npc:5391}: clear the cage and the start of his path first, stay beside him and pull every attacker onto yourself. Many players lose him the first time; if he dies, abandon the quest and take it again at his cage."] = "{npc:5391} está enjaulado en el extremo norte del santuario. Libéralo y mantenlo con vida durante la salida; después, su caja fuerte espera junto al camino. Cuidado: durante la salida, los buscagrietas de los Perdidos (37-38) del campamento y sus mascotas, con los Perdidos que los rodean, atacan a {npc:5391}: despeja antes la jaula y el inicio de su camino, quédate a su lado y atrae a todos los atacantes hacia ti. Muchos jugadores lo pierden la primera vez; si muere, abandona la misión y vuelve a tomarla en su jaula.",
		["{npc:5476} guards the road junction in the west of the swamp. {npc:217412} stands a short way north of him.\n{npc:217412} may not be here on Forever: if {npc:217412} doesn't offer {quest:93176}, skip it."] = "{npc:5476} vigila el cruce de caminos en el oeste del pantano. {npc:217412} está un poco al norte de él.\nPuede que {npc:217412} no esté aquí en Forever: si {npc:217412} no ofrece {quest:93176}, sáltala.",
		["{npc:5677}, at the summoning circle"] = "{npc:5677}, en el círculo de invocación",
		["{npc:6122} binds the incubus to you"] = "{npc:6122} vincula al íncubo contigo",
		["{npc:6122} waits in the {object:2164}'s cellar, in the {object:2101}. Use the {item:6913} at the summoning circle there and defeat the succubus it calls. If you took {quest:65602}, hand him the {item:190309} too, place it at the same circle and defeat the incubus."] = "{npc:6122} espera en el sótano de {object:2164}, en {object:2101}. Usa el {item:6913} en el círculo de invocación de allí y derrota a la súcubo que aparece. Si aceptaste {quest:65602}, dale también la {item:190309}, colócala en el mismo círculo y derrota al íncubo.",
		["{object:2707}; underwater"] = "{object:2707}; bajo el agua",
		["{object:2708}; underwater"] = "{object:2708}; bajo el agua",
		["{object:2709}; underwater"] = "{object:2709}; bajo el agua",
		["{object:2710}; underwater"] = "{object:2710}; bajo el agua",
		["{quest:651} is a group quest at this level: three Cresting Exiles (38-39) guard the {object:2691} and attack together. Grouping up is encouraged, look for people to do it with. Skip it if you are alone."] = "{quest:651} es una Misión de Grupo a este Nivel: tres Éxilus coronadores (38-39) vigilan {object:2691} y atacan juntos. Se recomienda formar Grupo, busca gente con quien hacerla. Omítela si estás solo.",
		["{quest:65602}, if you took it"] = "{quest:65602}, si la aceptaste",
		["{quest:92457}: the remnants and echoes, inside"] = "{quest:92457}: los restos y ecos, adentro",
		["{quest:92458}: the {item:251961}, inside"] = "{quest:92458}: {item:251961}, adentro",
		["{zone:1455} flight master"] = "Maestro de vuelo de {zone:1455}",
} end)()
t.guides["forever/alliance/30-40/06-badlands"] = (function() return {
		["Buzzards circle the plain to the east. Careful: the Dustbelcher Maulers, Shamans and Wyrmhunters (40-43) camp far to the south-west: leave them.\nThe battered skeleton lies at the edge of the Stonevault trogg camp; {quest:739}, Agmond's killer, walks among the Bonesnappers.\nCareful: the Stonevault Bonesnappers are 39-40 and the Shamans 40-41, a level or two over you here: pull them from the camp's edge, one at a time.\nCareful: Dustbelcher Lords are level 44-45. They use {spell:5242} and {spell:1160}, and below 50% health they call for help from allies within 15 yd. Seven of them stand about 750 yd south of {area:340}."] = "Las águilas ratoneras sobrevuelan la llanura al este. Cuidado: los aplastadores, chamanes y cazavermis Rotapolvo (40-43) acampan muy al suroeste: déjalos.\nEl esqueleto maltrecho está en el borde del campamento de los troggs Grutacanto; {quest:739}, el asesino de Agmond, anda entre los Cascahuesos.\nCuidado: los Cascahuesos Grutacanto son de nivel 39-40 y los chamanes 40-41, uno o dos niveles por encima de ti aquí: atráelos desde el borde del campamento, de a uno.\nCuidado: Los señores Rotapolvo son de nivel 44-45. Usan {spell:5242} y {spell:1160}, y por debajo del 50% de salud piden ayuda a los aliados a menos de 15 m. Siete de ellos están unos 750 m al sur de {area:340}.",
		["East from the {area:1877} to {area:346}: {npc:2860} takes the scrap metal."] = "Al este desde {area:1877} hasta {area:346}: {npc:2860} recibe la chatarra.",
		["For {npc:4454} at the {area:2240}: the {zone:1446} guide passes him at 45, keep it"] = "Para {npc:4454} en {area:2240}: la guía de {zone:1446} pasa junto a él a nivel 45, guárdala",
		["Head back west to the road and follow it south out of {zone:1432} through the pass into the {zone:1418}. {npc:2910} and {npc:2860} camp side by side at the dig."] = "Vuelve al oeste hasta el camino y síguelo al sur saliendo de {zone:1432} por el paso hasta {zone:1418}. {npc:2910} y {npc:2860} acampan uno al lado del otro en la excavación.",
		["Head north to {area:1517}'s entrance, in the north of the {zone:1418}: the chest lies just inside the cave mouth. {npc:2932} and the Obsidian Golems (38) stand beside it and Shadowforge Diggers (35-36) work the tunnel, all elite: keep your group together."] = "Ve al norte hasta la entrada de {area:1517}, en el norte de {zone:1418}: el cofre está justo al entrar por la boca de la cueva. {npc:2932} y los gólems de obsidiana (38) están a su lado y los excavadores Forjatiniebla (35-36) trabajan en el túnel, todos élite: mantén unido a tu grupo.",
		["Head north-east to the abandoned dig; the supply crate lies there among the Dustbelcher ogres."] = "Ve al noreste hasta la excavación abandonada; la caja de suministros está ahí, entre los ogros Rotapolvo.",
		["Head south to {area:345}."] = "Ve al sur hasta {area:345}.",
		["Head west into the {area:1878}; {npc:2921} works by his machines in the middle of it."] = "Ve al oeste hacia {area:1878}; {npc:2921} trabaja junto a sus máquinas en el medio.",
		["Into {zone:1418}"] = "A {zone:1418}",
		["Lesser Rock Elementals"] = "Elementales de roca inferiores",
		["Rock Elementals"] = "Elementales de roca",
		["Ryedol's next errand goes into {area:1517}: skip it."] = "El siguiente encargo de Ryedol es en {area:1517}: omítelo.",
		["The Lesser Rock Elementals wander the {area:1878} west of {npc:2921}; every rock elemental can drop {npc:1470}'s Rock Elemental Shards. The Dustbelcher Ogres (38-39) on the {area:1878}'s west side drop {npc:2860}'s scrap. Careful: a {npc:269756}, a level 42 elite, drifts about the {area:1878}: give it a wide berth.\nCareful: the Lesser Rock Elementals are 37-39 and hit hard: fight them one at a time."] = "Los elementales de roca inferiores recorren {area:1878} al oeste de {npc:2921}; cualquier elemental de roca puede soltar los fragmentos de elemental de roca de {npc:1470}. Los ogros Rotapolvo (38-39) del lado oeste de {area:1878} sueltan la chatarra de {npc:2860}. Cuidado: un {npc:269756}, élite de nivel 42, deambula por {area:1878}: mantente bien lejos.\nCuidado: los elementales de roca inferiores son de nivel 37-39 y pegan fuerte: enfréntalos de a uno.",
		["The Rock Elementals roam south-east of {npc:2921}; Giant Buzzards and Elder Crag Coyotes share the plain to their west. Careful: a {npc:269756}, a level 42 elite, drifts about the {area:1878}: give it a wide berth."] = "Los elementales de roca recorren el sureste de {npc:2921}; las águilas ratoneras gigantes y los coyotes del risco mayores comparten la llanura al oeste. Cuidado: un {npc:269756}, élite de nivel 42, deambula por {area:1878}: mantente bien lejos.",
		["The battered skeleton lies just east of the ogres, at the edge of the Stonevault trogg camp; the Bonesnappers and Shamans around it drop the flakes. Theldurin sits by the ruined camp further south."] = "El esqueleto maltrecho está justo al este de los ogros, en el borde del campamento de troggs Grutacanto; los Cascahuesos y los chamanes de alrededor sueltan las escamas. Theldurin está sentado junto al campamento en ruinas, más al sur.",
		["The clams lie on Stranglethorn's north-west coast, in the next guide: keep it"] = "Las almejas están en la costa noroeste de Vega de Tuercespina, en la siguiente guía: guárdala",
		["The excavation crate"] = "La caja de la excavación",
		["The {object:126260}"] = "{object:126260}",
		["Theldurin sits by the ruined camp south of the trogg camp. His tablet lies just inside {area:1517}'s cave mouth, beside level 38 elites: a quest for a group."] = "Theldurin está sentado junto al campamento en ruinas al sur del campamento trogg. Su tablilla está justo al entrar por la boca de la cueva de {area:1517}, junto a élites de nivel 38: una misión para grupo.",
		["To {area:2101}"] = "A {area:2101}",
		["for {npc:2786} in {zone:1455}: keep it"] = "para {npc:2786} en {zone:1455}: guárdala",
		["{area:345}: kill these as you meet them"] = "{area:345}: mata a estos según te los encuentres",
		["{area:346}: kill these as you meet them"] = "{area:346}: mata a estos según te los encuentres",
		["{item:278402}, from the Shadowforge diggers and the Bonesnappers"] = "{item:278402}, de los excavadores Forjatiniebla y los Cascahuesos",
		["{item:278403}, in the Shadowforge camp"] = "{item:278403}, en el campamento Forjatiniebla",
		["{item:4630}, from the Dustbelcher Ogres"] = "{item:4630}, de los ogros Rotapolvo",
		["{item:4631}; below ground"] = "{item:4631}; bajo tierra",
		["{item:7847}, if you still need one: the Buzzards east of {area:345} drop it only rarely"] = "{item:7847}, si aún te falta: las águilas ratoneras al este de {area:345} la sueltan muy rara vez",
		["{item:7847}: the Starving Buzzards (35-37) circling the hills north of the digsite drop it most often; leave the Giant Buzzards (39-41) of the far west"] = "{item:7847}: las águilas ratoneras hambrientas (35-37) que sobrevuelan las colinas al norte de la excavación la sueltan más a menudo; deja las águilas ratoneras gigantes (39-41) del extremo oeste",
		["{npc:1470}, in the inn; below ground"] = "{npc:1470}, en la posada; bajo tierra",
		["{npc:269577} of the Explorers' League camps at the foot of the pass. His artifacts drop from the Shadowforge diggers at {area:346} and the Stonevault Bonesnappers at {area:345}, and the helmet lies in the Shadowforge camp."] = "{npc:269577}, de la Liga de Expedicionarios, acampa al pie del paso. Sus artefactos los sueltan los excavadores Forjatiniebla de {area:346} y los Cascahuesos Grutacanto de {area:345}, y el casco está en el campamento Forjatiniebla.",
		["{npc:269577}: keep it, the {item:278404} waits for the 40-50 {zone:1418} visit"] = "{npc:269577}: guárdala, el {item:278404} espera a la visita de 40-50 a {zone:1418}",
		["{npc:4618} and {npc:2817} camp in the {area:1877}, on the road between {area:1517} and {area:345}."] = "{npc:4618} y {npc:2817} acampan en {area:1877}, en el camino entre {area:1517} y {area:345}.",
		["{npc:4618} and {npc:2817} camp together in the {area:1877}, in the middle of the {zone:1418}."] = "{npc:4618} y {npc:2817} acampan juntos en {area:1877}, en el centro de {zone:1418}.",
		["{quest:739} himself (42) walks among the Bonesnappers: leave him for the later {zone:1418} guide at 43, and kill the Bonesnappers for this quest now."] = "El propio {quest:739} (42) anda entre los rompehuesos: déjalo para la guía posterior de {zone:1418}, a nivel 43, y mata ahora a los rompehuesos para esta misión.",
} end)()
t.guides["forever/alliance/30-40/06b-desolace"] = (function() return {
		["A long trip out to Kalimdor"] = "Un largo viaje hasta Kalimdor",
		["A {npc:217590} crawls about the {area:596}: catch one with the tool from {npc:217412}'s {item:213565}."] = "Un {npc:217590} anda por {area:596}: atrapa uno con la herramienta de {item:213565} de {npc:217412}.",
		["Back at the coven on the way west: the Mana Eaters (37-38) on its north edge and the Mage Hunters (38-39) further in drop the brains. {npc:5760} (40, elite) walks among the Mage Hunters: pull them out to you."] = "De vuelta en el aquelarre camino al oeste: los devoradores de maná (37-38) de su borde norte y los cazadores de magos (38-39) más adentro sueltan los cerebros. {npc:5760} (40, élite) anda entre los cazadores de magos: atráelos hacia ti.",
		["Fly to Theramore"] = "Vuela a Isla Theramore",
		["Fly to {area:150}"] = "Vuela a {area:150}",
		["Follow the road north to {area:608}: {npc:5396} stands at its south end, {npc:5638} in the middle, {npc:1182} to the north."] = "Sigue el camino al norte hasta {area:608}: {npc:5396} está en su extremo sur, {npc:5638} en el centro, {npc:1182} al norte.",
		["Follow the road south to {area:2407}."] = "Sigue el camino al sur hasta {area:2407}.",
		["Follow the road west across the north of {zone:1443} to the ruins of {area:2405}. {npc:11863}'s tower stands on the hill there, on the way to the wreck."] = "Sigue el camino al oeste por el norte de {zone:1443} hasta las ruinas de {area:2405}. La torre de {npc:11863} está en la colina de ahí, de camino al naufragio.",
		["Kodo bones, demons and lost treasure in south {zone:1443}."] = "Huesos de kodo, demonios y tesoros perdidos en el sur de {zone:1443}.",
		["Maraudine centaurs"] = "Centauros Maraudine",
		["Off the boat, walk up the pier to Baldruc, the flight master by the gate of {area:514}."] = "Al bajar del barco, sube por el muelle hasta Baldruc, el maestro de vuelo junto a la puerta de {area:514}.",
		["Rackmore's chest lies just south-east of the {object:177673}."] = "El cofre de Rackmore está justo al sureste de {object:177673}.",
		["Short: about one level of quests"] = "Corta: alrededor de un nivel de misiones",
		["Stays on the main route"] = "Se mantiene en la ruta principal",
		["The Maraudine centaurs hold the {area:607} west of the graveyard; every kind drops the totems."] = "Los centauros Maraudine ocupan {area:607}, al oeste del cementerio; todos sueltan los tótems.",
		["The demons gather at the {area:602} in southern {zone:1443}. Nether Maidens (37-38) hold its north-west side and drop the wings; Doomwarder Captains (38) stand at the south end and drop the blood.\nCareful: Nether Sorceresses (39-40) stand beside the Doomwarder Captains, and {npc:5760}, a level 40 elite, walks the coven's middle: pull the captains away from them. Most of the mobs here walk patrol routes, so you can easily pull extra mobs."] = "Los demonios se reúnen en {area:602}, en el sur de {zone:1443}. Las doncellas abisales (37-38) ocupan su lado noroeste y sueltan las alas; los capitanes Guardiavil (38) están en el extremo sur y sueltan la sangre.\nCuidado: Las hechiceras abisales (39-40) están junto a los capitanes Guardiavil, y {npc:5760}, un élite de nivel 40, recorre el centro del aquelarre: aleja a los capitanes de ellos. La mayoría de los enemigos patrullan, así que es fácil atraer de más.",
		["The ghost magnets"] = "Los imanes fantasmales",
		["The next guide starts in Theramore."] = "La siguiente guía empieza en Isla Theramore.",
		["The wrecked ship's chest lies just south-west of {npc:11863}'s tower."] = "El cofre del barco naufragado está justo al suroeste de la torre de {npc:11863}.",
		["The {area:2657}"] = "{area:2657}",
		["Then on to {zone:1434}"] = "Luego, a {zone:1434}",
		["Theramore flight master"] = "Maestro de vuelo de Theramore",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:6134}'s magnets draw the Magrami Spectres a few yards from the Magram Necrokhans and Corpsefeeders (45, elite) in the {area:2657}. Skip it if you are alone."] = "Son enemigos élite: se recomienda agruparse, busca gente para hacerla. Los imanes de {quest:6134} atraen a los espectros Magrami a pocos metros de los necrokhans y los devoracadáveres Magram (45, élite) en {area:2657}. Omítela si vas solo.",
		["Undead Ravagers roam the bone fields south of the Magram village, east of the Coven: the arrow leads to their western edge. Careful: Magram Necrokhans and Corpsefeeders (45, elite) walk the bone fields further east, with Magram Necromancers (42): pull the Ravagers to you, away from them."] = "Los devastadores no-muertos recorren los campos de huesos al sur de la aldea Magram, al este del Aquelarre: la flecha lleva a su borde oeste. Cuidado: los necrokhans Magram y los devoracadáveres (45, élite) recorren los campos de huesos más al este, con nigromantes Magram (42): atrae a los devastadores hacia ti, lejos de ellos.",
		["Underwater"] = "Bajo el agua",
		["Use the {item:15848} at its arrow, on the fields' eastern side, to draw the Magrami Spectres; the Necrokhans and Corpsefeeders (45, elite) walk close by: keep the group together."] = "Usa {item:15848} en su flecha, en el lado este de los campos, para atraer a los espectros Magrami; los necrokhans y los devoracadáveres (45, élite) andan cerca: mantén el grupo unido.",
		["escort {npc:12277} back toward the graveyard"] = "escolta a {npc:12277} de vuelta hacia el cementerio",
		["for {npc:3980} in {area:271}: keep it"] = "para {npc:3980} en {area:271}: guárdala",
		["for {npc:5637} in {zone:1455}: keep it"] = "para {npc:5637} en {zone:1455}: guárdala",
		["{area:144} flight master"] = "Maestro de vuelo de {area:144}",
		["{area:598}: kill these as you meet them"] = "{area:598}: mata a estos según te los encuentres",
		["{item:15766}, on the {object:177673}"] = "{item:15766}, en {object:177673}",
		["{item:15881}, from the Slitherblade naga"] = "{item:15881}, de los naga Filozante",
		["{item:6251}, from the Nether Maidens"] = "{item:6251}, de las doncellas abisales",
		["{item:6252}, from the Doomwarder Captains"] = "{item:6252}, de los capitanes Guardiavil",
		["{npc:11863}: {quest:93464}, from Magtoor in the {zone:1435}"] = "{npc:11863}: {quest:93464}, de Magtoor en {zone:1435}",
		["{npc:12277} is held in the centaur camp west of the graveyard. Free her and keep her alive on the walk out; she stops by the graveyard.\nCareful: The scripted groups are linked and only appear during the escort, so you cannot clear them in advance or pull them one at a time. Clearing the normal centaurs on the path before you start does help."] = "{npc:12277} está cautiva en el campamento centauro al oeste del cementerio. Libérala y mantenla con vida en la salida; se detiene junto al cementerio.\nCuidado: Los grupos programados están vinculados y solo aparecen durante la escolta, así que no puedes despejarlos antes ni atraerlos de a uno. Sí ayuda despejar antes los centauros normales del camino.",
		["{object:177787} lies beside {object:35251}, if you didn't take it on your first {zone:1443} visit. His silver key drops from the Drysnap crabs around the wreck; the golden one comes from the Slitherblade naga on the north-west coast, next."] = "{object:177787} está junto a {object:35251}, si no lo tomaste en tu primera visita a {zone:1443}. Su llave de plata la sueltan los cangrejos Secachasquido alrededor del naufragio; la dorada viene de los nagas Filozante de la costa noroeste, lo siguiente.",
} end)()
t.guides["forever/alliance/40-50/01-stranglethorn-vale"] = (function() return {
		["\"Sea Wolf\" MacKinley, on the top floor"] = "MacKinley «Lobo de Mar», en el piso superior",
		["\"Stinky\" Ignatz"] = "\"Apestoso\" Ignatz",
		["An {npc:217588} crawls in the jungle south-east of Nesingwary's camp, on the way to the {area:99}: catch one with the tool from {npc:217412}'s {item:213565}."] = "Una {npc:217588} anda por la jungla al sureste del campamento de Nesingwary, de camino a {area:99}: atrapa una con la herramienta de {item:213565} de {npc:217412}.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. Skyborne learn it from {npc:265756}, the stablemaster and riding trainer at the {area:17684} in {area:16638} on Zephras Isle, who also sells the Galestriders: the skyboat to the isle leaves the north side of {area:279} about every five minutes. Collectibles, Mounts · Level 40 lists the Galestriders."] = "A nivel 40 y con 100 de oro puedes aprender a montar, y aprenderlo te da una montura. Los Celestes lo aprenden con {npc:265756}, el maestro de establos e instructor de equitación de {area:17684} en {area:16638}, en la isla Zephras, que también vende los zancavientos: el barco celeste a la isla sale del lado norte de {area:279} más o menos cada cinco minutos. Coleccionables, Monturas · Nivel 40 muestra los zancavientos.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4732} teaches Humans at {area:88} in eastern {zone:1429}, beside {npc:384}'s horses. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "A nivel 40 y con 100 de oro puedes aprender a montar, y al aprenderlo recibes una montura. {npc:4732} enseña a los humanos en {area:88}, en el este de {zone:1429}, junto a los caballos de {npc:384}. Forever podría dejar que cualquier raza aprenda con cualquier instructor de equitación (sin confirmar). Coleccionables, Monturas · Nivel 40 muestra todos los colores.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4753} teaches Night Elves in {zone:1457}, beside {npc:4730}'s sabers: the boat from {area:17203} to {area:442}, then the flight to {area:702}. Forever may let any race learn from any riding trainer (unconfirmed), such as {npc:4732} at {area:88} in {zone:1429}. Collectibles, Mounts · Level 40 lists every colour."] = "A nivel 40 y con 100 de oro puedes aprender a montar, y al aprenderlo recibes una montura. {npc:4753} enseña a los elfos de la noche en {zone:1457}, junto a los sables de {npc:4730}: el barco de {area:17203} a {area:442} y luego el vuelo a {area:702}. Forever podría dejar que cualquier raza aprenda con cualquier instructor de equitación (sin confirmar), como {npc:4732} en {area:88}, en {zone:1429}. Coleccionables, Monturas · Nivel 40 muestra todos los colores.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4772} teaches Dwarves at {area:803}, east of {area:131} on the road to {zone:1432}, beside {npc:1261}'s rams. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "A nivel 40 y con 100 de oro puedes aprender a montar, y al aprenderlo recibes una montura. {npc:4772} enseña a los enanos en {area:803}, al este de {area:131}, en el camino a {zone:1432}, junto a los carneros de {npc:1261}. Forever podría dejar que cualquier raza aprenda con cualquier instructor de equitación (sin confirmar). Coleccionables, Monturas · Nivel 40 muestra todos los colores.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:7954} teaches Gnomes at {area:189}, just east of {area:131}, beside {npc:7955}'s mechanostriders. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "A nivel 40 y con 100 de oro puedes aprender a montar, y al aprenderlo recibes una montura. {npc:7954} enseña a los gnomos en {area:189}, justo al este de {area:131}, junto a los mecazancudos de {npc:7955}. Forever podría dejar que cualquier raza aprenda con cualquier instructor de equitación (sin confirmar). Coleccionables, Monturas · Nivel 40 muestra todos los colores.",
		["Bloodsail camp"] = "Campamento Velasangre",
		["Bloodsail pirates: kill these as you meet them"] = "Piratas Velasangre: mata a estos según te los encuentres",
		["Boat to {area:150}"] = "Barco a {area:150}",
		["Boat to {area:17203}"] = "Barco al {area:17203}",
		["Boat to {area:35}"] = "Barco a {area:35}",
		["Corrosive Swamp Oozes"] = "Mocos corrosivos del pantano",
		["Defeat the challengers and {npc:6238}"] = "Derrota a los retadores y a {npc:6238}",
		["East from the stalkers' slopes to the ruins of Zul'Mamwe: the Skullsplitter Mystics (39-40) in its northern half carry {npc:739}'s fetishes. Careful: the Witch Doctors, Berserkers and Headhunters (41-44) hold the ruins' southern half: stay north. Then north-west toward the coast: the Shadowmaw Panthers (37-38) prowl the jungle west of the ruins, often stealthed."] = "Al este de las laderas de los acechadores, hasta las ruinas de Zul'Mamwe: los místicos Machacacráneos (39-40) de su mitad norte llevan los fetiches de {npc:739}. Cuidado: los médicos brujos, rabiosos y cazacabezas (41-44) ocupan la mitad sur de las ruinas: quédate al norte. Luego ve al noroeste hacia la costa: las panteras Faucesombría (37-38) merodean por la selva al oeste de las ruinas, a menudo en sigilo.",
		["East from the {area:99} to {area:101}: {npc:218230} is caged at its western edge. The Kurzen Subchiefs (35-36) and Elites (36-37) carry his cage key; the fighter's uniform lies in a supply crate in the compound's eastern part.\nCareful: {npc:813}, an elite of 39-40, stands at the compound's north end beside three of the Subchiefs: take the key from the Subchiefs and Elites further south and leave him be."] = "Al este de {area:99} hasta {area:101}: {npc:218230} está enjaulado en su borde oeste. Los subjefes de Kurzen (35-36) y los élites (36-37) llevan la llave de su jaula; el uniforme de luchador está en una caja de suministros en la parte este de la base.\nCuidado: {npc:813}, un élite de nivel 39-40, está en el extremo norte de la base junto a tres de los subjefes: consigue la llave de los subjefes y élites más al sur y déjalo en paz.",
		["Fly to Theramore"] = "Vuela a Isla Theramore",
		["Fly to {area:35}"] = "Vuela a {area:35}",
		["Fly to {area:392}"] = "Vuela a {area:392}",
		["Fly to {area:42}"] = "Vuela a {area:42}",
		["Fly to {area:442}"] = "Vuela a {area:442}",
		["Fly to {area:702}"] = "Vuela a {area:702}",
		["Fly to {zone:1453}"] = "Vuela a {zone:1453}",
		["Follow the road east back to Theramore. The officers are in {area:514}."] = "Sigue el camino al este de vuelta a Theramore. Los oficiales están en {area:514}.",
		["Follow the road south to {area:35}."] = "Sigue el camino al sur hasta {area:35}.",
		["For {npc:218229} in {area:35}, at the end of the jungle loop"] = "Para {npc:218229} en {area:35}, al final del circuito por la selva",
		["Go on north-west to the bay on the north-west coast. The Giant Clams lie on its floor and hold the pearls; {npc:2624} swims among them and drops the {item:4034}."] = "Sigue al noroeste hasta la bahía de la costa noroeste. Las almejas gigantes están en su fondo y guardan las perlas; {npc:2624} nada entre ellas y suelta {item:4034}.",
		["Gorilla hills"] = "Colinas de los gorilas",
		["Head east; the Tangled Horrors along the way also drop the essays. Search the edge of the {area:74}, where the temple's ruins break the water."] = "Ve al este; los horrores enredados del camino también sueltan los ensayos. Busca en el borde de {area:74}, donde las ruinas del templo asoman del agua.",
		["Head north-east past Nesingwary's camp and follow the road north to the camp at the top of the vale."] = "Ve al noreste pasando el campamento de Nesingwary y sigue el camino al norte hasta el campamento de lo alto de la vega.",
		["Head south to the giant's hut in the middle of the marsh."] = "Ve al sur hasta la choza del gigante en medio del pantano.",
		["Jungle Stalkers"] = "Acechadores de la selva",
		["Leave town by the tunnel and follow the coast north; the letter lies in the Bloodsail camp on the beach, where \"Pretty Boy\" Duncan walks.\nCareful: the Bloodsail Mages and Warlocks here are level 40-43 and cast from range: pull one at a time and fight with your back to the open beach."] = "Sal del pueblo por el túnel y sigue la costa al norte; la carta está en el campamento Velasangre de la playa, donde camina \"El Guapo\" Duncan.\nCuidado: los magos y brujos Velasangre de aquí son de nivel 40-43 y lanzan hechizos a distancia: atráelos de uno en uno y pelea de espaldas a la playa abierta.",
		["Level 40 with 100 gold later on? {npc:4732} teaches riding at {area:88} in {zone:1429}: Collectibles, Mounts · Level 40 has the trip."] = "¿Nivel 40 y 100 de oro más adelante? {npc:4732} enseña equitación en {area:88}, en {zone:1429}: Coleccionables, Monturas · Nivel 40 tiene el viaje.",
		["Mirefin murlocs"] = "Múrlocs Ancalodo",
		["North-east from the bay toward Nesingwary's camp: {npc:729}, the great tiger (37), lairs on the hilltop just south-west of the camp."] = "Al noreste de la bahía, hacia el campamento de Nesingwary: {npc:729}, el gran tigre (37), tiene su guarida en la cima de la colina justo al suroeste del campamento.",
		["On the top floor"] = "En el piso superior",
		["On the way back east, the Corrosive Swamp Oozes (38-40) creep through the marsh south of the road, between the middle of the marsh and Theramore: one of them carries Jameson's training sword. Careful: Elder Daggermaws (48-49) lurk in the water among them, and the larger Bubbling Swamp Oozes (39-40) are elite: leave both alone."] = "De vuelta al este, los mocos corrosivos del pantano (38-40) se arrastran por el pantano al sur del camino, entre el centro del pantano e Isla Theramore: uno lleva la espada de entrenamiento de Jameson. Cuidado: los bocadagas ancianos (48-49) acechan en el agua entre ellos, y los mocos de pantano burbujeantes, más grandes (39-40), son élite: evita a ambos.",
		["Paladin: {quest:1661}"] = "Paladín: {quest:1661}",
		["Riding and Galestriders: {npc:265756}, at the {area:17684} in {area:16638} on Zephras Isle."] = "Montar y Galestriders: {npc:265756}, en {area:17684}, en {area:16638}, en la Isla Zephras.",
		["Riding at 40"] = "Equitación a nivel 40",
		["Seahorn's next errand goes back to Arathi: skip it."] = "El siguiente encargo de Seahorn vuelve a Arathi: omítelo.",
		["Skyboat to Zephras Isle: the north side of {area:279}, about every five minutes."] = "Barco celeste a la isla Zephras: el lado norte de {area:279}, más o menos cada cinco minutos.",
		["Stinky waits west of the manor, in the marsh below {area:504}. Lead him to his Bogbean leaves and keep the swamp creatures off him."] = "Apestoso espera al oeste de la mansión, en el pantano bajo {area:504}. Llévalo hasta sus hojas de frijol de pantano y mantén a las criaturas del pantano lejos de él.",
		["Stormwind City"] = "Ciudad de Ventormenta",
		["Take the road north to the ruined manor; Jarl lives in the shack beside it and the loose dirt is at the corner of the house. Jarl wants three {quest:1218}: if you passed {npc:4897}, buy them from her in Theramore first."] = "Toma el camino al norte hasta la mansión en ruinas; Jarl vive en la choza de al lado y la tierra suelta está en la esquina de la casa. Jarl quiere tres {quest:1218}: si pasaste por {npc:4897}, cómpraselas primero en Theramore.",
		["The Darkmist spiders nest around the cavern in the north-west of the marsh; every spider drops eyes.\nCareful: Darkmist Lurkers move about stealthed and use poison once in combat. The spiders stand close together, so adds are common; pulling single targets from the outer edge cuts down on them."] = "Las arañas Niebla Negra anidan alrededor de la cueva del noroeste del pantano; todas las arañas sueltan ojos.\nCuidado: Los acechadores Niebla Negra se mueven en sigilo y usan veneno en combate. Las arañas están muy juntas, así que es común atraer de más; atraer objetivos sueltos desde el borde exterior lo reduce.",
		["The Jungle Stalkers roam the slopes west of the mine."] = "Los acechadores de la selva recorren las laderas al oeste de la mina.",
		["The Mirefin murlocs crowd the north coast past {area:497}."] = "Los múrlocs Ancalodo llenan la costa norte pasada {area:497}.",
		["The Silt Crawlers (40-41) crowd the north end of the eastern shore, and the driftwood washes up along it from there.\nCareful: the big Monstrous Crawlers (43-44) further south on the shore are over you: take the legs at the north end and pick up the driftwood without pulling them."] = "Los reptadores de cieno (40-41) llenan el extremo norte de la orilla este, y la madera a la deriva llega a la orilla desde ahí.\nCuidado: los grandes reptadores monstruosos (43-44), más al sur en la orilla, te superan: consigue las patas en el extremo norte y recoge la madera sin atraerlos.",
		["The Skullsplitter trolls hold the ruins just east of the mine; any of them can drop tusks, their panthers always do.\nFollow the road north-east to the Venture Co. camp at the {area:310}; the miners, surveyors and foremen drop the crystals.\nCareful: Stealthed Shadowmaw Panthers and Stranglethorn Tigresses roam the area around the camp."] = "Los trols Machacacráneos ocupan las ruinas justo al este de la mina; cualquiera puede soltar colmillos, y sus panteras siempre los sueltan.\nSigue el camino al noreste hasta el campamento de Ventura y Cía. en {area:310}; los mineros, agrimensores y capataces sueltan los cristales.\nCuidado: Las panteras Faucesombría y las tigresas de Tuercespina recorren en sigilo la zona alrededor del campamento.",
		["The burned inn stands on the road west, toward the {zone:1413}; the guard's badge lies in the ashes."] = "La posada quemada está en el camino al oeste, hacia {zone:1413}; la insignia del guardia está entre las cenizas.",
		["The deserters camp south of the road, west of {npc:4503}'s hut."] = "Los desertores acampan al sur del camino, al oeste de la choza de {npc:4503}.",
		["The north-west coast"] = "La costa noroeste",
		["The scroll lies in the marsh north of Biggs. The Swampwalkers north of it can drop Khadgar's essays."] = "El pergamino está en el pantano al norte de Biggs. Los caminalodos al norte de él pueden soltar los ensayos de Khadgar.",
		["The sunken temple"] = "El templo sumergido",
		["Theramore"] = "Theramore",
		["Theramore flight master"] = "Maestro de vuelo de Theramore",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:728} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Son enemigos élite: se recomienda agruparse, busca gente para hacerlo. {npc:728} es élite de nivel 40: la mayoría de las clases lo hacen solas a nivel 42, pero puede que necesites ayuda. Omítelo si estás solo: la ruta te hace recuperar esa experiencia matando enemigos.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:730} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Son enemigos élite: se recomienda agruparse, busca gente para hacerlo. {npc:730} es élite de nivel 43: la mayoría de las clases lo hacen solas a nivel 45, pero puede que necesites ayuda. Omítelo si estás solo: la ruta te hace recuperar esa experiencia matando enemigos.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:731} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nCareful: Tigers and stealthed shadowmaw panthers roam close to him. Clear them before you pull him. When he is pulled, {npc:731} calls for help from creatures within 20 yd."] = "Son enemigos élite: se recomienda agruparse, busca gente para hacerlo. {npc:731} es élite de nivel 43: la mayoría de las clases lo hacen solas a nivel 45, pero puede que necesites ayuda. Omítelo si estás solo: la ruta te hace recuperar esa experiencia matando enemigos.\nCuidado: Tigres y panteras Fauceumbría en sigilo rondan cerca de él. Despéjalos antes de atraerlo. Cuando lo atraes, {npc:731} pide ayuda a las criaturas en 20 m.",
		["Tram to {zone:1455}"] = "Tranvía a {zone:1455}",
		["Upstairs"] = "Arriba",
		["Warlock: {quest:4488}"] = "Brujo: {quest:4488}",
		["Zul'Mamwe's Mystics and the Shadowmaw Panthers"] = "Los místicos de Zul'Mamwe y las panteras Faucesombría",
		["for {npc:5635} at {area:348}: keep it"] = "para {npc:5635} en {area:348}: guárdalo",
		["for {npc:770} at the {area:99}, on the northern loop"] = "para {npc:770} en {area:99}, en el circuito norte",
		["only if you carry a {item:3853} (a blacksmith's craft)"] = "solo si llevas una {item:3853} (una creación de herrero)",
		["with the spices from Theramore"] = "con las especias de Theramore",
		["{area:103}: kill these as you meet them"] = "{area:103}: mata a estos según te los encuentres",
		["{area:1438} flight master"] = "Maestro de vuelo de {area:1438}",
		["{area:150} flight master"] = "Maestro de vuelo de {area:150}",
		["{area:35} flight master"] = "Maestro de vuelo de {area:35}",
		["{area:392} flight master"] = "Maestro de vuelo de {area:392}",
		["{area:42} flight master"] = "Maestro de vuelo de {area:42}",
		["{area:442} flight master"] = "Maestro de vuelo de {area:442}",
		["{area:702} flight master"] = "Maestro de vuelo de {area:702}",
		["{item:216616}, from the Subchiefs (or the Elites)"] = "{item:216616}, de los subjefes (o de los élites)",
		["{item:2466}, from the Skullsplitter Mystics"] = "{item:2466}, de los místicos Machacacráneos",
		["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}, para \"Ojolodo\" Jarl",
		["{item:4611}; underwater"] = "{item:4611}; bajo el agua",
		["{item:5938}, from the Silt Crawlers"] = "{item:5938}, de los reptadores de cieno",
		["{npc:1141} cooks in the {object:2169}; {npc:5384} is in the {object:28027}."] = "{npc:1141} cocina en {object:2169}; {npc:5384} está en {object:28027}.",
		["{npc:1261}: other colours, 20g"] = "{npc:1261}: otros colores, 20g",
		["{npc:1440}, the Royal Library in {object:2117}"] = "{npc:1440}, en la Biblioteca Real de {object:2117}",
		["{npc:218230}, back at his cage on the way out"] = "{npc:218230}, de vuelta en su jaula al salir",
		["{npc:218230}, in his cage, if you didn't take it on the 30-40 loop"] = "{npc:218230}, en su jaula, si no la aceptaste en el circuito 30-40",
		["{npc:2486}'s Stranglethorn Fever ({npc:1514}) waits for the level-48 {area:35} stop: leave it for now."] = "La Fiebre de Tuercespina de {npc:2486} ({npc:1514}) espera a la parada de nivel 48 en {area:35}: déjala por ahora.",
		["{npc:2487}, top floor: {quest:669}, if you did {area:327} with a group"] = "{npc:2487}, último piso: {quest:669}, si hiciste {area:327} en grupo",
		["{npc:2488}, on the top floor"] = "{npc:2488}, en el piso superior",
		["{npc:2542}, upstairs"] = "{npc:2542}, arriba",
		["{npc:2624} swims off the north-west coast, on the northern loop"] = "{npc:2624} nada frente a la costa noroeste, en el circuito norte",
		["{npc:271167}: {quest:98233}, from the oozes on the way back east"] = "{npc:271167}: {quest:98233}, de los mocos de camino de vuelta al este",
		["{npc:384}: other colours, 20g"] = "{npc:384}: otros colores, 20g",
		["{npc:461}, in the {object:2164}: {npc:6251} in {area:392} takes it at the end of the next guide"] = "{npc:461}, en {object:2164}: {npc:6251} en {area:392} la recibe al final de la siguiente guía",
		["{npc:4730}: other colours, 20g"] = "{npc:4730}: otros colores, 20g",
		["{npc:4794}, inside"] = "{npc:4794}, adentro",
		["{npc:4794}: the crawlers are on the {zone:1435} shore, keep it"] = "{npc:4794}: los reptadores están en la orilla de {zone:1435}, guárdala",
		["{npc:4944}, on the top floor"] = "{npc:4944}, en el piso de arriba",
		["{npc:4948}, on the top floor"] = "{npc:4948}, en el piso de arriba",
		["{npc:4964}, on the top floor of {area:514}"] = "{npc:4964}, en el piso de arriba de {area:514}",
		["{npc:4966} holds the tower with a few deserters. He turns on you: beat him until he yields.\nCareful: Hendel has two guards who join the fight when he turns hostile. The guards flee once he surrenders.\n{npc:4967} and {npc:4968} wait beside the tower: once he yields, hand in to both on the spot."] = "{npc:4966} ocupa la torre con unos cuantos desertores. Se vuelve contra ti: golpéalo hasta que se rinda.\nCuidado: Hendel tiene dos guardias que se unen a la pelea cuando se vuelve hostil. Los guardias huyen en cuanto él se rinde.\n{npc:4967} y {npc:4968} esperan junto a la torre: cuando se rinda, entrega a ambos ahí mismo.",
		["{npc:4967}, at the tower"] = "{npc:4967}, en la torre",
		["{npc:5385}, upstairs"] = "{npc:5385}, arriba",
		["{npc:5464}, by the flight master"] = "{npc:5464}, junto al maestro de vuelo",
		["{npc:5476} stands by the road junction in the west of the swamp."] = "{npc:5476} está junto al cruce de caminos en el oeste del pantano.",
		["{npc:5637} is in the Reclaimers' hall by the {object:32356}, {npc:2786} in the {object:32383}."] = "{npc:5637} está en la sala de los Reclamadores, junto a {object:32356}, y {npc:2786} en {object:32383}.",
		["{npc:5694}: for {npc:5464} in {area:42}, on the way to the swamp"] = "{npc:5694}: para {npc:5464} en {area:42}, de camino al pantano",
		["{npc:6171}, in the Cathedral of Light"] = "{npc:6171}, en la Catedral de la Luz",
		["{npc:6236} offers The Windwatcher next (1791): the Whirlwind weapon chain, with an elite at the end, is in the Warrior class guide Whirlwind Weapon."] = "{npc:6236} ofrece después El Vigía del viento (1791): la cadena del arma de Torbellino, con un élite al final, está en la guía de clase de guerrero Arma Torbellino.",
		["{npc:718}, beside him"] = "{npc:718}, a su lado",
		["{npc:737}, upstairs"] = "{npc:737}, en el piso de arriba",
		["{npc:737}, upstairs: the Skullsplitter trolls, on the northern loop"] = "{npc:737}, arriba: los trols Machacacráneos, en el circuito del norte",
		["{npc:739}: the {area:301} report bundle for {npc:2277} in {area:271}, on the {zone:1418} & {zone:1425} guide: keep it"] = "{npc:739}: el paquete de informes de {area:301} para {npc:2277} en {area:271}, en la Guía de {zone:1418} y {zone:1425}: guárdalo",
		["{npc:773}, upstairs"] = "{npc:773}, en el piso de arriba",
		["{npc:773}: for {quest:2864} in {zone:1446}, keep it"] = "{npc:773}: para {quest:2864} en {zone:1446}, guárdalo",
		["{npc:7955}: other colours, 20g"] = "{npc:7955}: otros colores, 20g",
		["{quest:1218}: {npc:4897} in Theramore, if you left without them"] = "{quest:1218}: {npc:4897} en Isla Theramore, si te fuiste sin ellas",
		["{quest:1260} stands near the inn; {npc:4897}, a trade supplier a few steps south, sells the spices Jarl wants."] = "{quest:1260} está cerca de la posada; {npc:4897}, una proveedora de comercio a pocos pasos al sur, vende las especias que quiere Jarl.",
		["{quest:1260}, inside"] = "{quest:1260}, adentro",
		["{zone:1453} flight master"] = "Maestro de vuelo de {zone:1453}",
		["{zone:1453} has no shaman trainer"] = "{zone:1453} no tiene instructor de chamanes",
} end)()
t.guides["forever/alliance/40-50/01b-riverglades"] = (function() return {
		["About 90 quests in Forever's new zone, from {area:16724}: the level for its port and Western Front."] = "Unas 90 misiones en la nueva zona de Forever, desde {area:16724}: el nivel para su puerto y el Frente Occidental.",
		["Back east along the road to {area:16744}."] = "De vuelta al este por el camino hasta {area:16744}.",
		["Back east through the town to Elbrim's farm: the doll and the locket are in the burnt farmhouse beside it."] = "Vuelve al este por el pueblo hasta la granja de Elbrim: la muñeca y el relicario están en la granja quemada de al lado.",
		["Back north along the shore: hand in the murlocs and the hide on the docks on your way to the crawlers."] = "Regresa al norte por la costa: entrega lo de los múrlocs y la piel en los muelles de camino a los reptadores.",
		["Back past {area:16744} and south to the Holmsbys' farm by the river."] = "Regresa pasando {area:16744} y ve al sur hasta la granja de los Holmsby junto al río.",
		["Back south-west along the river: kill the Mudfin Warriors and Oracles on the banks for {npc:258317} (they drop {npc:256438}'s heads) and the {npc:258588} in the shallows for the shells. {npc:258935}, one of {npc:256438}'s lumberjacks, is stuck on the bank just north-west of the murlocs; {npc:259049}'s hat lies on the riverbank among them; the fresh manure is in the fields of {area:16735}, between the river and the farm. {npc:263380}, an elite (level 42), prowls the river: if he comes your way, back off and let him pass."] = "Regresa al suroeste por el río: mata a los guerreros y oráculos Fangoaleta de las orillas para {npc:258317} (sueltan las cabezas de {npc:256438}) y a los {npc:258588} en las aguas poco profundas para las conchas. {npc:258935}, uno de los leñadores de {npc:256438}, está atrapado en la orilla justo al noroeste de los múrlocs; el sombrero de {npc:259049} está en la orilla entre ellos; el estiércol fresco está en los campos de {area:16735}, entre el río y la granja. {npc:263380}, un élite (nivel 42), ronda el río: si viene hacia ti, retrocede y déjalo pasar.",
		["Back through the port"] = "De vuelta por el puerto",
		["Back to the port, from the north pier west through the docks."] = "De vuelta al puerto, desde el muelle norte hacia el oeste por los muelles.",
		["Back to the port."] = "De vuelta al puerto.",
		["Back to {area:16724}"] = "De vuelta a {area:16724}",
		["Coyote pelts"] = "Pieles de coyote",
		["Down to the port."] = "Baja al puerto.",
		["East along the cliffs to the far end of the pirates' camp: {npc:260390} waits by the water, {npc:260391} beside him."] = "Al este por los acantilados hasta el extremo del campamento pirata: {npc:260390} espera junto al agua, con {npc:260391} a su lado.",
		["East along the road towards {area:16724}: hand {npc:258317} his murlocs as you pass {area:16725}."] = "Al este por el camino hacia {area:16724}: entrégale sus múrlocs a {npc:258317} al pasar por {area:16725}.",
		["East down the road to {area:16727}, the goblins' harbour. {npc:255897} keeps a stall at the west end of the docks; {npc:263120}, {npc:255894} and {npc:259962} are at the inn, and {npc:259961} works the north pier. Zizplink's drink needs three things the port's traders sell: the chum from {npc:260487}, the degreaser and the old poison from {npc:260565} and {npc:260560}, by {npc:255897}'s stall."] = "Ve al este por el camino hasta {area:16727}, el puerto de los goblins. {npc:255897} tiene un puesto en el extremo oeste de los muelles; {npc:263120}, {npc:255894} y {npc:259962} están en la posada, y {npc:259961} trabaja en el muelle norte. La bebida de Zizplink necesita tres cosas que venden los comerciantes del puerto: la carnaza de {npc:260487}, el desengrasante y el veneno viejo de {npc:260565} y {npc:260560}, junto al puesto de {npc:255897}.",
		["Finish the {item:268632}"] = "Termina las {item:268632}",
		["Fly from {zone:1455} to {area:69} in Redridge, then follow the road north out of town and up through {area:2417}: it comes down into the western {zone:2548} by the {area:16737}."] = "Vuela de {zone:1455} a {area:69} en Crestagrana, luego sigue el camino al norte saliendo del pueblo y sube por {area:2417}: baja al oeste de {zone:2548} junto a {area:16737}.",
		["Fly to {area:144}"] = "Vuela a {area:144}",
		["Follow the road east to {area:16744}, the Alliance outpost above the river. The gnolls you passed on the way in are Captain Dalton's job: you go back for them after the lumber camp."] = "Sigue el camino al este hasta {area:16744}, el puesto de la Alianza sobre el río. Los gnolls que pasaste al entrar son trabajo del capitán Dalton: vuelves por ellos después del campamento maderero.",
		["Free him, then get him out: {npc:259057} fights his way out of {area:16726}, and you keep the ogres off him. If he falls, take the quest from him again."] = "Libéralo y sácalo de ahí: {npc:259057} se abre paso para salir de {area:16726}, y tú mantienes a los ogros lejos de él. Si cae, vuelve a aceptar la misión de él.",
		["From the inn: {npc:260070} on the way in, then {npc:257558} and {npc:257591} in the keep."] = "Desde la posada: {npc:260070} al entrar, luego {npc:257558} y {npc:257591} en el castillo.",
		["Holmsby farm"] = "Granja de los Holmsby",
		["Into the {zone:2548}"] = "Hacia {zone:2548}",
		["Leave {zone:1453}"] = "Sal de {zone:1453}",
		["Most beasts in the {zone:2548} drop {item:268632} for {npc:260231}: the shore crawlers on this coast and the boars on the ridge west of the pirates.\nCareful: {npc:257001} (elite, 42), Komuk (a Horde elite, 45) and {npc:263380} (elite, 42) range over the zone's wilds: take your beasts away from them."] = "La mayoría de las bestias de {zone:2548} sueltan {item:268632} para {npc:260231}: los reptadores de la costa y los jabalíes de la cresta al oeste de los piratas.\nCuidado: {npc:257001} (élite, 42), Komuk (un élite de la Horda, 45) y {npc:263380} (élite, 42) recorren las zonas salvajes: lleva a tus bestias lejos de ellos.",
		["No class trainer stands in the {zone:2548}, and the {zone:1418} & {zone:1425} guide passes none: {npc:257087} flies to {zone:1453}, where you train before you go on."] = "No hay instructor de clase en {zone:2548}, y la guía de {zone:1418} y {zone:1425} no pasa por ninguno: {npc:257087} vuela a {zone:1453}, donde entrenas antes de seguir.",
		["No class trainer stands in the {zone:2548}: train here in {zone:1453} before you fly on."] = "No hay instructor de clase en {zone:2548}: entrena aquí en {zone:1453} antes de seguir volando.",
		["No flight path to {area:144} yet: go to {zone:1455} (by the {area:2257} from {zone:1453}), ride out of its gates east through {zone:1426} and the tunnel into {zone:1432}, and on along the road to {area:144}."] = "Aún no tienes ruta de vuelo a {area:144}: ve a {zone:1455} (por el {area:2257} desde {zone:1453}), sal por sus puertas al este a través de {zone:1426} y el túnel hasta {zone:1432}, y sigue por el camino hasta {area:144}.",
		["No shaman trainer stands in the {zone:2548} or in {zone:1453}, and the {zone:1418} & {zone:1425} guide passes none: fly to {area:1537} and train there; {area:144} is a short flight on."] = "No hay instructor de chamanes en {zone:2548} ni en {zone:1453}, y la guía de {zone:1418} y {zone:1425} no pasa por ninguno: vuela a {area:1537} y entrena ahí; {area:144} está a un vuelo corto.",
		["North along the beach from the docks: the crawlers drop the meat for {npc:259962} and the spittle for Zizplink, and their entrails count for {npc:260231}. {npc:260235}, a big crab, scuttles along the rocks east of the docks. {npc:259758}, a rare elite of level 49, roams this coast from the docks up to the pirates' camp: if you see him, keep well away."] = "Ve al norte por la playa desde los muelles: los reptadores sueltan la carne para {npc:259962} y la saliva para Zizplink, y sus entrañas cuentan para {npc:260231}. {npc:260235}, un cangrejo grande, corretea por las rocas al este de los muelles. {npc:259758}, un élite raro de nivel 49, recorre esta costa desde los muelles hasta el campamento pirata: si lo ves, mantente bien lejos.",
		["North along the coast from the port: the Eastsea raiders and bombardiers have dug in on the slopes west of the buccaneers' camp, among their powder kegs. They stand close together: pull them one at a time. {npc:259758}, a rare elite of level 49, roams these cliffs and the beach below: if you see him, keep well away."] = "Al norte por la costa desde el puerto: los asaltantes y bombarderos de Marleste se atrincheraron en las laderas al oeste del campamento de los bucaneros, entre sus barriles de pólvora. Están muy juntos: atráelos de uno en uno. {npc:259758}, un élite raro de nivel 49, recorre estos acantilados y la playa de abajo: si lo ves, mantente bien lejos.",
		["North of the camps the cult works ogre miners in a mine, driven by the Twilight Subjugators.\nCareful: Twilight Enforcers (elites, level 45) walk past the mine's mouth on their way through the camps. Wait for one to pass before you go in, and pull the miners and Subjugators back out to you."] = "Al norte de los campamentos, el culto obliga a ogros mineros a trabajar en una mina, vigilados por los subyugadores Crepusculares.\nCuidado: los ejecutores Crepusculares (élites, nivel 45) pasan frente a la entrada de la mina en su ruta por los campamentos. Espera a que pase uno antes de entrar y atrae a los mineros y subyugadores hacia afuera.",
		["North past {area:16729}: fill {npc:262031}'s phial in the marsh water north-east of the tower."] = "Al norte, más allá de {area:16729}: llena el frasco de {npc:262031} en el agua del pantano al noreste de la torre.",
		["North up the long valley towards {area:16685}: {npc:258023} holds a small camp below the Twilight cult's fortress."] = "Ve al norte por el largo valle hacia {area:16685}: {npc:258023} ocupa un pequeño campamento bajo la fortaleza del culto Crepuscular.",
		["North up the road to the lumber camp."] = "Al norte por el camino hasta el campamento maderero.",
		["North up the road to the lumber camp. {npc:256438} runs it; his third job, the saplings, comes once his plant food is in."] = "Al norte por el camino hasta el campamento maderero. {npc:256438} lo dirige; su tercer encargo, los retoños, llega cuando le entregues el alimento para plantas.",
		["North up the track towards {area:16729}: the foreman's crate lies by the road."] = "Ve al norte por el camino hacia {area:16729}: la caja del capataz está junto al camino.",
		["North-east across the fields to {area:16725}: {npc:258317} wants the Mudfin murlocs on the river thinned out, the same murlocs whose heads {npc:256438} needs, so one pass along the river does both."] = "Al noreste a través de los campos hasta {area:16725}: {npc:258317} quiere que reduzcas a los múrlocs Fangoaleta del río, los mismos cuyas cabezas necesita {npc:256438}, así que una pasada por el río sirve para ambas.",
		["North-east along the coast to the pirates' camp on the cliffs. The buccaneers and musketeers carry the smuggled goods. {npc:259758} walks the camp too: keep an eye out for him."] = "Ve al noreste por la costa hasta el campamento pirata en los acantilados. Los bucaneros y mosqueteros llevan la mercancía de contrabando. {npc:259758} también recorre el campamento: estate atento a él.",
		["North-east of Elbrim's farm, the Horde drills its trainees in the fields north of {area:16743}. Stay north of the fort: its guards are far above your level. The supply crates lie around the drill grounds. Three elites work this ground: {npc:263071} (42) walks among the trainees, {npc:263615} (42) lurks at the north end, and Komuk (45), a Horde elite, patrols the hills to the east; give each of them room.\nCareful: Rog'mar Grunts (55) guard the fort's north wall, around 59,39 to 61,41. Leave the crates and trainees by the wall and take the ones further north, around 57-61,34-37."] = "Al noreste de la granja de Elbrim, la Horda entrena a sus reclutas en los campos al norte de {area:16743}. Quédate al norte del fuerte: sus guardias tienen un nivel muy superior al tuyo. Las cajas de suministros están por los campos de entrenamiento. Tres élites rondan la zona: {npc:263071} (42) camina entre los reclutas, {npc:263615} (42) acecha en el extremo norte y Komuk (45), un élite de la Horda, patrulla las colinas del este; mantén distancia con cada uno.\nCuidado: los Brutos de Rog'mar (55) vigilan el muro norte del fuerte, por 59,39 a 61,41. Deja las cajas y reclutas junto al muro y ve por los que están más al norte, por 57-61,34-37.",
		["North-east to {npc:263367}'s workshop. {npc:263367}'s stress test is a fight with his G45-B4G beside the workshop: hand the quest in once it's beaten."] = "Ve al noreste hasta el taller de {npc:263367}. La prueba de resistencia de {npc:263367} es una pelea con su G45-B4G junto al taller: entrega la misión una vez que lo venzas.",
		["North-west to {area:16726}, the ogres' town. Its ogres side with the Horde and attack you on sight, and Clugfist on his hill in the middle is an elite (level 50): keep to the town's north-eastern edge, where {npc:259057} hides."] = "Al noroeste hasta {area:16726}, el pueblo de los ogros. Sus ogros están del lado de la Horda y te atacan en cuanto te ven, y Clugfist, en su colina del centro, es élite (nivel 50): mantente en el borde noreste del pueblo, donde se esconde {npc:259057}.",
		["On east along the road to {area:16724}. {npc:257087}, the gryphon master, stands at its western gate; {npc:260070} and {npc:260080} are on the way in, {npc:263613} tends the wounded by the barracks, {npc:257558} and {npc:257591} wait in the keep at the east end, and the inn is in the south of the walls."] = "Sigue al este por el camino hasta {area:16724}. {npc:257087}, la maestra de grifos, está en la puerta oeste; {npc:260070} y {npc:260080} están a la entrada, {npc:263613} atiende a los heridos junto al cuartel, {npc:257558} y {npc:257591} esperan en la fortaleza al extremo este, y la posada está en el sur del recinto.",
		["One of Benjy's horses ran north up the river, past the farm. Give it the feed, then lead it home."] = "Uno de los caballos de Benjy huyó al norte río arriba, más allá de la granja. Dale el forraje y llévalo a casa.",
		["Rotflesh Mushrooms"] = "Champiñones carnepútrida",
		["Saplings"] = "Retoños",
		["Search around the stables south of the farmhouse for the horses' tracks; the bundles of hay lie around the farm."] = "Busca las huellas de los caballos alrededor de los establos al sur de la granja; los fardos de heno están por toda la granja.",
		["Shaman trainer"] = "Instructor de chamanes",
		["South across the plains to {area:16724}: {npc:257591} and {npc:257558} stand together in the keep at the east end, {npc:257591} first, her news is what Brant's next orders wait on. With {area:16723} saved, {npc:263089} by the orchard and {npc:263613} by the barracks have work for you too."] = "Ve al sur por las llanuras hasta {area:16724}: {npc:257591} y {npc:257558} están juntos en el castillo, en el extremo este; primero {npc:257591}, pues las siguientes órdenes de Brant dependen de sus noticias. Con {area:16723} a salvo, {npc:263089} junto al huerto y {npc:263613} junto a los cuarteles también tienen trabajo para ti.",
		["South back to {area:16724}."] = "Regresa al sur a {area:16724}.",
		["South-east out of the hills towards the port: the shore crawlers on the beach north of the docks are the quickest entrails. {npc:259758} wanders down to this beach too."] = "Al sureste, sal de las colinas hacia el puerto: los reptadores de la costa en la playa al norte de los muelles son las entrañas más rápidas. {npc:259758} también baja a esta playa.",
		["South-east, round {area:16743}'s east side, to {npc:263367}'s workshop on the hill. Komuk and the {area:16726} ogres walk the road east of the fort: let them pass before you cross it."] = "Ve al sureste, rodeando el lado este de {area:16743}, hasta el taller de {npc:263367} en la colina. Komuk y los ogros de {area:16726} recorren el camino al este del fuerte: déjalos pasar antes de cruzarlo.",
		["South-west across the plains to {area:16724}: {npc:257558} in the keep at the east end."] = "Al suroeste por las llanuras hasta {area:16724}: {npc:257558} está en la fortaleza del extremo este.",
		["South-west along the shore from the port: the saltwater murlocs camp on the beaches. On the way, a painted hide is stretched beside the path: it starts {quest:95260} for {npc:260231} at the docks."] = "Ve al suroeste por la costa desde el puerto: los múrlocs de agua salada acampan en las playas. De camino, hay una piel pintada extendida junto al sendero: inicia {quest:95260} para {npc:260231} en los muelles.",
		["South-west past {area:16744}: {npc:262399}, a prospector, has camped by the Cinderscale dragonkin's hollow."] = "Al suroeste, pasando {area:16744}: {npc:262399}, una prospectora, acampó junto a la hondonada de los dragonantes Escamaceniza.",
		["The Cinderscale hollow"] = "La hondonada Escamaceniza",
		["The Eastsea pirates"] = "Los piratas de Mareste",
		["The Plains Coyotes roam west and south-west of the keep, towards {area:16725}."] = "Los coyotes de las llanuras merodean al oeste y suroeste del castillo, hacia {area:16725}.",
		["The Rog'mar Poachers hunt the plains north of the tower; the Wildplains lions roam among them. A picked carcass lies in the grass east of the tower: its skull starts {quest:95983}.\nCareful: {npc:263380}, an elite (level 42), hunts along the river west of the plains: keep an eye on the riverbank."] = "Los Cazadores furtivos Rog'mar cazan en las llanuras al norte de la torre; los leones de las llanuras salvajes merodean entre ellos. Un cadáver descarnado yace en la hierba al este de la torre: su cráneo inicia {quest:95983}.\nCuidado: {npc:263380}, un élite (nivel 42), caza a lo largo del río al oeste de las llanuras: vigila la orilla.",
		["The Roving Tallstriders graze the meadows south-west of the workshop; further south-west the marsh bubbles with gas: fill the vials at the vents."] = "Las zancaaltas errantes pastan en las praderas al suroeste del taller; más al suroeste, el pantano burbujea con gas: llena los viales en las fumarolas.",
		["The Stranglethorn guide leaves Dwarves and Gnomes at their riding trainer in {zone:1426}: ride back west into {zone:1455}, where the flight to {area:69} leaves from the gryphon master."] = "La guía de Tuercespina deja a enanos y gnomos con su instructor de equitación en {zone:1426}: cabalga de vuelta al oeste hasta {zone:1455}, donde sale el vuelo a {area:69} desde el maestro de grifos.",
		["The Twilight camps"] = "Los campamentos Crepusculares",
		["The Twilight cult"] = "El culto Crepuscular",
		["The cathedral"] = "La catedral",
		["The coyote den"] = "La guarida de coyotes",
		["The coyotes den in the hills south of the farm: {npc:258522}, the big dark one, sits at the back of it; the Plains Coyotes around it drop the pelts."] = "Los coyotes tienen su guarida en las colinas al sur de la granja: {npc:258522}, el grande y oscuro, está al fondo; los Coyotes de las llanuras de alrededor sueltan las pieles.",
		["The crawlers and {npc:260235}"] = "Los reptadores y {npc:260235}",
		["The cult's camps fill the valley north and west of Riftan. Free the captive Farholde Scouts as you find them, and kill a {npc:258652} for {npc:257591}: her soulstone takes it. Twilight Enforcers (elites, level 45) patrol through the camps: watch where they walk before each pull. {npc:256881} and {npc:256891} (elites, 46) hold the fortress at the valley's head: pull the cultists away from them."] = "Los campamentos del culto llenan el valle al norte y al oeste de Riftan. Libera a los exploradores de Farholde cautivos según los encuentres y mata a un {npc:258652} para {npc:257591}: su piedra de alma lo captura. Los ejecutores Crepusculares (élites, nivel 45) patrullan los campamentos: observa por dónde caminan antes de atraer a cada enemigo. {npc:256881} y {npc:256891} (élites, 46) ocupan la fortaleza al fondo del valle: aleja a los cultistas de ellos.",
		["The cultists fill the streets and fields of {area:16723}. Start at the ritual circles in the middle (fill Claire's catalyst there), work west through the burnt houses to the edge of town, then back north-east to the loose soil west of Elbrim's farm: bury the {item:266148} the Twilight Raiders drop there. The charms, pages and finger bones drop from the cultists.\nKeep the {item:4338} they drop: {npc:263613} in {area:16724} asks for twenty when you are back there. Now and then a cultist drops the {quest:94885}: right-click it to start the quest.\nCareful: {npc:256899}, an elite ogre (level 41), walks the western streets of {area:16723}, around 44-47,47-52. Pull the cultists out towards you and let him pass; players died here more than anywhere else in the zone.\n{npc:263380}, the river's elite (level 42), can wander up from the south-western fields: let him pass."] = "Los cultistas llenan las calles y los campos de {area:16723}. Empieza en los círculos rituales del centro (llena ahí el catalizador de Claire), avanza al oeste por las casas quemadas hasta el borde del pueblo y luego vuelve al noreste a la tierra suelta al oeste de la granja de Elbrim: entierra ahí los {item:266148} que sueltan los Asaltantes Crepusculares. Los amuletos, las páginas y los huesos de dedo los sueltan los cultistas.\nGuarda el {item:4338} que sueltan: {npc:263613} en {area:16724} te pide veinte cuando regreses. De vez en cuando un cultista suelta {quest:94885}: haz clic derecho para iniciar la misión.\nCuidado: {npc:256899}, un ogro élite (nivel 41), recorre las calles del oeste de {area:16723}, alrededor de 44-47,47-52. Atrae a los cultistas hacia ti y déjalo pasar; aquí murieron más jugadores que en ningún otro lugar de la zona.\n{npc:263380}, el élite del río (nivel 42), puede subir desde los campos del suroeste: déjalo pasar.",
		["The lost horse"] = "El caballo perdido",
		["The meadows"] = "Los prados",
		["The murlocs, south-west"] = "Los múrlocs, al suroeste",
		["The next guide starts in the {zone:1418}, south of {zone:1432}: fly to {area:144}."] = "La siguiente guía empieza en {zone:1418}, al sur de {zone:1432}: vuela a {area:144}.",
		["The next guide starts in the {zone:1418}, south of {zone:1432}: fly to {area:144}. {zone:1453}'s gryphon master stands in the {object:2096}."] = "La siguiente guía empieza en {zone:1418}, al sur de {zone:1432}: vuela a {area:144}. El maestro de grifos de {zone:1453} está en el {object:2096}.",
		["The ogre mine"] = "La mina de los ogros",
		["The pirates' second wave"] = "La segunda oleada pirata",
		["The pirates' ships"] = "Los barcos piratas",
		["The plains"] = "Las llanuras",
		["The stables"] = "Los establos",
		["The tallstriders and the marsh"] = "Las zancaaltas y el pantano",
		["The western {zone:2548}"] = "El oeste de {zone:2548}",
		["The whelps nest all over the hollow; the warriors (level 41-42) guard its back, by the {item:271611}. Scaldaron, a rare elite drake, can be up here too: leave him be unless you have a group."] = "Las crías anidan por toda la hondonada; los guerreros (nivel 41-42) protegen el fondo, junto a la {item:271611}. Scaldaron, un draco élite raro, también puede estar aquí: déjalo en paz a menos que tengas grupo.",
		["The {area:16737}"] = "{area:16737}",
		["The {area:16743} training grounds"] = "Los campos de entrenamiento de {area:16743}",
		["The {npc:260244} prowls the shallows south-west of the port, below the murlocs' beaches. {npc:257001}, an elite, walks the shore close by: give him room."] = "{npc:260244} merodea las aguas poco profundas al suroeste del puerto, bajo las playas de los múrlocs. {npc:257001}, un élite, recorre la orilla cerca: mantén distancia.",
		["The {object:628948} poster by the inn"] = "El cartel de {object:628948} junto a la posada",
		["The {object:628948} poster by the inn: {npc:260235}"] = "El cartel de {object:628948} junto a la posada: {npc:260235}",
		["Train before the {zone:1418}"] = "Entrena antes de {zone:1418}",
		["Use {npc:256438}'s {item:266161} on bare ground around the camp: five saplings."] = "Usa el {item:266161} de {npc:256438} en suelo despejado alrededor del campamento: cinco retoños.",
		["West across the river to {area:16736}: the Peasant Woodpiles around the camp give the wood bundles.\nCareful: {npc:263380}, an elite (level 42), prowls the river by the camp: if he comes your way, back off and let him pass."] = "Ve al oeste, cruzando el río, hasta {area:16736}: las pilas de leña de campesino alrededor del campamento dan los fardos de madera.\nCuidado: {npc:263380}, un élite (nivel 42), merodea por el río junto al campamento: si viene hacia ti, retrocede y déjalo pasar.",
		["West from the northern ship, up the ridge: the Rotflesh Mushrooms grow among the rocks, close to the Twilight ogres' camp. The Mature Paletusks on the ridge give entrails too."] = "Al oeste del barco del norte, sube la cresta: los Champiñones carnepútrida crecen entre las rocas, cerca del campamento de los ogros Crepusculares. Los colmillos pálidos maduros de la cresta también dan entrañas.",
		["West into the {area:16737}: the Redridge gnolls camp on the slopes all the way from the hills west of the lumber camp to the pass you came in by. The stolen saw blades lie only in the western camps, near the pass.\nCareful: {npc:255906}, an elite gnoll (level 40), roams the south-western camps: pull the gnolls away from him."] = "Al oeste hacia {area:16737}: los gnolls de Crestagrana acampan en las laderas desde las colinas al oeste del campamento maderero hasta el paso por el que entraste. Las hojas de sierra robadas solo están en los campamentos del oeste, cerca del paso.\nCuidado: {npc:255906}, un gnoll élite (nivel 40), recorre los campamentos del suroeste: aleja a los gnolls de él.",
		["West of the port, the wildflowers grow in the meadows below {npc:263367}'s workshop."] = "Al oeste del puerto, las flores silvestres crecen en los prados bajo el taller de {npc:263367}.",
		["West through the keep: {npc:263089} by the orchard, then the cathedral and {npc:259859} south of the inn if you have their errands."] = "Al oeste por la fortaleza: {npc:263089} junto al huerto, luego la catedral y {npc:259859} al sur de la posada si tienes sus encargos.",
		["West to {area:16725}: {npc:258317} stands by the farmhouse."] = "Ve al oeste a {area:16725}: {npc:258317} está junto a la granja.",
		["Your class trainer"] = "Tu instructor de clase",
		["Your hearthstone is bound at {area:16724}'s inn: use it, or ride back south to the keep."] = "Tu piedra de hogar está vinculada a la posada de {area:16724}: úsala o cabalga de vuelta al sur hasta el castillo.",
		["fill the {item:269990} at the ritual circles"] = "llena el {item:269990} en los círculos rituales",
		["find {npc:257250} and talk to him"] = "encuentra a {npc:257250} y habla con él",
		["free five captive Farholde Scouts"] = "libera a cinco exploradores de Farholde cautivos",
		["go with {npc:258963} to save {npc:258935}"] = "acompaña a {npc:258963} para salvar a {npc:258935}",
		["grind on {npc:257901}"] = "mata a {npc:257901}",
		["help {npc:259057} break out of {area:16726}"] = "ayuda a {npc:259057} a escapar de {area:16726}",
		["kill a {npc:258652}"] = "mata a un {npc:258652}",
		["lead {npc:259158} out of {area:16723} to his treasure, west of the town"] = "lleva a {npc:259158} fuera de {area:16723} hasta su tesoro, al oeste del pueblo",
		["the middle ship"] = "el barco del medio",
		["the northern ship"] = "el barco del norte",
		["the stress test: beat G45-B4G beside the workshop"] = "la prueba de resistencia: vence a G45-B4G junto al taller",
		["the {object:645166} poster"] = "el cartel {object:645166}",
		["walk it back to {area:16725}"] = "llévalo de vuelta a {area:16725}",
		["{area:16724}, the west side"] = "{area:16724}, el lado oeste",
		["{area:16735} and the river"] = "{area:16735} y el río",
		["{item:17028}, from {npc:272437}"] = "{item:17028}, de {npc:272437}",
		["{item:268505}, the southern ship"] = "{item:268505}, el barco del sur",
		["{item:268632} as you go"] = "{item:268632} sobre la marcha",
		["{item:269997}, on the graves"] = "{item:269997}, en las tumbas",
		["{item:271653}, from {npc:260565}"] = "{item:271653}, de {npc:260565}",
		["{item:271654}, from {npc:260560}"] = "{item:271654}, de {npc:260560}",
		["{item:271657}, from {npc:260487}"] = "{item:271657}, de {npc:260487}",
		["{item:272126}, on the Wounded Soldiers beside him"] = "{item:272126}, en los Soldados heridos a su lado",
		["{npc:255906} is an elite gnoll (level 40) who roams the south-western camps of the {area:16737}: grouping up is advised."] = "{npc:255906} es un gnoll élite (nivel 40) que recorre los campamentos del suroeste de {area:16737}: se recomienda ir en grupo.",
		["{npc:256881} is an elite (level 46) in the fortress at the head of the valley, with the Enforcers around him: grouping up is advised."] = "{npc:256881} es un élite (nivel 46) en la fortaleza al fondo del valle, rodeado de ejecutores: se recomienda ir en grupo.",
		["{npc:256899}, the two-headed ogre, is an elite (level 41) at the western edge of {area:16723}: grouping up is advised. Claire then has the filled catalyst for {npc:257591} in {area:16724}."] = "{npc:256899}, el ogro de dos cabezas, es un élite (nivel 41) en el borde oeste de {area:16723}: se recomienda ir en grupo. Luego Claire tiene el catalizador lleno para {npc:257591} en {area:16724}.",
		["{npc:257001} is an elite (level 42) on the south shore: grouping up is advised."] = "{npc:257001} es un élite (nivel 42) en la costa sur: se recomienda ir en grupo.",
		["{npc:257087} flies to {zone:1453}. {npc:278088} waits in the {object:2098}."] = "{npc:257087} vuela a {zone:1453}. {npc:278088} espera en la {object:2098}.",
		["{npc:257087}, at the western gate"] = "{npc:257087}, en la puerta oeste",
		["{npc:257250} lies wounded among the camps at the valley's western edge.\nCareful: {npc:256881} and {npc:256891} (elites, 46) hold the fortress north of him: come at Ryan from the south."] = "{npc:257250} yace herido entre los campamentos del borde oeste del valle.\nCuidado: {npc:256881} y {npc:256891} (élites, 46) ocupan la fortaleza al norte de él: acércate a Ryan desde el sur.",
		["{npc:257558}, in the keep"] = "{npc:257558}, en la fortaleza",
		["{npc:257558}: Kilgar's head for {npc:1748} in {object:2117}"] = "{npc:257558}: la cabeza de Kilgar para el {npc:1748} en el {object:2117}",
		["{npc:257591}: {quest:94881}, for later in this guide"] = "{npc:257591}: {quest:94881}, para más adelante en esta guía",
		["{npc:257595}, at the inn"] = "{npc:257595}, en la posada",
		["{npc:258963} stands at the camp's south end. He sets off for {npc:258935}, south-east of the camp, as soon as you take {quest:94861}: go with him and keep the attackers off, and wait if {npc:263380} is in sight. If it fails, {npc:258963} offers the quest again."] = "{npc:258963} está en el extremo sur del campamento. Sale a buscar a {npc:258935}, al sureste del campamento, en cuanto aceptas {quest:94861}: acompáñalo y mantén alejados a los atacantes, y espera si {npc:263380} está a la vista. Si fallas, {npc:258963} vuelve a ofrecer la misión.",
		["{npc:259051} keeps the west end of {area:16744}."] = "{npc:259051} vigila el extremo oeste de {area:16744}.",
		["{npc:259158} wants out of {area:16723}: lead him west to his treasure at the edge of town and keep the cultists off him."] = "{npc:259158} quiere salir de {area:16723}: llévalo al oeste hasta su tesoro en el borde del pueblo y mantén a los cultistas lejos de él.",
		["{npc:259352} holds {area:16729}, the tower on the plains north-east of the crate."] = "{npc:259352} vigila {area:16729}, la torre en las llanuras al noreste de la caja.",
		["{npc:259352}'s tower stands just south-west of the marsh."] = "La torre de {npc:259352} está justo al suroeste del pantano.",
		["{npc:259352}'s tower."] = "La torre de {npc:259352}.",
		["{npc:259863}, by the inn: {quest:95330}, for {area:16736} later in this guide"] = "{npc:259863}, junto a la posada: {quest:95330}, para {area:16736} más adelante en esta guía",
		["{npc:262031} keeps the old cathedral at the south-west corner of {area:16724}. The bats roost in its upper floor; {npc:272437} sells the holy candles beside it; the graves are in the chapel graveyard.\n{npc:271742}, an elite of level 53, stands in the cathedral: he leaves you be, so never attack him, and pull the bats away from him."] = "{npc:262031} cuida la vieja catedral en la esquina suroeste de {area:16724}. Los murciélagos anidan en el piso superior; {npc:272437} vende las velas sagradas junto a ella; las tumbas están en el cementerio de la capilla.\n{npc:271742}, un élite de nivel 53, está en la catedral: no te ataca, así que nunca lo ataques y aleja a los murciélagos de él.",
		["{npc:262031}, in the cathedral at the keep's south-west corner."] = "{npc:262031}, en la catedral de la esquina suroeste del castillo.",
		["{npc:263071} is an elite (level 42) at the Horde's training grounds north of {area:16743}, where this guide goes later: grouping up is advised."] = "{npc:263071} es un élite (nivel 42) en el campo de entrenamiento de la Horda al norte de {area:16743}, adonde esta guía va más adelante: se recomienda ir en grupo.",
		["{npc:263071}, the elite, walks the training grounds."] = "{npc:263071}, el élite, recorre los campos de entrenamiento.",
		["{npc:263089} stands west of the inn, by the orchard: the apples hang on the trees around it."] = "{npc:263089} está al oeste de la posada, junto al huerto: las manzanas cuelgan de los árboles de alrededor.",
		["{npc:263315}, an elite lion (level 41), prowls the plains north of {area:16729}, on your way back north: grouping up is advised."] = "{npc:263315}, un león élite (nivel 41), merodea por las llanuras al norte de {area:16729}, de regreso al norte: se recomienda ir en grupo.",
		["{npc:263367}'s workshop"] = "El taller de {npc:263367}",
		["{npc:263380} is an elite (level 42) who hunts along the river between {area:16725} and {area:16729}, on your way north later in this guide: grouping up is advised. The poster hangs by the keep; {npc:259859}, who takes the fang, stands south of the inn."] = "{npc:263380} es un élite (nivel 42) que caza a lo largo del río entre {area:16725} y {area:16729}, en tu camino al norte más adelante en esta guía: se recomienda ir en grupo. El cartel cuelga junto a la fortaleza; {npc:259859}, que recibe el colmillo, está al sur de la posada.",
		["{npc:263380}, the elite, hunts along the river between {area:16725} and {area:16729}, on your way north."] = "{npc:263380}, el élite, caza a lo largo del río entre {area:16725} y {area:16729}, en tu camino al norte.",
		["{npc:263613} tends the wounded beside the barracks: bandage three of his soldiers, then he has a note for {npc:262031} in the cathedral."] = "{npc:263613} atiende a los heridos junto al cuartel: venda a tres de sus soldados y luego te dará una nota para {npc:262031} en la catedral.",
		["{npc:263613}: twenty {item:4338}, from {area:16723}'s cultists and the pirates; hand it in when you are back"] = "{npc:263613}: veinte {item:4338}, de los cultistas y piratas de {area:16723}; entrégala cuando vuelvas",
		["{npc:263749} (level 44) carries the key: he paces the lanes south of {npc:259057}'s hut.\nThe {item:275043} lies just west of the lanes: its fighters (elites, 41-45) only fight in a bout, so leave them be."] = "{npc:263749} (nivel 44) lleva la llave: recorre los pasillos al sur de la choza de {npc:259057}.\nEl {item:275043} está justo al oeste de los pasillos: sus luchadores (élite, 41-45) solo pelean en un combate, así que déjalos en paz.",
		["{quest:94877}: for later in this guide"] = "{quest:94877}: para más adelante en esta guía",
		["{quest:94879}, for later in this guide"] = "{quest:94879}, para más adelante en esta guía",
		["{quest:94884}: for {npc:257591} in {area:16724}"] = "{quest:94884}: para {npc:257591} en {area:16724}",
		["{quest:94885}: only if a cultist dropped the log"] = "{quest:94885}: solo si un cultista soltó el registro",
		["{quest:94886}: for later in this guide"] = "{quest:94886}: para más adelante en esta guía",
		["{quest:94887}: for later in this guide"] = "{quest:94887}: para más adelante en esta guía",
		["{quest:94891}: for {npc:257591}"] = "{quest:94891}: para {npc:257591}",
		["{quest:94892}: for {npc:257558} in {area:16724}"] = "{quest:94892}: para {npc:257558} en {area:16724}",
		["{quest:94893}: for {npc:278088} in {zone:1453}"] = "{quest:94893}: para {npc:278088} en {zone:1453}",
		["{quest:94907}: for later in this guide"] = "{quest:94907}: para más adelante en esta guía",
		["{quest:94928}: for {area:16727}, keep it"] = "{quest:94928}: para {area:16727}, guárdala",
		["{quest:95059}: for {npc:257558} in {area:16724}, keep it"] = "{quest:95059}: para {npc:257558} en {area:16724}, guárdala",
		["{quest:95064}: for later, at the Horde's training grounds north of {area:16743}"] = "{quest:95064}: para después, en el campo de entrenamiento de la Horda al norte de {area:16743}",
		["{quest:95066}: for {npc:257558} in {area:16724}, keep it"] = "{quest:95066}: para {npc:257558} en {area:16724}, guárdala",
		["{quest:95122}: for later in this guide"] = "{quest:95122}: para más adelante en esta guía",
		["{quest:95123}: for later in this guide"] = "{quest:95123}: para más adelante en esta guía",
		["{quest:95148}: for {npc:257558} in {area:16724}, keep it"] = "{quest:95148}: para {npc:257558} en {area:16724}, guárdala",
		["{quest:95261}: the beasts' entrails come as you go; the mushrooms are for later"] = "{quest:95261}: las entrañas de las bestias salen sobre la marcha; los champiñones son para después",
		["{quest:95267}: a big beast in the shallows south-west of the port, near {npc:257001}, the elite"] = "{quest:95267}: una gran bestia en las aguas poco profundas al suroeste del puerto, cerca de {npc:257001}, el élite",
		["{quest:95293}: for {npc:260390} at the pirates' camp"] = "{quest:95293}: para {npc:260390} en el campamento pirata",
		["{quest:95329}: for {npc:259352} at {area:16729}, keep it"] = "{quest:95329}: para {npc:259352} en {area:16729}, guárdala",
		["{quest:95426}: for later, the same training grounds"] = "{quest:95426}: para después, en el mismo campo de entrenamiento",
		["{quest:95961}: for {npc:263120} in {area:16727}, keep it"] = "{quest:95961}: para {npc:263120} en {area:16727}, guárdala",
		["{quest:95975}: for later, the wildflowers west of the port"] = "{quest:95975}: para más adelante, las flores silvestres al oeste del puerto",
		["{quest:95984}: for later, where the tallstriders graze by {npc:263367}'s workshop; keep it"] = "{quest:95984}: para después, donde pastan los zancudos junto al taller de {npc:263367}; guárdala",
		["{quest:96009}: for {area:16736} later in this guide"] = "{quest:96009}: para {area:16736} más adelante en esta guía",
		["{quest:96084}: for later in this guide"] = "{quest:96084}: para más adelante en esta guía",
		["{quest:96125}: for {npc:259057} in {area:16726}, keep it"] = "{quest:96125}: para {npc:259057} en {area:16726}, guárdala",
		["{zone:1453} flight master"] = "Maestro de vuelo de {zone:1453}",
		["{zone:1455} flight master"] = "Maestro de vuelo de {zone:1455}",
} end)()
t.guides["forever/alliance/40-50/02-badlands"] = (function() return {
		["Back through the pass: the Stonevault troggs dig outside {area:1517} at the {zone:1418}' northern edge. The carved urns and the magenta mushroom clusters sit in their caves and tunnels, outside the dungeon itself."] = "De vuelta por el paso: los troggs Grutacanto cavan afuera de {area:1517}, en el borde norte de {zone:1418}. Las urnas talladas y los grupos de champiñones magenta están en sus cuevas y túneles, fuera de la propia mazmorra.",
		["Back to {zone:1432}"] = "De vuelta a {zone:1432}",
		["Fly to {area:150}"] = "Vuela a {area:150}",
		["Fly to {area:271}"] = "Vuela a {area:271}",
		["From Theramore, ride north into the {zone:1413} to {area:392}, or fly if you know its flight path. {npc:6251} teaches in the house by the bank."] = "Desde Theramore, cabalga al norte por {zone:1413} hasta {area:392}, o vuela si conoces su ruta de vuelo. {npc:6251} enseña en la casa junto al banco.",
		["Into {zone:1418}"] = "A {zone:1418}",
		["Into {zone:1432}"] = "A {zone:1432}",
		["Mudsprocket"] = "Fangoengranaje",
		["Raleigh's next errand is in the {area:796}: skip it."] = "El siguiente encargo de Raleigh es en {area:796}: omítelo.",
		["Ride back east to {area:1898}."] = "Cabalga de vuelta al este hasta {area:1898}.",
		["Ride back north to Ironband's camp."] = "Cabalga de vuelta al norte hasta la Excavación de Vetaferro.",
		["Ride north through the pass into {zone:1432} and east along the south shore to Ironband's camp."] = "Cabalga al norte por el paso hasta {zone:1432} y al este por la orilla sur hasta el campamento de Ironband.",
		["Ride north-east out of {area:271} on the road into the {zone:1425}; {area:348} sits just past the border. {npc:5635} holds court at the top, {quest:1450} tends the aviary and {npc:7884} stands by the inn."] = "Cabalga hacia el noreste fuera de {area:271} por el camino hacia {zone:1425}; {area:348} está justo pasando la frontera. {npc:5635} recibe en la cima, {quest:1450} cuida el aviario y {npc:7884} está junto a la posada.",
		["Ride south out of {zone:1432} through the pass into the {zone:1418}; {npc:2860} camps at the dig."] = "Cabalga hacia el sur, fuera de {zone:1432}, por el paso hasta {zone:1418}; {npc:2860} acampa en la excavación.",
		["Ride west along the loch to {area:144}."] = "Cabalga al oeste por el lago hasta {area:144}.",
		["Take the road south-west out of Theramore to Mudsprocket, the goblin camp at the edge of the {area:511}. {npc:270723} and {npc:270727} stand together in the camp."] = "Toma el camino al suroeste desde Theramore hasta Fangoengranaje, el campamento goblin al borde de {area:511}. {npc:270723} y {npc:270727} están juntos en el campamento.",
		["Talonaxe's next task waits for a later {zone:1425} guide."] = "La siguiente tarea de Talonaxe espera a una guía posterior de {zone:1425}.",
		["The Scalding Whelps nest in the ravine east of {npc:2888}; leave the Scorched Guardians (elite) alone. The {item:4612} drops rarely: take it if it comes while you grind."] = "Las Crías hirvientes anidan en el barranco al este de {npc:2888}; deja en paz a los Guardianes abrasados (élite). {item:4612} cae rara vez: tómalo si aparece mientras cazas.",
		["The first two cages stand together in the Witherbark village south of {npc:5634}; the third is in the next village to the east. Every Witherbark troll can drop a necklace.\nCareful: {npc:270772} (49) and his Hexed Larvae (45) keep to the huts of the western village, around 25,64: take the necklaces from the trolls outside."] = "Las dos primeras jaulas están juntas en la aldea Secacorteza al sur de {npc:5634}; la tercera está en la siguiente aldea al este. Cualquier trol Secacorteza puede soltar un collar.\nCuidado: {npc:270772} (49) y sus Larvas embrujadas (45) se quedan en las chozas de la aldea del oeste, alrededor de 25,64: consigue los collares de los trols de afuera.",
		["The {area:1517} dig"] = "La excavación de {area:1517}",
		["The {area:511}"] = "{area:511}",
		["The {item:280092} grows in the bog east of the camp: gather it first. Then the Searing Hatchlings and Whelps (41-43) and the Firemane dragonkin nest in the bog north and west of Mudsprocket, on the way back; all of them drop the shed scales.\nCareful: the Firemane Scalebanes and Flamecallers are 43-44 and cast fire: pull them one at a time."] = "La {item:280092} crece en la ciénaga al este del campamento: recógela primero. Luego las Proles abrasadoras y los vástagos (41-43) y los dragonantes Pirocabello anidan en la ciénaga al norte y al oeste de Fangoengranaje, de regreso; todos sueltan las escamas mudadas.\nCuidado: los Horrocrustos Pirocabello y los Clamafuegos son de nivel 43-44 y lanzan fuego: atráelos de uno en uno.",
		["Then ride back north-east to Theramore's flight master."] = "Luego cabalga de vuelta al noreste hasta el maestro de vuelo de Theramore.",
		["Theramore"] = "Isla Theramore",
		["Theramore flight master"] = "Maestro de vuelo de Theramore",
		["Warlock: {quest:3631}"] = "Brujo: {quest:3631}",
		["Witherbark villages"] = "Aldeas Secacorteza",
		["{area:144} flight master"] = "Maestro de vuelo de {area:144}",
		["{area:348} flight master"] = "Maestro de vuelo de {area:348}",
		["{item:8047}; below ground"] = "{item:8047}; bajo tierra",
		["{npc:1470} is below ground in {area:144}, by the inn, where the flight lands. His mushrooms grow in the {area:1517} dig at the {zone:1418}' northern edge, on this guide's loop back north."] = "{npc:1470} está bajo tierra en {area:144}, junto a la posada, donde aterriza el vuelo. Sus champiñones crecen en la excavación de {area:1517}, en el borde norte de {zone:1418}, en el regreso al norte de esta guía.",
		["{npc:1470}, below ground"] = "{npc:1470}, bajo tierra",
		["{npc:2277} stands in {area:271}, by the inn."] = "{npc:2277} está en {area:271}, junto a la posada.",
		["{npc:269577} camps at the foot of the pass into {zone:1432}, on the way north."] = "{npc:269577} acampa al pie del paso hacia {zone:1432}, de camino al norte.",
		["{npc:269577}'s {item:278404} lies in the middle of the Stonevault trogg camp, where {quest:739} walks."] = "El {item:278404} de {npc:269577} está en medio del campamento trogg Bóveda Pétrea, donde camina {quest:739}.",
		["{npc:2817}'s next quest pays no experience: skip it."] = "La siguiente misión de {npc:2817} no da experiencia: omítela.",
		["{npc:2817}: Blue Pearls from Stranglethorn"] = "{npc:2817}: perlas azules de Tuercespina",
		["{npc:2888} camps by himself in {area:1898}, south-east of the digsite."] = "{npc:2888} acampa solo en {area:1898}, al sureste de la excavación.",
		["{npc:2888}'s next task is an elite hunt: skip it."] = "La siguiente tarea de {npc:2888} es una cacería de élite: omítela.",
		["{npc:2944} does not stay at {area:342}: he walks a long loop around the {zone:1418} with his guards, from the camp in the west along the south of the zone to about 61,69, north to about 49,49 and back west to the camp. The arrow follows his loop west from here until you meet him."] = "{npc:2944} no se queda en {area:342}: recorre un largo circuito por {zone:1418} con sus guardias, desde el campamento en el oeste por el sur de la zona hasta aproximadamente 61,69, al norte hasta aproximadamente 49,49 y de vuelta al oeste hasta el campamento. La flecha sigue su circuito hacia el oeste desde aquí hasta que lo encuentres.",
		["{npc:3980} preaches by the inn."] = "{npc:3980} predica junto a la posada.",
		["{npc:3980}, upstairs"] = "{npc:3980}, arriba",
		["{npc:4794}, inside"] = "{npc:4794}, adentro",
		["{npc:4944}, on the top floor"] = "{npc:4944}, en el piso de arriba",
		["{npc:5634} camps on the road east of {area:348}."] = "{npc:5634} acampa en el camino al este de {area:348}.",
		["{npc:5636}, beside the flight master at the top; inside"] = "{npc:5636}, junto al maestro de vuelo de arriba; adentro",
		["{npc:7884}, inside"] = "{npc:7884}, adentro",
		["{object:2743}; below ground"] = "{object:2743}; bajo tierra",
		["{quest:1450}, inside"] = "{quest:1450}, adentro",
		["{quest:706}: its {item:4612} is a rare drop, so the work and hand-in are optional too"] = "{quest:706}: su {item:4612} cae rara vez, así que el trabajo y la entrega también son opcionales",
} end)()
t.guides["forever/alliance/40-50/03-feralas"] = (function() return {
		["Back to the coast"] = "De vuelta a la costa",
		["Back to the {area:1117}. Every Hatecrest naga there can drop scales."] = "Vuelve a {area:1117}. Cualquier naga Crestafuria de allí puede soltar escamas.",
		["Boat to {area:1108}"] = "Barco a {area:1108}",
		["Boat to {area:1116}"] = "Barco a {area:1116}",
		["Boats to and from the island"] = "Barcos de ida y vuelta a la isla",
		["Careful: {npc:222286}, an elite of level 43, stands at the camp's north-east edge, around 67,39: pull the Naturalists, Raiders and Shamans away from her."] = "Cuidado: {npc:222286}, una élite de nivel 43, está en el borde noreste del campamento, alrededor de 67,39: aleja de ella a los naturalistas, asaltantes y chamanes.",
		["Coming from the south: {npc:7877} and {npc:7878} first, then {npc:7900} beside {npc:7880}'s building, then the stairs. {npc:7880} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart. {npc:7852} is by the flight master, on the way out."] = "Viniendo desde el sur: primero {npc:7877} y {npc:7878}, luego {npc:7900} junto al edificio de {npc:7880}, luego la escalera. {npc:7880} está en el piso de arriba de su edificio: sube por adentro, la flecha no distingue los pisos. {npc:7852} está junto al maestro de vuelo, a la salida.",
		["Feathermoon flight master"] = "Maestro de vuelo de Plumaluna",
		["Feathermoon's isle, ogres, yetis and the {area:1121}."] = "La isla de Plumaluna, ogros, yetis y {area:1121}.",
		["Fly to {area:489}"] = "Vuela a {area:489}",
		["From {area:489} ride west along the road to the Grimtotem camp north of it. {npc:7956} waits outside it; free the Sprite Darters from the pen in the middle and keep {npc:7956} and at least six of them alive."] = "Desde {area:489} cabalga al oeste por el camino hasta el campamento Tótem Siniestro, al norte. {npc:7956} espera afuera; libera a los duendes dardo del corral del centro y mantén con vida a {npc:7956} y al menos a seis de ellos.",
		["Gordunni ogres"] = "Ogros Gordunni",
		["Grimtotem camp"] = "Campamento Tótem Siniestro",
		["Grimtotem tauren"] = "Taurens Tótem Siniestro",
		["Grind to 45"] = "Sube a nivel 45 matando",
		["Hatecrest naga"] = "Nagas Crestafuria",
		["Into {zone:1413}"] = "Hacia {zone:1413}",
		["Ironfur bears"] = "Osos Cueracero",
		["No flight path to {area:489} yet: take the boat back to the coast and ride east along the road to {area:489}, on the {zone:1441} border."] = "Aún no tienes ruta de vuelo a {area:489}: toma el barco de vuelta a la costa y cabalga al este por el camino hasta {area:489}, en la frontera con {zone:1441}.",
		["Ride east to the Gordunni camp in the hills south-east of the yeti valley: Warlocks and Shaman hold the camp, Brutes wander the slopes around it and further north.\nCareful: the {npc:5236} are 44-45 and the Warlocks 43-44, casters a level or two over you here: pull them one at a time from the camp's edge, and take the Brutes (42-43) on the slopes first."] = "Cabalga al este hasta el campamento Gordunni en las colinas al sureste del valle de los yetis: brujos y chamanes ocupan el campamento, y toscos rondan las laderas a su alrededor y más al norte.\nCuidado: los {npc:5236} son de nivel 44-45 y los brujos de 43-44, lanzadores de hechizos uno o dos niveles por encima de ti aquí: atráelos de uno en uno desde el borde del campamento, y primero mata a los toscos (42-43) de las laderas.",
		["Ride north into the yeti valley. Every Feral Scar yeti can drop a thick hide; {npc:5346} (level 48) prowls the middle."] = "Cabalga al norte hacia el valle de los yetis. Cualquier yeti Cicatriz Feral puede soltar una piel gruesa; {npc:5346} (nivel 48) merodea por el centro.",
		["Ride north out of {area:1105}: the Ironfur Bears (41-42) at the foot of the {area:1136} drop Rhapsody's last liver.\nCareful: Ironfur Patriarchs (48-49) and the Rage Scar yetis (46-49) roam the hills further north: stay at their edge."] = "Cabalga al norte saliendo de {area:1105}: los Osos Cueracero (41-42) al pie de {area:1136} sueltan el último hígado de Rhapsody.\nCuidado: Patriarcas Cueracero (48-49) y los yetis Cicatriz de Rabia (46-49) rondan las colinas más al norte: quédate en su borde.",
		["Ride north-east to the night elf outpost on the {zone:1441} border."] = "Cabalga al noreste hasta el puesto de los elfos de la noche en la frontera de {zone:1441}.",
		["Ride south-east to the Woodpaw gnolls; the courier's backpacks lie in their southern camp, and a parcel inside them starts a delivery to {area:489}. The Zukk'ash hive is just south: fight down to the pod that holds Raschal, free him and keep him alive on the way out."] = "Cabalga al sureste hasta los gnolls Zarpaleña; las mochilas del mensajero están en su campamento del sur, y un paquete dentro de ellas inicia una entrega a {area:489}. La colmena Zukk'ash está justo al sur: abre paso hasta la vaina que retiene a Raschal, libéralo y mantenlo con vida al salir.",
		["Ride to {area:489}"] = "Cabalga a {area:489}",
		["Ride west into {area:1105}: its yetis are 43-45. The Rage Scar yetis in the hills to the north are 46-49: leave them. Or, with a group, run the {area:978} dungeon instead."] = "Cabalga al oeste hacia {area:1105}: sus yetis son de nivel 43-45. Los yetis Cicatriz de Rabia de las colinas del norte son de nivel 46-49: déjalos. O, con un grupo, haz en su lugar el calabozo {area:978}.",
		["Stays on the main route"] = "Se mantiene en la ruta principal",
		["Take the boat to the {area:1108} and follow the shore south to the wrecked row boat on the beach."] = "Toma el barco a {area:1108} y sigue la orilla al sur hasta el bote de remos destrozado en la playa.",
		["The courier's boat"] = "El bote del mensajero",
		["The {area:1121} is the island just south of {area:1120}: swim over. Hatecrest Serpent Guards and Sorceresses hold it; {npc:8136} (level 47) waits in the cave at its south end. Pull his guards first."] = "{area:1121} es la isla justo al sur de {area:1120}: cruza nadando. La ocupan guardias serpiente y hechiceras Crestafuria; {npc:8136} (nivel 47) espera en la cueva de su extremo sur. Atrae primero a sus guardias.",
		["Then on to {zone:1446}"] = "Luego hacia {zone:1446}",
		["Two new flight paths for later"] = "Dos nuevas rutas de vuelo para más adelante",
		["Walk south along the island to the naga ruins; the gazebo stands among them."] = "Camina al sur por la isla hasta las ruinas naga; el cenador está entre ellas.",
		["You came into {zone:1444} from {zone:2652}, so {area:489}'s flight path is still to learn: take the boat back to the coast and ride east along the road; you pick up the flight path when this guide ends at {area:489}."] = "Llegaste a {zone:1444} desde {zone:2652}, así que aún te falta la ruta de vuelo de {area:489}: toma el barco de vuelta a la costa y cabalga al este por el camino; obtendrás la ruta de vuelo cuando esta guía termine en {area:489}.",
		["for Tyrande in {zone:1457}: the route takes you there at 47"] = "para Tyrande Susurravientos en {zone:1457}: la ruta te lleva allí a nivel 47",
		["grind on {npc:5292} at {area:1105}, {zone:1444}"] = "mata {npc:5292} en {area:1105}, {zone:1444}",
		["{area:1116} stands on {area:1120}, off the {area:1108}: the boat from the coast's dock crosses to it. {npc:7880} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{area:1116} está en {area:1120}, frente a {area:1108}: el barco del muelle de la costa cruza hasta allí. {npc:7880} está en el piso de arriba de su edificio: sube por adentro, la flecha no distingue los pisos.",
		["{area:489} flight master"] = "Maestro de vuelo de {area:489}",
		["{item:11463}, from the backpacks"] = "{item:11463}, de las mochilas",
		["{item:9248}; below ground"] = "{item:9248}; bajo tierra",
		["{npc:3936}, beside him"] = "{npc:3936}, a su lado",
		["{npc:4048} walks around {area:489}: look inside the circle on the map"] = "{npc:4048} recorre {area:489}: busca dentro del círculo del mapa",
		["{npc:7764}: his answer waits in {area:702}, later"] = "{npc:7764}: su respuesta espera en {area:702}, más adelante",
		["{npc:7852}'s next order, Improved Quality, wants Rage Scar hides from yetis of 46-49: skip it."] = "El siguiente encargo de {npc:7852}, Calidad mejorada, pide pieles Cicatriz de Rabia de yetis de nivel 46-49: omítelo.",
		["{npc:7877}, at the top of the stronghold"] = "{npc:7877}, en lo alto del bastión",
		["{npc:7879}, upstairs"] = "{npc:7879}, arriba",
		["{npc:7880} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:7880} está en el piso de arriba de su edificio: sube por adentro, la flecha no distingue los pisos.",
		["{npc:8136} waits for the end of the mainland loop."] = "{npc:8136} espera hasta el final de la vuelta por el continente.",
		["{object:164954}, inside"] = "{object:164954}, adentro",
} end)()
t.guides["forever/alliance/40-50/04-tanaris"] = (function() return {
		["\"Sea Wolf\" MacKinley in {area:35}: the route takes you there at the end of the {zone:1425} guide, keep it"] = "MacKinley «Lobo de Mar» en {area:35}: la ruta te lleva allí al final de la guía de {zone:1425}, guárdala",
		["Boat to {area:150}"] = "Barco a {area:150}",
		["Careful: Thieves cast Disarm. Rogues stay hidden with Sneak. Assassins use Execute when your health is at 20% or lower."] = "Cuidado: Los ladrones lanzan Desarmar. Los pícaros se mantienen ocultos con Sigilo. Los asesinos usan Ejecutar cuando tu salud está al 20% o menos.",
		["Class trainer"] = "Instructor de clase",
		["Fly to {area:271}"] = "Vuela a {area:271}",
		["Fly to {area:348}"] = "Vuela a {area:348}",
		["Fly to {area:442}"] = "Vuela a {area:442}",
		["Follow the coast south to the pirate cove. Southsea pirates crowd the beach and the boats: work along the edge and pull one at a time. {npc:7883} stands on the far side; {npc:7881}'s stolen cargo lies in the camp.\nCareful: Two or three pirates stand with {npc:7883}, and many more pirates from the town join the fight once it starts."] = "Sigue la costa al sur hasta la cala pirata. Los piratas de los Mares del Sur llenan la playa y los botes: avanza por el borde y atráelos de a uno. {npc:7883} está en el otro extremo; la carga robada de {npc:7881} está en el campamento.\nCuidado: Dos o tres piratas están con {npc:7883}, y muchos más piratas del pueblo se suman a la pelea en cuanto empieza.",
		["For your {area:978} run, later in this guide: {quest:2864} wants scarab shells, {npc:7407}, by the water tower, his {quest:2768} back, and Trenton Lighthammer Troll Temper from the Sandfury trolls."] = "Para tu recorrido por {area:978}, más adelante en esta guía: {quest:2864} quiere caparazones de escarabajo, {npc:7407}, junto a la torre de agua, quiere de vuelta su {quest:2768}, y Trenton Lighthammer, temple de trol de los trols Furiarena.",
		["From {npc:6015}, {area:977} is just west along the shore."] = "Desde {npc:6015}, {area:977} está justo al oeste por la costa.",
		["Gives the {item:8585}"] = "Da el {item:8585}",
		["No flight path to {area:348} yet: ride north-east out of {area:271} on the road into the {zone:1425}; {area:348} sits just past the border."] = "Aún no tienes ruta de vuelo a {area:348}: cabalga al noreste saliendo de {area:271} por el camino hacia {zone:1425}; {area:348} está justo pasando la frontera.",
		["Pool by {area:979}"] = "Estanque junto a {area:979}",
		["Portal to {zone:1438}"] = "Portal a {zone:1438}",
		["Ride back west toward {area:976}. The Wastewander bandits and thieves hold the dunes on the way; any of them can carry a water pouch.\nCareful: Wastewander Rogues (level 43-44) move stealthed, so they can approach unseen."] = "Cabalga de vuelta al oeste hacia {area:976}. Los bandidos y ladrones Vagayermos ocupan las dunas por el camino; cualquiera puede llevar un odre de agua.\nCuidado: Los pícaros Vagayermos (nivel 43-44) se mueven en sigilo, así que pueden acercarse sin que los veas.",
		["Ride east across the dunes to the goblin harbour on the north-east coast."] = "Cabalga al este por las dunas hasta el puerto goblin de la costa noreste.",
		["Ride north-west to the Sandfury troll camp at {area:979}. Use the {item:8584} at the edge of its pool to tap it; the trolls stand close, so pull the nearest first.\nCareful: tapping the pool brings Scarabs (level 44-47) out of the sand to attack you: tap it, then step away from the trolls and fight the Scarabs one by one."] = "Cabalga al noroeste hasta el campamento trol Furiarena en {area:979}. Usa la {item:8584} al borde de su estanque para tomar la muestra; los trols están cerca, así que atrae primero al más cercano.\nCuidado: tomar la muestra hace salir de la arena escarabajos (nivel 44-47) que te atacan: tómala, aléjate de los trols y pelea con los escarabajos de uno en uno.",
		["Ride south to the dig camp at the {area:1938}. {npc:7771} hands you a detector helm: wear it to see the {quest:3161} mounds, which lie thick in the sand around the camp and south-west toward the ogres."] = "Cabalga al sur hasta el campamento de excavación en {area:1938}. {npc:7771} te da un yelmo detector: póntelo para ver los montículos de {quest:3161}, abundantes en la arena alrededor del campamento y al suroeste, hacia los ogros.",
		["Ride south-east off the {area:439} into {zone:1446}. {area:976} is just inside the border."] = "Cabalga al sureste desde {area:439} hacia {zone:1446}. {area:976} está justo al cruzar la frontera.",
		["Ride south-east to {area:985}. {npc:7847} stands in the middle of the southern Wastewander camp: clear around him first.\nCareful: Two stealthed Wastewander Rogues travel with him wherever he goes. At his spawn camp, two shadowmages and their minions are close enough to join a fight with him. Out by the towers you can fight him without them."] = "Cabalga al sureste hasta {area:985}. {npc:7847} está en el centro del campamento Vagayermos del sur: despeja primero a su alrededor.\nCuidado: Dos pícaros Vagayermos en sigilo lo acompañan adondequiera que vaya. En su campamento de aparición, dos magos oscuros y sus esbirros están lo bastante cerca para sumarse a la pelea. Junto a las torres puedes pelear con él sin ellos.",
		["Ride south-west to the ogre compound and keep to its south end; the compound's quest waits for the Un'Goro guide.\nWhy the grind to 47: {npc:5955} waits at the edge of the {quest:3362} (mobs of 48-50). Grind it on the Dunemaul Ogres (45-46) at the compound's south end, the safer camp, not on the Brutes and Enforcers (46-48) inside."] = "Cabalga al suroeste hasta el recinto de los ogros y quédate en su extremo sur; la misión del recinto espera a la guía de Un'Goro.\nPor qué subir a 47: {npc:5955} espera en el borde de {quest:3362} (enemigos de 48-50). Sube matando Ogros Machacaduna (45-46) en el extremo sur del recinto, el campamento más seguro, no a los brutos y ejecutores (46-48) del interior.",
		["Step through the portal into {zone:1457}. The Temple of the Moon is in the south of the city."] = "Cruza el portal hacia {zone:1457}. El Templo de la Luna está en el sur de la ciudad.",
		["Take the boat from {area:442}'s dock to {area:702}; {npc:3838}, the hippogryph master, stands on the rise just east of the landing: learn the flight path on the way up to the village."] = "Toma el barco desde el muelle de {area:442} hasta {area:702}; {npc:3838}, el maestro de hipogrifos, está en la loma justo al este del desembarcadero: aprende la ruta de vuelo de camino a la aldea.",
		["Temple of the Moon"] = "Templo de la Luna",
		["The Wanted poster beside him"] = "El cartel de Se busca a su lado",
		["The pool by {area:979}"] = "El estanque junto a {area:979}",
		["The same poster: {npc:7847} comes much later, after {area:976}"] = "El mismo cartel: {npc:7847} llega mucho más tarde, después de {area:976}",
		["The tougher Wastewander rogues, shadow mages and assassins camp south-east of {area:976}, south of the bandits. Leave {npc:7847} in the middle of the southern camp for later.\nCareful: Wastewander Rogues keep Sneak up while out of combat, so hidden rogues can join a fight you start at a camp."] = "Los pícaros, magos oscuros y asesinos Vagayermos más duros acampan al sureste de {area:976}, al sur de los bandidos. Deja a {npc:7847}, en el centro del campamento del sur, para después.\nCuidado: Los pícaros Vagayermos mantienen Sigilo fuera de combate, así que pícaros ocultos pueden sumarse a una pelea que empieces en un campamento.",
		["The {area:1938}"] = "{area:1938}",
		["The {quest:2768}: {npc:7407}, by the water tower."] = "{quest:2768}: {npc:7407}, junto a la torre de agua.",
		["The {quest:3042}: {npc:7804}, in town."] = "{quest:3042}: {npc:7804}, en el pueblo.",
		["Your {area:978} scarab shells: {npc:7876}, on the north side of town."] = "Tus caparazones de escarabajo de {area:978}: {npc:7876}, en el lado norte del pueblo.",
		["grind on {npc:5471}, at the compound's south end"] = "farmea {npc:5471}, en el extremo sur del recinto",
		["keep it: the {area:982}'s Centipaar (48-50) wait for the Un'Goro guide's {area:976} landing at about 49.5"] = "consérvala: los Centipaar (48-50) de {area:982} esperan a la llegada a {area:976} de la guía de Un'Goro, a nivel 49.5 aprox.",
		["the book on her table"] = "el libro sobre su mesa",
		["the soil comes from {zone:1449}, later"] = "la tierra viene de {zone:1449}, más adelante",
		["{area:1336}: kill these as you meet them"] = "{area:1336}: mata a estos según te los encuentres",
		["{area:150} flight master"] = "Maestro de vuelo de {area:150}",
		["{area:1937}: kill these as you meet them"] = "{area:1937}: mata a estos según te los encuentres",
		["{area:702} flight master"] = "Maestro de vuelo de {area:702}",
		["{area:976} flight master"] = "Maestro de vuelo de {area:976}",
		["{area:978} is a dungeon for a group of five; its quests here are level 45 to 47. Its gate lies about 400 yards north of the pool.\nInside: the Scarabs drop the shells, every Sandfury troll can drop {quest:3042}, and {npc:7604} carries the {quest:2768}."] = "{area:978} es una mazmorra para un grupo de cinco; sus misiones de aquí son de nivel 45 a 47. Su puerta está a unos 400 m al norte del estanque.\nAdentro: los escarabajos sueltan los caparazones, cualquier trol Furiarena puede soltar {quest:3042}, y {npc:7604} lleva {quest:2768}.",
		["{item:278186}, from any Dunemaul ogre"] = "{item:278186}, de cualquier ogro Machacaduna",
		["{npc:11758}: keep it, the {area:983} waits for the same landing"] = "{npc:11758}: consérvala, {area:983} espera a esa misma llegada",
		["{npc:270263}, just east of the aviary: {quest:86616}, from the {area:355}'s Soothsayers"] = "{npc:270263}, justo al este del aviario: {quest:86616}, de los Veritas Vilrama de {area:355}",
		["{npc:3516}, at the top of the tree"] = "{npc:3516}, en lo alto del árbol",
		["{npc:4454}: {quest:1137}, from Martek in the {zone:1418}"] = "{npc:4454}: {quest:1137}, de parte de Martek en {zone:1418}",
		["{npc:5636}, beside the flight master"] = "{npc:5636}, junto al maestro de vuelo",
		["{npc:5636}: {quest:86620}, the eggs in the hills just east of {area:348}"] = "{npc:5636}: {quest:86620}, los huevos en las colinas justo al este de {area:348}",
		["{npc:5955}'s escort"] = "La escolta de {npc:5955}",
		["{npc:5955}, beside her: Oasis"] = "{npc:5955}, a su lado: Oasis",
		["{npc:7407}, by the water tower"] = "{npc:7407}, junto a la torre de agua",
		["{npc:7408}, next to him"] = "{npc:7408}, a su lado",
		["{npc:7564}: keep it for the same landing"] = "{npc:7564}: consérvala para esa misma llegada",
		["{npc:7763}: his crate goes to {area:702}, later"] = "{npc:7763}: su caja va a {area:702}, más adelante",
		["{npc:7881}, in the port's tavern; inside"] = "{npc:7881}, en la taberna del puerto; adentro",
		["{npc:7881}, inside"] = "{npc:7881}, adentro",
		["{npc:7882}, inside"] = "{npc:7882}, adentro",
		["{npc:7882}: {quest:97530}, the bangles come from the ogres on your way south"] = "{npc:7882}: {quest:97530}, los brazaletes los sueltan los ogros en tu camino al sur",
		["{npc:7884}, inside"] = "{npc:7884}, adentro",
		["{npc:7907} stands upstairs, above {npc:7916}: go up inside, the arrow cannot tell the floors apart."] = "{npc:7907} está arriba, encima de {npc:7916}: sube por adentro, la flecha no distingue los pisos.",
		["{npc:7907}'s next errand goes to {zone:1446}: skip it."] = "El siguiente encargo de {npc:7907} va a {zone:1446}: sáltalo.",
		["{npc:7916}: the feathers lie in the {zone:1425}, next"] = "{npc:7916}: las plumas están en {zone:1425}, lo siguiente",
		["{quest:2768}: {npc:7604}, inside"] = "{quest:2768}: {npc:7604}, adentro",
		["{quest:2864}, north side of town"] = "{quest:2864}, en el lado norte del pueblo",
		["{quest:2864}: keep it, the {quest:3362} waits for the Un'Goro guide's {area:976} landing"] = "{quest:2864}: consérvala, {quest:3362} espera a la llegada a {area:976} de la guía de Un'Goro",
		["{quest:2865}: the Scarabs, inside"] = "{quest:2865}: los escarabajos, adentro",
		["{quest:2873}; upstairs"] = "{quest:2873}; arriba",
		["{quest:3042}: the Sandfury trolls, inside"] = "{quest:3042}: los trols Furiarena, adentro",
		["{zone:1457} first, while you are on this side of the sea: Troyas' answer, {npc:7763}'s crate, Tyrande and the soil errand, then the boat from {area:442} to {area:150} and the gryphon to {area:348}."] = "Primero {zone:1457}, mientras estás de este lado del mar: la respuesta de Troyas, la caja de {npc:7763}, Tyrande y el encargo de la tierra; luego el barco de {area:442} a {area:150} y el grifo a {area:348}.",
} end)()
t.guides["forever/alliance/40-50/05-the-hinterlands"] = (function() return {
		["\"Sea Wolf\" MacKinley, on the top floor"] = "MacKinley «Lobo de Mar», en el piso superior",
		["Class trainer"] = "Instructor de clase",
		["Fly to {area:1537}"] = "Vuela a {area:1537}",
		["Fly to {area:35}"] = "Vuela a {area:35}",
		["Gorilla hills"] = "Colinas de los gorilas",
		["Hand in the fangs and stay: three waves of gorillas come, {npc:1514} last.\nCareful: three waves of gorillas come one after another with little rest between, then {npc:1514}. Start at full health and mana, and stay near Unbagwa. Some classes find it hard alone: a friend makes it easy."] = "Entrega los colmillos y quédate: vienen tres oleadas de gorilas, {npc:1514} al final.\nCuidado: tres oleadas de gorilas llegan una tras otra con poco descanso entre ellas, y luego {npc:1514}. Empieza con la salud y el maná al máximo, y quédate cerca de Unbagwa. A algunas clases les cuesta solas: con un amigo es fácil.",
		["Inside"] = "Adentro",
		["Leave town by the tunnel and ride north along the coast past the Bloodsail camp: the naga comb the beaches beyond it and drop the reeds."] = "Sal del pueblo por el túnel y cabalga al norte por la costa pasando el campamento Velasangre: las nagas recorren las playas más allá y sueltan los juncos.",
		["Lost Gryphon Eggs"] = "Huevos de grifo perdidos",
		["MacKinley's next task sends you after elite ogres: skip it."] = "La siguiente tarea de MacKinley te envía tras ogros élite: omítela.",
		["Naga Explorers"] = "Expedicionarios naga",
		["OOX-09/HL"] = "OOX-09/HL",
		["On the way back to {area:348}: the lost gryphon eggs lie in the hills just east of the aviary."] = "De regreso a {area:348}: los huevos de grifo perdidos están en las colinas justo al este del aviario.",
		["Ride back down to town."] = "Cabalga de vuelta abajo hasta el pueblo.",
		["Ride back south-east to the Mistvale gorilla hills above {area:35}. {npc:1449} sits among the gorillas: take ten Gorilla Fangs from the Elder Mistvale Gorillas first."] = "Regresa al sureste a las colinas de gorilas Velo de Bruma sobre {area:35}. {npc:1449} está entre los gorilas: primero consigue diez Colmillos de gorila de los Gorilas Velo de Bruma ancianos.",
		["Ride north to {area:351} in the middle of the {zone:1425}. Green Sludges and Jade Oozes crawl all around it.\nCareful: Panthers move around the area in stealth."] = "Cabalga al norte hasta {area:351}, en el centro de {zone:1425}. Los lodos verdes y los mocos de jade se arrastran por todo el lugar.\nCuidado: Las panteras se mueven por la zona en sigilo.",
		["Ride on north along the coast to Zanzil's village. Every Zanzil follower can drop the mixture; {npc:2537} walks the south of the camp."] = "Sigue al norte por la costa hasta la aldea de Zanzil. Cualquier seguidor de Zanzil puede soltar la mezcla; {npc:2537} recorre el sur del campamento.",
		["Ride south-east to the {area:355}, the stepped Vilebranch temple in the south of the {zone:1425}, and climb to the top. Qiaga and {npc:8636} (elite, 50) stand up there: touch the top and come straight back down.\nCareful: Elite trolls guard the top platform, including {npc:7996} and {npc:8636}, along with several Vilebranch Soothsayers. The soothsayers cast spells and are linked to the rest of the group."] = "Cabalga al sureste hasta {area:355}, el templo escalonado Vilrama en el sur de {zone:1425}, y sube a la cima. Qiaga y {npc:8636} (élite, 50) están allí arriba: toca la cima y baja enseguida.\nCuidado: Trols élite vigilan la plataforma de arriba, entre ellos {npc:7996} y {npc:8636}, junto con varios adivinos Vilrama. Los adivinos lanzan hechizos y están vinculados al resto del grupo.",
		["Set your hearth at the {object:26486}: the {zone:1427} guide starts with the hearth back here and the gryphon to {area:144}."] = "Vincula tu piedra de hogar en {object:26486}: la guía de {zone:1427} empieza con la piedra de hogar de vuelta aquí y el grifo a {area:144}.",
		["The Bloodsail captains"] = "Los capitanes Velasangre",
		["The charts and orders lie in the pirate camp on the {area:43}, just south of {area:35}; its Swashbucklers walk the shore. The Warlocks and Swashbucklers (41-43) are under you now."] = "Las cartas y órdenes están en el campamento pirata de {area:43}, justo al sur de {area:35}; sus espadachines recorren la orilla. Los brujos y espadachines (41-43) ya están por debajo de tu nivel.",
		["The three Bloodsail ships lie at anchor off the coast just south of {area:35}: {npc:2550} (45) and {npc:2548} (46) on the nearer decks, {npc:2546} (48) on the flagship, each with a crew of 42-45 pirates. Swim out, clear each deck from the edge and pull one at a time."] = "Los tres barcos Velasangre están anclados frente a la costa justo al sur de {area:35}: {npc:2550} (45) y {npc:2548} (46) en las cubiertas más cercanas, {npc:2546} (48) en el buque insignia, cada uno con una tripulación de piratas de nivel 42-45. Nada hasta ellos, despeja cada cubierta desde el borde y atráelos de a uno.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:1494} (level 52 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Son enemigos élite: se recomienda agruparse, busca gente con quien hacerlo. {npc:1494} (élite de nivel 52) requiere un grupo de 2. Sáltalo si vas solo: la ruta te hace recuperar la experiencia matando enemigos.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:8552} needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Son enemigos élite: se recomienda agruparse, busca gente para hacerlo. {quest:8552} necesita un grupo de 2. Omítela si estás solo: la ruta te hace recuperar esa experiencia matando enemigos.",
		["Tram to {zone:1453}"] = "Tranvía a {zone:1453}",
		["Unbagwa's ritual"] = "El ritual de Unbagwa",
		["Vilebranch Soothsayers"] = "Veritas Vilrama",
		["Wildkin feathers"] = "Plumas de lechúcico salvaje",
		["Zanzil's village"] = "Poblado de Zanzil",
		["for {npc:2616} in Theramore: keep it, the Un'Goro guide lands there"] = "para {npc:2616} en Theramore: guárdalo, la guía de Un'Goro termina allí",
		["{area:1537} inn"] = "Posada de {area:1537}",
		["{area:348} flight master"] = "Maestro de vuelo de {area:348}",
		["{area:43}: kill these as you meet them"] = "{area:43}: mata a estos según te los encuentres",
		["{npc:1449}, inside {area:1742}"] = "{npc:1449}, dentro de {area:1742}",
		["{npc:2487}, top floor"] = "{npc:2487}, piso superior",
		["{npc:2498}'s next Zanzil errand starts in {zone:1441}: skip it."] = "El siguiente encargo de {npc:2498} sobre Zanzil empieza en {zone:1441}: omítelo.",
		["{npc:2498}, inside"] = "{npc:2498}, adentro",
		["{npc:2535} and {npc:2536} stand together in the hills just north of Zanzil's village."] = "{npc:2535} y {npc:2536} están juntos en las colinas justo al norte de la aldea de Zanzil.",
		["{npc:270263}, just east of the aviary"] = "{npc:270263}, justo al este del aviario",
		["{npc:5636}, inside"] = "{npc:5636}, adentro",
		["{npc:7916}'s Wildkin Feathers lie on the ground across the {zone:1425}, south and east of {area:348}, where the owlbeasts roam: pick them up as you ride between the altar and {area:351}."] = "Las plumas de lechúcico salvaje de {npc:7916} están en el suelo por todo {zone:1425}, al sur y al este de {area:348}, donde deambulan las lechubestias: recógelas mientras cabalgas entre el altar y {area:351}.",
		["{zone:1453} flight master"] = "Maestro de vuelo de {zone:1453}",
} end)()
t.guides["forever/alliance/40-50/06-searing-gorge"] = (function() return {
		["Below ground"] = "Bajo tierra",
		["Carry the {object:149047} south along the rim of the Cauldron and light the four Sentry Braziers, from the south-west round to the south-east."] = "Lleva la {object:149047} al sur por el borde de La Caldera y enciende los cuatro braseros centinela, del suroeste al sureste.",
		["Class trainer"] = "Instructor de clase",
		["Dorius stands by the road beside the {area:247}. Escort him north-east to {area:1959} and keep him alive; when it is over, read the {object:175704} he leaves on the road."] = "Dorius está junto al camino al lado de {area:247}. Escóltalo al noreste hasta {area:1959} y mantenlo con vida; cuando termine, lee {object:175704} que deja en el camino.",
		["Fly to {area:144}"] = "Vuela a {area:144}",
		["Fly to {area:1537}"] = "Vuela a {area:1537}",
		["For {npc:8256} in {zone:1455}, at the end of this guide"] = "Para {npc:8256} en {zone:1455}, al final de esta guía",
		["Four rune rubbings in {zone:1447}: keep it"] = "Cuatro calcos de runas en {zone:1447}: guárdala",
		["From {area:144} ride south into the {zone:1418}, then west past the Horde town of {area:340} (give it room) and up the trail into {zone:1427}: the {area:247} is just inside, in the south-east. The prisoner in the wooden outhouse wants 15 {item:4306} and eight dead Dark Iron Geologists from the dig site around it. The outhouse also opens with the key, if you found one."] = "Desde {area:144} cabalga al sur hasta {zone:1418}, luego al oeste pasando el pueblo de la Horda de {area:340} (mantén distancia) y sube por el sendero hasta {zone:1427}: {area:247} está justo al entrar, en el sureste. El prisionero de la letrina de madera quiere 15 {item:4306} y ocho geólogos Hierro Negro muertos de la excavación que la rodea. La letrina también se abre con la llave, si encontraste una.",
		["Golems and elementals"] = "Gólems y elementales",
		["Heavy War Golems patrol the floor of the Cauldron below {npc:8479}; Magma Elementals drift among them. Golems and elementals drop the oil, elementals the hearts."] = "Los gólems de guerra pesados patrullan el fondo de La Caldera, debajo de {npc:8479}; los elementales de magma flotan entre ellos. Los gólems y elementales sueltan el aceite; los elementales, los corazones.",
		["If you skipped The {item:3985} or Facing Negolash, grind here to level 48.27 to stay on the route's plan."] = "Si te saltaste {item:3985} o Enfrentar a Negolash, mata enemigos aquí hasta el nivel 48.27 para seguir el plan de la ruta.",
		["Into {zone:1427}"] = "Hacia {zone:1427}",
		["Level 48.27"] = "Nivel 48.27",
		["Level 48.66"] = "Nivel 48.66",
		["Level 48.98"] = "Nivel 48.98",
		["Listen to {npc:8479}'s story once more."] = "Escucha la historia de {npc:8479} una vez más.",
		["Ride west along the north of the Gorge to {area:1446}, the scaffolded camp on the north-west rim."] = "Cabalga al oeste por el norte de la Garganta hasta {area:1446}, el campamento con andamios del borde noroeste.",
		["Searing Lava Spiders"] = "Arañas de lava superiores",
		["Sentry Braziers"] = "Braseros centinela",
		["The Grimesilt outhouse"] = "La letrina de Limugre",
		["The prisoner's next task, Ledger from {zone:1446}, sends you to the {zone:1435} and {zone:1445}: skip it."] = "La siguiente tarea del prisionero, El libro de contabilidad de {zone:1446}, te envía a {zone:1435} y {zone:1445}: omítela.",
		["The spiders roam the plateaus and lava pools south of {npc:8436}, on the way to {npc:8479}."] = "Las arañas recorren las mesetas y pozas de lava al sur de {npc:8436}, de camino a {npc:8479}.",
		["The {object:149502} it gives holds a {item:10575}: keep it for {npc:9459} in the {zone:1428}"] = "El {object:149502} que te da contiene una {item:10575}: guárdala para {npc:9459} en {zone:1428}",
		["The {object:179827} board"] = "El tablón {object:179827}",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:14621} is a level 50 elite: most classes solo it at level 52, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Son enemigos élite: se recomienda agruparse, busca gente con quien hacerlo. {npc:14621} es un élite de nivel 50: la mayoría de las clases lo hacen solas a nivel 52, pero puede que necesites ayuda. Sáltalo si vas solo: la ruta te hace recuperar la experiencia matando enemigos.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:5860} (level 50 elite) needs a group of 3. Skip it if you are alone: the route has you grind the XP back."] = "Son enemigos élite: se recomienda agruparse, busca gente con quien hacerlo. {npc:5860} (élite de nivel 50) requiere un grupo de 3. Sáltalo si vas solo: la ruta te hace recuperar la experiencia matando enemigos.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:8436} stands inside the Twilight camp at {area:1442}, west of {area:1446}, among Twilight Fire Guards, Idolaters and Geomancers (level 48-49 elites), with {npc:8282} (level 51, rare elite) beside him: {quest:3377} needs a group of 4. Skip it if you are alone."] = "Son enemigos élite: se recomienda agruparse, busca gente con quien hacerlo. {npc:8436} está dentro del campamento del Crepúsculo en {area:1442}, al oeste de {area:1446}, entre guardias de fuego, idólatras y geománticos crepusculares (élites de nivel 48-49), con {npc:8282} (élite raro de nivel 51) a su lado: {quest:3377} requiere un grupo de 4. Sáltala si vas solo.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:3181} needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Son enemigos élite: se recomienda agruparse, busca gente con quien hacerlo. {quest:3181} requiere un grupo de 2. Sáltalo si vas solo: la ruta te hace recuperar la experiencia matando enemigos.",
		["To {zone:1455}"] = "A {zone:1455}",
		["Xiggs waits in the {object:32359}."] = "Xiggs espera en el Distrito Militar ({object:32359}).",
		["grind on {npc:5839}"] = "farmea {npc:5839}",
		["grind on {npc:9318}"] = "farmea {npc:9318}",
		["{area:1443} opens in the north of the Cauldron. The Secret Plans lie on its upper ledge; Incendosaurs swim in the lava pools further in, so pull them to the edge. Stay clear of {npc:14621} and his elite guards deep inside."] = "{area:1443} se abre en el norte de La Caldera. Los Diseños secretos: flujo ígneo están en su cornisa superior; los incendosaurios nadan en los charcos de lava más adentro, así que atráelos al borde. Aléjate de {npc:14621} y sus guardias élite en lo más profundo.",
		["{area:1446} flight master"] = "Maestro de vuelo de {area:1446}",
		["{item:18922}; below ground"] = "{item:18922}; bajo tierra",
		["{npc:8479} stands on the rim of the Cauldron, south of {area:1446}. Listen to his story."] = "{npc:8479} está en el borde de La Caldera, al sur de {area:1446}. Escucha su historia.",
		["{npc:8509} and the dragonflight's hoard are beside {npc:8479}, on the rim south of {area:1446}."] = "{npc:8509} y el tesoro del Vuelo Negro están junto a {npc:8479}, en el borde al sur de {area:1446}.",
		["{npc:9616}: the oozes are in {zone:1448}, keep it"] = "{npc:9616}: los mocos están en {zone:1448}, guárdala",
		["{quest:3453} lies on the ground at {npc:8479}'s feet; {quest:3462} stands beside him."] = "{quest:3453} está en el suelo a los pies de {npc:8479}; {quest:3462} está a su lado.",
		["{quest:3462}: hand it in on the way back to {area:1446}"] = "{quest:3462}: entrégala de regreso a {area:1446}",
		["{zone:1427}: kill these as you meet them"] = "{zone:1427}: mata a estos según te los encuentres",
		["{zone:1455} flight master"] = "Maestro de vuelo de {zone:1455}",
} end)()
t.guides["forever/alliance/40-50/07-un-goro-crater"] = (function() return {
		["Back east to {npc:9619} with the glands."] = "De vuelta al este con {npc:9619} con las glándulas.",
		["Crystal clusters stand all over the crater. The pits' Tar Lords (53-54) and the oozes around them (50-54) are over you: take the clusters on the jungle's north-eastern edge, among the Lashers and young beasts (48-50)."] = "Hay grupos de cristales por todo el cráter. Los Señores de alquitrán de los pozos (53-54) y los mocos a su alrededor (50-54) te superan: toma los cristales del borde noreste de la jungla, entre los Azotadores y las bestias jóvenes (48-50).",
		["Ends with {npc:9298} in {zone:1452}: keep it"] = "Termina con {npc:9298} en {zone:1452}: guárdala",
		["Fly to {area:150}"] = "Vuela a {area:150}",
		["Fly to {area:392}"] = "Vuela a {area:392}",
		["Fly to {area:976}"] = "Vuela a {area:976}",
		["For {npc:7775} in {zone:1444}: keep it"] = "Para {npc:7775} en {zone:1444}: guárdala",
		["Lar'korwi Mates and the raft"] = "Compañeras de Lar'korwi ({npc:9683}) y la balsa",
		["Level 50"] = "Nivel 50",
		["Ride back north-east to {area:976}: {npc:11758} stands on the east side of town."] = "Cabalga de vuelta al noreste hasta {area:976}: {npc:11758} está en el lado este del pueblo.",
		["Ride east into the eastern jungle: Bloodpetal Lashers and Threshers (48-50) drop the petals and {quest:3764}. Crystal clusters stand all over the crater, many around the foot of {area:537}: take a few extra of each colour.\nCareful: the Living Blazes (54-55) walk the top of {area:537}, and the Bloodpetal Flayers and Trappers (51-53) hold the jungle's south: take your crystals from the ridge's foot and your petals in the north.\n{npc:9998}'s scales: the {npc:9165} (48-50) glide over the north-east of the jungle and the Young Diemetradons (49-50) graze beside them. There are only ten of those: the Diemetradons (51) on the jungle's western edge, a short way west of the Threshers, drop the scales too. They are a level over you: take them one at a time."] = "Cabalga al este hacia la jungla del este: los Azotadores y Trilladores Sangrepétalo (48-50) sueltan los pétalos y {quest:3764}. Hay grupos de cristales por todo el cráter, muchos al pie de {area:537}: toma algunos de más de cada color.\nCuidado: las Llamaradas vivientes (54-55) recorren la cima de {area:537}, y los Despellejadores y Tramperos Sangrepétalo (51-53) ocupan el sur de la jungla: toma tus cristales al pie de la cresta y tus pétalos en el norte.\nEscamas para {npc:9998}: los {npc:9165} (48-50) planean sobre el noreste de la jungla y los Diemetradones jóvenes (49-50) pastan a su lado. Solo hay diez de ellos: los Diemetradones (51) del borde oeste de la jungla, un poco al oeste de los Trilladores, también sueltan las escamas. Te superan por un nivel: enfréntalos de uno en uno.",
		["Ride north-west to the refuge.\nGive the elite devilsaurs and stegodons a wide berth. Pick up every {npc:271301} and {object:157936} you pass from here on."] = "Cabalga al noroeste hasta el refugio.\nMantente bien lejos de los demosaurios y estegodones élite. Recoge cada {npc:271301} y {object:157936} que encuentres de aquí en adelante.",
		["Ride south past the {area:1938} to the {area:981}, the Hazzali tunnels; Scrimshank's gear lies deep inside.\nCareful: One bug guards the gear. Many bugs patrol the tunnels, some of them level 50, so fights often pull extra adds."] = "Cabalga al sur más allá de {area:1938} hasta {area:981}, los túneles Hazzali; el equipo de Scrimshank está en lo más profundo.\nCuidado: Un insecto vigila el equipo. Muchos insectos patrullan los túneles, algunos de nivel 50, así que las peleas suelen atraer enemigos de más.",
		["Ride south to the ogre compound. Brutes and Enforcers (46-48) fill it; {npc:12046} (49) stands in the middle with guards around him: clear them first."] = "Cabalga al sur hasta el complejo ogro. Está lleno de brutos y déspotas (46-48); {npc:12046} (49) está en el centro rodeado de guardias: despéjalos primero.",
		["Ride west into {quest:3362}. The Dew Collectors drop the glands; only some are full, so keep the Laden one. Gnarled Thistleshrubs and Rootshapers share the valley.\nCareful: the thistleshrubs wander a lot, so you can easily pull extra mobs."] = "Cabalga al oeste hasta {quest:3362}. Los recolectores de rocío sueltan las glándulas; solo algunas están llenas, así que guarda la cargada. Los cardizales nudosos y los formarraíces comparten el valle.\nCuidado: los cardizales deambulan mucho, así que puedes atraer enemigos de más con facilidad.",
		["Ride west out of {area:976} to the long ramp down into {zone:1449}. {npc:9619} camps at the foot of the ramp, in the south-east corner of the crater."] = "Cabalga al oeste desde {area:976} hasta la larga rampa que baja a {zone:1449}. {npc:9619} acampa al pie de la rampa, en la esquina sureste del cráter.",
		["Ride west to the Centipaar hive in the dunes. Any Centipaar can drop insect parts.\nCareful: Centipaar Swarmers cast {npc:4196} both in and out of combat, which brings small adds that interrupt you."] = "Cabalga al oeste hasta la colmena Centipaar en las dunas. Cualquier Centipaar puede soltar partes de insecto.\nCuidado: los enjambristas Centipaar lanzan {npc:4196} dentro y fuera de combate, lo que atrae pequeños enemigos que te interrumpen.",
		["The Lar'korwi Mates prowl the jungle west of {npc:9619}. The wrecked raft lies on the shore of the lake there; the small pack sits in the water beside it. Keep the compass, map and key for {npc:8737}. Any beast in the crater may drop {item:11116}: right-click it."] = "Las Compañeras de Lar'korwi ({npc:9683}) merodean por la jungla al oeste de {npc:9619}. La balsa destrozada está en la orilla del lago de allí; la mochila pequeña está en el agua a su lado. Guarda la brújula, el mapa y la llave para {npc:8737}. Cualquier bestia del cráter puede soltar {item:11116}: haz clic derecho en él.",
		["The dead Threshadon lies by the water north of {npc:9619}.\nCareful: Venomhide Ravasaurs (50-51) hunt along the water there: pull them one at a time before you loot the carcass.\nAny ravasaur may drop a {item:280459}: right-click it, {npc:9619} takes it."] = "El threshadon muerto yace junto al agua al norte de {npc:9619}.\nCuidado: los ravasaurios Pellejo Venenoso (50-51) cazan junto al agua allí: atráelos de uno en uno antes de saquear el cadáver.\nCualquier ravasaurio puede soltar una {item:280459}: haz clic derecho en ella, {npc:9619} la recibe.",
		["Theramore"] = "Theramore",
		["Theramore flight master"] = "Maestro de vuelo de Theramore",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it."] = "No hiciste esto en la visita anterior de la ruta a esta zona: ahora va primero. Es rápido y abre las misiones que le siguen.",
		["grind on {npc:6511}"] = "sube de nivel con {npc:6511}",
		["{area:392} flight master"] = "Maestro de vuelo de {area:392}",
		["{area:537} and the eastern jungle"] = "{area:537} y la jungla del este",
		["{item:11316}, from the Lashers and Threshers"] = "{item:11316}, de los Azotadores y Trilladores",
		["{item:8593}; below ground"] = "{item:8593}; bajo tierra",
		["{npc:12046}, below ground"] = "{npc:12046}, bajo tierra",
		["{npc:2616} stands on the docks where the boat lands."] = "{npc:2616} está en los muelles donde llega el barco.",
		["{npc:5594}, inside"] = "{npc:5594}, adentro",
		["{npc:8737}, at the back of the refuge"] = "{npc:8737}, al fondo del refugio",
		["{npc:9117}, at the back of the cave; below ground"] = "{npc:9117}, al fondo de la cueva; bajo tierra",
		["{npc:9117}, below ground"] = "{npc:9117}, bajo tierra",
		["{npc:9998}: his scales come from the young beasts of the eastern jungle"] = "{npc:9998}: sus escamas salen de las bestias jóvenes de la jungla del este",
		["{object:161504}, underwater"] = "{object:161504}, bajo el agua",
		["{quest:3362}: kill these as you meet them"] = "{quest:3362}: mata a estos según te los encuentres",
		["{quest:3764}, from the Threshers and the dirt piles"] = "{quest:3764}, de los Trilladores y los montones de tierra",
		["{quest:87494}, if a ravasaur dropped the scale"] = "{quest:87494}, si un ravasaurio soltó la escama",
		["{zone:1455} flight master"] = "Maestro de vuelo de {zone:1455}",
} end)()
t.guides["forever/alliance/50-60/01-burning-steppes"] = (function() return {
		["Archesonus stands beside King Magni in the {object:171709}."] = "Archesonus está junto al rey Magni en {object:171709}.",
		["Archesonus stands beside King Magni in the {object:171709}: the relics you read in the Steppes are his."] = "Archesonus está junto al rey Magni en {object:171709}: las reliquias que leíste en las Estepas son suyas.",
		["Ardalan is inside {area:1438}."] = "Ardalan está dentro de {area:1438}.",
		["Back south-west to {area:3137}."] = "Regresa al suroeste a {area:3137}.",
		["Back to the {zone:1419}"] = "De vuelta a {zone:1419}",
		["Back up through {npc:8395}'s teleport."] = "De vuelta arriba por el teletransporte de {npc:8395}.",
		["Below ground"] = "Bajo tierra",
		["East along the road to {area:1235}"] = "Al este por el camino hasta {area:1235}",
		["Ends with {quest:4808} in {area:2255}, {zone:1452}: keep it"] = "Termina con {quest:4808} en {area:2255}, {zone:1452}: guárdala",
		["Fly to {area:1438}"] = "Vuela a {area:1438}",
		["Fly to {area:144}"] = "Vuela a {area:144}",
		["Fly to {area:150}"] = "Vuela a {area:150}",
		["Fly to {area:1537}"] = "Vuela a {area:1537}",
		["Fly to {area:2418}"] = "Vuela a {area:2418}",
		["Fly to {area:271}"] = "Vuela a {area:271}",
		["Fly to {area:348}"] = "Vuela a {area:348}",
		["Fly to {area:415}"] = "Vuela a {area:415}",
		["Fly to {area:69}"] = "Vuela a {area:69}",
		["Follow the road west, then climb north to the goblin camp on {area:251}."] = "Sigue el camino al oeste y luego sube al norte hasta el campamento goblin en {area:251}.",
		["From {area:415}, ride east along the road past {area:2358} into {zone:1447}: {area:1235} lies just over the border, in {zone:1447}'s south-west corner."] = "Desde {area:415}, cabalga al este por el camino más allá de {area:2358} hasta {zone:1447}: {area:1235} está justo pasando la frontera, en la esquina suroeste de {zone:1447}.",
		["Get off your mount before you talk to {npc:8395}: he teleports you up to {npc:8379}'s tower on the cliff above his camp."] = "Bájate de la montura antes de hablar con {npc:8395}: te teletransporta arriba, a la torre de {npc:8379} en el acantilado sobre su campamento.",
		["Hearth back to {zone:1455}'s inn."] = "Usa la piedra de hogar para volver a la posada de {zone:1455}.",
		["Into {zone:1447}"] = "Hacia {zone:1447}",
		["Just north-east of the shrine: {npc:239822} and {npc:240482} keep the Alliance camp at {area:3137}."] = "Justo al noreste del santuario: {npc:239822} y {npc:240482} están en el campamento de la Alianza en {area:3137}.",
		["Kum'isha waits at the {area:2517}, the hill south-west of the keep. The {zone:1419} mobs on the way drop the Imperfect Draenethyst Fragments; bring her what you have. Come at her hill straight from the keep, along the road, and leave by the same way.\nCareful: Felcular, {npc:7664} and Ilifar are all level 60 elites. Razelikh casts {spell:2691}, {spell:8255} and Decimate, and as its health drops it adds {object:141891}, {spell:10854} and then Enrage at 15%.\nCareful: {npc:247015}, a level 55 elite, stands by Kum'isha's hill (about 50,35) and to the west (about 39,32), and the Dreadmaul and Shadowsworn camps around it are 53-55: take the fragments from the mobs on the way from the keep, not beside him."] = "Kum'isha espera en {area:2517}, la colina al suroeste del bastión. Los enemigos de {zone:1419} del camino sueltan los trozos draenetistas imperfectos; llévale los que tengas. Llega a su colina directo desde el bastión, por el camino, y vete por el mismo lado.\nCuidado: Felcular, {npc:7664} e Ilifar son todos élites de nivel 60. Razelikh lanza {spell:2691}, {spell:8255} y Diezmar, y a medida que baja su salud suma {object:141891}, {spell:10854} y luego Enfurecer al 15%.\nCuidado: {npc:247015}, un élite de nivel 55, está junto a la colina de Kum'isha (alrededor de 50,35) y al oeste (alrededor de 39,32), y los campamentos Machacamiedo y Juramorte a su alrededor son de nivel 53-55: consigue los trozos de los enemigos del camino desde el bastión, no a su lado.",
		["Listen to his tale, then ride back south to Kum'isha."] = "Escucha su historia y luego cabalga de vuelta al sur con Kum'isha.",
		["Mosshoof Coursers"] = "Trotadores Pezuñamusgo",
		["Mosshoof Runners"] = "Corredores Pezuñamusgo",
		["On the road back south, {npc:235903} takes the satyrs."] = "En el camino de vuelta al sur, {npc:235903} se encarga de los sátiros.",
		["Ride back east along the road to the Vigil."] = "Cabalga de vuelta al este por el camino hasta la Vigilia.",
		["Ride back south to the camp."] = "Regresa al sur, al campamento.",
		["Ride back west to {npc:8395}'s camp and get off your mount: he teleports you up to Xylem again."] = "Cabalga de vuelta al oeste hasta el campamento de {npc:8395} y bájate de la montura: te teletransporta otra vez hasta Xylem.",
		["Ride east out of {area:69} and up the pass into the {zone:1428}: {area:2418} stands at the top."] = "Cabalga al este saliendo de {area:69} y sube por el paso hasta {zone:1428}: {area:2418} está en lo alto.",
		["Ride north from {area:271} into Alterac and west to the walls of {area:279}: {npc:34365} stands outside them. Her quest goes to {npc:266524} in {area:1438}, where this guide flies later."] = "Cabalga al norte desde {area:271} hacia Alterac y al oeste hasta las murallas de {area:279}: {npc:34365} está fuera de ellas. Su misión va a {npc:266524} en {area:1438}, adonde esta guía vuela más adelante.",
		["Ride north from {area:271} up the road through Alterac to {area:3197}."] = "Cabalga al norte desde {area:271} por el camino a través de Alterac hasta {area:3197}.",
		["Ride north out of the {zone:1419} into the {zone:1435}: the {npc:10996} stands by the road from the {zone:1419}. Keep clear of {area:75}, the Horde town to the north-east."] = "Cabalga al norte desde {zone:1419} hacia {zone:1435}: {npc:10996} está junto al camino que viene de {zone:1419}. Mantente lejos de {area:75}, el pueblo de la Horda al noreste.",
		["Ride north-east from the shrine: {npc:8405} camps at the {area:1224}, in the hills above the road."] = "Cabalga al noreste desde el santuario: {npc:8405} acampa en {area:1224}, en las colinas sobre el camino.",
		["Swim to the small island off the southern tip of {zone:1447}. If {npc:8392} isn't there, fire your {item:10444} to signal him, and wait for him to land."] = "Nada hasta la islita frente a la punta sur de {zone:1447}. Si {npc:8392} no está ahí, dispara tu {item:10444} para avisarle y espera a que aterrice.",
		["The Highborne ghosts haunt the ruins around the shrine; the Haldarr satyrs hold the camp just north of it. {npc:222478} is held in the satyrs' camp: free her and walk her out."] = "Los fantasmas altonato rondan las ruinas alrededor del santuario; los sátiros Haldarr ocupan el campamento justo al norte. {npc:222478} está prisionera en el campamento de los sátiros: libérala y escóltala hasta afuera.",
		["The Mosshoof Runners (45-47) graze the hills north of {area:3137}, on the way to the satyrs."] = "Los Corredores Pezuñamusgo (45-47) pastan en las colinas al norte de {area:3137}, de camino a los sátiros.",
		["The Spitelash Sirens wander the ruins and the beach around the {area:1223}, just south of {npc:8395}. Only the Sirens carry the coral, not the Screamers."] = "Las sirenas Látigo de Ira deambulan por las ruinas y la playa alrededor de {area:1223}, justo al sur de {npc:8395}. Solo las sirenas llevan el coral, no las chillonas.",
		["The Spitelash Warriors (46-47) and Screamers (47-48) hold the western shore north-east of the satyrs."] = "Los Guerreros Látigo de Ira (46-47) y los Chilladores Látigo de Ira (47-48) ocupan la costa oeste al noreste de los sátiros.",
		["The apprentice at the top of the tower sends you back down."] = "El aprendiz de lo alto de la torre te manda de vuelta abajo.",
		["The blood elves are at the {area:1220}, on the way to {npc:8420}"] = "Los elfos de sangre están en {area:1220}, de camino a {npc:8420}",
		["The bloodmages"] = "Los magos de sangre",
		["The bloodmages' second tier pays for the same parts with a buff item and no experience: skip it."] = "El segundo nivel de los magos de sangre paga las mismas partes con un objeto de beneficio y sin experiencia: omítelo.",
		["The relics are in the {zone:1428}: keep it"] = "Las reliquias están en {zone:1428}: guárdala",
		["The relics are the carved stones scattered through the {area:250} around {area:251}: click them until the information is recovered. Take the ones on the ruins' southern edge, nearest {area:251}.\nCareful: the ruins' War Reavers and Thaurissan Firewalkers are 53-55, and {npc:8978} (57) holds the {object:147516} camp south-west of {area:251}: take the relics at the edge of the ruins, pull one at a time, and keep away from the camp."] = "Las reliquias son las piedras talladas repartidas por {area:250}, alrededor de {area:251}: haz clic en ellas hasta recuperar la información. Toma las del borde sur de las ruinas, las más cercanas a {area:251}.\nCuidado: los atracadores de guerra y caminafuegos Thaurissan de las ruinas son de nivel 53-55, y {npc:8978} (57) ocupa el campamento Hierro Negro al suroeste de {area:251}: toma las reliquias del borde de las ruinas, atrae de uno en uno y mantente lejos del campamento.",
		["The shrine lies in the south-west corner of {zone:1447}, south of {area:3137}."] = "El santuario está en la esquina suroeste de {zone:1447}, al sur de {area:3137}.",
		["The western shore"] = "La costa oeste",
		["The {area:1221}"] = "{area:1221}",
		["The {area:1223}"] = "{area:1223}",
		["To {zone:1455}"] = "A {zone:1455}",
		["Xylem's last task, Destroy Morphaz, is in the {area:1417}: skip it."] = "La última tarea de Xylem, Destruir a Morphaz, está en {area:1417}: sáltala.",
		["{area:144} flight master"] = "Maestro de vuelo de {area:144}",
		["{area:197}: kill these as you meet them"] = "{area:197}: mata a estos según te los encuentres",
		["{area:2418} flight master"] = "Maestro de vuelo de {area:2418}",
		["{area:2418} sits in the south-east of the Steppes, at the top of the pass up from Redridge."] = "{area:2418} está en el sureste de las Estepas, en lo alto del paso que sube desde Crestagrana.",
		["{area:250}: kill these as you meet them"] = "{area:250}: mata a estos según te los encuentres",
		["{area:3197} flight master"] = "Maestro de vuelo de {area:3197}",
		["{area:348} flight master"] = "Maestro de vuelo de {area:348}",
		["{area:442} flight master"] = "Maestro de vuelo de {area:442}",
		["{item:10575}, from the hoard"] = "{item:10575}, del tesoro",
		["{item:20028}, from the blood elf surveyors and reclaimers"] = "{item:20028}, de los agrimensores y reclamadores elfos de sangre",
		["{item:7972}: the {npc:7864}, about 10%"] = "{item:7972}: {npc:7864}, cerca del 10%",
		["{npc:10838} stands in the middle of the camp."] = "{npc:10838} está en el centro del campamento.",
		["{npc:222478}, in the camp"] = "{npc:222478}, en el campamento",
		["{npc:235903} camps by the road north to {npc:8420}: his satyrs are in {npc:8420}'s camp."] = "{npc:235903} acampa junto al camino al norte hacia {npc:8420}: sus sátiros están en el campamento de {npc:8420}.",
		["{npc:3546}: {quest:87295}, the scales come from the basilisks ahead"] = "{npc:3546}: {quest:87295}, las escamas vienen de los basiliscos más adelante",
		["{npc:7034}, below ground"] = "{npc:7034}, bajo tierra",
		["{npc:7363} walks around here: look inside the circle on the map"] = "{npc:7363} recorre esta zona: busca dentro del círculo del mapa",
		["{npc:8022}' next task, {item:9471}, is a {area:978} quest: skip it."] = "La siguiente tarea de {npc:8022}, {item:9471}, es una misión de {area:978}: omítela.",
		["{npc:8420} camps at the {area:1219} in the north; his equipment lies all over the {area:1220} just south-east of him.\nCareful: the Blood Elf Surveyors are 51-52 and the Reclaimers 52-53, with {npc:6647} (53) among them: take the equipment from the camp's edge and pull the elves one at a time.\n{npc:235903}'s satyrs, rogues and hellcallers (51-53) are the Legashi around {npc:8420}'s camp; the Legashi Soulstealers, Hellraisers and Blackguards (53) further east are not part of it: stay west of them."] = "{npc:8420} acampa en {area:1219}, en el norte; su equipo está por todo {area:1220}, justo al sureste de él.\nCuidado: los peritos elfos de sangre son de nivel 51-52 y los reclamadores 52-53, con {npc:6647} (53) entre ellos: toma el equipo desde el borde del campamento y atrae a los elfos de uno en uno.\nLos sátiros, pícaros e invocainfiernos (51-53) de {npc:235903} son los Legashi alrededor del campamento de {npc:8420}; los robaalmas, alzainfiernos y canallas Legashi (53) más al este no cuentan: mantente al oeste de ellos.",
		["{npc:9177}' next tasks ({npc:9176}, and fifty Blackrock Medallions) send you among the Blackrock orcs of 55-58 at the foot of {area:254}: skip them."] = "Las siguientes tareas de {npc:9177} ({npc:9176} y cincuenta medallones Roca Negra) te mandan entre los orcos Roca Negra de nivel 55-58 al pie de {area:254}: omítelas.",
		["{quest:2990}, at the top of the keep"] = "{quest:2990}, en lo alto del castillo",
		["{quest:3701} is a group quest at this level: its relics stand among War Reavers and Firewalkers of 53-55, with {npc:8978} (57) close by, two to five over you, and the route has no later {zone:1428} visit. Grouping up is encouraged, look for people to do it with. Skip it if you are alone."] = "{quest:3701} es una misión de grupo a este nivel: sus reliquias están entre atracadores de guerra y caminafuegos de nivel 53-55, con {npc:8978} (57) cerca, de dos a cinco niveles por encima de ti, y la ruta no vuelve a {zone:1428} más adelante. Se recomienda agruparse, busca gente con quien hacerla. Omítela si vas solo.",
		["{zone:1419}: kill these as you meet them"] = "{zone:1419}: mata a estos según te los encuentres",
		["{zone:1447}: kill these as you meet them"] = "{zone:1447}: mata a estos según te los encuentres",
		["{zone:1455} flight master"] = "Maestro de vuelo de {zone:1455}",
		["{zone:1455} inn"] = "Posada de {zone:1455}",
} end)()
t.guides["forever/alliance/50-60/02-felwood"] = (function() return {
		["Back to {npc:14637} on the dock."] = "Regresa con {npc:14637} en el muelle.",
		["Below ground"] = "Bajo tierra",
		["Boat to {area:1108}"] = "Barco a {area:1108}",
		["Careful: {npc:9454} (54) stands at the back of the {area:2481}, at about 32.2,67.1, with Shadowstalkers around him: clear them one at a time, then pull him alone at full health."] = "Cuidado: {npc:9454} (54) está al fondo de {area:2481}, alrededor de 32.2,67.1, con acechasombras a su alrededor: elimínalos de uno en uno y luego atráelo solo con la salud llena.",
		["First crater"] = "Primer cráter",
		["Fly to {area:702}"] = "Vuela a {area:702}",
		["Follow the road north to the cratered vale and walk to each crater, killing the Entropic Beasts and Horrors between them.\nCareful: an {npc:7136} (53, elite) stands among the craters: walk round it."] = "Sigue el camino al norte hasta la cañada de cráteres y camina hasta cada cráter, matando las bestias entrópicas y los horrores que hay entre ellos.\nCuidado: un {npc:7136} (53, élite) está entre los cráteres: rodéalo.",
		["From {area:702}, fly to {area:1116}."] = "Desde {area:702}, vuela a {area:1116}.",
		["Into {zone:1452}"] = "Hacia {zone:1452}",
		["Lead {npc:7774} back to {npc:7765} at walking pace: she wanders off, so ring the bell to call her back (not in combat), and clear the harpies on the way before she reaches them."] = "Lleva a {npc:7774} de vuelta con {npc:7765} al paso: se aleja, así que toca la campana para llamarla (no en combate), y despeja las arpías del camino antes de que llegue a ellas.",
		["Portal to {zone:1438}"] = "Portal a {zone:1438}",
		["Putrescent organs: kill these as you meet them"] = "Órganos putrefactos: mátalos a medida que los encuentres",
		["Ride east along the road to {area:2255}."] = "Cabalga al este por el camino hasta {area:2255}.",
		["Ride north up the road from the Sanctuary, all the way to the cave mouth of {area:1769}; {npc:15395} guards it."] = "Cabalga al norte por el camino desde el Santuario, hasta llegar a la entrada de la cueva de {area:1769}; {npc:15395} la vigila.",
		["Ride south-east from {area:1763} to the {area:2479}, the druids' camp by the road in southern {zone:1448}."] = "Cabalga al sureste desde {area:1763} hasta {area:2479}, el campamento de los druidas junto al camino en el sur de {zone:1448}.",
		["Ride west into the Ravenwind Ruins: {npc:7774} hides in the small round building at the back. Open the chest beside her for {item:9189}: it lasts 15 minutes, like the quest."] = "Cabalga al oeste hacia las Ruinas de Viento Cuervo: {npc:7774} se esconde en el pequeño edificio redondo del fondo. Abre el cofre junto a ella para obtener {item:9189}: dura 15 minutos, igual que la misión.",
		["Second crater"] = "Segundo cráter",
		["The Jadefire satyrs hold the glen west of the road, with {npc:9454} at its back.\nCareful: Jadefire Shadowstalkers (level 51-52) use Sneak and {spell:7992} and are stealthed, so they often join fights uninvited.\nCursed Oozes slide about the glen's streams: kill them and use Laris's Empty Ooze Jar on their remains."] = "Los sátiros Fuego de Jade ocupan la cañada al oeste del camino, con {npc:9454} al fondo.\nCuidado: Los acechasombras Fuego de Jade (nivel 51-52) usan Sigilo y {spell:7992} y van ocultos, así que a menudo se suman a las peleas sin que los llames.\nLos mocos malditos se deslizan por los arroyos de la cañada: mátalos y usa el tarro vacío para mocos de Laris sobre sus restos.",
		["The Warpwood treants of {area:1767}, east of {area:2618}, carry the {item:11503}."] = "Los antárboles Combadera de {area:1767}, al este de {area:2618}, llevan {item:11503}.",
		["The giant {npc:7765} sits just north-west of {npc:7775}'s camp."] = "El gigante {npc:7765} está sentado justo al noroeste del campamento de {npc:7775}.",
		["The {area:2479}"] = "{area:2479}",
		["The {item:11242} grows inside a ruined building north of {npc:7765}: climb in through the break in its wall from the ledge beside it."] = "La {item:11242} crece dentro de un edificio en ruinas al norte de {npc:7765}: entra por la brecha de su muro desde la cornisa de al lado.",
		["Third crater"] = "Tercer cráter",
		["Use the {item:12922} at the corrupted moonwell in the middle of {area:1763}."] = "Usa {item:12922} en el pozo de la luna corrupto del centro de {area:1763}.",
		["{area:1108}: kill these as you meet them"] = "{area:1108}: mata a estos según te los encuentres",
		["{area:1763} again"] = "{area:1763} otra vez",
		["{area:2618} is the satyr valley in the north-west, with {npc:10648} at its far end. He drops the {quest:939}; every Jadefire satyr can drop {item:11674}.\nCareful: {npc:10648} (55) stands at the valley's far end with Hellcallers (53-54) around him: clear them one at a time before you pull him."] = "{area:2618} es el valle de los sátiros en el noroeste, con {npc:10648} al fondo. Él suelta {quest:939}; cualquier sátiro Fuego de Jade puede soltar {item:11674}.\nCuidado: {npc:10648} (55) está al fondo del valle con invocadores infernales (53-54) a su alrededor: elimínalos de uno en uno antes de atraerlo.",
		["{area:2618}: kill these as you meet them"] = "{area:2618}: mata a estos según te los encuentres",
		["{area:702} flight master"] = "Maestro de vuelo de {area:702}",
		["{item:11949}: Tainted Oozes slide about {area:1763}'s fel pools"] = "{item:11949}: los mocos corruptos se deslizan por las pozas viles de {area:1763}",
		["{item:18904}, on the Wave and Deep Striders in the water"] = "{item:18904}, en los Zancaolas y Zancaprofundas del agua",
		["{item:18958}, from the Sea Sprays"] = "{item:18958}, de los Rocíos del mar",
		["{npc:10920}: {quest:86577}, from the bears and wolves you meet in {zone:1448}"] = "{npc:10920}: {quest:86577}, de los osos y lobos que encuentres en {zone:1448}",
		["{npc:11554} the furbolg stands by the road just south of the {area:2479}."] = "{npc:11554}, el fúrbolg, está junto al camino justo al sur de {area:2479}.",
		["{npc:11556} stands right at the {zone:1452} exit of {area:1769}'s tunnel, where you come out."] = "{npc:11556} está justo en la salida a {zone:1452} del túnel de {area:1769}, por donde sales.",
		["{npc:11558}: walks around here: look inside the circle on the map"] = "{npc:11558}: recorre esta zona: busca dentro del círculo del mapa",
		["{npc:15395} waits at the north end of {zone:1448}"] = "{npc:15395} espera en el extremo norte de {zone:1448}",
		["{npc:4217}, upstairs"] = "{npc:4217}, arriba",
		["{npc:7740}: {quest:162}, from {area:976}"] = "{npc:7740}: {quest:162}, desde {area:976}",
		["{npc:7907} stands upstairs, above {npc:7916}: go up inside, the arrow cannot tell the floors apart."] = "{npc:7907} está arriba, encima de {npc:7916}: sube por adentro, la flecha no distingue los pisos.",
		["{npc:9116}, inside"] = "{npc:9116}, adentro",
		["{npc:9528}, in the ruins just east of {npc:11554}"] = "{npc:9528}, en las ruinas justo al este de {npc:11554}",
		["{zone:1448}'s Angerclaw bears and Felpaw wolves carry the putrescent organs {npc:10920} wants: the Bears and Wolves (47-48) of the south and the Maulers and Scavengers (49-50) along the road north of {area:1763}. Kill them as you ride between the stops."] = "Los osos Zarpira y los lobos Zarpavil de {zone:1448} llevan los órganos putrefactos que quiere {npc:10920}: los osos y lobos (47-48) del sur y los magulladores y carroñeros (49-50) a lo largo del camino al norte de {area:1763}. Mátalos mientras cabalgas entre las paradas.",
		["{zone:1455} has no druid trainer"] = "{zone:1455} no tiene instructor de druidas",
} end)()
t.guides["forever/alliance/50-60/03-winterspring"] = (function() return {
		["Below ground"] = "Bajo tierra",
		["Bones and equipment"] = "Huesos y equipo",
		["Careful: Ancient Irontree Walkers, level 59 elites, stand among the {quest:5086}: work the Horrors at the camp's north-east tip (about 50.6,22.4), one at a time, and look for a walker before each pull."] = "Cuidado: los Caminantes ancestrales Troncoferro, élites de nivel 59, están entre {quest:5086}: encárgate de los Horrores en la punta noreste del campamento (alrededor de 50.6,22.4), de uno en uno, y busca un caminante antes de cada atracción.",
		["Cross the south of the crater to {npc:9619} by the ramp."] = "Cruza el sur del cráter hasta {npc:9619}, junto a la rampa.",
		["Eastern Pylon and the crate"] = "Pilón del este y el cajón",
		["Escort {npc:9999}"] = "Escolta a {npc:9999}",
		["Fly to Theramore"] = "Vuela a Isla Theramore",
		["Fly to {area:2255}"] = "Vuela a {area:2255}",
		["Fly to {area:392}"] = "Vuela a {area:392}",
		["Fly to {area:415}"] = "Vuela a {area:415}",
		["Fly to {area:541}"] = "Vuela a {area:541}",
		["Fly to {area:976}"] = "Vuela a {area:976}",
		["From Theramore, ride west into the {zone:1413} and north up the coast to {area:392}."] = "Desde Theramore, cabalga al oeste hacia {zone:1413} y al norte por la costa hasta {area:392}.",
		["Into {zone:1452}"] = "Hacia {zone:1452}",
		["Lead her out of {area:1770} and keep her alive until she is outside the cave: clear the way back first."] = "Llévala fuera de {area:1770} y mantenla con vida hasta que esté afuera de la cueva: despeja antes el camino de vuelta.",
		["Lead {npc:9999} north to {area:541}. When he faints, use {item:11804} on him to wake him."] = "Lleva a {npc:9999} al norte hasta {area:541}. Cuando se desmaye, usa {item:11804} en él para despertarlo.",
		["Pristine Yeti Horns"] = "Cuernos prístinos de yeti ({item:12367})",
		["Ride back south-east to the Sanctuary."] = "Cabalga de vuelta al sureste hasta el Santuario.",
		["Ride east along the road to {area:2255}."] = "Cabalga al este por el camino hasta {area:2255}.",
		["Ride east to {area:1943}, where the robot stands among the gorillas. Stay out of the deep cave there."] = "Cabalga al este hasta {area:1943}, donde el robot está entre los gorilas. No entres en la cueva profunda de allí.",
		["Ride east to {area:537}, climb it and use {npc:10541} at the lava vents near the top."] = "Cabalga al este hasta {area:537}, súbela y usa {npc:10541} en las grietas de lava cerca de la cima.",
		["Ride north along the east side to the gorilla plateau. {npc:9622}, a level 55 gorilla, sits in its deepest cave: clear the gorillas at the cave mouth first."] = "Cabalga al norte por el lado este hasta la meseta de los gorilas. {npc:9622}, un gorila de nivel 55, está en su cueva más profunda: limpia antes los gorilas de la boca de la cueva.",
		["Ride north out of {area:415} into {zone:1448} to the {area:2479}, the druids' camp by the road."] = "Cabalga al norte saliendo de {area:415} hasta {zone:1448}, a {area:2479}, el campamento de los druidas junto al camino.",
		["Ride south-west to {npc:7771}'s camp at the {area:1938}."] = "Cabalga al suroeste hasta el campamento de {npc:7771} en {area:1938}.",
		["Tar Beasts wallow in the {area:538}; the fire elementals of {area:537} in the middle carry the ash; the Gorishi wasps of the {area:540} in the south carry the gland. Every creature in the crater can drop {item:11018}.\nCareful: Gorishi Workers that drop below 45% health have a 50% chance to call for help from allies within 25 yd."] = "Las bestias de alquitrán se revuelcan en {area:538}; los elementales de fuego de {area:537}, en el centro, llevan la ceniza; las avispas Gorishi de {area:540}, en el sur, llevan la glándula. Cualquier criatura del cráter puede soltar {item:11018}.\nCuidado: Las obreras Gorishi que bajan del 45% de salud tienen un 50% de probabilidad de pedir ayuda a los aliados a menos de 25 m.",
		["The Gorishi hive"] = "La colmena Gorishi",
		["The Tar Beasts and Tar Lords wallow in the {area:538}, south of the refuge on the way down into the crater."] = "Las Bestias de alquitrán y los Señores del alquitrán se revuelcan en {area:538}, al sur del refugio, de camino al cráter.",
		["The crater"] = "El cráter",
		["The gorillas live on {area:1943}, east of {area:541}. Keep their pelts for {npc:9619}. Stay out of the deepest cave: {npc:9622} is level 55.\nCareful: Un'Goro Gorillas (level 50-51) call for help from allies within 20 yd once they drop to 25% health. There is a cave full of apes in the area, and fighting there brings many adds."] = "Los gorilas viven en {area:1943}, al este de {area:541}. Guarda sus pieles para {npc:9619}. No entres en la cueva más profunda: {npc:9622} es de nivel 55.\nCuidado: Los gorilas de Un'Goro (nivel 50-51) piden ayuda a los aliados a menos de 20 m cuando bajan al 25% de salud. En la zona hay una cueva llena de simios, y pelear ahí trae muchos enemigos de más.",
		["The gorillas live on {area:1943}, just east of the pylon: take the pelts for {npc:9619} now, while you are up here. Stay out of the deepest cave: {npc:9622} is level 55.\nCareful: Un'Goro Gorillas (level 50-51) call for help from allies within 20 yd once they drop to 25% health. There is a cave full of apes in the area, and fighting there brings many adds."] = "Los gorilas viven en {area:1943}, justo al este del pilón: consigue ahora las pieles para {npc:9619}, ya que estás aquí arriba. No entres en la cueva más profunda: {npc:9622} es de nivel 55.\nCuidado: Los Gorilas de Un'Goro (nivel 50-51) piden ayuda a aliados a menos de 20 m cuando bajan al 25% de salud. Hay una cueva llena de simios en la zona, y pelear allí atrae a muchos enemigos más.",
		["The pelts come from the gorillas on {area:1943}"] = "Las pieles salen de los gorilas de {area:1943}",
		["The pylon stands on the eastern cliffs above {npc:9684}'s lair; the expedition's {item:11113} sits at the abandoned camp in the eastern jungle."] = "El pilón está en los acantilados del este, sobre la guarida de {npc:9684}; el {item:11113} de la expedición está en el campamento abandonado de la jungla del este.",
		["The pylon stands on the western cliffs."] = "El pilón está en los acantilados del oeste.",
		["The wooden sign beside {npc:9997}"] = "El letrero de madera junto a {npc:9997}",
		["The {area:2479}"] = "{area:2479}",
		["The {item:280417} is a short ride west of {npc:9619}'s camp."] = "El {item:280417} está a poca distancia al oeste del campamento de {npc:9619}.",
		["The {quest:5086}"] = "{quest:5086}",
		["Wait a moment for {npc:9116}"] = "Espera un momento a {npc:9116}",
		["West along the south of the crater: the Gorishi hive fills it. Use the Scraping Vial on a hatchery, a chamber with hanging larvae."] = "Al oeste por el sur del cráter: la colmena Gorishi lo llena. Usa el Vial raspador en una sala de cría, una cámara con larvas colgando.",
		["{area:1770} braziers"] = "Braseros de {area:1770}",
		["{area:1942}: kill these as you meet them"] = "{area:1942}: mata a estos según te los encuentres",
		["{area:1943}: kill these as you meet them"] = "{area:1943}: mata a estos según te los encuentres",
		["{area:2246}: kill these as you meet them"] = "{area:2246}: mata a estos según te los encuentres",
		["{area:392} flight master"] = "Maestro de vuelo de {area:392}",
		["{area:489} flight master"] = "Maestro de vuelo de {area:489}",
		["{area:538}: kill these as you meet them"] = "{area:538}: mata a estos según te los encuentres",
		["{area:541} flight master"] = "Maestro de vuelo de {area:541}",
		["{area:976} flight master"] = "Maestro de vuelo de {area:976}",
		["{item:11478}; below ground"] = "{item:11478}; bajo tierra",
		["{item:11479}; below ground"] = "{item:11479}; bajo tierra",
		["{item:11480}; below ground"] = "{item:11480}; bajo tierra",
		["{npc:10301}'s camp"] = "El campamento de {npc:10301}",
		["{npc:11016}, in her cell; below ground"] = "{npc:11016}, en su celda; bajo tierra",
		["{npc:11020}, below ground"] = "{npc:11020}, bajo tierra",
		["{npc:11557}; below ground"] = "{npc:11557}; bajo tierra",
		["{npc:11558}: walks around here: look inside the circle on the map"] = "{npc:11558}: recorre esta zona: busca dentro del círculo del mapa",
		["{npc:5594}, inside"] = "{npc:5594}, adentro",
		["{npc:8496}, inside"] = "{npc:8496}, adentro",
		["{npc:9116}, inside"] = "{npc:9116}, adentro",
		["{npc:9117}, below ground"] = "{npc:9117}, bajo tierra",
		["{npc:9299} is a ghost at the graveyard just east of town: drink a {item:11243} there, which kills you, release your spirit and talk to him as a ghost. Then run back to your body to come back to life: the gravestone stands nearby."] = "{npc:9299} es un fantasma en el cementerio justo al este del pueblo: bebe un {item:11243} allí, lo cual te mata, libera tu espíritu y habla con él como fantasma. Luego corre de vuelta a tu cuerpo para revivir: la lápida está cerca.",
