t.guides["forever/alliance/50-60/04-western-plaguelands"] = (function() return {
		["Andorhal"] = "Andorhal",
		["Boat to {area:150}"] = "Barco a {area:150}",
		["Climb the hill west of {area:190} to look down on the town.\nCareful: Sentinels posted at the gate can detect stealthed players. Additional sentinels are found within the town, and an elite walks a patrol route nearby."] = "Sube a la colina al oeste de {area:190} para mirar el pueblo desde arriba.\nCuidado: Los centinelas apostados en la puerta pueden detectar a los jugadores en sigilo. Hay más centinelas dentro del pueblo, y un élite patrulla cerca.",
		["Diseased Grizzlies"] = "Osos pardos malsanos",
		["Fly to {area:150}"] = "Vuela a {area:150}",
		["Fly to {area:1537}"] = "Vuela a {area:1537}",
		["Fly to {area:271}"] = "Vuela a {area:271}",
		["Fly to {area:3197}"] = "Vuela a {area:3197}",
		["Fly to {area:442}"] = "Vuela a {area:442}",
		["Fly to {area:702}"] = "Vuela a {area:702}",
		["Fly to {zone:1453}"] = "Vuela a {zone:1453}",
		["For {npc:11053} at {area:3197}, at the end of this guide"] = "Para {npc:11053} en {area:3197}, al final de esta guía",
		["For {zone:1453}: keep it"] = "Para {zone:1453}: guárdala",
		["Inside"] = "Adentro",
		["Into {zone:1423}"] = "Hacia {zone:1423}",
		["Listen to his story"] = "Escucha su historia",
		["Mark {npc:10902} with the {item:12815}"] = "Marca {npc:10902} con la {item:12815}",
		["Mark {npc:10903} with the {item:12815}"] = "Marca {npc:10903} con la {item:12815}",
		["Mark {npc:10904} with the {item:12815}"] = "Marca {npc:10904} con la {item:12815}",
		["Mark {npc:10905} with the {item:12815}"] = "Marca {npc:10905} con la {item:12815}",
		["Portal to {zone:1438}"] = "Portal a {zone:1438}",
		["Pureheart, Dumah, Valorfist and MacDonnell stand around the middle of the camp, by the flight master."] = "Puricorazón, Dumah, Puño de Valor y MacDonnell están en el centro del campamento, junto al maestro de vuelo.",
		["Radley and Durgen"] = "Radley y Durgen",
		["Ride north up the road to the Northridge lumber mill; {npc:11610} hides at the camp's edge."] = "Sigue el camino al norte hasta el Aserradero Crestanorte; {npc:11610} se esconde en el borde del campamento.",
		["Ride north-west to {area:2276}, at the edge of the {area:2277}."] = "Cabalga al noroeste hasta {area:2276}, en el borde de {area:2277}.",
		["Skeletal Flayers and Slavering Ghouls roam the fields north of the camp; all the Scourge here drop Scourgestones while you wear the {quest:5401} (equip it as a trinket first).\nCareful: These undead notice you from far away, and other undead nearby join the fight when one is pulled.\nCareful: The {npc:10411} (3 spawns, 15 min respawn) turns invisible when out of combat and calls in Rockwing Gargoyles once a fight starts."] = "Los Despellejadores esqueléticos y Necrófagos esclavizantes rondan los campos al norte del campamento; toda la Plaga de aquí suelta piedras de la Plaga mientras lleves la {quest:5401} (equípala primero como abalorio).\nCuidado: Estos no-muertos te detectan desde lejos, y otros no-muertos cercanos se suman a la pelea cuando atraes a uno.\nCuidado: {npc:10411} (3 apariciones, reaparece en 15 min) se vuelve invisible fuera de combate y llama a Gárgolas Ventorroca en cuanto empieza una pelea.",
		["Stormwind City"] = "Ciudad de Ventormenta",
		["The Andorhal watchtowers"] = "Las atalayas de Andorhal",
		["The Scarlet Crusade"] = "La Cruzada Escarlata",
		["The Scarlet Medics, Hunters, Knights and Mages patrol the lumber camp and the road toward {area:190}."] = "Los Médicos, Cazadores, Caballeros y Magos Escarlata patrullan el aserradero y el camino hacia {area:190}.",
		["The flight lands in {area:702}. {npc:7916} stands a short walk north-west of the flight master."] = "El vuelo aterriza en {area:702}. {npc:7916} está a un paseo corto al noroeste del maestro de vuelo.",
		["The lake for {quest:5845}"] = "El lago para {quest:5845}",
		["The three pieces of the doll lie in the ruined houses of {area:2262}; picking one up can call out ghosts. Combine them into the doll."] = "Las tres piezas de la muñeca están en las casas en ruinas de {area:2262}; recoger una puede atraer fantasmas. Combínalas para formar la muñeca.",
		["Underwater"] = "Bajo el agua",
		["Upstairs"] = "Arriba",
		["{area:150} flight master"] = "Maestro de vuelo de {area:150}",
		["{area:190} overlook"] = "Mirador de {area:190}",
		["{area:197}: kill these as you meet them"] = "{area:197}: mata a estos según te los encuentres",
		["{area:199} cauldron"] = "Caldero de {area:199}",
		["{area:202} cauldron"] = "Caldero de {area:202}",
		["{area:202}: kill these as you meet them"] = "{area:202}: mata a estos según te los encuentres",
		["{area:2277}: kill these as you meet them"] = "{area:2277}: mata a estos según te los encuentres",
		["{area:3197} flight master"] = "Maestro de vuelo de {area:3197}",
		["{area:702} flight master"] = "Maestro de vuelo de {area:702}",
		["{item:12841}: wear the {quest:5401} while you kill"] = "{item:12841}: lleva puesta la {quest:5401} mientras matas",
		["{item:12886}; inside"] = "{item:12886}; adentro",
		["{item:12888}; inside"] = "{item:12888}; adentro",
		["{item:12894}, at the monument"] = "{item:12894}, en el monumento",
		["{item:12954}; inside"] = "{item:12954}; adentro",
		["{item:12956}; underwater"] = "{item:12956}; bajo el agua",
		["{item:14047}, from your bags"] = "{item:14047}, de tus bolsas",
		["{item:2592}, from your bags"] = "{item:2592}, de tus bolsas",
		["{item:4306}, from your bags"] = "{item:4306}, de tus bolsas",
		["{item:4338}, from your bags"] = "{item:4338}, de tus bolsas",
		["{npc:10926}'s doll"] = "La muñeca de {npc:10926}",
		["{npc:10927}: keep it for {area:2262}"] = "{npc:10927}: guárdala para {area:2262}",
		["{npc:11063}'s next task, at {area:2264}, is among Scourge of 57-60: skip it."] = "La siguiente tarea de {npc:11063}, en {area:2264}, transcurre entre la Plaga de nivel 57-60: omítela.",
		["{npc:11610} hides at the lumber camp's edge."] = "{npc:11610} se esconde en el borde del campamento maderero.",
		["{npc:14722} takes sixty Silk, sixty Mageweave and sixty {item:14047}: hand in what you carry (or buy at the Auction House), skip the rest."] = "{npc:14722} acepta sesenta de paño de seda, sesenta de tejido mágico y sesenta de {item:14047}: entrega lo que tengas (o cómpralo en la casa de subastas) y sáltate el resto.",
		["{npc:14722}, in the {object:2096}"] = "{npc:14722}, en {object:2096}",
		["{npc:1852} is a level 61 elite"] = "{npc:1852} es élite de nivel 61",
		["{npc:332}, in SI:7"] = "{npc:332}, en el IV:7",
		["{npc:3520}, who walks the canals"] = "{npc:3520}, que recorre los canales",
		["{npc:4217}, upstairs"] = "{npc:4217}, arriba",
		["{object:175894}, inside"] = "{object:175894}, adentro",
		["{object:175924}, in the farmhouse; inside"] = "{object:175924}, en la casa de la granja; adentro",
		["{quest:5210}, at {area:2268}: keep it"] = "{quest:5210}, en {area:2268}: guárdala",
		["{zone:1423}: kill these as you meet them"] = "{zone:1423}: mata a estos según te los encuentres",
		["{zone:1453} flight master"] = "Maestro de vuelo de {zone:1453}",
		["{zone:1455} flight master"] = "Maestro de vuelo de {zone:1455}",
		["{zone:1455} has no druid trainer"] = "{zone:1455} no tiene instructor de druidas",
} end)()
t.guides["forever/alliance/50-60/06-silithus"] = (function() return {
		["Below ground"] = "Bajo tierra",
		["Bronzebeard's Encampment"] = "Campamento Barbabronce",
		["Fly to {area:541}"] = "Vuela a {area:541}",
		["From the hold, west into the sands: Dredge Crushers dig there; Stonelash Pincers, Flayers and Rock Stalkers hunt the same sands."] = "Desde el bastión, al oeste hacia las arenas: allí excavan los trituradores deslizantes; los tenazarios latipiedra, desolladores y acecharrocas cazan en las mismas arenas.",
		["Hand him the ten texts you kept"] = "Entrégale los diez textos que guardaste",
		["Havunth's camp sits just west of {area:3425}.\nCareful: Havunth is level 60: clear his camp first and fight him at full health."] = "El campamento de Havunth está justo al oeste de {area:3425}.\nCuidado: Havunth es de nivel 60: limpia primero su campamento y pelea con él con la salud al máximo.",
		["Into {zone:1451}"] = "Hacia {zone:1451}",
		["Level 60"] = "Nivel 60",
		["Ride back south-east to the hermit."] = "Cabalga de vuelta al sureste hasta el ermitaño.",
		["Ride back south-west to the {area:2742} tower in {area:2738}; climb it and kill the ambushers that rise for the encrusted object."] = "Cabalga de vuelta al suroeste hasta la torre de {area:2742} en {area:2738}; súbela y mata a los emboscadores que surgen por el objeto incrustado.",
		["Ride north along the west side to Mayna's small camp.\nCareful: Mayna is level 60: clear her camp first and fight her at full health."] = "Cabalga al norte por el lado oeste hasta el pequeño campamento de Mayna.\nCuidado: Mayna es de nivel 60: limpia primero su campamento y pelea con ella con la salud al máximo.",
		["Ride on west to {area:3425}. {npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Sigue cabalgando al oeste hasta {area:3425}. {npc:15189} está en el piso de arriba de su edificio: sube por adentro, la flecha no distingue los pisos.",
		["Ride south-west to the dwarves' camp near the southern mountains and question {npc:15171} and {npc:15170}. {npc:15190}'s satchel lies in the sand south-east of the camp, where Deathclasp, an elite scorpid, patrols: grab it while he is away."] = "Cabalga al suroeste hasta el campamento de los enanos cerca de las montañas del sur e interroga a {npc:15171} y {npc:15170}. La cartera de {npc:15190} está en la arena al sureste del campamento, donde patrulla Pinzamorten, un escórpido élite: tómala mientras esté lejos.",
		["Ten more for {quest:8323}"] = "Diez más para {quest:8323}",
		["The hermit hides among the rocks south-east of {area:2738}."] = "El ermitaño se esconde entre las rocas al sureste de {area:2738}.",
		["The {area:2742} tower"] = "La torre de {area:2742}",
		["The {area:3098}"] = "{area:3098}",
		["Twilight Tablet Fragments"] = "{item:20378}",
		["Twilight's Hammer cultists"] = "Sectarios del Martillo Crepuscular",
		["{area:2742}: kill these as you meet them"] = "{area:2742}: mata a estos según te los encuentres",
		["{npc:11741} walks around here: look inside the circle on the map"] = "{npc:11741} recorre esta zona: busca dentro del círculo del mapa",
		["{npc:15183}: the tablet fragments come from the Twilight dig"] = "{npc:15183}: los fragmentos de tablilla salen de la excavación Crepuscular",
		["{npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15189} está en el piso de arriba de su edificio: sube por dentro, la flecha no distingue los pisos.",
		["{npc:15189}, upstairs"] = "{npc:15189}, en el piso de arriba",
		["{npc:15190} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15190} está en el piso de arriba de su edificio: sube por dentro, la flecha no distingue los pisos.",
		["{npc:15190}, upstairs beside {npc:15189}"] = "{npc:15190}, arriba junto a {npc:15189}",
		["{npc:17080} camps outside {area:2743}, the western hive. Pick up a Silithyst at one of the red geysers nearby and carry it to the Alliance extractor at his camp.\nCareful: You lose the Silithyst if you mount, stealth, use {spell:642}, {spell:5384} or Vanish. Blink and {spell:17} do not drop it."] = "{npc:17080} acampa afuera de {area:2743}, la colmena del oeste. Recoge una silitista en uno de los géiseres rojos cercanos y llévala al extractor de la Alianza de su campamento.\nCuidado: Pierdes la silitista si montas, entras en sigilo o usas {spell:642}, {spell:5384} o Desvanecerse. Traslación y {spell:17} no la hacen caer.",
		["{npc:17082}, at the Alliance tents: for {npc:17080} at {area:2743}"] = "{npc:17082}, en las tiendas de la Alianza: para {npc:17080} en {area:2743}",
		["{zone:1451}: kill these as you meet them"] = "{zone:1451}: mata a estos según te los encuentres",
} end)()
t.guides["forever/alliance/dwarf/01-dun-morogh"] = (function() return {
		["Back east through {area:131}: {npc:1252} by Eric's campfire takes the {quest:287} report, and {npc:1269} the cogs and gears. The Shaman quest here waits for level 10: a Shaman still short of it finishes on the Ice Claw Bears (7-8), Snow Leopards and Large Crag Boars in the fields just south of {area:131}."] = "De vuelta al este por {area:131}: {npc:1252}, junto a la fogata de Eric, recibe el informe de {quest:287}, y {npc:1269} los engranajes. La misión de chamán de aquí requiere nivel 10: si a un chamán aún le falta, que lo complete con los osos zarpahelada (7-8), leopardos de las nieves y jabalíes del risco grandes en los campos justo al sur de {area:131}.",
		["Back north to {area:77} on the way to the tunnel: {npc:2756} stands by {npc:8416} at its door. Gozwin's camp is in the hills just north-west; the {npc:269075} (level 6) prowls around it."] = "Vuelve al norte a {area:77} de camino al túnel: {npc:2756} está junto a {npc:8416} en su puerta. El campamento de Gozwin está en las colinas justo al noroeste; {npc:269075} (nivel 6) merodea a su alrededor.",
		["Back north to {npc:257808}'s camp above the tunnel. {npc:257808} gives you the {item:6636}. Climb to the peak above his camp, drink the Sapta beside the Spirit Stone and defeat the {npc:5893}, then place its {item:6655} in the {object:61934}, atop the Shrine of Eternal Flame."] = "De vuelta al norte al campamento de {npc:257808}, sobre el túnel. {npc:257808} te da la {item:6636}. Sube a la cima sobre su campamento, bebe la sapta junto a la piedra espiritual y derrota a {npc:5893}; luego pon su {item:6655} en {object:61934}, en lo alto del santuario de la Llama Eterna.",
		["Back through the tunnel to {npc:257597}' cave above the farm, then west along the road to {zone:1455}."] = "De vuelta por el túnel a la cueva de {npc:257597}, sobre la granja, y luego al oeste por el camino hasta {zone:1455}.",
		["Back to the tunnel post"] = "De vuelta al puesto del túnel",
		["Back to the {area:136}, the wendigo cave south-west of {area:131} where {npc:271546} camps. Flintfire's shipments lie on the cave floor, {npc:278166} is missing deep inside, and {quest:98326} (level 9) keeps the {item:280426} at the back.\nCareful: Wendigos, Elder Wendigos and Wendigo Shamans (up to level 8) stand close together inside the cave, so fights easily pull several at once; drawing them out one at a time with ranged attacks avoids this."] = "De vuelta a {area:136}, la cueva de wendigos al suroeste de {area:131} donde acampa {npc:271546}. Los cargamentos de Fuegosílex están en el suelo de la cueva, {npc:278166} está perdido en lo más hondo y {quest:98326} (nivel 9) guarda el {item:280426} al fondo.\nCuidado: los wendigos, wendigos ancianos y chamanes wendigo (hasta nivel 8) están muy juntos dentro de la cueva, así que es fácil atraer a varios a la vez; sacarlos de uno en uno con ataques a distancia lo evita.",
		["Back to the {area:925}"] = "De vuelta a {area:925}",
		["Back to {area:77}"] = "De vuelta a {area:77}",
		["Back to {npc:257446} in {area:77}. He gives you the {item:6635}: take the rubble-marked path that climbs west from the south of the valley to the Spirit Stone on the ridge, drink the Sapta beside it and speak to the {npc:5891}, then bring its {item:6656} back to Teo."] = "De vuelta con {npc:257446} en {area:77}. Te da la {item:6635}: toma el sendero marcado con escombros que sube al oeste desde el sur del valle hasta la piedra espiritual de la cresta, bebe la sapta a su lado y habla con {npc:5891}; luego llévale su {item:6656} a Teo.",
		["Back to {npc:257597}"] = "De vuelta con {npc:257597}",
		["Below ground"] = "Bajo tierra",
		["Brewnall: kill these as you meet them"] = "Brewnall: mata a estos según te los encuentres",
		["Catch {npc:13016}"] = "Atrapa {npc:13016}",
		["Crag Boars and Young Black Bears roam the fields from Rumbleshot's camp north-east to {area:131} and the depot: kill them on the walk back."] = "Los jabalíes de los riscos y los osos negros jóvenes recorren los campos desde el campamento de Retumbatiro al noreste hasta {area:131} y el depósito: mátalos en el camino de vuelta.",
		["Druid trainer"] = "Instructor de druidas",
		["Each of Grif Wildheart's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him at the {area:131} smithy. Large Crag Boars, Snow Leopards and Ice Claw Bears all roam the fields just south and east of {area:131}."] = "Cada misión de Grif Corazón Salvaje te da una {item:15908}: úsala en la bestia que nombra y luego devuélvele la vara en la herrería de {area:131}. Los Jabalíes del risco grandes ({npc:1126}), los Leopardos de las nieves ({npc:1201}) y los Osos zarpahelada ({npc:1196}) recorren los campos justo al sur y al este de {area:131}.",
		["East along the hills to the mine at the north end of the loch: the Miners' League crates sit in its tunnels, among more Tunnel Rats. Shamans: the Tunnel Rat Geomancers (level 12-13) here carry the {item:5026}.\nCareful: the Tunnel Rat Geomancers (12-13) cast from range in the narrow tunnels: pull them one at a time."] = "Al este por las colinas hasta la mina en el extremo norte del lago: las cajas de la Liga de Expedicionarios están en sus túneles, entre más ratatúneles. Chamanes: los geománticos Ratatúnel (nivel 12-13) de aquí llevan el {item:5026}.\nCuidado: los geománticos Ratatúnel (12-13) lanzan hechizos a distancia en los túneles estrechos: atráelos de uno en uno.",
		["East back into {object:171524}: the {area:2257} leaves from its east end. Ride it to {zone:1453}."] = "Al este de vuelta hasta {object:171524}: {area:2257} sale de su extremo este. Tómalo hasta {zone:1453}.",
		["East from the {object:32372} into {object:171524}: the {object:660964} lie by its mailbox. From here the guide goes once round the city: north to the {object:32383}, west to the {object:32362}, south through the Commons to the {object:171709}, east through the {object:32359} and back to {object:171524} for the tram."] = "Al este desde {object:32372} hasta {object:171524}: {object:660964} está junto a su buzón. Desde aquí la guía da una vuelta por la ciudad: al norte hasta {object:32383}, al oeste hasta {object:32362}, al sur por la Explanada hasta {object:171709}, al este por {object:32359} y de vuelta a {object:171524} para el tranvía.",
		["East to the {object:32359}: the warrior trainers and {npc:11865} in the {object:32390}, the hunter trainers beside it."] = "Al este hasta {object:32359}: los instructores de guerreros y {npc:11865} en {object:32390}, y los instructores de cazadores a su lado.",
		["Farsen camps on the ridge overlooking the {area:134} from the west. Talk to him for his farsight."] = "Farsen acampa en la cresta que domina {area:134} desde el oeste. Habla con él para usar su visión lejana.",
		["Feather Charms, from the Frostmane Novices"] = "Talismanes de plumas ({item:6753}), de los Novicios Peloescarcha ({npc:946})",
		["Firewood"] = "Leña",
		["Follow the road east past the depot to {area:138}."] = "Sigue el camino al este pasando el almacén hasta {area:138}.",
		["Follow the road north-east from {area:131} to the depot below the {zone:1455} road."] = "Sigue el camino al noreste desde {area:131} hasta el almacén bajo el camino de {zone:1455}.",
		["Follow the road through the tunnel and north-east to {area:131}. Start outside: {npc:1252} and Eric's campfire are in front of the {area:2102}."] = "Sigue el camino por el túnel y al noreste hasta {area:131}. Empieza afuera: {npc:1252} y la hoguera de Eric están frente a {area:2102}.",
		["From the {object:28027} south-west to {object:2098}: {npc:1646}'s compass is in his old house in {zone:1436}, on the way. The flight master and the {object:2096} are south of the square."] = "Desde {object:28027} al suroeste hasta {object:2098}: la brújula de {npc:1646} está en su vieja casa de {zone:1436}, en el camino. El maestro de vuelo y {object:2096} están al sur de la plaza.",
		["From the {quest:2997} she gives you"] = "Del {quest:2997} que te da",
		["Frostmane Troll Whelps fill the slopes south and east of {npc:786}'s camp."] = "Las Crías de trol Peloescarcha ({npc:706}) llenan las laderas al sur y al este del campamento de {npc:786}.",
		["Gretchen camps just outside the {area:136}, the wendigo cave south-west of {area:131}. The den comes after {area:137}, once its level 8 Elder Wendigos and Shamans are no longer above you."] = "Gretchen acampa justo afuera de {area:136}, la cueva de los wendigos al suroeste de {area:131}. La guarida viene después de {area:137}, cuando sus wendigos ancianos y chamanes de nivel 8 ya no te superen.",
		["Head back out of {zone:1455} and east along the road to {area:212}. {npc:6177} lies dead by its shore: use the {item:6866} on him. The Dark Iron Spies sneaking around the lake carry the script."] = "Sal otra vez de {zone:1455} y ve al este por el camino hasta {area:212}. {npc:6177} yace muerto junto a su orilla: usa {item:6866} sobre él. Los espías Hierro Negro que merodean por el lago llevan el escrito.",
		["Heal and fortify {npc:12427}"] = "Sana y fortalece a {npc:12427}",
		["Ice Claw Bears, Elder Crag Boars and Snow Leopards roam the hills around the lake and {area:137}."] = "Los osos zarpahelada, jabalíes del risco ancianos y leopardos de las nieves recorren las colinas alrededor del lago y de {area:137}.",
		["Iceclaw Bear Pendants, from the Frostmane Troll Whelps on the slopes above the camp"] = "Colgantes de oso garrahielo ({item:264356}), de las Crías de trol Peloescarcha ({npc:706}) en las laderas sobre el campamento",
		["Inside {area:77}"] = "Dentro de {area:77}",
		["Kill the Crag Boars on the way: their ribs drop before you have {npc:1267}'s quest and count toward it. Back in the distillery: {npc:1699} teaches {skill:185}, then the ribs go to {npc:1267}."] = "Mata los jabalíes de los riscos por el camino: sus costillas caen antes de tener la misión de {npc:1267} y cuentan para ella. De vuelta en la destilería: {npc:1699} enseña {skill:185}, y luego las costillas van para {npc:1267}.",
		["Last: some classes' trainers stand outside"] = "Por último: los instructores de algunas clases están afuera",
		["Leave {zone:1453} by the main gate and follow the road south to {area:87}: east Elwynn comes before {zone:1436}."] = "Sal de {zone:1453} por la puerta principal y sigue el camino al sur hasta {area:87}: el este de Elwynn va antes que {zone:1436}.",
		["Leper Gnomes wander the {area:133} road north of {area:137} and carry the cogs and gears. {area:135} comes next, in the hills south-west of the village.\nCareful: the Leper Gnomes (8-10) walk the road in twos and threes, and many players died here: pull them one at a time."] = "Los gnomos parias recorren el camino de {area:133} al norte de {area:137} y llevan los engranajes. Después sigue {area:135}, en las colinas al suroeste del pueblo.\nCuidado: los gnomos parias (8-10) andan por el camino de dos en dos y de tres en tres, y muchos jugadores murieron aquí: atráelos de uno en uno.",
		["Level 4 spells"] = "Hechizos de nivel 4",
		["North of the {object:32372}: {npc:258098}, the shaman trainer, stands at the south end of the {object:32383}, the rogue and warlock trainers and {npc:6120} just north of him."] = "Al norte de {object:32372}: {npc:258098}, el instructor de chamanes, está en el extremo sur de {object:32383}, y los instructores de pícaros y brujos y {npc:6120}, justo al norte de él.",
		["North through the hills west of the road to {npc:1343} at the {area:925}. The Tunnel Rat kobolds dig in the hills on the way; Elder Black Bears, Mountain Boars and Forest Lurkers roam the same ground."] = "Al norte por las colinas al oeste del camino hasta {npc:1343}, en {area:925}. Los kóbolds Rata del Túnel cavan en las colinas por el camino; los osos negros ancianos, jabalíes montañeses y acechadores del bosque recorren el mismo terreno.",
		["North up the road to {area:144}. {npc:1340} walks the road through town, {npc:1963} stands outside the {area:2101}, {npc:1681} on the east side of town; {npc:1572} keeps the gryphons."] = "Al norte por el camino hasta {area:144}. {npc:1340} recorre el camino por el pueblo, {npc:1963} está afuera de {area:2101}, {npc:1681} en el lado este del pueblo; {npc:1572} cuida los grifos.",
		["On the road back west to {zone:1455}."] = "En el camino de vuelta al oeste a {zone:1455}.",
		["Ragged Young Wolves roam the snow just south of {area:77}."] = "Los Lobos jóvenes pulgosos rondan la nieve justo al sur de {area:77}.",
		["Ride the tram to {zone:1453}: {npc:13018} waits on the {zone:1453} platform. {npc:5413} stands in the {object:28027}, just outside the tram."] = "Toma el tranvía hasta {zone:1453}: {npc:13018} espera en el andén de {zone:1453}. {npc:5413} está en {object:28027}, justo afuera del tranvía.",
		["Rockjaw Ambushers by {area:212}, north of the quarry, and Rockjaw Backbreakers further east drop the {quest:95214}. Dark Iron Spies sneak around the lake shore east of the quarry; one of them drops the {item:274268}."] = "Los emboscadores Quijarroca junto a {area:212}, al norte de la cantera, y los rompespaldas Quijarroca más al este sueltan {quest:95214}. Los espías Hierro Negro merodean por la orilla del lago al este de la cantera; uno de ellos suelta {item:274268}.",
		["Rockjaw Skullthumpers, Bonesnappers and Ambushers share the quarry and the slopes north of it; the Ambushers drop the {item:268548}."] = "Los machacacráneos, rompehuesos y emboscadores Quijarroca comparten la cantera y las laderas al norte; los emboscadores sueltan {item:268548}.",
		["Rockjaw Troggs and Burly Rockjaw Troggs dig all over the valley floor south of {area:77}."] = "Los Troggs Comepiedras ({npc:707}) y los Troggs Comepiedras fornidos ({npc:724}) cavan por todo el fondo del valle al sur de {area:77}.",
		["Sit by Eric's campfire (type /sit) and wait for the buff. With a profession learned, Eric also offers its Camping 101, which its trainer takes: blacksmithing with {npc:1241} and {skill:129} with {npc:2326} in {area:131}, mining and engineering at {area:189}."] = "Siéntate junto a la fogata de Eric (escribe /sit) y espera el beneficio. Si ya aprendiste una profesión, Eric también ofrece su Campamento 101, que se entrega a su instructor: herrería con {npc:1241} y {skill:129} con {npc:2326} en {area:131}, minería e ingeniería en {area:189}.",
		["Small Crag Boars graze around {npc:714}'s camp and along the west side of the valley."] = "Los Jabalíes del risco pequeños ({npc:708}) pastan alrededor del campamento de {npc:714} y a lo largo del lado oeste del valle.",
		["Snow Leopards and boars roam the snow between the ranch and the quarry. Blacksmiths: Copper Bars come from smelting {item:2770} or the trade vendors."] = "Los Leopardos de las nieves ({npc:1201}) y los jabalíes recorren la nieve entre la granja y la cantera. Herreros: las Barras de cobre ({item:2840}) salen de fundir {item:2770} o de los mercaderes de comercio.",
		["South down the road past the tunnel post into {area:923}: the Stonesplinter Seers (level 13-14) stand among the troggs in its middle. Stay out of the far south end, where Shamans and Bonesnappers (level 15-16) camp, and keep clear of Headsplitter (15) on his walk. The Seers come with other troggs and cast from range: pull one at a time."] = "Al sur por el camino, pasando el puesto del túnel, hasta {area:923}: los videntes Rompecantos (nivel 13-14) están entre los troggs en el centro. No entres al extremo sur, donde acampan chamanes y rompehuesos (nivel 15-16), y aléjate de Partecráneos (15) en su ruta. Los videntes van con otros troggs y lanzan hechizos a distancia: atráelos de uno en uno.",
		["South down the road to {area:144}, finishing the ears, meat and ichor on the way. {npc:1340} walks the road through town."] = "Ve al sur por el camino hasta {area:144}, terminando las orejas, la carne y el icor por el camino. {npc:1340} recorre el camino que atraviesa el pueblo.",
		["South through the Commons: {npc:1274} stands in the {object:171709} with King Magni."] = "Al sur por la Explanada: {npc:1274} está en {object:171709} con el rey Magni.",
		["Stonesplinter troggs"] = "Troggs Rompecantos",
		["The Fire Spirit Stone"] = "La piedra espiritual del fuego",
		["The Scalding Mornbrew lasts five minutes: go straight north to {npc:836} inside {area:77}."] = "La bebida caliente dura cinco minutos: ve directo al norte con {npc:836}, dentro de {area:77}.",
		["The boars"] = "Los jabalíes",
		["The firewood lies in the snow around the frozen lake by the refuge."] = "La leña está en la nieve alrededor del lago helado junto al refugio.",
		["The paladin, priest and mage trainers are in the {object:32386}, in the {object:32362}."] = "Los instructores de paladines, sacerdotes y magos están en {object:32386}, en {object:32362}.",
		["The pilots stand at the depot; {npc:1269} is on the road back west, north of {area:131}."] = "Los pilotos están en el depósito; {npc:1269} está en el camino de vuelta al oeste, al norte de {area:131}.",
		["The quarry lies just east of Farsen's ridge."] = "La cantera está justo al este de la cresta de Farsen.",
		["The quarry troggs"] = "Los troggs de la cantera",
		["The three rifles lie in the snow around the frozen lake by the refuge. Minor Ice Elementals drift around the lake and along the way: kill them as you go for {quest:99160}.\nFinish off the Minor Ice Elementals around the small lake just west of the refuge if you are still short."] = "Los tres rifles están en la nieve alrededor del lago congelado junto al refugio. Los elementales de hielo menores flotan alrededor del lago y por el camino: mátalos sobre la marcha para {quest:99160}.\nTermina los elementales de hielo menores alrededor del laguito justo al oeste del refugio si todavía te faltan.",
		["The troggs"] = "Los troggs",
		["The troll cave"] = "La cueva de los trols",
		["The tunnel"] = "El túnel",
		["The tunnel post"] = "El puesto del túnel",
		["The west hills and the {area:925}"] = "Las colinas del oeste y {area:925}",
		["The {area:133} road"] = "El camino de {area:133}",
		["The {area:2257}"] = "{area:2257}",
		["The {item:2676} grows in baskets up on {area:802}, the snowy slope north of the road between {area:131} and Brewnall: climb from the road west of {area:131}. The Frostmane Seers camped on the ridge drop it too."] = "{item:2676} crece en cestas arriba en {area:802}, la ladera nevada al norte del camino entre {area:131} y Aldea Cervecera: sube desde el camino al oeste de {area:131}. Los videntes Peloescarcha acampados en la cresta también la sueltan.",
		["The {item:6652}"] = "La {item:6652}",
		["The {object:176785} sits next to {npc:271546}, south of the {area:136}."] = "{object:176785} está al lado de {npc:271546}, al sur de {area:136}.",
		["The {object:269} in the basement"] = "{object:269}, en el sótano",
		["The {object:270} in the distillery; below ground"] = "{object:270} de la destilería; bajo tierra",
		["Tram to {zone:1453}"] = "Tranvía a {zone:1453}",
		["Upstairs"] = "Arriba",
		["Use the {item:6866} on {npc:6177}"] = "Usa el {item:6866} en {npc:6177}",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Ya que estás aquí: aprende Bastones con {npc:11867} ({object:2096}, 10 de plata); en un cazador, el arma cuerpo a cuerpo vale sobre todo por sus estadísticas, y las de dos manos son las que más tienen.",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Ya que estás aquí: aprende Bastones con {npc:11867} ({object:2096}, 10 de plata); un bastón tiene más estadísticas de hechizo que un arma de una mano mientras subes de nivel.",
		["While you're here: learn Swords from {npc:11867} ({object:2096}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "Ya que estás aquí: aprende Espadas con {npc:11867} ({object:2096}, 10 de plata); una espada en la mano principal hace subir de nivel a un pícaro a buen ritmo.",
		["While you're here: learn {spell:197} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Paladin fastest."] = "Ya que estás aquí: aprende {spell:197} con {npc:11865} ({object:32359}, 10 de plata); con armas de dos manos un paladín sube de nivel más rápido.",
		["While you're here: learn {spell:197} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "Ya que estás aquí: aprende {spell:197} con {npc:11865} ({object:32359}, 10 de plata); con armas de dos manos un guerrero sube de nivel más rápido.",
		["While you're here: learn {spell:199} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "Ya que estás aquí: aprende {spell:199} con {npc:11865} ({object:32359}, 10 de plata); con armas de dos manos un guerrero sube de nivel más rápido.",
		["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Paladin fastest."] = "Ya que estás aquí: aprende {spell:202} con {npc:11867} ({object:2096}, 10 de plata); con armas de dos manos un paladín sube de nivel más rápido.",
		["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "Ya que estás aquí: aprende {spell:202} con {npc:11867} ({object:2096}, 10 de plata); con armas de dos manos un guerrero sube de nivel más rápido.",
		["You start in front of {area:77}, the stone hall at the north end of the valley. {npc:658} waits outside the door."] = "Empiezas frente a {area:77}, el salón de piedra del extremo norte del valle. {npc:658} espera fuera de la puerta.",
