t.guides["forever/class/priest/priest-robes-alliance"] = (function() return {
		["A free uncommon robe at 5: heal and fortify a wounded guard near your first town."] = "Una túnica poco común gratis a nivel 5: cura y fortalece a un guardia herido cerca de tu primer pueblo.",
		["At 5, {npc:3595}, the priest trainer on the second level of {area:256}, the great tree in {area:188}, sends you to {npc:3600} in {area:186}. Train {spell:613} (Rank 2) from her while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "A nivel 5, {npc:3595}, la instructora de sacerdotes en el segundo nivel de {area:256}, el gran árbol de {area:188}, te manda con {npc:3600} en {area:186}. Entrena {spell:613} (rango 2) con ella mientras estás aquí: se abre a nivel 4 por 1 de plata, y la siguiente misión necesita justo ese rango.",
		["At 5, {npc:375}, the priest trainer inside {area:24}, sends you to {npc:377} in {area:87}. Train {spell:613} (Rank 2) from Anetta while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "A nivel 5, {npc:375}, la instructora de sacerdotes dentro de {area:24}, te manda con {npc:377} en {area:87}. Entrena {spell:613} (rango 2) con Anetta mientras estás aquí: se abre a nivel 4 por 1 de plata, y la siguiente misión necesita justo ese rango.",
		["At 5, {npc:837}, the priest trainer inside {area:77} in {area:132}, sends you to {npc:1226} in {area:131}. Train {spell:613} (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "A nivel 5, {npc:837}, el instructor de sacerdotes dentro de {area:77} en {area:132}, te manda con {npc:1226} en {area:131}. Entrena {spell:613} (rango 2) con él mientras estás aquí: se abre a nivel 4 por 1 de plata, y la siguiente misión necesita justo ese rango.",
		["Back at the north edge of {area:186}: {npc:3600} gives you the {item:16604}."] = "De vuelta en el borde norte de {area:186}: {npc:3600} te da {item:16604}.",
		["Back inside the {area:2102}: {npc:1226} gives you {item:16605}."] = "De vuelta dentro de {area:2102}: {npc:1226} te da {item:16605}.",
		["Back upstairs in the Lion's Pride Inn: Josetta gives you {item:16605}."] = "De vuelta arriba en la Posada Orgullo de León: Josetta te da {item:16605}.",
		["Follow the road south out of {area:9} to {area:87}. {npc:377} is upstairs in the Lion's Pride Inn."] = "Sigue el camino al sur desde {area:9} hasta {area:87}. {npc:377} está en el piso de arriba de la Posada Orgullo de León.",
		["Heal and fortify {npc:12423}"] = "Sana y fortalece a {npc:12423}",
		["Heal and fortify {npc:12427}"] = "Sana y fortalece a {npc:12427}",
		["Heal and fortify {npc:12429}"] = "Cura y fortalece a {npc:12429}",
		["Leave {area:188} by the ramp and follow the road south-west to {area:186}. {npc:3600} is in the building at the north edge of the village."] = "Sal de {area:188} por la rampa y sigue el camino al suroeste hasta {area:186}. {npc:3600} está en el edificio del borde norte de la aldea.",
		["Priest Robes at 5 (Alliance)"] = "Túnicas de sacerdote a nivel 5 (Alianza)",
		["Take the tunnel north-east out of {area:132} and follow the road east to {area:131}. {npc:1226} is inside the {area:2102}."] = "Toma el túnel al noreste para salir de {area:132} y sigue el camino al este hasta {area:131}. {npc:1226} está dentro de {area:2102}.",
		["{npc:12423} kneels by a tree on the lake shore east of {area:87}, off the road: walk along the shore, the minimap misses him from the road. Cast {spell:613} (Rank 2) on him first, then {spell:1243}. Rank 1 of {spell:613} does not count; drag Rank 2 onto your bar from the spellbook (or cast both from the spellbook if an action bar addon gets in the way). He walks off once both land and is back in about 3 minutes."] = "{npc:12423} está arrodillado junto a un árbol en la orilla del lago al este de {area:87}, fuera del camino: ve por la orilla, desde el camino el minimapa no lo muestra. Lanza primero {spell:613} (rango 2) sobre él y luego {spell:1243}. El rango 1 de {spell:613} no cuenta; arrastra el rango 2 a tu barra desde el libro de hechizos (o lanza los dos desde el libro si un addon de barras te molesta). Se va cuando recibe los dos y vuelve en unos 3 minutos.",
		["{npc:12427} kneels on a ridge between two low walls just south of {area:131}, across the road from the hunter pet trainer: if the road starts going downhill, you have passed him. Cast {spell:613} (Rank 2) on him first, then {spell:1243}; he speaks after each spell. Rank 1 of {spell:613} does not count."] = "{npc:12427} está arrodillado en una loma entre dos muros bajos, justo al sur de {area:131}, al otro lado del camino del instructor de mascotas de cazador: si el camino empieza a bajar, ya lo pasaste. Lanza primero {spell:613} (rango 2) sobre él y luego {spell:1243}; habla después de cada hechizo. El rango 1 de {spell:613} no cuenta.",
		["{npc:12429} kneels on the rocks at the edge of {area:259}, about 100 yards south of {area:186}, with no quest mark over her. Cast {spell:613} (Rank 2) on her first, then {spell:1243}; she runs off toward the lake once both land and is back in about 5 minutes. Rank 1 of {spell:613} does not count."] = "{npc:12429} está arrodillada en las rocas del borde de {area:259}, a unos 100 m al sur de {area:186}, sin marca de misión encima. Lanza primero {spell:613} (rango 2) sobre ella y luego {spell:1243}; corre hacia el lago cuando recibe los dos y vuelve en unos 5 minutos. El rango 1 de {spell:613} no cuenta.",
		["{spell:613} (Rank 2), if Anetta did not teach it yet"] = "{spell:613} (rango 2), si Anetta todavía no te lo enseñó",
		["{spell:613} (Rank 2), if {npc:3595} did not teach it yet"] = "{spell:613} (rango 2), si {npc:3595} todavía no te lo enseñó",
		["{spell:613} (Rank 2), if {npc:837} did not teach it yet"] = "{spell:613} (rango 2), si {npc:837} todavía no te lo enseñó",
} end)()
t.guides["forever/class/priest/priest-robes-horde"] = (function() return {
		["A free uncommon robe at 5: heal and fortify a wounded guard near your first town."] = "Una túnica poco común gratis a nivel 5: cura y fortalece a un guardia herido cerca de tu primer pueblo.",
		["At 5, {npc:2123}, the priest trainer in the chapel of {area:154}, sends you to {npc:2129} in {area:159}. Train {spell:613} (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "A nivel 5, {npc:2123}, el instructor de sacerdotes en la capilla de {area:154}, te manda con {npc:2129} en {area:159}. Entrena {spell:613} (rango 2) con él mientras estás aquí: se abre a nivel 4 por 1 de plata, y la siguiente misión necesita justo ese rango.",
		["At 5, {npc:3707}, the priest trainer in the Den in the middle of the {area:363}, sends you to {npc:3706} in {area:362}. Train {spell:613} (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "A nivel 5, {npc:3707}, el instructor de sacerdotes en la Guarida en el centro de {area:363}, te manda con {npc:3706} en {area:362}. Entrena {spell:613} (rango 2) con él mientras estás aquí: se abre a nivel 4 por 1 de plata, y la siguiente misión necesita justo ese rango.",
		["Back in the {area:362} barracks: {npc:3706} gives you the {item:16606}."] = "De vuelta en el cuartel de {area:362}: {npc:3706} te da {item:16606}.",
		["Back upstairs in the {area:159} inn: Beryl gives you the {item:16607}."] = "De vuelta arriba en la posada de {area:159}: Beryl te da {item:16607}.",
		["Follow the road east out of {area:154} to {area:159}. {npc:2129} is upstairs in the inn, {area:2119}."] = "Sigue el camino al este para salir de {area:154} hasta {area:159}. {npc:2129} está en el piso de arriba de la posada, {area:2119}.",
		["Follow the road out of the {area:363} north-east to {area:362}. {npc:3706} is inside the barracks, the first building on the right as you come into town."] = "Sigue el camino al noreste para salir de {area:363} hasta {area:362}. {npc:3706} está dentro del cuartel, el primer edificio a la derecha al entrar al pueblo.",
		["Heal and fortify {npc:12428}"] = "Cura y fortalece a {npc:12428}",
		["Heal and fortify {npc:12430}"] = "Sana y fortalece a {npc:12430}",
		["Priest Robes at 5 (Horde)"] = "Túnicas de sacerdote a nivel 5 (Horda)",
		["{npc:12428} kneels, half-dead, beside the north gate of {area:159}'s graveyard, a short walk north of the inn. Cast {spell:613} (Rank 2) on him first, then {spell:1243}: Fortitude first does not count, nor does Rank 1 of {spell:613}. If an addon gets in the way, cast both from the spellbook."] = "{npc:12428} está arrodillado, medio muerto, junto a la puerta norte del cementerio de {area:159}, a poca distancia al norte de la posada. Lanza primero {spell:613} (rango 2) sobre él y luego {spell:1243}: Entereza primero no cuenta, ni tampoco el rango 1 de {spell:613}. Si un addon te molesta, lanza los dos desde el libro de hechizos.",
		["{npc:12430} kneels behind a group of rocks just off the road, a short walk south of {area:362}. Cast {spell:613} (Rank 2) on her first, then {spell:1243}. Rank 1 of {spell:613} does not count; drag Rank 2 onto your bar from the spellbook. She leaves once both land and is back in about 5 minutes."] = "{npc:12430} está arrodillada detrás de un grupo de rocas justo al lado del camino, a poca distancia al sur de {area:362}. Lanza primero {spell:613} (rango 2) sobre ella y luego {spell:1243}. El rango 1 de {spell:613} no cuenta; arrastra el rango 2 a tu barra desde el libro de hechizos. Se va cuando recibe los dos y vuelve en unos 5 minutos.",
		["{spell:613} (Rank 2), if Duesten did not teach it yet"] = "{spell:613} (rango 2), si Duesten todavía no te lo enseñó",
		["{spell:613} (Rank 2), if {npc:3707} did not teach it yet"] = "{spell:613} (rango 2), si {npc:3707} todavía no te lo enseñó",
} end)()
t.guides["forever/class/priest/starshards-and-elunes-grace"] = (function() return {
		["At 10 in {zone:1426}, {npc:1226}, the priest trainer inside the {area:2102} in {area:131}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "A nivel 10 en {zone:1426}, {npc:1226}, el instructor de sacerdotes dentro de {area:2102} en {area:131}, te da {quest:5628}, una carta para {npc:11401} en {zone:1457}.",
		["At 10 in {zone:1429}, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "A nivel 10 en {zone:1429}, {npc:377}, en el piso de arriba de la Posada Orgullo de León en {area:87}, te da {quest:5628}, una carta para {npc:11401} en {zone:1457}.",
		["At 10 in {zone:1453}, {npc:5489} at the altar of the Cathedral of Light hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}. {npc:11397} in the Park has the same letter."] = "A nivel 10 en {zone:1453}, {npc:5489}, en el altar de la Catedral de la Luz, te da {quest:5628}, una carta para {npc:11401} en {zone:1457}. {npc:11397}, en el Parque, tiene la misma carta.",
		["At 10 in {zone:1455}, {npc:5142} in the {object:32386} ({object:32362}) hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "A nivel 10 en {zone:1455}, {npc:5142} en {object:32386} ({object:32362}) te da {quest:5628}, una carta para {npc:11401} en {zone:1457}.",
		["At 10, go to {npc:11401} on the upper balcony of the Temple of the Moon, at the south end of {zone:1457}: take the ramp up from the temple floor; she stands beside {npc:7999}. {quest:5627} is given and taken back at once and teaches {spell:10797}. No letter needed. Forever made {spell:10797} hit much harder, on a 30-second cooldown."] = "A nivel 10, ve con {npc:11401} en el balcón superior del Templo de la Luna, en el extremo sur de {zone:1457}: sube por la rampa desde el suelo del templo; está junto a {npc:7999}. {quest:5627} se da y se recibe enseguida y enseña {spell:10797}. No hace falta carta. Forever hizo que {spell:10797} pegue mucho más fuerte, con 30 segundos de reutilización.",
		["At 10, {npc:3600}, the priest trainer in the building at the north edge of {area:186}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}. {area:186} is on the road west to {zone:1457}."] = "A nivel 10, {npc:3600}, la instructora de sacerdotes en el edificio del borde norte de {area:186}, te da {quest:5628}, una carta para {npc:11401} en {zone:1457}. {area:186} está en el camino al oeste hacia {zone:1457}.",
		["At 20 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you an {spell:2651} letter for {npc:11401} in {zone:1457}. {npc:11397} in the Park has the same letter."] = "A nivel 20 en {zone:1453}, {npc:376}, en el altar de la Catedral de la Luz, te da una carta de {spell:2651} para {npc:11401} en {zone:1457}. {npc:11397}, en el Parque, tiene la misma carta.",
		["At 20 in {zone:1455}, {npc:11406} in the {object:32386} ({object:32362}) hands you an {spell:2651} letter for {npc:11401} in {zone:1457}."] = "A nivel 20 en {zone:1455}, {npc:11406} en {object:32386} ({object:32362}) te da una carta de {spell:2651} para {npc:11401} en {zone:1457}.",
		["At 20, {npc:11401} on the upper balcony of the Temple of the Moon, beside {npc:7999}, teaches {quest:5672} with a quest she gives and takes back at once. In Forever, {quest:5672} halves the chance for melee and ranged attacks to hit you for 15 seconds or until three attacks miss."] = "A nivel 20, {npc:11401}, en el balcón superior del Templo de la Luna junto a {npc:7999}, enseña {quest:5672} con una misión que te da y recibe enseguida. En Forever, {quest:5672} reduce a la mitad la probabilidad de que te golpeen los ataques cuerpo a cuerpo y a distancia durante 15 segundos o hasta que fallen tres ataques.",
		["Hand Laurena's letter to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "Entrégale la carta de Laurena a {npc:11401}, en el balcón superior del Templo de la Luna en {zone:1457}, junto a {npc:7999}: el barco de {area:17203} (o {area:150}) a {area:442}, el barco a {area:702} y luego el portal para subir a {zone:1457}.",
		["Hand Nara's letter to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "Entrégale la carta de Nara a {npc:11401}, en el balcón superior del Templo de la Luna en {zone:1457}, junto a {npc:7999}: el barco de {area:17203} (o {area:150}) a {area:442}, el barco a {area:702} y luego el portal para subir a {zone:1457}.",
		["Hand Rohan's letter to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "Entrégale la carta de Rohan a {npc:11401}, en el balcón superior del Templo de la Luna en {zone:1457}, junto a {npc:7999}: el barco de {area:17203} (o {area:150}) a {area:442}, el barco a {area:702} y luego el portal para subir a {zone:1457}.",
		["Take the road west from {area:186} into {zone:1457} and go up to the upper balcony of the Temple of the Moon, beside {npc:7999}: {npc:11401} takes {quest:5629} and teaches {spell:10797}."] = "Toma el camino al oeste desde {area:186} hasta {zone:1457} y sube al balcón superior del Templo de la Luna, junto a {npc:7999}: {npc:11401} recibe {quest:5629} y enseña {spell:10797}.",
		["The Night Elf priest spells: {spell:10797} at 10, {spell:2651} at 20. Free, no objectives."] = "Los hechizos de sacerdote elfo de la noche: {spell:10797} a nivel 10, {spell:2651} a nivel 20. Gratis, sin objetivos.",
		["{npc:11406}: take his {spell:2651} letter"] = "{npc:11406}: toma su carta de {spell:2651}",
		["{npc:1226}: take {quest:5628}"] = "{npc:1226}: toma {quest:5628}",
		["{npc:3600}: take {quest:5628}"] = "{npc:3600}: toma {quest:5628}",
