t.guides["forever/class/priest/touch-of-weakness-and-dark-sacrifice"] = (function() return {
		["At 10 in {zone:1411}, {npc:3706}, the priest trainer inside the barracks of {area:362}, hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}."] = "A nivel 10 en {zone:1411}, {npc:3706}, el instructor de sacerdotes dentro del cuartel de {area:362}, te da una carta de {spell:2652} para {npc:4606} en {zone:1458}.",
		["At 10 in {zone:1412}, {npc:11407}, just south-west of {area:222}, hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}."] = "A nivel 10 en {zone:1412}, {npc:11407}, justo al suroeste de {area:222}, te da una carta de {spell:2652} para {npc:4606} en {zone:1458}.",
		["At 10 in {zone:1454}, {npc:6018} in the {object:172961} hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}. The zeppelin to {zone:1420} leaves from the tower outside {zone:1454}'s front gate."] = "A nivel 10 en {zone:1454}, {npc:6018} en {object:172961} te da una carta de {spell:2652} para {npc:4606} en {zone:1458}. El zepelín a {zone:1420} sale de la torre afuera de la puerta principal de {zone:1454}.",
		["At 10 in {zone:1456}, {npc:3044}, the priest trainer in the cave under {area:1640}, hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}."] = "A nivel 10 en {zone:1456}, {npc:3044}, el instructor de sacerdotes en la cueva debajo de {area:1640}, te da una carta de {spell:2652} para {npc:4606} en {zone:1458}.",
		["At 10, go to {npc:4606}, the priest trainer in the {zone:1458}'s {object:36070}: she gives {quest:5658} and takes it back at once. No letter needed. From {area:159}, follow the road south to the ruined city of Lordaeron; the {zone:1458}'s lifts are at the back of the throne room. {quest:5658} strikes the next melee attacker for Shadow damage and lowers its melee attack power for 2 minutes."] = "A nivel 10, ve con {npc:4606}, la instructora de sacerdotes en {object:36070} de {zone:1458}: te da {quest:5658} y la recibe enseguida. No hace falta carta. Desde {area:159}, sigue el camino al sur hasta la ciudad en ruinas de Lordaeron; los elevadores de {zone:1458} están al fondo de la sala del trono. {quest:5658} golpea al siguiente atacante cuerpo a cuerpo con daño de Sombra y reduce su poder de ataque cuerpo a cuerpo durante 2 minutos.",
		["At 20 in {zone:1454}, {npc:6018} in the {object:172961} hands you a {quest:5644} letter for {npc:4606} in the {zone:1458}."] = "A nivel 20 en {zone:1454}, {npc:6018} en {object:172961} te da una carta de {quest:5644} para {npc:4606} en {zone:1458}.",
		["At 20 in {zone:1456}, {npc:3044} in the cave under {area:1640} hands you a {quest:5644} letter for {npc:4606} in the {zone:1458}."] = "A nivel 20 en {zone:1456}, {npc:3044}, en la cueva debajo de {area:1640}, te da una carta de {quest:5644} para {npc:4606} en {zone:1458}.",
		["At 20, {npc:4606} in the {object:36070} teaches {quest:5679} with a quest she gives and takes back at once (its text still speaks of {spell:2944}, which every priest now learns from the trainer)."] = "A nivel 20, {npc:4606} en {object:36070} enseña {quest:5679} con una misión que te da y recibe enseguida (su texto todavía habla de {spell:2944}, que ahora todos los sacerdotes aprenden del instructor).",
		["Hand the letter to {npc:4606} in the {zone:1458}'s {object:36070}: the zeppelin from the tower outside {zone:1454} lands in {zone:1420}, a short walk from the {zone:1458}."] = "Entrégale la carta a {npc:4606} en {object:36070} de {zone:1458}: el zepelín desde la torre afuera de {zone:1454} aterriza en {zone:1420}, a poca distancia de {zone:1458}.",
		["Hand the letter to {npc:4606} in the {zone:1458}'s {object:36070}: the zeppelin from the tower outside {zone:1454} lands in {zone:1420}."] = "Entrégale la carta a {npc:4606} en {object:36070} de {zone:1458}: el zepelín desde la torre afuera de {zone:1454} aterriza en {zone:1420}.",
		["Hand the letter to {npc:4606} in the {zone:1458}'s {object:36070}: travel to {zone:1454} and take the zeppelin to {zone:1420}."] = "Entrégale la carta a {npc:4606} en {object:36070} de {zone:1458}: viaja a {zone:1454} y toma el zepelín a {zone:1420}.",
		["The Undead priest spells: {spell:2652} at 10, {quest:5644} (new in Forever) at 20. Free, no objectives."] = "Los hechizos de sacerdote no-muerto: {spell:2652} a nivel 10, {quest:5644} (nuevo en Forever) a nivel 20. Gratis, sin objetivos.",
		["{npc:11407}: take the {spell:2652} letter"] = "{npc:11407}: toma la carta de {spell:2652}",
		["{npc:3044}: take his {quest:5644} letter"] = "{npc:3044}: toma su carta de {quest:5644}",
		["{npc:3044}: take his {spell:2652} letter"] = "{npc:3044}: toma su carta de {spell:2652}",
		["{npc:3706}: take his {spell:2652} letter"] = "{npc:3706}: toma su carta de {spell:2652}",
		["{npc:6018}: take his {quest:5644} letter"] = "{npc:6018}: toma su carta de {quest:5644}",
		["{npc:6018}: take his {spell:2652} letter"] = "{npc:6018}: toma su carta de {spell:2652}",
		["{quest:5644}: {npc:3044}'s letter"] = "{quest:5644}: la carta de {npc:3044}",
		["{quest:5646}: {npc:6018}'s letter"] = "{quest:5646}: la carta de {npc:6018}",
		["{quest:5660}: {npc:3706}'s letter"] = "{quest:5660}: la carta de {npc:3706}",
		["{quest:5661}: {npc:11407}'s letter"] = "{quest:5661}: la carta de {npc:11407}",
		["{quest:5662}: {npc:6018}'s letter"] = "{quest:5662}: la carta de {npc:6018}",
		["{quest:5663}: {npc:3044}'s letter"] = "{quest:5663}: la carta de {npc:3044}",
		["{spell:2652} and {quest:5644}"] = "{spell:2652} y {quest:5644}",
} end)()
t.guides["forever/class/rogue/blade-of-cunning-alliance"] = (function() return {
		["A dagger at 10 from your home town's rogue quests."] = "Una daga a nivel 10 de las misiones de pícaro de tu ciudad natal.",
		["At 10 {npc:1234}, the rogue trainer in the {area:2102} in {area:131}, sends you to {npc:5165} in {zone:1455}."] = "A nivel 10, {npc:1234}, el instructor de pícaros de {area:2102} en {area:131}, te envía con {npc:5165} en {zone:1455}.",
		["At 10 {npc:3599}, the rogue trainer in the {area:186} inn, gives you a rose for {npc:4163} in {zone:1457}. If you lose the rose, abandon the quest and take it again."] = "A nivel 10, {npc:3599}, el instructor de pícaros en la posada de {area:186}, te da una rosa para {npc:4163} en {zone:1457}. Si pierdes la rosa, abandona la misión y vuelve a tomarla.",
		["At 10 {npc:917}, the rogue trainer upstairs in the Lion's Pride Inn in {area:87}, gives you a package for {npc:332} in {zone:1453}. Train {spell:921} if you lack it: this chain needs it."] = "A nivel 10, {npc:917}, el instructor de pícaros en el piso de arriba de la Posada Orgullo de León en {area:87}, te da un paquete para {npc:332} en {zone:1453}. Entrena {spell:921} si no lo tienes: esta cadena lo necesita.",
		["Back to Mathias Shaw"] = "Regresa con Mathias Shaw",
		["Back to {npc:4163}"] = "Regresa con {npc:4163}",
		["Back to {npc:5165}"] = "Regresa con {npc:5165}",
		["Head north to {zone:1453}. Shaw stands upstairs in the SI:7 building in {object:2100} (the quest says the Barracks; it means SI:7)."] = "Ve al norte hasta {zone:1453}. Shaw está en el piso de arriba del edificio del IV:7 en {object:2100} (la misión dice el Cuartel; se refiere al IV:7).",
		["Head west to {area:133}. Beside the road to its entrance stands a wooden spiral tower: {npc:6886} waits stealthed on the top platform, next to a level 10 {npc:1211}, so you only see him up close."] = "Ve al oeste hasta {area:133}. Junto al camino a su entrada hay una torre de madera en espiral: {npc:6886} espera en sigilo en la plataforma de arriba, al lado de un {npc:1211} de nivel 10, así que solo lo ves de cerca.",
		["Head west to {zone:1457}. {npc:4163} is below ground in the {area:1658}: the way down is the opening at the foot of the split tree left of the Arch Druid's tree, near the nightsaber trainer. Her map marker shows above ground."] = "Ve al oeste hasta {zone:1457}. {npc:4163} está bajo tierra en {area:1658}: la bajada es la abertura al pie del árbol partido a la izquierda del árbol del Archidruida, cerca del instructor de sables de la noche. Su marcador del mapa aparece en la superficie.",
		["Pick Pocket Sethir the Ancient for {item:7737}"] = "Roba a Sethir el Anciano para {item:7737}",
		["The {npc:6846} (level 10, a goblin) works in the dock house at {area:797}, on the river at Elwynn's southern edge, south of {area:87}. Stealth in and {spell:921} him from behind: the schedule never drops from his corpse. Do not open with {spell:2070} or a fight: he calls in three waves of bodyguards. Keep away from the fireplaces in the house; they burn you out of stealth. He is back 2 to 5 minutes after a death."] = "El {npc:6846} (nivel 10, un goblin) trabaja en la casa del muelle de {area:797}, en el río del borde sur de Elwynn, al sur de {area:87}. Entra en sigilo y usa {spell:921} sobre él por la espalda: el horario nunca cae de su cadáver. No empieces con {spell:2070} ni con una pelea: llama a tres oleadas de guardaespaldas. Mantente lejos de las chimeneas de la casa; te sacan del sigilo con fuego. Vuelve de 2 a 5 minutos después de morir.",
		["{item:7298} (Alliance)"] = "{item:7298} (Alianza)",
		["{npc:332}, SI:7"] = "{npc:332}, IV:7",
		["{npc:5165} is in the {object:32383}, the rogue quarter in the north of {zone:1455}: go into the building with a shady dealer outside and down the stairs."] = "{npc:5165} está en {object:32383}, el barrio de los pícaros en el norte de {zone:1455}: entra al edificio con un comerciante turbio afuera y baja la escalera.",
		["{npc:6909} (level 12 satyr) lives out on a great branch north of the {area:264}: go through the V-shaped gap in the wall north of the glade and out along the branch. Pick his pocket for the journal; killing him does not give it, and a fight brings out three Minions of Sethir. He walks between the main branch and a side branch: wait stealthed at the far end of the main branch and pick him from behind when he comes back. Then {spell:2983} away. He is back 8 1/2 minutes after a death."] = "{npc:6909} (sátiro de nivel 12) vive en una gran rama al norte de {area:264}: pasa por el hueco en forma de V en el muro al norte del claro y sal por la rama. Róbale el diario; matarlo no te lo da, y una pelea saca a tres esbirros de Sethir. Camina entre la rama principal y una rama lateral: espera en sigilo en el extremo de la rama principal y róbale por la espalda cuando vuelva. Luego aléjate con {spell:2983}. Vuelve 8 minutos y medio después de morir.",
		["{spell:921} the {npc:6846} for the {item:7675}"] = "{spell:921} al {npc:6846} para {item:7675}",
} end)()
t.guides["forever/class/rogue/blade-of-cunning-horde"] = (function() return {
		["A dagger at 10 from your home town's rogue quests."] = "Una daga a nivel 10 de las misiones de pícaro de tu ciudad natal.",
		["At 10 {npc:2130}, the rogue trainer upstairs in the {area:2119} in {area:159}, sends you to {quest:1885} in the {zone:1458}."] = "A nivel 10, {npc:2130}, la instructora de pícaros en el piso de arriba de {area:2119} en {area:159}, te manda con {quest:1885} en {zone:1458}.",
		["At 10 {npc:3170}, the rogue trainer in {area:362}, sends you to {quest:1859} in {zone:1454}. It is only a pointer: an Orc already in {zone:1454} can skip it and take {quest:1963} from {quest:1859} straight away."] = "A nivel 10, {npc:3170}, el instructor de pícaros en {area:362}, te manda con {quest:1859} en {zone:1454}. Es solo una indicación: un orco que ya está en {zone:1454} puede omitirla y tomar {quest:1963} de {quest:1859} directamente.",
		["Back to {npc:6446}"] = "De vuelta con {npc:6446}",
		["Back to {npc:6467}"] = "De vuelta con {npc:6467}",
		["Pick Pocket Gamon for {item:7208}"] = "Roba a Gamon para {item:7208}",
		["The {object:36073}"] = "{object:36073}",
		["{item:7209}, once you have the key"] = "{item:7209}, cuando tengas la llave",
		["{item:7295}, from the satchel"] = "{item:7295}, de la cartera",
		["{item:7298} (Horde)"] = "{item:7298} (Horda)",
		["{npc:6446}'s reward"] = "Recompensa de {npc:6446}",
		["{npc:6467} and {npc:2425}"] = "{npc:6467} y {npc:2425}",
		["{npc:6467} sends the ledger on to {npc:2425}, the big demon in the middle of the Hall of the Dark Lady in the {object:36126}, past its elite guards; the way in is the passage off the Apothecarium. If you lose the ledger, take another from {npc:6522}'s bookshelf."] = "{npc:6467} manda el libro de cuentas a {npc:2425}, el demonio grande en el centro de la Sala de la Dama Oscura en {object:36126}, pasando sus guardias élite; la entrada es el pasaje que sale del Boticarium. Si pierdes el libro, toma otro de la estantería de {npc:6522}.",
		["{npc:6494} (level 13, not elite) is a troll pirate on the {area:391} south of {area:392}: he walks the fenced hill path between the lower pirate camp by the beached ship and the upper camp by a big tree. Fight him at the foot of the hill, away from the camps. He always drops his satchel and is back 4 1/2 minutes after a death; one satchel per kill, so two rogues need two kills. Hand the satchel in unopened: picking its lock now destroys it and you must kill him again."] = "{npc:6494} (nivel 13, no élite) es un pirata trol en {area:391}, al sur de {area:392}: recorre el sendero cercado de la colina entre el campamento pirata de abajo, junto al barco varado, y el de arriba, junto a un árbol grande. Pelea con él al pie de la colina, lejos de los campamentos. Siempre suelta su morral y vuelve 4 minutos y medio después de morir; un morral por muerte, así que dos pícaros necesitan dos muertes. Entrega el morral sin abrir: forzar su cerradura ahora lo destruye y tienes que volver a matarlo.",
		["{npc:6497} (level 13) walks the road between the {area:228} and the {zone:1458}, north of the {area:228}. He looks like a friendly traveller with no quest mark. Talk to him and pick both of his answers: he turns hostile. Kill him for the letter (it always drops). Fight him away from guards, who can take the kill and leave no loot; only one rogue per kill gets the letter. He is back 5 minutes after a death."] = "{npc:6497} (nivel 13) recorre el camino entre {area:228} y {zone:1458}, al norte de {area:228}. Parece un viajero amistoso sin marca de misión. Háblale y elige sus dos respuestas: se vuelve hostil. Mátalo para la carta (siempre cae). Pelea con él lejos de los guardias, que pueden quedarse con la muerte y no dejar botín; solo un pícaro por muerte recibe la carta. Vuelve 5 minutos después de morir.",
		["{npc:6522} is in the Apothecarium, in its biggest room, where two huge guards watch a small bridge. His ledger is on the bookshelf in the back room behind him, not the shelf on the wall next to him."] = "{npc:6522} está en el Boticarium, en su sala más grande, donde dos guardias enormes vigilan un puentecito. Su libro de cuentas está en la estantería de la sala de atrás, detrás de él, no en el estante de la pared a su lado.",
		["{quest:1859} hands the satchel back: now open it. {npc:6466} (level 12) kneels by the innkeeper in the inn in the {object:172982}; stealth up and pick his pocket for {item:7208} (do not kill him: the key almost never drops). Players often kill him, so you may wait up to 5 minutes for him. Then use the key on {item:7209} in your bags. If you have trained {spell:1804}, you can pick the satchel's lock instead."] = "{quest:1859} te devuelve el morral: ahora ábrelo. {npc:6466} (nivel 12) está arrodillado junto al posadero en la posada de {object:172982}; entra en sigilo y róbale {item:7208} (no lo mates: la llave casi nunca cae). Los jugadores suelen matarlo, así que puede que lo esperes hasta 5 minutos. Luego usa la llave sobre {item:7209} en tus bolsas. Si entrenaste {spell:1804}, puedes forzar la cerradura del morral en su lugar.",
		["{quest:1859} stands in the {object:172960}, the canyon under the {object:172982}. Trolls: take {quest:1963} from him at 10."] = "{quest:1859} está en {object:172960}, el cañón bajo {object:172982}. Si eres trol, acepta {quest:1963} de él a nivel 10.",
		["{quest:1885} stands in the {object:36073}."] = "{quest:1885} está en {object:36073}.",
} end)()
t.guides["forever/class/rogue/certificate-of-thievery"] = (function() return {
		["At 16 {npc:1234} in the {area:2102} in {area:131} sends you to {npc:5165} in {zone:1455}'s {object:32383}."] = "A nivel 16, {npc:1234}, en {area:2102} en {area:131}, te manda con {npc:5165} en {object:32383} de {zone:1455}.",
		["At 16 {npc:3599} in the {area:186} inn sends you to {quest:2259} in {zone:1457}."] = "A nivel 16, {npc:3599}, en la posada de {area:186}, te manda con {quest:2259} en {zone:1457}.",
		["At 16 {npc:917}, the rogue trainer upstairs in the Lion's Pride Inn in {area:87}, sends you to {npc:6946} in {zone:1453}. Taking it shuts out the other towns' breadcrumbs."] = "A nivel 16, {npc:917}, el instructor de pícaros en el piso de arriba de la Posada Orgullo de León en {area:87}, te manda con {npc:6946} en {zone:1453}. Tomarla bloquea las misiones indicadoras de los otros pueblos.",
		["Back to {npc:6966}"] = "Regresa con {npc:6966}",
		["Head east through {zone:1429} into Redridge, or fly to {area:69}. {npc:6966} stands on a crate on one of the {area:69} docks, south of town; he gives you {item:5060} with the job ({npc:3090} in {area:69} sells more). {spell:1804} does not work without the tools in your bags."] = "Ve al este por {zone:1429} hasta Montañas Crestagrana, o vuela a {area:69}. {npc:6966} está sobre una caja en uno de los muelles de {area:69}, al sur del pueblo; te da {item:5060} con el trabajo ({npc:3090} en {area:69} vende más). {spell:1804} no funciona sin las herramientas en tus bolsas.",
		["Your first lockpicking job at 16: {npc:6966}'s lockbox at {quest:2282}, for {quest:2300}."] = "Tu primer trabajo de forzar cerraduras a nivel 16: la caja fuerte de {npc:6966} en {quest:2282}, para {quest:2300}.",
		["{npc:4214} stands in the {area:1658}. Then the boat from {area:702} to {area:442}, and the boat from {area:442} to {area:17203}."] = "{npc:4214} está en {area:1658}. Luego el barco de {area:702} a {area:442}, y el barco de {area:442} a {area:17203}.",
		["{npc:5165} is in the house with a shady dealer outside, in the {object:32383}, down the stairs. Then fly or take the {area:2257} to {zone:1453}."] = "{npc:5165} está en la casa con un comerciante turbio afuera, en {object:32383}, bajando la escalera. Luego vuela o toma {area:2257} a {zone:1453}.",
		["{npc:6946} stands upstairs in the {quest:2300} building in {object:2100}, behind the rogue trainers. Before you leave: if you lack {spell:1804}, {npc:13283} in the {quest:2300} building teaches it; Lockpicking is the test of the next quest."] = "{npc:6946} está en el piso de arriba del edificio del {quest:2300} en {object:2100}, detrás de los instructores de pícaros. Antes de irte: si no tienes {spell:1804}, {npc:13283}, en el edificio del {quest:2300}, la enseña; Forzar cerraduras es la prueba de la siguiente misión.",
		["{quest:2282} stands east of {area:69}, up off the road; Blackrock orcs roam near it. Inside, the Practice Lockboxes come back almost at once: pick them until {object:121264} opens for you (about 25 Lockpicking). Your Lockpicking cap rises 5 per level, so a low character may stall. Some boxes are trapped (a frost trap, for one); the skill still goes up. On Forever level 20 spiders wander near the boxes: clear them first or bring a friend. The lockbox always holds the token and is back two seconds after use. Practise on while it still gives skill: the next class quest needs about 75."] = "{quest:2282} está al este de {area:69}, subiendo fuera del camino; los orcos Roca Negra rondan cerca. Adentro, las cajas fuertes de práctica vuelven casi enseguida: fuérzalas hasta que {object:121264} se abra para ti (unos 25 de Forzar cerraduras). Tu tope de Forzar cerraduras sube 5 por nivel, así que un personaje de nivel bajo puede estancarse. Algunas cajas tienen trampa (una de escarcha, por ejemplo); la habilidad igual sube. En Forever, arañas de nivel 20 deambulan cerca de las cajas: despéjalas primero o trae a un amigo. La caja siempre tiene la ficha y vuelve dos segundos después de usarla. Sigue practicando mientras dé habilidad: la siguiente misión de clase necesita unos 75.",
} end)()
t.guides["forever/class/rogue/plundering-the-plunderers"] = (function() return {
		["At 16 {npc:3170}, the rogue trainer in {area:362}, sends you to {npc:3401} in {zone:1454}."] = "A nivel 16, {npc:3170}, el instructor de pícaros de {area:362}, te envía con {npc:3401} en {zone:1454}.",
		["At 16 {npc:6467} in the {object:36073} sends you to {npc:3401} in {zone:1454}. Take {quest:1998} from him too; it is done in {zone:1421} at the end of this guide."] = "A nivel 16, {npc:6467} en {object:36073} te envía con {npc:3401} en {zone:1454}. Acepta también {quest:1998} de él; se completa en {zone:1421} al final de esta guía.",
		["Back to {npc:6467}"] = "Regresa con {npc:6467}",
		["Back to {npc:7161}"] = "Regresa con {npc:7161}",
		["Fly or walk to {area:392} on the {zone:1413} coast. {npc:7161} stands in a small shed near the bank, up the hill to the left before the docks. His Gizmotronic Apparatus beside him hands out what the job needs: take an {item:7970} and {item:5060} ({spell:1804} does not work without the tools in your bags)."] = "Vuela o camina a {area:392}, en la costa de {zone:1413}. {npc:7161} está en un cobertizo cerca del banco, subiendo la colina a la izquierda antes de los muelles. Su Aparato gizmotrónico, a su lado, entrega lo que hace falta para el trabajo: toma un {item:7970} y {item:5060} ({spell:1804} no funciona sin las herramientas en tus bolsas).",
		["Follow the coast south from {area:392} to the first beached pirate ship, the Tide Razor, and climb aboard up its bow. On the middle deck the Buccaneer's Strongboxes come back fast: pick them until your Lockpicking is about 30 (a few are trapped with a frost nova or turn you into a rat; picking still works as a rat). Keep picking while they still give skill: the poisons job at 20 ends at a lockbox that needs about 75, and these boxes are the closest practice. Then go down to the bottom hold and pick the lock of {object:123462}: it is empty, but opening it calls a giant level 50 {npc:7168} into the next room. Stay stealthed, put the {item:7970} on your action bar, target {npc:7168} and use it: the parrot shrinks to level 18. Kill it for the {item:7968}."] = "Sigue la costa al sur desde {area:392} hasta el primer barco pirata varado, el Navaja de la Marea, y sube a bordo por la proa. En la cubierta del medio, las cajas fuertes de bucanero vuelven rápido: fuérzalas hasta tener unos 30 de Forzar cerraduras (algunas tienen trampa con nova de escarcha o te convierten en rata; como rata igual puedes forzar). Sigue forzando mientras den habilidad: el trabajo de venenos a nivel 20 termina en una caja que necesita unos 75, y estas cajas son la práctica más cercana. Luego baja a la bodega de abajo y fuerza la cerradura de {object:123462}: está vacío, pero abrirlo llama a una {npc:7168} gigante de nivel 50 a la sala siguiente. Quédate en sigilo, pon {item:7970} en tu barra de acción, selecciona a {npc:7168} y úsalo: el loro se encoge a nivel 18. Mátalo para {item:7968}.",
		["If you have no {item:5060} left, ask {npc:6566}, the outfitter in the {object:36073}."] = "Si no te quedan {item:5060}, pídeselas a {npc:6566}, la proveedora en {object:36073}.",
		["Take the zeppelin from {zone:1454} to the {zone:1458} and head south into Silverpine. {quest:1998} (level 16) stands alone on the old ferry dock on {area:1338}, north-east of the {area:228}. His Uppercut knocks you back, so do not fight him at the dock's edge. He always drops his head and is back 4 1/2 minutes after a death."] = "Toma el zepelín de {zone:1454} a {zone:1458} y ve al sur hacia Bosque de Argénteos. {quest:1998} (nivel 16) está solo en el viejo muelle del transbordador de {area:1338}, al noreste de {area:228}. Su Gancho te empuja hacia atrás, así que no pelees con él en el borde del muelle. Siempre suelta su cabeza y vuelve 4 minutos y medio después de morir.",
		["Ten {item:7676}, the rogue energy drink, from the Horde lockpicking jobs at 16."] = "Diez {item:7676}, la bebida de energía de los pícaros, de los trabajos de forzar cerraduras de la Horda a nivel 16.",
		["The Kirin Tor keep their reports in walled {area:233}, in south-east Silverpine. Facing the town hall, take the building on the right: the {object:103815} is in a corner room upstairs (any Lockpicking opens it; the {item:5060} must be in your bags). Three casters of level 19-20 guard that floor and see through stealth, one walking in and out of the strongbox room: time it or fight them one at a time."] = "El Kirin Tor guarda sus informes en {area:233}, amurallado, en el sureste de Bosque de Argénteos. De frente al ayuntamiento, entra al edificio de la derecha: {object:103815} está en una sala de la esquina en el piso de arriba (cualquier nivel de Forzar cerraduras la abre; {item:5060} tiene que estar en tus bolsas). Tres lanzadores de hechizos de nivel 19-20 custodian ese piso y ven a través del sigilo, uno entra y sale de la sala de la caja: calcula el momento o pelea con ellos de a uno.",
		["Undead take the zeppelin from the towers outside the {zone:1458} to {zone:1411}. {npc:3401} and {quest:2379} stand in the {object:172960}, the canyon under the {object:172982}. Train {spell:1804} from {npc:3401} (or any rogue trainer) now if you lack it: this job is a lockpicking test."] = "Los no-muertos toman el zepelín desde las torres afuera de {zone:1458} hasta {zone:1411}. {npc:3401} y {quest:2379} están en {object:172960}, el cañón debajo de {object:172982}. Entrena ahora {spell:1804} con {npc:3401} (o cualquier instructor de pícaros) si no la tienes: este trabajo es una prueba de forzar cerraduras.",
		["{item:7968}: {npc:7168}, after the {item:7970}"] = "{item:7968}: {npc:7168}, después de {item:7970}",
		["{npc:3401} and {quest:2379}"] = "{npc:3401} y {quest:2379}",
		["{npc:7161}: ten {item:7676}"] = "{npc:7161}: diez {item:7676}",
} end)()
t.guides["forever/class/rogue/poisons-alliance"] = (function() return {
		["/lay with the Doc targeted"] = "/lay con el Doc seleccionado",
		["All four are in {zone:1453}. {item:3421}: Bernard or {npc:1303}'s flower shop by the {object:2096} canal. A {item:3372}: many general goods and alchemy vendors ({npc:1257}, {npc:1325} and others). A {item:4371}: the Auction House in the {object:2096}; the engineering suppliers keep only one and are nearly always sold out, and an engineer can make one. The {item:8431} lies on the floor beside the left end of the counter in {object:2177}, the tailor's shop on the canals; you can only pick it up with this quest. If you skip the cure, an {item:6452} ({skill:129}) or a druid's {spell:526} also clears the {spell:9810}."] = "Las cuatro cosas están en {zone:1453}. {item:3421}: Bernard o la florería de {npc:1303} junto al canal de {object:2096}. Un {item:3372}: muchos vendedores de mercancías y de alquimia ({npc:1257}, {npc:1325} y otros). Un {item:4371}: la casa de subastas de {object:2096}; los proveedores de ingeniería tienen solo uno y casi siempre está agotado, y un ingeniero puede fabricarlo. {item:8431} está en el suelo junto al extremo izquierdo del mostrador de {object:2177}, la sastrería de los canales; solo puedes recogerlo con esta misión. Si omites la cura, un {item:6452} ({skill:129}) o {spell:526} de un druida también quita {spell:9810}.",
		["At 20 {npc:332}, upstairs in the SI:7 building in {object:2100}, sends you to {npc:7024} in {zone:1436}. This chain is how you learn Poisons on Forever, so do not skip it."] = "A nivel 20, {npc:332}, en el piso de arriba del edificio del IV:7 en {object:2100}, te manda con {npc:7024} en {zone:1436}. En Forever así se aprende Venenos, así que no la omitas.",
		["Back to {npc:7207}"] = "Regresa con {npc:7207}",
		["Forever teaches Poisons through this chain, not the trainer; the {item:7676} recipe comes with it."] = "Forever enseña Venenos con esta cadena, no con el instructor; la receta de {item:7676} viene con ella.",
		["Get the key first. The {npc:7051} (level 23, not elite) starts at the tower entrance and walks a loop around the outside; it is the spiky-haired one trailing yellow sparkles. Stealth up and {spell:921} it from behind: it always has the key. It hits hard: if stealth breaks, {spell:2983} away. Watch for the pair of Defias Drones that also patrol. Then sneak up the tower. Defias Tower Patrollers (23) and Sentries (24) guard the floors; an Ambush with a dagger kills them outright if you would rather clear them. {npc:7053}, a level 26 elite, waits on the top floor: Sap him, or bring a friend. The {object:123214} beside his desk needs Lockpicking of about 70-75 (practise on the boxes at {area:97} in Redridge first). A trick: while the Sentries are away, jump from the chair to the lamp to the bookshelf above the chest, step out of stealth and open the chest from there. Opening it poisons you with the {spell:9810}, which stops your stealth for a while and lets the drone see you; that is why the key comes first. Then get out."] = "Consigue primero la llave. El {npc:7051} (nivel 23, no élite) sale de la entrada de la torre y da una vuelta por fuera; es el de pelo en punta que deja chispas amarillas. Entra en sigilo y usa {spell:921} por detrás: siempre tiene la llave. Pega fuerte: si se rompe el sigilo, huye con {spell:2983}. Atento a la pareja de Zánganos Defias que también patrulla. Luego sube a escondidas por la torre. Los Guardias de torre Defias (23) y los centinelas (24) custodian los pisos; una Emboscada con daga los mata de un golpe si prefieres despejarlos. {npc:7053}, un élite de nivel 26, espera en el último piso: aplícale Porrazo, o trae a un amigo. {object:123214}, junto a su escritorio, necesita unos 70-75 de Forzar cerraduras (practica antes con las cajas de {area:97}, en Montañas Crestagrana). Un truco: mientras los centinelas no están, salta de la silla a la lámpara y a la estantería sobre el cofre, sal del sigilo y abre el cofre desde ahí. Abrirlo te envenena con {spell:9810}, que te quita el sigilo por un rato y deja que el zángano te vea; por eso la llave va primero. Luego sal.",
		["Head north through Elwynn to {zone:1453}; Mathias Shaw is upstairs in SI:7. He teaches Poisons and gives you the {item:7676} recipe. Poisons are made, not bought: each batch of {spell:8681} takes a {item:2928} and an {item:3371}, which {npc:1325} and {npc:1326} sell in {object:2100} next to SI:7. Buy a stack of each, open Poisons from your spellbook to make them, then use a poison on your weapon."] = "Ve al norte por Elwynn hasta {zone:1453}; Mathias Shaw está en el piso de arriba de IV:7. Te enseña Venenos y te da la receta de {item:7676}. Los venenos se fabrican, no se compran: cada tanda de {spell:8681} lleva un {item:2928} y un {item:3371}, que {npc:1325} y {npc:1326} venden en {object:2100}, junto a IV:7. Compra un montón de cada uno, abre Venenos desde tu libro de hechizos para fabricarlos y luego aplica un veneno a tu arma.",
		["Kearnen hides stealthed against the west side of a big tree with two small trees in front of it, just north of {npc:7053}'s Defias tower in the far east of {zone:1436}, by the {zone:1431} border. Read {item:8046} for the tower's layout if you like."] = "Kearnen se esconde en sigilo contra el lado oeste de un árbol grande con dos árboles chicos delante, justo al norte de la torre Defias de {npc:7053}, en el extremo este de {zone:1436}, junto a la frontera con {zone:1431}. Lee {item:8046} si quieres conocer la distribución de la torre.",
		["Poisons (Alliance)"] = "Venenos (Alianza)",
		["The cure's ingredients"] = "Los ingredientes de la cura",
		["{item:4371}: the Auction House"] = "{item:4371}: la casa de subastas",
		["{item:7908}: the {object:123214}, top floor"] = "{item:7908}: {object:123214}, último piso",
		["{npc:332}: Poisons"] = "{npc:332}: Venenos",
		["{npc:7053} on the top floor is a level 26 elite: easier at 24 or with a friend. Get the key first: the {npc:7051} (level 23, the spiky-haired one trailing yellow sparkles) walks a loop around the tower; stealth up and {spell:921} it from behind. Then up the tower past the Defias Tower Patrollers (23) and Sentries (24) to the {object:123214} beside Klaven's desk (Lockpicking about 70-75). Opening it poisons you with the {spell:9810}, which stops your stealth for a while."] = "{npc:7053}, en el último piso, es un élite de nivel 26: más fácil a nivel 24 o con un amigo. Consigue primero la llave: el {npc:7051} (nivel 23, el de pelo en punta que deja chispas amarillas) da vueltas alrededor de la torre; entra en sigilo y usa {spell:921} por detrás. Luego sube la torre pasando a los Guardias de torre Defias (23) y los centinelas (24) hasta el {object:123214} junto al escritorio de Klaven (Forzar cerraduras unos 70-75). Abrirlo te envenena con {spell:9810}, que te quita el sigilo por un rato.",
		["{quest:2359}, solo"] = "{quest:2359}, en solitario",
		["{quest:2359}, with a group"] = "{quest:2359}, en grupo",
		["{quest:2607} still sits on you. {npc:7207} works in the cellar of the SI:7 building: the stairs down are under the stairs to the upper floor, behind {npc:1325}. Target him and type /lay (nothing after it) to be examined, then wait. If he does nothing, abandon the quest, take it again and wait until he asks you to lie down."] = "Todavía tienes {quest:2607} encima. {npc:7207} trabaja en el sótano del edificio del IV:7: la bajada está debajo de la escalera al piso de arriba, detrás de {npc:1325}. Selecciónalo y escribe /lay (sin nada después) para que te examine, y espera. Si no hace nada, abandona la misión, vuelve a tomarla y espera a que te pida que te acuestes.",
		["{spell:921} the {npc:7051} for the {item:7923}"] = "{spell:921} al {npc:7051} para {item:7923}",
} end)()
t.guides["forever/class/rogue/poisons-horde"] = (function() return {
		["/salute {npc:3401}"] = "/salute a {npc:3401}",
		["Back to {npc:3401}"] = "Vuelve con {npc:3401}",
		["Fly back to {zone:1454} ({area:392} or the Crossroads; dying at the tower and taking the spirit healer's way back to the Crossroads is quicker). Keep {item:8072} afterwards. Before you leave the {area:263}, buy {item:2928} and Empty Vials from Rekkul: once Hinott teaches Poisons, each batch of {spell:8681} takes one of each."] = "Vuela de regreso a {zone:1454} (desde {area:392} o el Cruce; es más rápido morir en la torre y volver al Cruce con el Ángel de la Resurrección). Guarda {item:8072} después. Antes de salir de {area:263}, compra {item:2928} y Viales vacíos a Rekkul: cuando Hinott te enseñe Venenos, cada tanda de {spell:8681} lleva uno de cada.",
		["Fly to the Crossroads and head north to the Venture Co. tower above the {area:382}. Fizzule stands under a tree east of the tower, outside it, and is hostile until signalled. Target him from about 50 yards and fire the {item:8051} twice, then walk up in front of him and /salute. In any other order he attacks. Lost the {item:8051}? Abandon and retake from {npc:3401}."] = "Vuela al Cruce y ve al norte hasta la torre de Ventura y Cía. sobre {area:382}. Fizzule está debajo de un árbol al este de la torre, afuera, y es hostil hasta que le hagas la señal. Selecciónalo desde unos 50 m y dispara {item:8051} dos veces, luego camina hasta ponerte frente a él y haz /salute. En cualquier otro orden te ataca. ¿Perdiste {item:8051}? Abandona y vuelve a tomarla con {npc:3401}.",
		["Forever teaches Poisons through this chain, not the trainer; the {item:7676} recipe comes with it."] = "Forever enseña Venenos con esta cadena, no con el instructor; la receta de {item:7676} viene con ella.",
		["Keep {item:8066} in your bags and use it on him every time you come near, or he turns hostile. {npc:7287} (level 22) walks by the tower: hug the wall, stealth up behind him and {spell:921} the key. Killing him does not give it; if his pockets are empty, kill him and wait 4 1/2 minutes for him to come back. Inside, floor by floor (everything comes back after 4 1/2 minutes): the Mutated Venture Co. Drones (level 25) on the ground floor die to one Ambush with a dagger; the Patrollers on the second floor take half their health from a one-point {spell:1943}; the Lookouts on the open third floor from a one-point {spell:2098}. {npc:7288} waits on the top floor: a level 23 elite, back 10 minutes after a kill. Open with Ambush (about half his health), then {spell:1776}, {spell:5277}, a healing potion and {item:7676}; a friend makes it easy. One head per kill. Then pick {object:129127} beside him for the cache: it poisons you with the {spell:9810}, which weakens your stealth and agility until {npc:2391} cures it."] = "Lleva {item:8066} en tus bolsas y úsalo con él cada vez que te acerques, o se vuelve hostil. {npc:7287} (nivel 22) camina junto a la torre: pégate a la pared, ponte en sigilo detrás de él y usa {spell:921} para la llave. Matarlo no la da; si no tiene nada en los bolsillos, mátalo y espera 4 minutos y medio a que vuelva. Adentro, piso por piso (todo vuelve a los 4 minutos y medio): los zánganos mutados de Ventura y Cía. (nivel 25) de la planta baja mueren con una Emboscada con daga; los patrulleros del segundo piso pierden la mitad de su salud con una {spell:1943} de un punto; los vigías del tercer piso abierto, con un {spell:2098} de un punto. {npc:7288} espera en el último piso: un élite de nivel 23 que vuelve 10 minutos después de morir. Empieza con Emboscada (más o menos la mitad de su salud), luego {spell:1776}, {spell:5277}, una poción de curación y {item:7676}; con un amigo es fácil. Una cabeza por muerte. Luego fuerza {object:129127}, a su lado, para el alijo: te envenena con {spell:9810}, que debilita tu sigilo y agilidad hasta que {npc:2391} te cura.",
		["Lockpicking about 75: pick the Buccaneer's Strongboxes on the Tide Razor"] = "Forzar cerraduras a unos 75: fuerza las cajas fuertes de bucanero del Navaja de la Marea",
		["Lockpicking practice"] = "Práctica de Forzar cerraduras",
		["Pick Pocket Foreman Silixiz for {item:8072}"] = "Roba al capataz Silixiz para {item:8072}",
		["Poisons (Horde)"] = "Venenos (Horda)",
		["Take the zeppelin from {zone:1454} to the {zone:1458} and follow the road south through {zone:1421} into {area:287}, to {area:272}. {npc:2391} works in the building next to the flight path, beside {npc:2216}, a wagon outside. If you lost the Sample of Zanzil's Mixture, abandon and retake from {npc:3401}. Stay beside him for about a minute while he brews the cure; if it never finishes, abandon and retake from him. Then open Poisons from your spellbook to make {spell:8681} from Rekkul's dust and vials, and use it on your weapon."] = "Toma el zepelín de {zone:1454} a {zone:1458} y sigue el camino al sur por {zone:1421} hasta {area:287}, a {area:272}. {npc:2391} trabaja en el edificio junto a la ruta de vuelo, al lado de {npc:2216}, con un carro afuera. Si perdiste la muestra de la Mezcla de Zanzil, abandona la misión y vuelve a tomarla de {npc:3401}. Quédate a su lado alrededor de un minuto mientras prepara la cura; si nunca termina, abandona y vuelve a tomarla de él. Luego abre Venenos desde tu libro de hechizos para fabricar {spell:8681} con el polvo y los viales de Rekkul, y aplícalo a tu arma.",
		["The Venture Co. tower, solo"] = "La torre de Ventura y Cía., en solitario",
		["The Venture Co. tower, with a group"] = "La torre de Ventura y Cía., en grupo",
		["Tide Razor"] = "Navaja de la Marea",
		["Wait for the cure"] = "Espera la cura",
		["{item:8051}, twice, at Fizzule"] = "{item:8051}, dos veces, hacia Fizzule",
		["{item:8074}: {npc:7288} (elite)"] = "{item:8074}: {npc:7288} (élite)",
		["{item:8095}: clears the {spell:9810}"] = "{item:8095}: quita {spell:9810}",
		["{npc:2391}: Poisons"] = "{npc:2391}: Venenos",
		["{npc:3401} stands in the {object:172960}, the canyon under the {object:172982}. Take the quest and wait: he speaks three lines and salutes you. After his third line, target him and type /salute. If it does not count, abandon the quest and take it again. The tower job ahead is built around Ambush, which needs a dagger: if you have none, Kareth, the blade merchant in the {object:172960}, sells a Jambiya."] = "{npc:3401} está en {object:172960}, el cañón debajo de {object:172982}. Toma la misión y espera: dice tres líneas y te saluda. Después de su tercera línea, selecciónalo y escribe /salute. Si no cuenta, abandona la misión y vuelve a tomarla. El trabajo de la torre que viene se basa en Emboscada, que necesita una daga: si no tienes, Kareth, la vendedora de hojas en {object:172960}, vende un Jambiya.",
		["{npc:7288} on the top floor is a level 23 elite: easier at 23 or with a friend. Keep {item:8066} in your bags and use it on him every time you come near, or he turns hostile. First Pick Pocket Silixiz's Tower Key from {npc:7287} (level 22), who walks by the tower: stealth up behind him (killing him does not give it). Then clear the tower floor by floor (everything comes back after 4 1/2 minutes): Mutated Venture Co. Drones (25) on the ground floor, Patrollers on the second, Lookouts on the open third, Gallywix on top, back 10 minutes after a kill. Pick {object:129127} beside him for the cache: it poisons you with the {spell:9810}, which weakens your stealth and agility until {npc:2391} cures it."] = "{npc:7288}, en el último piso, es un élite de nivel 23: más fácil a nivel 23 o con un amigo. Lleva {item:8066} en tus bolsas y úsalo con él cada vez que te acerques, o se vuelve hostil. Primero roba con Robar la Llave de la torre de Silixiz a {npc:7287} (nivel 22), que camina junto a la torre: ponte en sigilo detrás de él (matarlo no la da). Luego despeja la torre piso por piso (todo vuelve a los 4 minutos y medio): Zánganos mutados de Ventura y Cía. (25) en la planta baja, patrulleros en el segundo, vigías en el tercero abierto, Gallywix arriba, que vuelve 10 minutos después de morir. Fuerza {object:129127}, a su lado, para el alijo: te envenena con {spell:9810}, que debilita tu sigilo y agilidad hasta que {npc:2391} te cura.",
		["{object:129127} at the end of the tower job needs Lockpicking of about 70-75. Train {spell:1804} from Gest or {npc:3401} in the {object:172960} if you lack it, carry {item:5060}, and pick the Buccaneer's Strongboxes on the middle deck of the Tide Razor, the beached pirate ship south of {area:392}: they come back fast. Your cap rises 5 per level."] = "{object:129127}, al final del trabajo de la torre, necesita unos 70-75 de Forzar cerraduras. Entrena {spell:1804} con Gest o {npc:3401} en {object:172960} si no la tienes, lleva {item:5060} y fuerza las cajas fuertes de bucanero de la cubierta del medio del Navaja de la Marea, el barco pirata varado al sur de {area:392}: vuelven rápido. Tu tope sube 5 por nivel.",
		["{quest:2458}: keep the {item:8051}"] = "{quest:2458}: guarda la {item:8051}",
} end)()
t.guides["forever/class/rogue/ravenholdt"] = (function() return {
		["At 24 any capital's rogue trainer ({npc:332} or {npc:918} in {zone:1453}, Gest or Ormok in {zone:1454}, and the others) has an {item:17126} from {npc:13936} for you: ask for it in their talk window. Open it: the quest gives you the {item:17125} for {npc:6707}. Learn {spell:1846} from your trainer first if you have not; the way in is a test of it."] = "A nivel 24, el instructor de pícaros de cualquier capital ({npc:332} o {npc:918} en {zone:1453}, Gest u Ormok en {zone:1454}, y los demás) tiene una {item:17126} de {npc:13936} para ti: pídesela en su ventana de diálogo. Ábrela: la misión te da {item:17125} para {npc:6707}. Aprende antes {spell:1846} con tu instructor si no la tienes; la entrada es una prueba de eso.",
		["Back to {npc:13085}"] = "Regresa con {npc:13085}",
		["Back to {npc:13085}; the report sends you after the Perenolde heirlooms. Two towers stand among the {area:281}, in the middle of the {zone:1416}, held by ogres: the shield lies in the northern tower, the sword in the southern one, which elite ogres ring and watch from far off. Stay stealthed; nothing guards the heirlooms inside."] = "De vuelta con {npc:13085}; el informe te manda tras las reliquias de los Perenolde. Hay dos torres entre {area:281}, en el centro de {zone:1416}, ocupadas por ogros: el escudo está en la torre norte y la espada en la sur, rodeada de ogros élite que vigilan desde lejos. Mantente en sigilo; nada custodia las reliquias adentro.",
		["Falconcrest's men make the handoff at the southern end of {area:1057}, the old wall between Arathi and {area:287}. Kill the two guarding the box and take the {item:275882}. Keep the {item:275706}: {npc:13085} wants it back with the shipment."] = "Los hombres de Crestahalcón hacen la entrega en el extremo sur de {area:1057}, la vieja muralla entre Arathi y {area:287}. Mata a los dos que custodian la caja y toma {item:275882}. Guarda {item:275706}: {npc:13085} lo quiere de vuelta con el cargamento.",
		["Horde fly to {area:272}, Alliance to {area:271}. The trail to the manor is hard to see: it starts behind the plateau north of {area:275}, east of {area:272}, climbs into the hills and bends twice to a small tunnel. A chest sits in the tunnel: do not open it. Cast {spell:1846} near it and walk up close; that is the Rite of Cunning (it comes back after 5 minutes). Opening the chest calls Milton, an elite rogue of about level 32. Through the tunnel lies {area:3486}: {npc:6707} is upstairs inside. Do not attack anyone at the manor: it costs {npc:13936} reputation."] = "La Horda vuela a {area:272}, la Alianza a {area:271}. El sendero a la mansión cuesta verlo: empieza detrás de la meseta al norte de {area:275}, al este de {area:272}, sube a las colinas y dobla dos veces hasta un pequeño túnel. Hay un cofre en el túnel: no lo abras. Lanza {spell:1846} cerca y acércate caminando; ese es el Rito de la Astucia (vuelve a los 5 minutos). Abrir el cofre llama a Milton, un pícaro élite de nivel 32 más o menos. Pasando el túnel está {area:3486}: {npc:6707} está adentro, en el piso de arriba. No ataques a nadie en la mansión: cuesta reputación con {npc:13936}.",
		["In your mid 30s {npc:13085} has two more jobs; take both. {npc:266357} leads a Syndicate scouting party at {area:280}, in the east of the {zone:1416}, inside one of the houses with stealthed Syndicate around him. Pick his pocket for the report and do not kill him: he does not drop it. If you are lower than him he sees through stealth; Master of Deception helps, or Distract him, Vanish and come in from behind. {spell:921} can miss several times in a row."] = "A mediados de tus treintas, {npc:13085} tiene dos trabajos más; toma ambos. {npc:266357} dirige una partida de exploración del Sindicato en {area:280}, en el este de {zone:1416}, dentro de una de las casas, con miembros del Sindicato en sigilo a su alrededor. Róbale el informe y no lo mates: no lo suelta. Si eres de menor nivel que él, te ve a través del sigilo; Maestro del engaño ayuda, o distráelo, usa Esfumarse y entra por detrás. {spell:921} puede fallar varias veces seguidas.",
		["Opens {area:3486}, the hidden rogue house in the Alterac hills, and {npc:13085}'s jobs against the Syndicate."] = "Abre {area:3486}, la casa oculta de los pícaros en las colinas de Alterac, y los trabajos de {npc:13085} contra el Sindicato.",
		["Pick Pocket Barton for {item:275482}"] = "Roba a Barton para {item:275482}",
		["Pick Pocket Syndicate members for {quest:6701}"] = "Roba a los miembros del Sindicato para {quest:6701}",
		["Rite of Cunning: {spell:1846} beside the tunnel chest"] = "Rito de la Astucia: {spell:1846} junto al cofre del túnel",
		["She will not talk without something to bargain with. Her stash is upstairs in a house close to the keep: take the {item:275709}. If it is already open, wait for it to come back."] = "No va a hablar sin algo con qué negociar. Su escondite está en el piso de arriba de una casa cerca del castillo: toma {item:275709}. Si ya está abierto, espera a que vuelva.",
		["Stromgarde's Syndicate Prowlers and Conjurors are elite (level 35-36): a rogue of 36 can slip past them, but fighting one alone is hard, so stay hidden or bring a friend. Put on the {item:275706} ({quest:96784} hands it to you at the footlocker) to pass as one of them; stealth or suspicious acts can break it. If the footlocker gave you no uniform, Anastasia hands you one with {quest:96785}. {npc:266847} is not inside the keep: she stands on a ledge on the outside of the castle wall. Jump across to it from the roof of the house beside the ledge."] = "Los merodeadores y conjuradores del Sindicato de Stromgarde son élite (nivel 35-36): un pícaro de nivel 36 puede pasar a su lado sin que lo vean, pero pelear solo con uno es difícil, así que mantente oculto o trae a un amigo. Ponte {item:275706} ({quest:96784} te lo da en el baúl) para hacerte pasar por uno de ellos; el sigilo o los actos sospechosos pueden romperlo. Si el baúl no te dio uniforme, Anastasia te da uno con {quest:96785}. {npc:266847} no está dentro del castillo: está en una cornisa por fuera de la muralla. Salta hasta ella desde el techo de la casa junto a la cornisa.",
		["The {item:17126}"] = "{item:17126}",
		["{area:324} in western Arathi is a Syndicate stronghold; to get in you need a uniform. {area:313}, in north-western Arathi, is held by Syndicate Highwaymen, Pathstalkers and Mercenaries (level 30-32): find the {object:656157} there and take the uniform; that ends {quest:96783}."] = "{area:324}, en el oeste de Arathi, es un bastión del Sindicato; para entrar necesitas un uniforme. {area:313}, en el noroeste de Arathi, la ocupan salteadores, caminantes de senda y mercenarios del Sindicato (nivel 30-32): busca ahí {object:656157} y toma el uniforme; eso termina {quest:96783}.",
		["{item:275635}, in the southern tower"] = "{item:275635}, en la torre sur",
		["{item:275636}, in the northern tower"] = "{item:275636}, en la torre norte",
		["{item:275709}: Anastasia's Stash"] = "{item:275709}: el escondite de Anastasia",
		["{npc:13085}: 70 silver, 300 {npc:13936} reputation"] = "{npc:13085}: 70 de plata, 300 de reputación con {npc:13936}",
		["{npc:13936} reputation"] = "Reputación con {npc:13936}",
		["{npc:266216} is inside {area:275}, the Syndicate fortress south of the manor; he can stand in any of fifteen spots in the keep, so search. Quick and quiet, says {npc:13085}. Pick the pockets of the level 20-21 Syndicate Rogues, Shadow Mages and Watchmen on your way: they carry {quest:6701} for the guards' repeatable reputation quest."] = "{npc:266216} está dentro de {area:275}, la fortaleza del Sindicato al sur de la mansión; puede estar en cualquiera de quince lugares del castillo, así que búscalo. Rápido y en silencio, dice {npc:13085}. Roba a los pícaros, magos de las sombras y vigilantes del Sindicato de nivel 20-21 en el camino: llevan {quest:6701} para la misión repetible de reputación de los guardias.",
		["{npc:6766}: one emblem each time, 100 reputation"] = "{npc:6766}: un emblema cada vez, 100 de reputación",
		["{quest:96784}: the {item:275706}"] = "{quest:96784}: {item:275706}",
} end)()
t.guides["forever/class/rogue/the-azure-key"] = (function() return {
		["Alliance fly to {area:3137}, Horde to {area:1237}. Only the level 50-51 Timbermaw Shamans in the furbolg hills of northern {zone:1447} carry the bag (the level 47-49 furbolgs further south do not): about one kill in thirty drops it. {spell:921} them instead and you lose no Timbermaw reputation; if you are Unfriendly or better with {area:1769}, mark them At War in your reputation panel first. They cast {spell:403} and {spell:6535}, heal each other and run at low health."] = "La Alianza vuela a {area:3137}, la Horda a {area:1237}. Solo los chamanes Fauces de Madera de nivel 50-51, en las colinas de los fúrbolgs del norte de {zone:1447}, llevan la bolsa (los fúrbolgs de nivel 47-49 más al sur no): más o menos una muerte de cada treinta la suelta. Usa {spell:921} sobre ellos en su lugar y no pierdes reputación con los Fauces de Madera; si eres Adverso o mejor con {area:1769}, márcalos antes como En guerra en tu panel de reputación. Lanzan {spell:403} y {spell:6535}, se curan entre ellos y huyen con poca salud.",
		["At 50 {npc:3328} in the {object:172960} has it; so does {npc:4583} in the {zone:1458}'s {object:36073}."] = "A nivel 50, {npc:3328} en {object:172960} la tiene; también {npc:4583} en {object:36073} de {zone:1458}.",
		["At 50 {npc:918} in {zone:1453}'s {object:2100} has it; so do Syurna in {zone:1457} and {npc:5165} in {zone:1455}."] = "A nivel 50 la tiene {npc:918}, en {object:2100} de {zone:1453}; también Syurna en {zone:1457} y {npc:5165} en {zone:1455}.",
		["Back to Xylem"] = "Regresa con Xylem",
		["Look at the reward window before you hand in: Classic offered the {item:19982}, the {item:19984} or the {item:20255}, and Forever's notes say the choice may be gone."] = "Mira la ventana de recompensas antes de entregar: Classic ofrecía {item:19982}, {item:19984} o {item:20255}, y las notas de Forever dicen que puede que la elección ya no esté.",
		["Lord Ravenholdt"] = "Lord Ravenholdt",
		["Morphaz in the {area:1417}"] = "Morphaz en {area:1417}",
		["Morphaz, a level 52 elite green drake, lives deep in the {area:1417}: a group of five, level 50-54. The temple stands in the {area:74}; climb into the sunken building, swim down through it and follow the passage to the portal. Horde: fly to {area:75}; Alliance: fly to {area:1438} and ride on. He is not there when you arrive: first kill the six troll guardians (elites of 50-52) on the platforms around the upper ring, which opens the way down (the left-hand ramp from the entrance) to {npc:5710} in the Pit of Sacrifice. Jammal'an's death brings out two drakes, Weaver and Dreamscythe; when both are dead, Morphaz and Hazzas appear together and fight as a pair. Their {spell:12533} is nature damage: nature protection potions help; poisons and {spell:2094} do not work on them. The key always drops. Hunters, Priests and Mages of 50 need Morphaz too: one clear serves them all."] = "Morphaz, un draco verde élite de nivel 52, vive en lo profundo de {area:1417}: un grupo de cinco, nivel 50-54. El templo está en {area:74}; entra al edificio hundido, nada hacia abajo por dentro y sigue el pasaje hasta el portal. Horda: vuela a {area:75}; Alianza: vuela a {area:1438} y sigue a caballo. No está cuando llegas: primero mata a los seis guardianes trol (élites de 50-52) de las plataformas del anillo superior, lo que abre el camino de bajada (la rampa izquierda desde la entrada) hasta {npc:5710} en el Foso del Sacrificio. La muerte de Jammal'an saca a dos dracos, Tejedor y Guadañasueño; cuando ambos mueren, Morphaz y Hazzas aparecen juntos y pelean en pareja. Su {spell:12533} es daño de naturaleza: las pociones de protección contra la naturaleza ayudan; los venenos y {spell:2094} no funcionan con ellos. La llave siempre cae. Los cazadores, sacerdotes y magos de nivel 50 también necesitan a Morphaz: una limpieza sirve para todos.",
		["Ravenholdt reputation"] = "Reputación con Ravenholdt",
		["Ravenholdt reputation and experience at 50; Classic's item choice may be gone on Forever."] = "Reputación con Ravenholdt y experiencia a nivel 50; puede que en Forever ya no esté la elección de objeto de Classic.",
		["The Forest Oozes (level 52-53, {spell:6907} up close) drop a fragment four times in five: the biggest group, seven of them, is in the {area:2497} hills of north-eastern {zone:1447}, four more south-east of {area:1237}. Pick their pockets before the kill for an extra fragment or two. Killing the Mistwing Ravagers and hippogryphs that share their spots makes more oozes appear."] = "Los mocos del bosque (nivel 52-53, {spell:6907} de cerca) sueltan un fragmento cuatro de cada cinco veces: el grupo más grande, siete, está en las colinas de {area:2497}, en el noreste de {zone:1447}, y hay cuatro más al sureste de {area:1237}. Róbales antes de matarlos para uno o dos fragmentos extra. Matar a los devastadores alabruma y los hipogrifos que comparten sus lugares hace aparecer más mocos.",
		["{area:3486} hides in the hills east of {area:272}. Horde fly to {area:272}, Alliance to {area:271}. The trail starts behind the plateau north of {area:275}, climbs into the hills and runs through a small tunnel into the {zone:1416}; Lord Jorach is inside the manor. Do not attack anyone at the manor: lost Ravenholdt reputation makes him refuse to speak to you."] = "{area:3486} se esconde en las colinas al este de {area:272}. La Horda vuela a {area:272}, la Alianza a {area:271}. El sendero empieza detrás de la meseta al norte de {area:275}, sube a las colinas y pasa por un pequeño túnel hacia {zone:1416}; lord Jorach está dentro de la mansión. No ataques a nadie en la mansión: perder reputación con Ravenholdt hace que se niegue a hablarte.",
		["{item:20022}: Morphaz, inside the temple"] = "{item:20022}: Morphaz, dentro del templo",
		["{npc:8395}, camped below the cliffs just east of {area:1237}, teleports you up (dismount first); a trail leads to Xylem's tower."] = "{npc:8395}, que acampa debajo de los acantilados justo al este de {area:1237}, te teletransporta arriba (bájate de la montura antes); un sendero lleva a la torre de Xylem.",
		["{quest:8233} (Alliance)"] = "{quest:8233} (Alianza)",
		["{quest:8233} (Horde)"] = "{quest:8233} (Horda)",
} end)()
t.guides["forever/class/rogue/the-eye-of-bhossca"] = (function() return {
		["Back to the dead drop"] = "Regresa al buzón secreto",
		["C's dead drop"] = "El buzón secreto de C",
		["C's next job comes by letter: once you are level 30 and have done the horn job (The {item:210183}, its payment from this {object:410369} handed in), visit any capital city and C's letter arrives in the mailbox; only then does the {object:410369} near {area:204}, in southern Silverpine just south of {area:236}, offer it. The quest data lists a minimum of 25, but players get the letter, and the job, at 30."] = "El siguiente trabajo de C llega por carta: cuando tengas nivel 30 y hayas hecho el trabajo del cuerno ({item:210183}, con su pago de este {object:410369} entregado), visita cualquier capital y la carta de C llega al buzón; recién entonces {object:410369}, cerca de {area:204}, en el sur de Bosque de Argénteos justo al sur de {area:236}, lo ofrece. Los datos de la misión dicen nivel mínimo 25, pero los jugadores reciben la carta, y el trabajo, a nivel 30.",
		["Place the eye in the {object:410369} near Pyrewood. Check a capital mailbox for C's payment letter on your next planned city visit, then return here for the reward quest. The payment may not be available immediately; do not repeat the infiltration just because the reward has not appeared."] = "Deja el ojo en {object:410369} cerca de Piroleña. Revisa el buzón de una capital en tu próxima visita planeada para ver la carta de pago de C, y luego vuelve aquí para la misión de recompensa. Puede que el pago no esté disponible enseguida; no repitas la infiltración solo porque la recompensa todavía no apareció.",
		["Solo route: Graveyard key, Library letter, Graveyard benches and coffer, then Library reliquary for the eye. Read the letter before the bench puzzle; check the disguise each time you change wings."] = "Ruta en solitario: llave en el Cementerio, carta en la Biblioteca, bancos y cofre en el Cementerio, y luego el relicario de la Biblioteca para el ojo. Lee la carta antes del acertijo de los bancos; revisa el disfraz cada vez que cambies de ala.",
		["The monastery stands in the far north-east of {zone:1420}. Go in alone, out of any group. Before entering, take the {item:210955} from the {object:412147} in the stables behind the monastery and wear it; stealth and suspicious actions remove it, so put it back on after each wing change. In the Graveyard, in the Chamber of Atonement (the first big room), {spell:921} a {npc:4293} or Scarlet Crier for the {item:210963}. In the Library, open the Personal Letterbox in the Athenaeum with it and read the {item:210967}. It sends you back to sit on both benches between the two statues in the Graveyard. Watch for the mechanism's messages, then take the {item:210968} from the stone coffer: an elite stands by the coffer with a patrol behind it, but from beside the northern mausoleum you can turn the camera until the box shows and click it through the wall (an interact key works too). An elite ghost walks near the mausoleum; the broken piece at its edge keeps you out of its path. Then return to the Library for the locked reliquary and the eye. Avoid fighting through the instance."] = "El monasterio está en el extremo noreste de {zone:1420}. Entra solo, fuera de cualquier grupo. Antes de entrar, toma {item:210955} de {object:412147} en los establos detrás del monasterio y póntelo; el sigilo y las acciones sospechosas lo quitan, así que vuelve a ponértelo cada vez que cambies de ala. En el Cementerio, en la Cámara de la Expiación (la primera sala grande), usa {spell:921} sobre un {npc:4293} o un pregonero Escarlata para {item:210963}. En la Biblioteca, abre con él el buzón personal del Athenaeum y lee {item:210967}. Te manda de vuelta a sentarte en los dos bancos entre las dos estatuas del Cementerio. Atento a los mensajes del mecanismo, y luego toma {item:210968} del cofre de piedra: un élite está junto al cofre con una patrulla detrás, pero desde al lado del mausoleo norte puedes girar la cámara hasta ver la caja y hacer clic a través de la pared (una tecla de interactuar también sirve). Un fantasma élite camina cerca del mausoleo; el trozo roto en su borde te mantiene fuera de su camino. Luego vuelve a la Biblioteca por el relicario cerrado y el ojo. Evita pelear a lo largo de la instancia.",
		["The {area:796}"] = "El {area:796}",
		["The {item:277246}, C's payment for a solo job in the {area:796}, after The {item:210183}."] = "{item:277246}, el pago de C por un trabajo en solitario en el {area:796}, después de {item:210183}.",
		["the locked reliquary in the Library"] = "el relicario cerrado de la Biblioteca",
} end)()
t.guides["forever/class/rogue/the-horn-of-xelthos"] = (function() return {
		["Back to the dead drop"] = "De vuelta al buzón secreto",
		["C's dead drop"] = "El buzón secreto de C",
		["Go in alone and use the {item:210186} at the courtyard gate. Players also report a freed prisoner opening the courtyard door for you: if you die while he is opening it, stay dead until it is open; it stays open once you release. If you know Vanish, bring {item:5140} and check its cooldown before entering; keep it ready for a failed approach. Pickpocket the sister in the dining hall for the {item:210213}, then the brother in the room reached by turning right at the top of the stairs for the {item:210212} (a level 20 rogue without Vanish may need ranks in Master of Deception to reach the second one unseen). Combine them somewhere safe: this breaks stealth. Free a bag slot first: opening the chest with full bags can use up the key without giving the horn. Return to the courtyard stables and use the combined key on the chest for the horn. Stay clear of the nearby elites; the minimum quest level does not guarantee a safe approach."] = "Entra solo y usa {item:210186} en la puerta del patio. Los jugadores también dicen que un prisionero liberado te abre la puerta del patio: si mueres mientras la abre, quédate muerto hasta que esté abierta; queda abierta cuando liberas el espíritu. Si conoces Esfumarse, lleva {item:5140} y revisa su reutilización antes de entrar; tenlo listo por si falla el acercamiento. Roba a la hermana en el comedor para {item:210213} y luego al hermano en la sala a la que llegas doblando a la derecha arriba de la escalera para {item:210212} (un pícaro de nivel 20 sin Esfumarse puede necesitar rangos en Maestro del engaño para llegar al segundo sin ser visto). Combínalas en un lugar seguro: esto rompe el sigilo. Libera antes un espacio en las bolsas: abrir el cofre con las bolsas llenas puede gastar la llave sin darte el cuerno. Vuelve a los establos del patio y usa la llave combinada sobre el cofre para el cuerno. Mantente lejos de los élites cercanos; el nivel mínimo de la misión no garantiza un acercamiento seguro.",
		["Open the {object:410369} again, the chest outside Pyrewood you took the job from, and hand in the horn there. C's payment is a second hand-in at the same chest, with nothing to accept first, and it may not be there right away: players have waited from a quarter of an hour to two hours. Check a capital mailbox for C's follow-up letter on your next planned city visit, then return to this chest for it. Do not repeat the dungeon just because the payment is not yet offered."] = "Abre {object:410369} otra vez, el cofre cerca de Piroleña donde tomaste el trabajo, y entrega ahí el cuerno. El pago de C es una segunda entrega en el mismo cofre, sin nada que aceptar antes, y puede que no esté ahí enseguida: hay jugadores que han esperado de un cuarto de hora a dos horas. Revisa el buzón de una capital en tu próxima visita planeada para ver la carta de C, y luego vuelve a este cofre por él. No repitas la mazmorra solo porque el pago todavía no se ofrece.",
		["The {item:277210}, C's payment for a solo job inside {area:236}."] = "{item:277210}, el pago de C por un trabajo en solitario dentro de {area:236}.",
		["The {object:410369} is a chest in a house just outside {area:204} in southern Silverpine, south of {area:236}. Open it and read C's note: the job has to be done alone, out of any group."] = "{object:410369} es un cofre en una casa justo afuera de {area:204}, en el sur de Bosque de Argénteos, al sur de {area:236}. Ábrelo y lee la nota de C: el trabajo hay que hacerlo solo, fuera de cualquier grupo.",
		["{item:210183}, inside {area:236}"] = "{item:210183}, dentro de {area:236}",
		["{spell:921} a {npc:3989} for a {item:210187}"] = "{spell:921} a un {npc:3989} para una {item:210187}",
} end)()
t.guides["forever/class/shaman/call-of-air-alliance"] = (function() return {
		["At 30 {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:259023} in {zone:1417}. Your level 30 air totems (Grounding, {spell:10596}) need the {item:5178} he gives."] = "A nivel 30, {npc:258098}, el instructor de chamanes en {zone:1455}, te manda con {npc:259023} en {zone:1417}. Tus tótems de aire de nivel 30 (Derribo, {spell:10596}) necesitan {item:5178}, que te da él.",
		["Five Twisted Air Totems. The Maraudine centaurs (level 36-40) north and north-east of {area:2408} in western {zone:1443} carry them; the Scouts drop one nearly every other kill. Wranglers Net and Disarm, Windchasers heal, Stormers throw {spell:9654}: pull one at a time. Respawn about five minutes."] = "Cinco Tótems de aire retorcidos. Los centauros Maraudine (nivel 36-40) al norte y noreste de {area:2408}, en el oeste de {zone:1443}, los llevan; los exploradores sueltan uno casi en una de cada dos muertes. Los domadores lanzan red y desarman, los cazavientos curan y los tormenteros lanzan {spell:9654}: atráelos de a uno. Reaparecen en unos cinco minutos.",
		["Five Twisted Earth Totems. The Lost Ones (murlocs, level 34-39) north and north-east of {area:75} in the {zone:1435} carry them; most run for help when hurt."] = "Cinco Tótems de tierra retorcidos. Los Perdidos (múrlocs, nivel 34-39) al norte y noreste de {area:75}, en {zone:1435}, los llevan; la mayoría huye a pedir ayuda cuando está herida.",
		["Five Twisted Fire Totems. The Stonevault troggs (Skullthumpers, Bonesnappers and Shamans, level 37-41) south of {area:338} in the {zone:1418} carry them; the Shamans drop Fire Nova Totems and a {npc:3560}, the Bonesnappers run for help when hurt. Respawn about five minutes."] = "Cinco Tótems de fuego retorcidos. Los troggs Cámara de Piedra (machacacráneos, rompehuesos y chamanes, nivel 37-41) al sur de {area:338}, en {zone:1418}, los llevan; los chamanes ponen Tótems de nova de fuego y un {npc:3560}, y los rompehuesos huyen a pedir ayuda cuando están heridos. Reaparecen en unos cinco minutos.",
		["Five Twisted Water Totems. The Mirefin murlocs (level 35-38) north-east of {area:496} in northern {zone:1445} carry them."] = "Cinco Tótems de agua retorcidos. Los múrlocs Aleta Fango (nivel 35-38) al noreste de {area:496}, en el norte de {zone:1445}, los llevan.",
		["The steam pools"] = "Las pozas de vapor",
		["The {item:5178} that lets you place air totems, then a weapon of your choice at 40."] = "El {item:5178} que te permite colocar tótems de aire, y luego un arma a tu elección a nivel 40.",
		["Twisted Air Totems"] = "Tótems de aire retorcidos",
		["Twisted Earth Totems"] = "Tótems de tierra retorcidos",
		["Twisted Fire Totems"] = "Tótems de fuego retorcidos",
		["Twisted Water Totems"] = "Tótems de agua retorcidos",
		["{area:1717} is a five-player dungeon at the southern edge of the {zone:1413} (the arrow points at its entrance); {npc:4421} (level 33 elite) is its last boss. She casts {spell:8292}, {spell:139} on her allies and Purity; the {item:274463} drops only from her."] = "{area:1717} es una mazmorra de cinco jugadores en el borde sur de {zone:1413} (la flecha señala su entrada); {npc:4421} (élite de nivel 33) es su último jefe. Lanza {spell:8292}, {spell:139} sobre sus aliados y Pureza; {item:274463} solo lo suelta ella.",
		["{item:212792}, from the {npc:216474}"] = "{item:212792}, de {npc:216474}",
		["{item:274463}, from {npc:4421}"] = "{item:274463}, de {npc:4421}",
		["{npc:259023} camps in the hills just west of {area:321}, the Horde town in the north-east of Arathi: mind its guards. Fly to {area:320} and head north-east."] = "{npc:259023} acampa en las colinas justo al oeste de {area:321}, el pueblo de la Horda en el noreste de Arathi: cuidado con sus guardias. Vuela a {area:320} y ve al noreste.",
		["{npc:259023} hands you the {item:268582}. {zone:1441} is far: the boat to Theramore and the road west, or fly to {area:489} on the {zone:1444} border and head east into the canyon. Place the {item:268582} at the steam pools north-west of {area:484} to call the corrupted elementals and then the {npc:216474}; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The {item:212792} drops about every other kill, and every group member can loot it."] = "{npc:259023} te da {item:268582}. {zone:1441} está lejos: el barco a Theramore y el camino al oeste, o vuela a {area:489}, en la frontera con {zone:1444}, y ve al este hacia el cañón. Coloca {item:268582} en las pozas de vapor al noroeste de {area:484} para llamar a los elementales corrompidos y luego a la {npc:216474}; los jabaespines Crines de Acero se unen a la pelea mientras dura el ritual. Es una misión de grupo: lleva al menos uno o dos amigos. {item:212792} cae más o menos en una de cada dos muertes, y todos los del grupo pueden saquearlo.",
		["{npc:259023}: your {item:5178}"] = "{npc:259023}: tu {item:5178}",
		["{npc:6176} camps in the ruins in the east of {zone:1416}: from {area:272} follow the river east of town north into the hills. Pick your weapon: {item:280607}, {item:280605} or {item:280604}."] = "{npc:6176} acampa en las ruinas del este de {zone:1416}: desde {area:272} sigue el río al este del pueblo hacia el norte, hasta las colinas. Elige tu arma: {item:280607}, {item:280605} o {item:280604}.",
		["{npc:6176}: the {item:280696} and your weapon"] = "{npc:6176}: {item:280696} y tu arma",
		["{quest:94789} and the Tempest's Weapons (Alliance)"] = "{quest:94789} y las armas de la Tempestad (Alianza)",
} end)()
t.guides["forever/class/shaman/call-of-air-horde"] = (function() return {
		["At 30 Skyborne shamans get their own {quest:96136}. {npc:259119} waits where the airship from Zephras Isle lands, in northern {zone:1412} beside {zone:1456}. Your level 30 air totems need the Air Totem Prate Cloudseer gives. If she has nothing for you, head up to {npc:5906} in {zone:1456} (next step): the trainers' {quest:96136} is open to Skyborne and gives the same totem."] = "A nivel 30, los chamanes Skyborne tienen su propia {quest:96136}. {npc:259119} espera donde aterriza el barco aéreo desde la isla Zephras, en el norte de {zone:1412}, junto a {zone:1456}. Tus tótems de aire de nivel 30 necesitan el Tótem de aire que da Prate Cloudseer. Si no tiene nada para ti, sube con {npc:5906} en {zone:1456} (siguiente paso): la {quest:96136} de los instructores está abierta para los Skyborne y da el mismo tótem.",
		["At 30 {npc:5892} in the {object:172957} sends you to {npc:5905} in {zone:1441}. Your level 30 air totems (Grounding, {spell:10596}) need the {item:5178} she gives."] = "A nivel 30, {npc:5892}, en {object:172957}, te manda con {npc:5905} en {zone:1441}. Tus tótems de aire de nivel 30 (Derribo, {spell:10596}) necesitan {item:5178}, que te da ella.",
		["At 30 {npc:5906}, a shaman trainer on {area:1640} in {zone:1456}, sends you to {npc:5905} in {zone:1441}. Your level 30 air totems (Grounding, {spell:10596}) need the Air Totem Prate gives. Already carry {npc:5892}'s {quest:1532} from {zone:1454}? It goes to {npc:5905} too: skip {npc:5906}."] = "A nivel 30, {npc:5906}, un instructor de chamanes en {area:1640} en {zone:1456}, te manda con {npc:5905} en {zone:1441}. Tus tótems de aire de nivel 30 (Derribo, {spell:10596}) necesitan el Tótem de aire que da Prate. ¿Ya llevas {quest:1532} de {npc:5892} desde {zone:1454}? También va para {npc:5905}: omite a {npc:5906}.",
		["Five Twisted Air Totems. The Maraudine centaurs (level 36-40) north and north-east of {area:2408} in western {zone:1443} carry them; the Scouts drop one nearly every other kill. Wranglers Net and Disarm, Windchasers heal, Stormers throw {spell:9654}: pull one at a time. Respawn about five minutes."] = "Cinco Tótems de aire retorcidos. Los centauros Maraudine (nivel 36-40) al norte y noreste de {area:2408}, en el oeste de {zone:1443}, los llevan; los exploradores sueltan uno casi en una de cada dos muertes. Los domadores lanzan red y desarman, los cazavientos curan y los tormenteros lanzan {spell:9654}: atráelos de a uno. Reaparecen en unos cinco minutos.",
		["Five Twisted Earth Totems. The Lost Ones (murlocs, level 34-39) north and north-east of {area:75} in the {zone:1435} carry them; most run for help when hurt."] = "Cinco Tótems de tierra retorcidos. Los Perdidos (múrlocs, nivel 34-39) al norte y noreste de {area:75}, en {zone:1435}, los llevan; la mayoría huye a pedir ayuda cuando está herida.",
		["Five Twisted Fire Totems. The Stonevault troggs (Skullthumpers, Bonesnappers and Shamans, level 37-41) south of {area:338} in the {zone:1418} carry them; the Shamans drop Fire Nova Totems and a {npc:3560}, the Bonesnappers run for help when hurt. Respawn about five minutes."] = "Cinco Tótems de fuego retorcidos. Los troggs Cámara de Piedra (machacacráneos, rompehuesos y chamanes, nivel 37-41) al sur de {area:338}, en {zone:1418}, los llevan; los chamanes ponen Tótems de nova de fuego y un {npc:3560}, y los rompehuesos huyen a pedir ayuda cuando están heridos. Reaparecen en unos cinco minutos.",
		["Five Twisted Water Totems. The Mirefin murlocs (level 35-38) north-east of {area:496} in northern {zone:1445} carry them."] = "Cinco Tótems de agua retorcidos. Los múrlocs Aleta Fango (nivel 35-38) al noreste de {area:496}, en el norte de {zone:1445}, los llevan.",
		["Fly to {area:484}. {npc:5905} stands on a ledge above a cave mouth in the canyon wall north-east of the post, not inside the cave: climb the slope beside it. She also gives you an hour of faster attacks and running."] = "Vuela a {area:484}. {npc:5905} está en una cornisa sobre la entrada de una cueva en la pared del cañón al noreste del puesto, no dentro de la cueva: sube por la pendiente de al lado. También te da una hora de ataques y carrera más rápidos.",
		["The steam pools"] = "Las pozas de vapor",
		["The {item:5178} that lets you place air totems, then a weapon of your choice at 40."] = "El {item:5178}, que te permite colocar tótems de aire, y luego un arma a tu elección a nivel 40.",
		["Twisted Air Totems"] = "Tótems de aire retorcidos",
		["Twisted Earth Totems"] = "Tótems de tierra retorcidos",
		["Twisted Fire Totems"] = "Tótems de fuego retorcidos",
		["Twisted Water Totems"] = "Tótems de agua retorcidos",
		["{area:1717} is a five-player dungeon at the southern edge of the {zone:1413} (the arrow points at its entrance); {npc:4421} (level 33 elite) is its last boss. She casts {spell:8292}, {spell:139} on her allies and Purity; the {item:274463} drops only from her."] = "{area:1717} es una mazmorra de cinco jugadores en el borde sur de {zone:1413} (la flecha señala su entrada); {npc:4421} (élite de nivel 33) es su último jefe. Lanza {spell:8292}, {spell:139} sobre sus aliados y Pureza; {item:274463} solo lo suelta ella.",
		["{item:212792}, from the {npc:216474}"] = "{item:212792}, de la {npc:216474}",
		["{item:274463}, from {npc:4421}"] = "{item:274463}, de {npc:4421}",
		["{npc:4722} stands at {area:484}."] = "{npc:4722} está en {area:484}.",
		["{npc:5905} hands you the {item:268582}. Place the {item:268582} at the steam pools north-west of {area:484} to call the corrupted elementals and then the {npc:216474}; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The {item:212792} drops about every other kill, and every group member can loot it."] = "{npc:5905} te da {item:268582}. Coloca {item:268582} en las pozas de vapor al noroeste de {area:484} para llamar a los elementales corrompidos y luego a la {npc:216474}; los jabaespines Crines de Acero se unen a la pelea mientras dura el ritual. Es una misión de grupo: lleva al menos uno o dos amigos. {item:212792} cae más o menos en una de cada dos muertes, y todos los del grupo pueden saquearlo.",
		["{npc:5905}: your {item:5178}"] = "{npc:5905}: tu {item:5178}",
		["{npc:6176} camps in the ruins in the east of {zone:1416}: from {area:272} follow the river east of town north into the hills. Pick your weapon: {item:280607}, {item:280605} or {item:280604}; the {item:280696} shield comes with it."] = "{npc:6176} acampa en las ruinas del este de {zone:1416}: desde {area:272} sigue el río al este del pueblo hacia el norte, hasta las colinas. Elige tu arma: {item:280607}, {item:280605} o {item:280604}; el escudo {item:280696} viene con ella.",
		["{npc:6176}: the {item:280696} and your weapon"] = "{npc:6176}: {item:280696} y tu arma",
		["{quest:1531} and the Tempest's Weapons (Horde)"] = "{quest:1531} y las armas de la Tempestad (Horda)",
} end)()
t.guides["forever/class/shaman/call-of-earth-alliance"] = (function() return {
		["Back to Teo inside {area:77}. He hands you the {item:6635}: do not drink it yet."] = "De vuelta con Teo dentro de {area:77}. Te da {item:6635}: no lo bebas todavía.",
		["Bring the {item:6656} back to Teo inside {area:77}. Keep the {item:5175} in your bags for good: every earth totem needs it."] = "Lleva {item:6656} de vuelta a Teo dentro de {area:77}. Guarda {item:5175} en tus bolsas para siempre: todo tótem de tierra lo necesita.",
		["Iceclaw Bear Pendants"] = "Colgantes de oso Garrahelada",
		["Lost the {quest:94472}?"] = "¿Perdiste {quest:94472}?",
		["Only if the {quest:94472} is gone from your bags (drunk away from the stone, or sold): Teo gives you another."] = "Solo si {quest:94472} ya no está en tus bolsas (lo bebiste lejos de la piedra o lo vendiste): Teo te da otro.",
		["Teo's {quest:94373} needs the {quest:98581} handed in first: {npc:658}, where you entered {area:132}, gives it to Dwarf shamans after his {quest:179}. Bring it up the road to {npc:257446} inside {area:77}."] = "{quest:94373} de Teo necesita que antes entregues {quest:98581}: {npc:658}, donde entraste a {area:132}, se la da a los chamanes enanos después de su {quest:179}. Llévala camino arriba hasta {npc:257446}, dentro de {area:77}.",
		["The Frostmane Troll Whelps (level 3-4) hold the snowy slopes west and south-west of {area:77}, and the Frostmane Novices (level 3-4, they throw Frostbolts from range) camp south of it. Both carry the pendants; they respawn in about three minutes."] = "Las crías de trol Peloescarcha (nivel 3-4) ocupan las laderas nevadas al oeste y suroeste de {area:77}, y los novicios Peloescarcha (nivel 3-4, lanzan descargas de escarcha a distancia) acampan al sur. Ambos llevan los colgantes; reaparecen en unos tres minutos.",
		["The Spirit Stone"] = "La Piedra del Espíritu",
		["The Spirit Stone stands on a snowy ridge north-west of {area:77}. The trail is easy to miss: it climbs the hill from the valley floor; at the small camp near the top turn left and the stone comes into view. Stand beside it, drink the {item:6635} and speak to the {npc:5891} before it fades."] = "La Piedra del Espíritu está en una cresta nevada al noroeste de {area:77}. El sendero es fácil de pasar por alto: sube la colina desde el fondo del valle; en el campamentito cerca de la cima, dobla a la izquierda y aparece la piedra. Párate a su lado, bebe {item:6635} y habla con la {npc:5891} antes de que se desvanezca.",
		["Your {item:5175}: without it no earth totem can be cast. {spell:8071} comes with it at level 4."] = "Tu {item:5175}: sin él no puedes lanzar ningún tótem de tierra. {spell:8071} viene con él a nivel 4.",
		["it hands you the {item:6656}: keep it"] = "te da {item:6656}: guárdalo",
		["the level 4 shaman spells"] = "los hechizos de chamán de nivel 4",
		["{item:6635}, beside the Spirit Stone"] = "{item:6635}, junto a la piedra espiritual",
		["{npc:257446} trains shamans inside {area:77}, the hall at the south end of {area:132}. The quest opens at level 4. Never took it and now 10 or more? {npc:258098} in {zone:1455} or {npc:258113} in {area:131} gives you {quest:94373}, a pointer back to Teo: take it for the experience on the way."] = "{npc:257446} entrena chamanes dentro de {area:77}, el salón del extremo sur de {area:132}. La misión se abre a nivel 4. ¿Nunca la tomaste y ya tienes nivel 10 o más? {npc:258098} en {zone:1455} o {npc:258113} en {area:131} te da {quest:94373}, una indicación de vuelta a Teo: tómala por la experiencia en el camino.",
		["{npc:257446}: a new {quest:94472}"] = "{npc:257446}: un {quest:94472} nuevo",
		["{npc:257446}: {spell:8071} and your {item:5175}"] = "{npc:257446}: {spell:8071} y tu {item:5175}",
		["{quest:94373} (Alliance)"] = "{quest:94373} (Alianza)",
} end)()
t.guides["forever/class/shaman/call-of-earth-horde"] = (function() return {
		["Any Al'Aketh cultist can carry the {item:251924}: the Converts (level 2-3) around the standing stones just east of the village, or the Brutes and Neophytes (level 4) in the camp beyond {npc:252095}, south-west of the village. Keep killing until one drops it."] = "Cualquier sectario Al'Aketh puede llevar {item:251924}: los conversos (nivel 2-3) alrededor de las piedras erguidas justo al este de la aldea, o los brutos y neófitos (nivel 4) del campamento pasando a {npc:252095}, al suroeste de la aldea. Sigue matando hasta que uno lo suelte.",
		["Back to Boro in {area:16635}. He hands you the {quest:1462}: do not drink it yet."] = "De vuelta con Boro en {area:16635}. Te da {quest:1462}: no lo bebas todavía.",
		["Back to the Seer in {area:221}. She hands you the {quest:1462}: do not drink it yet."] = "De vuelta con la vidente en {area:221}. Te da {quest:1462}: no lo bebas todavía.",
		["Back to {npc:5887} outside the Den. She hands you the {quest:1462}: do not drink it yet."] = "De vuelta con {npc:5887} afuera de la Guarida. Te da {quest:1462}: no lo bebas todavía.",
		["Bring the {item:6656} back to Boro. Keep the {item:5175} in your bags for good: every earth totem needs it."] = "Lleva {item:6656} de vuelta a Boro. Guarda {item:5175} en tus bolsas para siempre: todo tótem de tierra lo necesita.",
		["Bring the {item:6656} back to the Seer. Keep the {item:5175} in your bags for good: every earth totem needs it."] = "Lleva {item:6656} de vuelta a la vidente. Guarda {item:5175} en tus bolsas para siempre: todo tótem de tierra lo necesita.",
		["Bring the {item:6656} back to {npc:5887} outside the Den. Keep the {item:5175} she gives you in your bags for good: every earth totem needs it."] = "Lleva {item:6656} de vuelta a {npc:5887} afuera de la Guarida. Guarda {item:5175} que te da en tus bolsas para siempre: todo tótem de tierra lo necesita.",
		["Felstalker Hooves"] = "Pezuñas de acechador vil",
		["Felstalkers (level 3-4) prowl the slope below the {area:365}, the cave in the north of the valley, and just inside its mouth among the Vile Familiars. Nearly every {npc:3102} drops a hoof (four kills in five); they respawn in a little over three minutes."] = "Los acechadores viles (nivel 3-4) merodean por la pendiente debajo de {area:365}, la cueva del norte del valle, y justo dentro de su entrada entre los familiares viles. Casi todos los {npc:3102} sueltan una pezuña (cuatro de cada cinco); reaparecen en poco más de tres minutos.",
		["Lost the {quest:1462}?"] = "¿Perdiste {quest:1462}?",
		["Lost the {quest:1463}?"] = "¿Perdiste {quest:1463}?",
		["Only if the {quest:1462} is gone from your bags: the Seer gives you another."] = "Solo si {quest:1462} ya no está en tus bolsas: la vidente te da otro.",
		["Only if the {quest:1463} is gone from your bags (drunk away from the rock, or sold): {npc:5887} gives you another."] = "Solo si {quest:1463} ya no está en tus bolsas (lo bebiste lejos de la roca o lo vendiste): {npc:5887} te da otro.",
		["The Bristleback Shamans (level 3-4) stand among the quilboar huts of {area:358}, east of the camp, and throw the odd {spell:403}. Four kills in five drop a salve; they respawn in about four minutes."] = "Los chamanes Lomopelo (nivel 3-4) están entre las chozas de jabaespines de {area:358}, al este del campamento, y lanzan algún {spell:403}. Cuatro de cada cinco sueltan un ungüento; reaparecen en unos cuatro minutos.",
		["The {area:16988}"] = "{area:16988}",
		["The {area:16988} is the hilltop shrine north-east of Boro: the path up starts on the hill just above the clearing where the flies were. Drink the {item:6635} beside the shrine and speak to the {npc:251166} before it fades."] = "{area:16988} es el santuario en lo alto de la colina al noreste de Boro: el sendero de subida empieza en la colina justo arriba del claro donde estaban las moscas. Bebe {item:6635} junto al santuario y habla con la {npc:251166} antes de que se desvanezca.",
		["Your {item:5175}: without it no earth totem can be cast. {spell:8071} comes with it at level 4."] = "Tu {item:5175}: sin él no puedes lanzar ningún tótem de tierra. {spell:8071} viene con él a nivel 4.",
		["it hands you the {item:6656}: keep it"] = "te da {item:6656}: guárdalo",
		["the level 4 shaman spells"] = "los hechizos de chamán de nivel 4",
		["{area:637} is a small pillar on a low mound due east of {npc:2991}'s well, east of the camp; it only shows from about fifteen yards away, and hostile boars graze around it. Stand beside it and drink the {item:6635}, then speak to the {npc:5891} before it fades (drink again if it does)."] = "{area:637} es un pilar pequeño sobre un montículo bajo justo al este del pozo de {npc:2991}, al este del campamento; solo se ve desde unos quince metros, y jabalíes hostiles pastan alrededor. Párate a su lado y bebe {item:6635}, luego habla con la {npc:5891} antes de que se desvanezca (vuelve a beber si pasa).",
		["{area:639} sits on a ledge in the hills just south of the Den. The {area:638} up starts at the foot of the hills south-west of the Den, between two idle peons; it climbs south-west into the hills, then bends back east to the rock. Stand right beside the stone and drink the {item:6635}: the {npc:5891} appears for a short while, so speak to it at once (walk almost under it if it does not answer). Coming back, you can drop down the ledge towards the Den instead of walking the path."] = "{area:639} está en una cornisa en las colinas justo al sur de la Guarida. {area:638} de subida empieza al pie de las colinas al suroeste de la Guarida, entre dos peones ociosos; sube al suroeste por las colinas y luego dobla de vuelta al este hasta la roca. Párate justo al lado de la piedra y bebe {item:6635}: la {npc:5891} aparece por un rato corto, así que háblale enseguida (acércate casi debajo de ella si no responde). Al volver, puedes bajar de la cornisa hacia la Guarida en vez de ir por el sendero.",
		["{item:6635}, beside the shrine"] = "{item:6635}, junto al santuario",
		["{item:6635}, beside {area:637}"] = "{item:6635}, junto a {area:637}",
		["{item:6635}, beside {area:639}"] = "{item:6635}, junto a {area:639}",
		["{npc:251374}, the shaman trainer, stands in {area:16635}. The quest opens at level 3."] = "{npc:251374}, el instructor de chamanes, está en {area:16635}. La misión se abre a nivel 3.",
		["{npc:251374}: {spell:8071} and your {item:5175}"] = "{npc:251374}: {spell:8071} y tu {item:5175}",
		["{npc:5887} stands just outside the Den, the cave in the middle of the {area:363}. The quest opens at level 4."] = "{npc:5887} está justo afuera de la Guarida, la cueva en el centro de {area:363}. La misión se abre a nivel 4.",
		["{npc:5887}: a new {quest:1463}"] = "{npc:5887}: un {quest:1463} nuevo",
		["{npc:5887}: {spell:8071} and your {item:5175}"] = "{npc:5887}: {spell:8071} y tu {item:5175}",
		["{npc:5888} stands in {area:221}. She may show no quest mark over her head: speak to her anyway. The quest opens at level 4."] = "{npc:5888} está en {area:221}. Puede que no tenga marca de misión sobre la cabeza: háblale igual. La misión se abre a nivel 4.",
		["{npc:5888}: a new {quest:1462}"] = "{npc:5888}: un {quest:1462} nuevo",
		["{npc:5888}: {spell:8071} and your {item:5175}"] = "{npc:5888}: {spell:8071} y tu {item:5175}",
		["{quest:1516} (Horde)"] = "{quest:1516} (Horda)",
} end)()
t.guides["forever/class/shaman/call-of-fire-alliance"] = (function() return {
		["At 10 {npc:258113}, the shaman trainer in {area:131}, or {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:257597}."] = "A nivel 10, {npc:258113}, la instructora de chamanes en {area:131}, o {npc:258098}, el instructor de chamanes en {zone:1455}, te manda con {npc:257597}.",
		["Back through the South Gate tunnel and up the trail to {npc:257597}' cave. Keep the {item:5176} in your bags for good: every fire totem needs it."] = "De vuelta por el túnel de la Puerta Sur y sube por el sendero hasta la cueva de {npc:257597}. Guarda {item:5176} en tus bolsas para siempre: todo tótem de fuego lo necesita.",
		["Back up the trail to {npc:257808}. He makes the {item:6636} from the tar and the pouch: keep it with the torch."] = "Vuelve a subir por el sendero hasta {npc:257808}. Prepara {item:6636} con el alquitrán y la bolsa: guárdalo con la antorcha.",
		["Click the {object:61934} atop the shrine with the torch in your bags to place the ember, then click it again for the next quest: the lit {item:277329}."] = "Haz clic en {object:61934}, en lo alto del santuario, con la antorcha en tus bolsas para colocar la brasa, y luego vuelve a hacer clic para la siguiente misión: {item:277329} encendida.",
		["Climb on past {npc:257808} to the peak. Drink the {item:6636} beside the rock statue there to see the {npc:5893} (level 12): it waits until you strike, but grows stronger the longer it is left, and it is immune to fire. Open at once with {spell:8017} and {spell:8042}. Its {item:6655} drops every time."] = "Sigue subiendo pasando a {npc:257808} hasta la cima. Bebe {item:6636} junto a la estatua de roca de ahí para ver a la {npc:5893} (nivel 12): espera a que ataques, pero se vuelve más fuerte cuanto más tiempo la dejas, y es inmune al fuego. Empieza enseguida con {spell:8017} y {spell:8042}. Su {item:6655} cae siempre.",
		["Follow the road east to the tunnel towards {area:806}. Out of the first tunnel, keep left past {npc:1959} and the tower: a slim trail, hard to see but shown on the minimap, winds up the mountain to {npc:257597}' cave above the farm. He hands you the {item:6653}: keep it until the end of the chain."] = "Sigue el camino al este hasta el túnel hacia {area:806}. Al salir del primer túnel, mantente a la izquierda pasando a {npc:1959} y la torre: un sendero angosto, difícil de ver pero que aparece en el minimapa, sube serpenteando por la montaña hasta la cueva de {npc:257597}, sobre la granja. Te da {item:6653}: guárdala hasta el final de la cadena.",
		["From {npc:257597}' ledge you can drop carefully down the mountain into {zone:1432}, or walk back through the tunnel. {npc:257808} keeps the shrine on the peak just south of {area:144}: a hidden trail along a cliff ledge, marked by stone totems, climbs to it from the road north of the peak."] = "Desde la cornisa de {npc:257597} puedes bajar con cuidado por la montaña hasta {zone:1432}, o volver por el túnel. {npc:257808} cuida el santuario en la cima justo al sur de {area:144}: un sendero oculto por una cornisa del acantilado, marcado con tótems de piedra, sube hasta él desde el camino al norte de la cima.",
		["Lost the {quest:94473}?"] = "¿Perdiste {quest:94473}?",
		["Only if the {quest:94473} is gone from your bags: {npc:257808} gives you another."] = "Solo si {quest:94473} ya no está en tus bolsas: {npc:257808} te da otro.",
		["The Shrine of Eternal Flame"] = "El Santuario de la Llama Eterna",
		["The Stonesplinter Seers (level 13-14) stand among the troggs of {area:923} in the south of the loch, and in the trogg camps north-east of {area:144}. They throw {spell:1245113} from 40 yards and run for help when hurt: pull one at a time. Respawn about five minutes."] = "Los videntes Rompepiedras (nivel 13-14) están entre los troggs de {area:923}, en el sur del lago, y en los campamentos de troggs al noreste de {area:144}. Lanzan {spell:1245113} desde 40 m y huyen a pedir ayuda cuando están heridos: atráelos de a uno. Reaparecen en unos cinco minutos.",
		["The Tunnel Rat Geomancers (level 12-13) work only inside the {area:149} at the north end of the loch, past {area:144}. They cast {spell:2136} behind a {spell:134} and run for help at low health."] = "Los geomantes rata de túnel (nivel 12-13) trabajan solo dentro de {area:149}, en el extremo norte del lago, pasando {area:144}. Lanzan {spell:2136} detrás de un {spell:134} y huyen a pedir ayuda con poca salud.",
		["The {object:61934}"] = "{object:61934}",
		["Your {item:5176} for every fire totem, {spell:3599} with it, and Forever's {item:263412}."] = "Tu {item:5176} para todo tótem de fuego, {spell:3599} con él, y {item:263412} de Forever.",
		["{item:6636}, beside the statue"] = "{item:6636}, junto a la estatua",
		["{npc:257597}: {spell:3599}, your {item:5176} and the {item:263412}"] = "{npc:257597}: {spell:3599}, tu {item:5176} y {item:263412}",
		["{npc:257808}: a new {quest:94473}"] = "{npc:257808}: un {quest:94473} nuevo",
		["{npc:258113}, {area:131}; or {npc:258098}, {zone:1455}"] = "{npc:258113}, {area:131}; o {npc:258098}, {zone:1455}",
		["{quest:94449} (Alliance)"] = "{quest:94449} (Alianza)",
} end)()
t.guides["forever/class/shaman/call-of-fire-horde"] = (function() return {
		["At 10 {npc:252382}, the shaman trainer beside {npc:251968} in {area:16638}, hands you the {item:6653} ({npc:254082} offers the same quest). Already left the isle? A {quest:97243} sends you back to them: take the skycutter from the cliffs south of {area:17045}, north of {zone:1456}. Learn {spell:8050} from her now: {npc:268605}, later in the chain, only takes fire damage."] = "A nivel 10, {npc:252382}, la instructora de chamanes junto a {npc:251968} en {area:16638}, te da {item:6653} ({npc:254082} ofrece la misma misión). ¿Ya saliste de la isla? Una {quest:97243} te manda de vuelta con ellos: toma el cortacielos desde los acantilados al sur de {area:17045}, al norte de {zone:1456}. Aprende ahora {spell:8050} con ella: {npc:268605}, más adelante en la cadena, solo recibe daño de fuego.",
		["At 10 {npc:3066}, the shaman trainer in {area:222}, sends you to {npc:5907} in the {zone:1413}. Already carry {npc:5906}'s letter from {zone:1456}? It goes to {npc:5907} too: skip Narm."] = "A nivel 10, {npc:3066}, el instructor de chamanes de {area:222}, te manda con {npc:5907} en {zone:1413}. ¿Ya llevas la carta de {npc:5906} desde {zone:1456}? También va para {npc:5907}: omite a Narm.",
		["At 10 {npc:3173}, the shaman trainer on the east side of {area:362}, sends you to {npc:5907} in the {zone:1413}. Already carry {npc:5892}'s letter from {zone:1454}? It goes to {npc:5907} too: skip {npc:3173}."] = "A nivel 10, {npc:3173}, el instructor de chamanes del lado este de {area:362}, te manda con {npc:5907} en {zone:1413}. ¿Ya llevas la carta de {npc:5892} desde {zone:1454}? También va para {npc:5907}: omite a {npc:3173}.",
		["Back east over the bridge, then south along the {zone:1411} bank of the river to where the mountains meet the water. The trail up starts at the foot of the mountain beside a small dark stone carved with symbols, near the quilboar camp; it is narrow, and a slip costs fall damage. {npc:5900} keeps the shrine at the top."] = "De vuelta al este por el puente, luego al sur por la orilla de {zone:1411} del río hasta donde las montañas llegan al agua. El sendero de subida empieza al pie de la montaña, junto a una piedrita oscura tallada con símbolos, cerca del campamento de jabaespines; es angosto, y un resbalón cuesta daño por caída. {npc:5900} cuida el santuario de la cima.",
		["Back to {npc:268592} at the Shrine of Flames."] = "De vuelta con {npc:268592} en el Santuario de las Llamas.",
		["Back to {npc:268592}. Accept the last quest, then wait by the {npc:268762} while he performs the ritual; when the fire spirits light the {object:148418}, hold the torch to it. From then you have six minutes: carry the flame straight to the {npc:268679} beside {npc:252382} in {area:16638}, with no detours or fights. Timer out? Abandon the quest and take it again from {npc:268592}."] = "De vuelta con {npc:268592}. Acepta la última misión y luego espera junto al {npc:268762} mientras hace el ritual; cuando los espíritus de fuego enciendan {object:148418}, acerca la antorcha. Desde ahí tienes seis minutos: lleva la llama directo al {npc:268679} junto a {npc:252382} en {area:16638}, sin desvíos ni peleas. ¿Se acabó el tiempo? Abandona la misión y vuelve a tomarla con {npc:268592}.",
		["Back up the trail to {npc:5900}. He makes the {quest:1464} from the tar and the pouch and hands it to you with the torch: keep both."] = "Vuelve a subir por el sendero hasta {npc:5900}. Prepara {quest:1464} con el alquitrán y la bolsa y te lo da con la antorcha: guarda ambos.",
		["Click the {object:61934} on the plateau with the torch in your bags to place the ember, then click it a second time: the next quest does not open by itself. It gives you the lit {item:277329}."] = "Haz clic en {object:61934} de la meseta con la antorcha en tus bolsas para colocar la brasa, y luego vuelve a hacer clic: la siguiente misión no se abre sola. Te da {item:277329} encendida.",
		["Down the trail, back over the bridge to {npc:5907} by his tower. Keep the {item:5176} in your bags for good: every fire totem needs it."] = "Baja por el sendero y vuelve por el puente hasta {npc:5907}, junto a su torre. Guarda {item:5176} en tus bolsas para siempre: todo tótem de fuego lo necesita.",
		["Drink the {item:6636} beside the {object:63674}, the big grey stone just below the summit, then climb to the plateau. Of the fire elementals there only the one in the middle can be attacked: it is level 12, immune to fire and grows stronger the longer the fight lasts, so open at once with {spell:8017} and {spell:8042} and leave the others alone. Its {item:6655} drops every time."] = "Bebe {item:6636} junto a {object:63674}, la gran piedra gris justo debajo de la cima, y luego sube a la meseta. De los elementales de fuego de ahí, solo se puede atacar al del medio: es de nivel 12, inmune al fuego y se vuelve más fuerte cuanto más dura la pelea, así que empieza enseguida con {spell:8017} y {spell:8042} y deja en paz a los otros. Su {item:6655} cae siempre.",
		["Keep the {item:5176} in your bags for good: every fire totem needs it."] = "Guarda {item:5176} en tus bolsas para siempre: todo tótem de fuego lo necesita.",
		["Lost the {quest:1464}?"] = "¿Perdiste {quest:1464}?",
		["Only if the {quest:1464} is gone from your bags: {npc:5900} gives you another."] = "Solo si {quest:1464} ya no está en tus bolsas: {npc:5900} te da otro.",
		["The Burning Blade Cultists (level 10-11, they call imps and cast {spell:348}) live deep in {area:371} north of {area:362}: climb the ramp just north-east of town and stay on the high ground above the ravines. The orcs at the cave mouth are not cultists; the cultists are further in, off to the left. Three kills in four drop a pouch. {area:817} by {zone:1454} is the wrong cave."] = "Los sectarios del Filo Ardiente (nivel 10-11, llaman diablillos y lanzan {spell:348}) viven en lo profundo de {area:371}, al norte de {area:362}: sube por la rampa justo al noreste del pueblo y mantente en lo alto sobre los barrancos. Los orcos de la entrada de la cueva no son sectarios; los sectarios están más adentro, hacia la izquierda. Tres de cada cuatro sueltan una bolsa. {area:817}, junto a {zone:1454}, no es la cueva.",
		["The Razormane casters north-east of the Crossroads drop the {item:5026} three times in four: Water Seekers and Thornweavers (level 10-11), Geomancers (level 12-13, they throw Fireballs and run for help when hurt) and Mystics (level 13-14, they heal themselves at low health). Pull them one at a time."] = "Los lanzadores de hechizos Crines de Acero al noreste del Cruce sueltan {item:5026} tres de cada cuatro veces: buscaaguas y tejespinas (nivel 10-11), geomantes (nivel 12-13, lanzan bolas de fuego y huyen a pedir ayuda cuando están heridos) y místicos (nivel 13-14, se curan con poca salud). Atráelos de a uno.",
		["The Shrine of Flames hides on the island's outer rim south-west of {area:16638}, just south-east of {area:16663}: {npc:268592} keeps it."] = "El Santuario de las Llamas se esconde en el borde exterior de la isla al suroeste de {area:16638}, justo al sureste de {area:16663}: {npc:268592} lo cuida.",
		["The {npc:5893}"] = "La {npc:5893}",
		["The {object:148418}"] = "{object:148418}",
		["The {object:61934}"] = "{object:61934}",
		["Your {item:5176} for every fire totem, {spell:3599} with it, and Forever's {item:263412}."] = "Tu {item:5176} para todo tótem de fuego, {spell:3599} con él, y {item:263412} de Forever.",
		["the ritual, then the {npc:268679} in {area:16638}"] = "el ritual, y luego el {npc:268679} en {area:16638}",
		["{item:6636}, beside the {object:63674}"] = "{item:6636}, junto a {object:63674}",
		["{npc:252382}: {spell:3599}, your {item:5176} and the {item:263412}"] = "{npc:252382}: {spell:3599}, tu {item:5176} y {item:263412}",
		["{npc:268602} (level 10, a turncoat Windshaper with a single spawn) holds the farm north-east past {area:16638}, just south of the {area:16629}, on the hill west of the falls north of the {area:17675}. Kill him and take his heart."] = "{npc:268602} (nivel 10, un Formavientos traidor que aparece en un solo lugar) ocupa la granja al noreste, pasando {area:16638}, justo al sur de {area:16629}, en la colina al oeste de la cascada al norte de {area:17675}. Mátalo y toma su corazón.",
		["{npc:5900}: a new {quest:1464}"] = "{npc:5900}: un {quest:1464} nuevo",
		["{npc:5907} hands you the {item:6653}: keep it until the end of the chain."] = "{npc:5907} te da {item:6653}: guárdala hasta el final de la cadena.",
		["{npc:5907} is not in the Crossroads: take the road north from the Crossroads and fork east towards {zone:1411}; past {area:1704} he paces by a tall tower east of the road (from {zone:1411}: over the Southfury bridge, past {area:379}). If you reach {zone:1440} you went too far."] = "{npc:5907} no está en el Cruce: toma el camino al norte desde el Cruce y en la bifurcación ve al este hacia {zone:1411}; pasando {area:1704}, camina de un lado a otro junto a una torre alta al este del camino (desde {zone:1411}: por el puente del Furia del Sur, pasando {area:379}). Si llegas a {zone:1440}, te pasaste.",
		["{npc:5907}: {npc:3066}'s letter"] = "{npc:5907}: la carta de {npc:3066}",
		["{npc:5907}: {npc:3173}'s letter"] = "{npc:5907}: la carta de {npc:3173}",
		["{npc:5907}: {npc:5892}'s letter"] = "{npc:5907}: la carta de {npc:5892}",
		["{npc:5907}: {npc:5906}'s letter"] = "{npc:5907}: la carta de {npc:5906}",
		["{npc:5907}: {spell:3599}, your {item:5176} and the {item:263412}"] = "{npc:5907}: {spell:3599}, tu {item:5176} y {item:263412}",
		["{object:660848} is the twisted stump on the hilltop by the Shen'dar Highlands Anchor Pylon, west of {area:16638}, in the hills south of the Windsong Crawlers' lakes. Knock on it to call {npc:268605} (level 10). The spirit shrugs off most magic: only fire hurts it, so keep {spell:8050} on it. Take its wooden mask."] = "{object:660848} es el tocón retorcido en lo alto de la colina junto al Pilón ancla de las Tierras Altas de Shen'dar, al oeste de {area:16638}, en las colinas al sur de los lagos de los reptadores Cantoviento. Golpéalo para llamar a {npc:268605} (nivel 10). El espíritu ignora casi toda la magia: solo el fuego lo daña, así que mantén {spell:8050} sobre él. Toma su máscara de madera.",
		["{object:660848}: knock on the bark"] = "{object:660848}: golpea la corteza",
		["{quest:1522} (Horde)"] = "{quest:1522} (Horda)",
} end)()
t.guides["forever/class/shaman/call-of-water-alliance"] = (function() return {
		["At 20 {npc:258098}, the shaman trainer in {zone:1455}'s {object:32362}, sends you to {npc:258043} in {zone:1432}."] = "A nivel 20, {npc:258098}, el instructor de chamanes en {object:32362} de {zone:1455}, te manda con {npc:258043} en {zone:1432}.",
		["Back to {npc:258043} by {area:146} with the {item:7810}. He hands you the {item:6637} and the {item:7811}: keep both for {zone:1436}."] = "De vuelta con {npc:258043}, junto a {area:146}, con {item:7810}. Te da {item:6637} y {item:7811}: guarda ambos para {zone:1436}.",
		["Back to {npc:258043} with the {item:7813}. Keep the {item:5177} in your bags for good: every water totem needs it."] = "De vuelta con {npc:258043} con {item:7813}. Guarda {item:5177} en tus bolsas para siempre: todo tótem de agua lo necesita.",
		["Fill the {item:265732} at the bottom of the waterfalls below {npc:258203}'s cave, where the fresh water meets the brackish. {object:147516} dwarves roam near the falls."] = "Llena {item:265732} al pie de las cascadas debajo de la cueva de {npc:258203}, donde el agua dulce se junta con la salobre. Enanos {object:147516} rondan cerca de las cascadas.",
		["Fly to {area:108} and head south to {area:20}: {area:919} and the {object:619896} lie just north of it. Drink the {item:6637} by the shrine to see the {npc:5894} (level 22, {spell:8056} and {spell:122}; one spawn, back three minutes after a kill), defeat it for its bracers (always dropped), then place them and the {item:7811} on the {object:619896} (this, not {npc:258043}, ends the quest). Click the shrine again: the {npc:5895} rises beside it; speak to it before you walk off (if it is gone, abandon and take the quest again at the shrine). It gives you the {item:7813}."] = "Vuela a {area:108} y ve al sur hasta {area:20}: {area:919} y {object:619896} están justo al norte. Bebe {item:6637} junto al santuario para ver a la {npc:5894} (nivel 22, {spell:8056} y {spell:122}; aparece en un solo lugar y vuelve tres minutos después de morir), derrótala para sus brazales (siempre caen), y luego colócalos junto con {item:7811} en {object:619896} (esto, no {npc:258043}, termina la misión). Vuelve a hacer clic en el santuario: la {npc:5895} se levanta a su lado; háblale antes de irte (si ya no está, abandona y vuelve a tomar la misión en el santuario). Te da {item:7813}.",
		["Lost the {quest:94616}?"] = "¿Perdiste {quest:94616}?",
		["Only if the {quest:94616} is gone from your bags: {npc:258043} gives you another before you leave for {zone:1436}."] = "Solo si {quest:94616} ya no está en tus bolsas: {npc:258043} te da otro antes de que salgas hacia {zone:1436}.",
		["Take the boat from {area:150} to {area:442} (it stops in {area:271} on the way), then fly or walk south through {zone:1439} to {area:415} in {zone:1440}. Fill the {item:265772} in the lake around the town, then the boat back to Menethil."] = "Toma el barco de {area:150} a {area:442} (para en {area:271} en el camino), luego vuela o camina al sur por {zone:1439} hasta {area:415}, en {zone:1440}. Llena {item:265772} en el lago alrededor del pueblo, y luego el barco de vuelta a Menethil.",
		["The blue waterskin"] = "El odre azul",
		["The brown waterskin"] = "El odre marrón",
		["The red waterskin"] = "El odre rojo",
		["The {item:5177} that lets you place water totems, and {spell:5394} with it."] = "El {item:5177} que te permite colocar tótems de agua, y con él {spell:5394}.",
		["the {item:7810}, for {npc:258043}"] = "el {item:7810}, para {npc:258043}",
		["{area:71} pour out of {area:68} at the east end of Redridge (fly from {zone:1455} to {area:69}). Fill the {item:265747} at their foot, where the Murloc Nightcrawlers gather; pull the murlocs off the spot first. If the skin vanishes without counting, abandon the quest and take it again from {npc:258203} for a new one."] = "{area:71} caen desde {area:68}, en el extremo este de Montañas Crestagrana (vuela de {zone:1455} a {area:69}). Llena {item:265747} al pie, donde se juntan los reptadores nocturnos múrloc; aleja antes a los múrlocs del lugar. Si el odre desaparece sin contar, abandona la misión y vuelve a tomarla con {npc:258203} para uno nuevo.",
		["{npc:258043}'s burrow hut stands on the north-western shore of the loch, below {area:146}, north of {area:144}."] = "La choza madriguera de {npc:258043} está en la orilla noroeste del lago, debajo de {area:146}, al norte de {area:144}.",
		["{npc:258043}: a new {quest:94616}"] = "{npc:258043}: un {quest:94616} nuevo",
		["{npc:258043}: your {item:6637}"] = "{npc:258043}: tu {item:6637}",
		["{npc:258043}: {spell:5394} and your {item:5177}"] = "{npc:258043}: {spell:5394} y tu {item:5177}",
		["{npc:258203}'s family lives in a cave beneath the southern falls of the {zone:1437}, east of {area:836}: not in a town. Through the Algaz tunnel north of {zone:1432}, then east off the road."] = "La familia de {npc:258203} vive en una cueva debajo de las cascadas del sur de {zone:1437}, al este de {area:836}: no en un pueblo. Por el túnel de Algaz al norte de {zone:1432}, y luego al este fuera del camino.",
		["{npc:5895}, beside the shrine"] = "{npc:5895}, junto al santuario",
		["{quest:94494} (Alliance)"] = "{quest:94494} (Alianza)",
} end)()
t.guides["forever/class/shaman/call-of-water-horde"] = (function() return {
		["At 20 {npc:5892} in the {object:172957} sends you to {npc:5901} in the {zone:1413}. (Swart in {area:362} gives the same letter: carry either.)"] = "A nivel 20, {npc:5892}, en {object:172957}, te manda con {npc:5901} en {zone:1413}. (Swart, en {area:362}, da la misma carta: lleva cualquiera de las dos.)",
		["At 20 {npc:5906}, a shaman trainer on {area:1640} in {zone:1456}, sends you to {npc:5901} in the {zone:1413}. ({npc:3066} in {area:222} gives the same letter: carry either.)"] = "A nivel 20, {npc:5906}, un instructor de chamanes en {area:1640} en {zone:1456}, te manda con {npc:5901} en {zone:1413}. ({npc:3066}, en {area:222}, da la misma carta: lleva cualquiera de las dos.)",
		["Back to {npc:5899}. She gives you the {item:7810} for {npc:5901}."] = "De vuelta con {npc:5899}. Te da {item:7810} para {npc:5901}.",
		["Back to {npc:5901} south of {area:392}. Keep the {item:5177} in your bags for good: every water totem needs it."] = "De vuelta con {npc:5901}, al sur de {area:392}. Guarda {item:5177} en tus bolsas para siempre: todo tótem de agua lo necesita.",
		["Click the {object:113791} to place the bracers and the drops. A few seconds later the pure {npc:5895} rises on the stone in the middle of the pool: speak to it while the {spell:8202} lasts (drink again by the stone if it has worn off). It gives you the {item:7813} for {npc:5901}. Gone before you could speak to it? Back at {npc:5901} ask for {quest:63} (a fresh {quest:972} for {npc:7007}, who stands just west of the shrine): hand it to Tiev, stay close while he calls the spirit back, then speak to it."] = "Haz clic en {object:113791} para colocar los brazales y las gotas. Unos segundos después, la {npc:5895} pura se levanta sobre la piedra en el centro de la poza: háblale mientras dure {spell:8202} (vuelve a beber junto a la piedra si se te pasó). Te da {item:7813} para {npc:5901}. ¿Se fue antes de que pudieras hablarle? De vuelta con {npc:5901}, pide {quest:63} (un {quest:972} nuevo para {npc:7007}, que está justo al oeste del santuario): dáselo a Tiev, quédate cerca mientras llama de vuelta al espíritu y luego háblale.",
		["Fly to the {area:228}. The shrine lies in a hollow just south-west of it: go round the back of the crypt to the thick tree between the two hills, hop past it onto the rocks and drop west down the slope to the pool (each drop costs a little health). Drink the {item:6637} beside the tall standing stone by the pool: several water elementals appear, and only the corrupt one near the middle can be attacked (Tab picks it). The {npc:5894} is level 22 and casts {spell:8056} and {spell:122}; if someone just killed it, it is back in about three minutes. Its bracers always drop."] = "Vuela a {area:228}. El santuario está en una hondonada justo al suroeste: rodea la cripta por detrás hasta el árbol grueso entre las dos colinas, salta pasándolo a las rocas y baja al oeste por la pendiente hasta la poza (cada bajada cuesta un poco de salud). Bebe {item:6637} junto a la piedra erguida alta al lado de la poza: aparecen varios elementales de agua, y solo se puede atacar al corrompido cerca del medio (Tab lo selecciona). La {npc:5894} es de nivel 22 y lanza {spell:8056} y {spell:122}; si alguien acaba de matarla, vuelve en unos tres minutos. Sus brazales siempre caen.",
		["Lost the {quest:972}?"] = "¿Perdiste {quest:972}?",
		["Only if the {quest:972} is gone from your bags: {npc:5901} gives you another."] = "Solo si {quest:972} ya no está en tus bolsas: {npc:5901} te da otro.",
		["The muddy pond below {npc:5899}'s hut. Step right into the puddle before you use the {item:7766} (too far away and it refuses). Filling it calls a hostile {npc:3456} (level 20): kill it, and watch for the quilboar hunter by the pond, who may start shooting afterwards."] = "La charca embarrada debajo de la choza de {npc:5899}. Métete en el charco antes de usar {item:7766} (demasiado lejos y no funciona). Llenarlo llama a un {npc:3456} hostil (nivel 20): mátalo, y cuidado con el cazador jabaespín junto a la charca, que puede empezar a disparar después.",
		["The right fountain stands in a ring of standing stones on the island of the small green lake south of {area:415}, west of Lake Mystral (not the island in Lake Mystral itself). From the {zone:1413} take the road north through the {area:1703} and on west. Water elementals and walking treants guard the lake and root you in place; an elite {npc:12836} roams {zone:1440} and can pass close by. Use the {item:7767} beside the fountain."] = "La fuente correcta está en un anillo de piedras erguidas en la isla del lago verde pequeño al sur de {area:415}, al oeste del lago Mystral (no en la isla del lago Mystral). Desde {zone:1413}, toma el camino al norte por {area:1703} y sigue al oeste. Elementales de agua y antárboles errantes custodian el lago y te enraízan; un {npc:12836} élite recorre {zone:1440} y puede pasar cerca. Usa {item:7767} junto a la fuente.",
		["The {item:5177} that lets you place water totems, and {spell:5394} with it."] = "{item:5177}, que te permite colocar tótems de agua, y con él {spell:5394}.",
		["The {npc:5895}"] = "La {npc:5895}",
		["The {object:107045}"] = "{object:107045}",
		["The {object:107045} stands in the middle of {area:272}, just outside the church. From the {zone:1413}: the zeppelin from {zone:1454} to {zone:1420}, then south past the {zone:1458} and through {zone:1421} (or fly once you have the {area:272} flight path). {area:287} is contested: Alliance players may attack. Stand beside the well and use the {item:7768}."] = "{object:107045} está en el centro de {area:272}, justo afuera de la iglesia. Desde {zone:1413}: el zepelín de {zone:1454} a {zone:1420}, luego al sur pasando {zone:1458} y por {zone:1421} (o vuela cuando tengas la ruta de vuelo de {area:272}). {area:287} es territorio en disputa: los jugadores de la Alianza pueden atacar. Párate junto al pozo y usa {item:7768}.",
		["The {object:107046}"] = "{object:107046}",
		["The {object:113791}"] = "{object:113791}",
		["the {item:7810}, for {npc:5901}"] = "{item:7810}, para {npc:5901}",
		["{item:6637}, beside the standing stone"] = "{item:6637}, junto a la piedra erguida",
		["{item:7766}, standing in the puddle"] = "{item:7766}, parado en el charco",
		["{item:7767}, beside the fountain"] = "{item:7767}, junto a la fuente",
		["{item:7768}, beside the well"] = "{item:7768}, junto al pozo",
		["{npc:5899} lives in the southern {zone:1413}, south of {area:378}: her hut sits on a hilltop of {area:1701} with a spinning windmill beside it, and the way up is the ridge by the lone tree. Quilboar camp all around the hill; Stormhides, thunderhawks and hyenas roam the plains on the way."] = "{npc:5899} vive en el sur de {zone:1413}, al sur de {area:378}: su choza está en lo alto de una colina de {area:1701} con un molino girando al lado, y la subida es la cresta junto al árbol solitario. Hay campamentos de jabaespines alrededor de toda la colina; en el camino, por las llanuras rondan pieltormentas, halcones del trueno y hienas.",
		["{npc:5901} hands you the {item:6637} and the {item:7811}: take everything she offers before you leave for Silverpine, or you will be back for more."] = "{npc:5901} te da {item:6637} y {item:7811}: toma todo lo que te ofrezca antes de salir hacia Bosque de Argénteos, o vas a tener que volver por más.",
		["{npc:5901} is not in {area:392}: take the small coast road south from {area:392} past the pirate camp and over a low hill; her fishing hut, with a shark strung up outside, stands by the water before the pirate ship. If you reach the ship you went too far."] = "{npc:5901} no está en {area:392}: toma el caminito de la costa al sur desde {area:392}, pasando el campamento pirata y cruzando una colina baja; su choza de pesca, con un tiburón colgado afuera, está junto al agua antes del barco pirata. Si llegas al barco, te pasaste.",
		["{npc:5901}: Narm's letter"] = "{npc:5901}: la carta de Narm",
		["{npc:5901}: Swart's letter"] = "{npc:5901}: la carta de Swart",
		["{npc:5901}: a new {quest:972}"] = "{npc:5901}: un {quest:972} nuevo",
		["{npc:5901}: your {item:6637}"] = "{npc:5901}: tu {item:6637}",
		["{npc:5901}: {npc:5892}'s letter"] = "{npc:5901}: la carta de {npc:5892}",
		["{npc:5901}: {npc:5906}' letter"] = "{npc:5901}: la carta de {npc:5906}",
		["{npc:5901}: {spell:5394} and your {item:5177}"] = "{npc:5901}: {spell:5394} y tu {item:5177}",
		["{quest:63} (Horde)"] = "{quest:63} (Horda)",
} end)()
t.guides["forever/class/shaman/darkreaver"] = (function() return {
		["200 Horde reputation"] = "200 de reputación con la Horda",
		["A five-player dungeon event: {area:2057} lies under {area:2298}, the island town in the south-east of the {zone:1422}. In the {object:179746}'s basement, first clear every mob in the room, then use the {item:18746} at its centre: four waves of spirits follow, each closing with an Aspect mini-boss (the first wave weak and slow, the rest elite). Fight in a corner so nothing else joins, and drink between waves: it is long. Then {npc:14516} (level 62 elite) appears: he Cleaves, casts {spell:686} and {spell:6958}, and Dominates a player's mind against the group. His head always drops."] = "Un evento de mazmorra de cinco jugadores: {area:2057} está debajo de {area:2298}, el pueblo en la isla del sureste de {zone:1422}. En el sótano de {object:179746}, primero despeja todos los enemigos de la sala y luego usa {item:18746} en su centro: siguen cuatro oleadas de espíritus, cada una con un minijefe Aspecto al final (la primera oleada débil y lenta, el resto élite). Pelea en una esquina para que no se sume nada más, y bebe entre oleadas: es largo. Luego aparece {npc:14516} (élite de nivel 62): da tajos, lanza {spell:686} y {spell:6958}, y domina la mente de un jugador contra el grupo. Su cabeza siempre cae.",
		["A {area:2057} fight at 60 for Horde reputation; the {item:20134} may be gone in Forever."] = "Una pelea en {area:2057} a nivel 60 por reputación con la Horda; puede que {item:20134} ya no esté en Forever.",
		["At 58 {npc:13417}, the shaman trainer in the {object:172957}, asks for two rare diamonds; every Horde shaman goes to him. Skyborne: Forever's quest page lists this quest for Orcs, Tauren and Trolls only: ask before you buy the diamonds."] = "A nivel 58, {npc:13417}, el instructor de chamanes en {object:172957}, te pide dos diamantes raros; todos los chamanes de la Horda van con él. Skyborne: la página de la misión en Forever la lista solo para orcos, taurens y trols: pregunta antes de comprar los diamantes.",
		["Both diamonds are rare: the auction house is the quick way. Miners find the {item:12800} in about one Thorium vein in a hundred (the Small Thorium Veins north of {area:2418} in the {zone:1428} respawn every five minutes). The {item:18335} drops from high-level elites at about one in a hundred, best from the rare elite Revanchion (about one in nine)."] = "Los dos diamantes son raros: la casa de subastas es la vía rápida. Los mineros encuentran {item:12800} más o menos en una de cada cien vetas de torio (las vetas de torio pequeñas al norte de {area:2418}, en {zone:1428}, reaparecen cada cinco minutos). {item:18335} lo sueltan élites de nivel alto más o menos uno de cada cien, mejor el élite raro Revanchion (más o menos uno de cada nueve).",
		["Two diamonds"] = "Dos diamantes",
		["he hands you the {item:18746}"] = "te da el {item:18746}",
		["{npc:13417}: 200 Horde reputation; the {item:20134} may be gone"] = "{npc:13417}: 200 de reputación con la Horda; puede que {item:20134} ya no esté",
		["{quest:8258} needs level 60."] = "{quest:8258} requiere nivel 60.",
} end)()
t.guides["forever/class/shaman/spirit-totem"] = (function() return {
		["A five-player dungeon: needs a group of five, about level 50-55. Fly to {area:75} and ride east. The {area:1417} ({area:1477}) stands in the middle of the {area:74}: climb the stairs on the ruin's south side, dive into the flooded hall, swim down through it and follow the stairs and passages down to the portal. Two feathers of each colour, one from each of six elite troll mini-bosses (level 51-52) on the balconies around the temple's great round room, every kill, and each player on the quest loots their own: Gasher and {npc:5716} the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green. Mijan heals the others ({spell:139}, a {npc:3560}): kill him first; Hukku summons guardians and throws Shadow Bolt Volleys."] = "Una mazmorra de cinco jugadores: necesita un grupo de cinco, de nivel 50-55 más o menos. Vuela a {area:75} y ve al este. {area:1417} ({area:1477}) está en el centro de {area:74}: sube la escalera del lado sur de la ruina, zambúllete en la sala inundada, nada hacia abajo por dentro y sigue las escaleras y pasajes hasta el portal. Dos plumas de cada color, una de cada uno de seis minijefes trol élite (nivel 51-52) de los balcones alrededor de la gran sala redonda del templo, en cada muerte, y cada jugador con la misión saquea las suyas: Gasher y {npc:5716} la ámbar, Hukku y Mijan la azul, Zolo y Loro la verde. Mijan cura a los demás ({spell:139}, un {npc:3560}): mátalo primero; Hukku invoca guardianes y lanza salvas de descargas de las Sombras.",
		["At 50 {npc:13417}, the shaman trainer in the {object:172957}, asks for the four elements for {npc:6176}."] = "A nivel 50, {npc:13417}, el instructor de chamanes en {object:172957}, te pide los cuatro elementos para {npc:6176}.",
		["At 50 {npc:3032}, a shaman trainer on {area:1640} in {zone:1456}, asks for the four elements for {npc:6176}. Skyborne: Forever's quest page lists {quest:8410} and {quest:8412} for Orcs, Tauren and Trolls only; if {npc:3032} has nothing for you, {npc:6176}'s own {quest:8411} is open to every Horde race, but {quest:8412} after it may still turn you away."] = "A nivel 50, {npc:3032}, un instructor de chamanes en {area:1640} en {zone:1456}, te pide los cuatro elementos para {npc:6176}. Skyborne: la página de la misión en Forever lista {quest:8410} y {quest:8412} solo para orcos, taurens y trols; si {npc:3032} no tiene nada para ti, {quest:8411} del propio {npc:6176} está abierta para todas las razas de la Horda, pero {quest:8412}, después, puede que igual te rechace.",
		["Eight of each. Fly or ride to the {area:813} and on to the west edge of the {zone:1422}, north-west of {area:3197}: the Venom Mist Lurkers (level 50-51, they poison) give the {item:20610} and the Diseased Black Bears (level 51-52, {spell:3427}) the {item:20611}, one kill in five each; the two Carrion Vultures there drop either. The bigger Diseased Grizzlies and Plague Lurkers further east almost never drop them. A few bears and lurkers also roam south-east of {area:159} in Tirisfal."] = "Ocho de cada uno. Vuela o ve a {area:813} y sigue hasta el borde oeste de {zone:1422}, al noroeste de {area:3197}: los acechadores Bruma Venenosa (nivel 50-51, envenenan) dan {item:20610} y los osos negros enfermos (nivel 51-52, {spell:3427}) {item:20611}, una muerte de cada cinco cada uno; los dos buitres carroñeros de ahí sueltan cualquiera. Los osos pardos enfermos y los acechadores de la peste, más grandes, más al este, casi nunca los sueltan. Algunos osos y acechadores también rondan al sureste de {area:159}, en Tirisfal.",
		["Experience and gold"] = "Experiencia y oro",
		["Experience and gold at 50, ending in the {area:1417}; the Classic item choice may be gone in Forever."] = "Experiencia y oro a nivel 50, terminando en {area:1417}; puede que en Forever ya no esté la elección de objeto de Classic.",
		["One each of {item:7069}, Fire, Earth and Water; all four trade, so the auction house is quickest. To farm them, {zone:1417} has the exiles near {area:320} (level 38-39, about one kill in eight to ten, respawn under seven minutes): Thundering Exiles south-east of it (air), Rumbling Exiles south-west (earth), Burning Exiles far to the north-west (fire), and the {npc:2794} far to the south-west (water, about one in seven). Water comes easier from the Patches of Elemental Water in {zone:1447} (two in five) or {npc:14269} by {area:69} in Redridge."] = "Uno de cada uno: {item:7069}, fuego, tierra y agua; los cuatro se pueden comerciar, así que la casa de subastas es lo más rápido. Para conseguirlos, {zone:1417} tiene los exiliados cerca de {area:320} (nivel 38-39, más o menos una muerte de cada ocho a diez, reaparecen en menos de siete minutos): exiliados atronadores al sureste (aire), exiliados retumbantes al suroeste (tierra), exiliados ardientes lejos al noroeste (fuego), y el {npc:2794} lejos al suroeste (agua, más o menos uno de cada siete). El agua sale más fácil de los parches de agua elemental en {zone:1447} (dos de cada cinco) o de {npc:14269}, junto a {area:69} en Montañas Crestagrana.",
		["Spider eye and bear claw"] = "Ojo de araña y garra de oso",
		["The four elements"] = "Los cuatro elementos",
		["The {area:1417}"] = "{area:1417}",
		["{item:20606}: Gasher, {npc:5716}"] = "{item:20606}: Gasher, {npc:5716}",
		["{item:20607}: Hukku, Mijan"] = "{item:20607}: Hukku, Mijan",
		["{item:20608}: Zolo, Loro"] = "{item:20608}: Zolo, Loro",
		["{item:7067}: Rumbling Exiles"] = "{item:7067}: Exiliados resonadores",
		["{item:7068}: Burning Exiles"] = "{item:7068}: Exiliados ardientes",
		["{item:7069}: Thundering Exiles"] = "{item:7069}: Exiliados tronadores",
		["{item:7070}: the {npc:2794}, or {zone:1447}'s water patches"] = "{item:7070}: el {npc:2794}, o los parches de agua de {zone:1447}",
		["{npc:6176} camps in the ruins of the east of {zone:1416}: from {area:272} follow the river east of town north into the hills."] = "{npc:6176} acampa en las ruinas del este de {zone:1416}: desde {area:272} sigue el río al este del pueblo hacia el norte, hasta las colinas.",
		["{npc:6176}: the old item choice may be gone, count on the experience"] = "{npc:6176}: puede que la vieja elección de objeto ya no esté, cuenta con la experiencia",
		["{quest:8412} and {quest:8413}"] = "{quest:8412} y {quest:8413}",
} end)()
t.guides["forever/class/warlock/dread-mage-hat"] = (function() return {
		["A cloth hat in your late 20s: Zardeth's errand for any Alliance player pays warlocks this extra."] = "Un sombrero de tela al final de tus veintes: el encargo de Zardeth para cualquier jugador de la Alianza le da esto extra a los brujos.",
		["At 25 {npc:1435}, in the cellar of the {object:2164} in the {object:2101} (beside the warlock trainers), wants two ingredients for a brew. Do it when your leveling takes you to {zone:1431} and the {zone:1437}."] = "A nivel 25, {npc:1435}, en el sótano de {object:2164} en {object:2101} (junto a los instructores de brujos), quiere dos ingredientes para un brebaje. Hazlo cuando tu leveleo te lleve a {zone:1431} y {zone:1437}.",
		["Back to Zardeth once more: he offers warlocks a reward, which his imp {npc:1733}, standing beside him, hands over."] = "De vuelta con Zardeth una vez más: les ofrece una recompensa a los brujos, que te entrega su diablillo {npc:1733}, que está a su lado.",
		["Back to Zardeth. He brews the {item:2788} and gives it to you for {npc:1439} in the Hall of Petitioners, the first hall on the right inside {object:2117}."] = "De vuelta con Zardeth. Prepara {item:2788} y te la da para {npc:1439}, en la Sala de los Peticionarios, la primera sala a la derecha dentro de {object:2117}.",
		["The root grows at the water's edge in the pool below the small falls east of {area:836}, beside the {object:147516} cave below the {area:146}: a tall, spiky wooden root, not at the foot of the dam itself."] = "La raíz crece en la orilla de la poza debajo de la pequeña cascada al este de {area:836}, junto a la cueva de {object:147516} debajo de {area:146}: una raíz de madera alta y espinosa, no al pie de la presa.",
		["{area:1098} stands in the north-east of {zone:1431}, north of {area:42}. The {object:321} is a small white flower low in the grass of the fenced garden beside Stalvan's house: hard to see, so sweep the garden with your mouse. Fetid Corpses (level 29) wander the grounds and come quickly: at 25, send your voidwalker at the nearest one, grab the flower and leave. {npc:315} (32) is inside the house; leave him alone."] = "{area:1098} está en el noreste de {zone:1431}, al norte de {area:42}. {object:321} es una florecita blanca, baja en la hierba del jardín cercado junto a la casa de Stalvan: cuesta verla, así que recorre el jardín con el mouse. Los cadáveres fétidos (nivel 29) deambulan por el terreno y llegan rápido: a nivel 25, manda a tu abisario contra el más cercano, agarra la flor y vete. {npc:315} (32) está dentro de la casa; déjalo en paz.",
} end)()
t.guides["forever/class/warlock/enchanted-gold-bloodrobe"] = (function() return {
		["A rare cloth robe for your 30s from {npc:6266}; its last parts wait for levels 37 and 39."] = "Una túnica de tela rara para tus 30, de {npc:6266}; sus últimas piezas esperan a los niveles 37 y 39.",
		["At 31 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "A nivel 31, {npc:3326} en {object:172960} te manda con {npc:6266} en {area:392}. Compra antes {item:5770} y {item:3577} (pasos siguientes) para ahorrarte un viaje.",
		["At 31 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}; the zeppelin from {zone:1420} flies to {zone:1411}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "A nivel 31, {npc:4563} en {object:36082} te manda con {npc:6266} en {area:392}; el zepelín desde {zone:1420} vuela a {zone:1411}. Compra antes {item:5770} y {item:3577} (pasos siguientes) para ahorrarte un viaje.",
		["At 31 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "A nivel 31, {npc:461}, en {object:2164}, en {object:2101}, te manda con {npc:6266} en {area:392}. Compra antes {item:5770} y {item:3577} (pasos siguientes) para ahorrarte un viaje.",
		["At 31 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "A nivel 31, {npc:5172} en {zone:1455} te manda con {npc:6266} en {area:392}. Compra antes {item:5770} y {item:3577} (pasos siguientes) para ahorrarte un viaje.",
		["Back to {npc:2670} in {area:35}: he offers {quest:4785} as a quest you hand straight back to him. He may show no quest marker; talk to him anyway."] = "De vuelta con {npc:2670} en {area:35}: ofrece {quest:4785} como una misión que le devuelves enseguida. Puede que no muestre marca de misión; háblale igual.",
		["Back to {npc:6266}"] = "Regresa con {npc:6266}",
		["Back to {npc:6266} with the thread, the coals and a {item:6265}. Then wait beside her while she works the robe (do not attack her: the quest log calls it a kill), and speak to her again."] = "De vuelta con {npc:6266} con el hilo, las brasas y una {item:6265}. Luego espera a su lado mientras trabaja la túnica (no la ataques: el registro de misiones lo llama matar) y vuelve a hablarle.",
		["Hatefury satyrs"] = "Sátiros Odio Feroz",
		["Tailors sew the {item:5770} from a rare pattern; miners smelt Gold Bars from {item:2776}. Everyone else buys both at the Auction House. If you wear the robe, take it off: {npc:6266} keeps it."] = "Los sastres cosen {item:5770} con un patrón raro; los mineros funden Barras de oro con {item:2776}. Los demás compran ambos en la casa de subastas. Si llevas puesta la túnica, quítatela: {npc:6266} se la queda.",
		["The Burning Exiles (level 38-39), fire elementals at the {area:334} in western {zone:1417}, drop the coal about one time in three. The guide waits for level 39 first: below it they hit too hard to solo. They resist fire: {spell:686} and Corruption. The Cresting Charms from the Cresting Exiles near {area:321} finish one off once you have hurt it. Make a {item:6265} with {spell:1120} on the way."] = "Los Exiliados ardientes (nivel 38-39), elementales de fuego en {area:334}, en el oeste de {zone:1417}, sueltan el carbón aproximadamente una de cada tres veces. La guía espera primero al nivel 39: por debajo pegan demasiado fuerte para ir solo. Resisten el fuego: {spell:686} y Corrupción. Los Talismanes blasonados de los Éxilus coronadores cerca de {area:321} rematan a uno cuando ya lo dañaste. Crea un {item:6265} con {spell:1120} en el camino.",
		["The Hatefury satyrs (level 31-32) hold {area:603} in the far north-east of {zone:1443}, past {area:608}: two kills in five give a vial, so plan on about 25."] = "Los sátiros Odio Feroz (nivel 31-32) ocupan {area:603}, en el extremo noreste de {zone:1443}, pasando {area:608}: dos de cada cinco muertes dan un vial, así que cuenta con unas 25.",
		["The Lesser Infernals (36-37) and Demon Portal Guardians (38) of {area:602}, in the south of {zone:1443}, drop the stone half the time. The guide waits for level 39 first: at 31 they are too strong to solo. They resist fire, so use {spell:686} and Corruption."] = "Los Infernales inferiores (36-37) y los Guardianes del portal de demonios (38) de {area:602}, en el sur de {zone:1443}, sueltan la piedra la mitad de las veces. La guía espera primero al nivel 39: a nivel 31 son demasiado fuertes para ir solo. Resisten el fuego, así que usa {spell:686} y Corrupción.",
		["The boat from {area:392} sails to {area:35}. {npc:2670} runs {object:59851} on an upper level of the town. Give him the {item:3577}; he will spin the thread later."] = "El barco de {area:392} navega a {area:35}. {npc:2670} atiende {object:59851} en un nivel superior del pueblo. Dale {item:3577}; él hilará el hilo después.",
		["Vials of Hatefury Blood"] = "Viales de sangre de odio feroz",
		["Wait beside {npc:6266} while she finishes the robe"] = "Espera junto a {npc:6266} mientras termina la túnica",
		["You need no thread yet: {npc:6266} wants demon parts from {zone:1443} next."] = "Todavía no necesitas el hilo: {npc:6266} quiere después partes de demonio de {zone:1443}.",
		["{item:3577}: the Auction House"] = "{item:3577}: la casa de subastas",
		["{item:5770} and a {item:3577}"] = "{item:5770} y {item:3577}",
		["{item:5770}: the Auction House"] = "{item:5770}: la casa de subastas",
		["{item:6265}: {spell:1120} on an Exile as it dies"] = "{item:6265}: {spell:1120} sobre un exiliado mientras muere",
		["{npc:2670}: {quest:4785}, handed straight back"] = "{npc:2670}: {quest:4785}, se le devuelve en el acto",
		["{npc:6266} again"] = "{npc:6266} otra vez",
		["{npc:6266} stands by {npc:6251}'s tower on the hill above {area:392}, behind the engineers' hut. She takes the robe, then sends the gold bar to {npc:2670} in {area:35}."] = "{npc:6266} está junto a la torre de {npc:6251}, en la colina sobre {area:392}, detrás de la choza de los ingenieros. Recibe la túnica y luego manda la barra de oro a {npc:2670} en {area:35}.",
} end)()
t.guides["forever/class/warlock/felhunter-alliance"] = (function() return {
		["At 30 {npc:6120}, in the {object:32383}, sends you to {npc:6251} in {area:392}."] = "A nivel 30, {npc:6120}, en {object:32383}, te envía con {npc:6251} en {area:392}.",
		["At 30 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6251} in {area:392}."] = "A nivel 30, {npc:6122}, en el sótano de {object:2164} en {object:2101}, te envía con {npc:6251} en {area:392}.",
		["Back to {npc:6251} in {area:392}. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the {quest:1804} on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon {quest:1795} and take it again from {npc:6251}. Keep the tome: {npc:6251} takes it back."] = "De vuelta con {npc:6251} en {area:392}. Cuando aceptas, dibuja el círculo de invocación y sus acólitos canalizan un círculo mayor encima: espera dentro de la torre hasta que terminen los dos. Luego usa {quest:1804} sobre el círculo. El manáfago (nivel 30, no élite) silencia y come maná, y desaparece a los dos minutos: ten afuera a tu abisario, empieza enseguida con tu daño en el tiempo y deja que el abisario aguante. Si mueres o gana él, abandona {quest:1795} y vuelve a tomarla con {npc:6251}. Guarda el tomo: {npc:6251} lo recupera.",
		["Back to {npc:6294}"] = "De vuelta con {npc:6294}",
		["Felhunter (Alliance)"] = "Manáfago (Alianza)",
		["Rods of Channeling"] = "Varas de canalización",
		["Rods of Channeling, from the Dragonmaw casters"] = "Varas de canalización, de los lanzadores de hechizos Faucedraco",
		["The Dragonmaw hold {area:1036} in the hills east of the road from {area:150} to {area:836}. Only the casters drop the rods, four kills in five: the Bonewarders (level 27, with skeleton pets) and Shadowwarders (28). A steep path north of the central spirit healer leads up into the camp past most of the warriors."] = "Los Faucedraco ocupan {area:1036} en las colinas al este del camino de {area:150} a {area:836}. Solo los lanzadores de hechizos sueltan las varas, cuatro de cada cinco veces: los guardahuesos (nivel 27, con mascotas esqueleto) y los guardasombras (28). Un sendero empinado al norte del ángel de la resurrección central sube al campamento evitando a la mayoría de los guerreros.",
		["The centaur cave opens in the cliffs north of {area:484}, a Horde town: keep clear of its guards. Inside, keep right at each fork, cross the pool by the small waterfall, and open the small dark box against the wall beside a larger chest: the larger one is the wrong one. You can open it only while on the quest. The centaurs respawn behind you on the way out."] = "La cueva de los centauros se abre en los acantilados al norte de {area:484}, un pueblo de la Horda: no te acerques a sus guardias. Adentro, ve por la derecha en cada bifurcación, cruza la poza junto a la cascadita y abre la cajita oscura contra la pared, al lado de un cofre más grande: el grande no es. Solo puedes abrirla mientras tienes la misión. Los centauros reaparecen detrás de ti al salir.",
		["The felhunter, the demon to bring against spellcasters, and a {item:22244} for your shards."] = "El manáfago, el demonio para enfrentar a los lanzadores de hechizos, y {item:22244} para tus fragmentos.",
		["The tome is a small grey-blue book lying in the sand of a murloc camp on the shore south-west of {area:271}, near the water's edge. Six or seven murlocs guard it and more lurk underwater: they come in groups, so Fear one and keep your voidwalker on the rest. Walk down to the water to click it; from the hillside the crates block the cursor."] = "El tomo es un librito gris azulado que está en la arena de un campamento múrloc en la orilla al suroeste de {area:271}, cerca del agua. Seis o siete múrlocs lo custodian y hay más acechando bajo el agua: vienen en grupo, así que aterra a uno y mantén a tu abisario con el resto. Baja hasta el agua para hacer clic en él; desde la ladera, las cajas tapan el cursor.",
		["{area:392} is a neutral goblin port on the {zone:1413} coast: the boat from {area:35} docks there. {npc:6251} stands on the hill above the town, behind the engineers' hut, by his little tower; {npc:6266} and two acolytes are with him. He sends you to {npc:6294} in {zone:1455}."] = "{area:392} es un puerto goblin neutral en la costa de {zone:1413}: ahí atraca el barco de {area:35}. {npc:6251} está en la colina sobre el pueblo, detrás de la choza de los ingenieros, junto a su torrecita; {npc:6266} y dos acólitos están con él. Te manda con {npc:6294} en {zone:1455}.",
		["{item:6931}, from the {quest:1802} on the sand"] = "{item:6931}, de {quest:1802} en la arena",
		["{item:6997}, in the {object:92423}"] = "{item:6997}, en {object:92423}",
		["{npc:6294} is in the library of the {object:32356}. He wants two lost pieces of the {quest:1758}: one on the {area:287} coast, one in {zone:1441}."] = "{npc:6294} está en la biblioteca de {object:32356}. Quiere dos partes perdidas de {quest:1758}: una en la costa de {area:287} y otra en {zone:1441}.",
		["{npc:6294} pieces the tome together and gives you the {item:7006}: keep it, {npc:6251} takes it with the rods."] = "{npc:6294} arma el tomo y te da {item:7006}: guárdalo, {npc:6251} lo recibe con las varas.",
		["{quest:1804}, on the circle"] = "{quest:1804}, sobre el círculo",
} end)()
t.guides["forever/class/warlock/felhunter-horde"] = (function() return {
		["At 30 {npc:5675}, in the {object:36082}, sends you to {npc:6251} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}. Take only one {quest:3001}: if {npc:6251} offers nothing, drop the duplicate from your log."] = "A nivel 30, {npc:5675}, en {object:36082}, te manda con {npc:6251} en {area:392}. El zepelín desde {zone:1420} vuela a {zone:1411}. Toma solo una {quest:3001}: si {npc:6251} no te ofrece nada, quita la repetida de tu registro.",
		["At 30 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:6251} in {area:392}."] = "A nivel 30, {npc:5875}, en {object:172960} bajo {object:172982}, te envía con {npc:6251} en {area:392}.",
		["Back to {npc:6251} in {area:392}. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the {quest:1804} on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon {quest:1795} and take it again from {npc:6251}. Keep the tome: {npc:6251} takes it back."] = "De vuelta con {npc:6251} en {area:392}. Cuando aceptas, dibuja el círculo de invocación y sus acólitos canalizan un círculo mayor encima: espera dentro de la torre hasta que terminen los dos. Luego usa {quest:1804} sobre el círculo. El manáfago (nivel 30, no élite) silencia y come maná, y desaparece a los dos minutos: ten afuera a tu abisario, empieza enseguida con tu daño en el tiempo y deja que el abisario aguante. Si mueres o gana él, abandona {quest:1795} y vuelve a tomarla con {npc:6251}. Guarda el tomo: {npc:6251} lo recupera.",
		["Back to {npc:6293}"] = "De vuelta con {npc:6293}",
		["Felhunter (Horde)"] = "Manáfago (Horda)",
		["Rods of Channeling"] = "Varas de mediación",
		["Rods of Channeling, from the Dragonmaw casters"] = "Varas de canalización, de los lanzadores de hechizos Faucedraco",
		["The Dragonmaw hold {area:1036} in the hills east of the road through the {zone:1437}, south of the {area:881} you cross from {zone:1417}. Only the casters drop the rods, four kills in five: the Bonewarders (level 27, with skeleton pets) and Shadowwarders (28). A steep path north of the central spirit healer leads up into the camp past most of the warriors."] = "Los Faucedraco ocupan {area:1036} en las colinas al este del camino que cruza {zone:1437}, al sur de {area:881}, que cruzas desde {zone:1417}. Solo los lanzadores de hechizos sueltan las varas, cuatro de cada cinco veces: los guardahuesos (nivel 27, con mascotas esqueleto) y los guardasombras (28). Un sendero empinado al norte del ángel de la resurrección central sube al campamento evitando a la mayoría de los guerreros.",
		["The centaur cave opens in the cliffs north of {area:484}. Inside, keep right at each fork, cross the pool by the small waterfall, and open the small dark box against the wall beside a larger chest: the larger one is the wrong one. You can open it only while on the quest. The centaurs respawn behind you on the way out."] = "La cueva de los centauros se abre en los acantilados al norte de {area:484}. Adentro, ve por la derecha en cada bifurcación, cruza la poza junto a la cascadita y abre la cajita oscura contra la pared, al lado de un cofre más grande: el grande no es. Solo puedes abrirla mientras tienes la misión. Los centauros reaparecen detrás de ti al salir.",
		["The felhunter, the demon to bring against spellcasters, and a {item:22244} for your shards."] = "El manáfago, el demonio ideal contra lanzadores de hechizos, y una {item:22244} para tus fragmentos.",
		["The tome is a small grey-blue book lying in the sand of a murloc camp on the shore south-west of {area:271}, near the water's edge. Six or seven murlocs guard it and more lurk underwater: they come in groups, so Fear one and keep your voidwalker on the rest. Walk down to the water to click it; from the hillside the crates block the cursor."] = "El tomo es un librito gris azulado que está en la arena de un campamento múrloc en la orilla al suroeste de {area:271}, cerca del agua. Seis o siete múrlocs lo custodian y hay más acechando bajo el agua: vienen en grupo, así que aterra a uno y mantén a tu abisario con el resto. Baja hasta el agua para hacer clic en él; desde la ladera, las cajas tapan el cursor.",
		["{area:392}'s flight point is a short flight from {zone:1454}'s. {npc:6251} stands on the hill above the town, behind the engineers' hut, by his little tower; {npc:6266} and two acolytes are with him. He sends you to {npc:6293} in the {zone:1458}."] = "El punto de vuelo de {area:392} está a un vuelo corto del de {zone:1454}. {npc:6251} está en la colina sobre el pueblo, detrás de la choza de los ingenieros, junto a su torrecita; {npc:6266} y dos acólitos están con él. Te manda con {npc:6293} en {zone:1458}.",
		["{item:6931}, from the {quest:1803} on the sand"] = "{item:6931}, de {quest:1803} en la arena",
		["{item:6997}, in the {object:92423}"] = "{item:6997}, en {object:92423}",
		["{npc:6293} is in the {object:36082} of the {zone:1458}. He wants two lost pieces of the {quest:1801}: one on the {area:287} coast, one in {zone:1441}."] = "{npc:6293} está en {object:36082} de {zone:1458}. Quiere dos partes perdidas de {quest:1801}: una en la costa de {area:287} y otra en {zone:1441}.",
		["{npc:6293} pieces the tome together and gives you the {item:7006}: keep it, {npc:6251} takes it with the rods."] = "{npc:6293} arma el tomo y te da {item:7006}: guárdalo, {npc:6251} lo recibe con las varas.",
		["{quest:1804}, on the circle"] = "{quest:1804}, sobre el círculo",
} end)()
t.guides["forever/class/warlock/imp-alliance"] = (function() return {
		["Feather Charms"] = "Amuletos de plumas",
		["Imp (Alliance)"] = "Diablillo (Alianza)",
		["The Defias tent stands in the vineyard east of the Abbey. The book is small: it lies on the ground just right of the tent's opening, beside a blue jug. Three Defias Thugs (level 3-4) guard the tent; pull them one at a time, or step inside the tent and click the book, where they cannot reach you. The book respawns three minutes after someone takes it."] = "La tienda Defias está en el viñedo al este de la Abadía. El libro es pequeño: está en el suelo, justo a la derecha de la entrada de la tienda, junto a una jarra azul. Tres matones Defias (nivel 3-4) custodian la tienda; atráelos de a uno, o métete en la tienda y haz clic en el libro, donde no te alcanzan. El libro reaparece tres minutos después de que alguien lo toma.",
		["The Frostmane Novices (level 3-4) sit at the back of the troll cave south of {area:77}, near Grek'nir the Cold by the icy pool: take the left tunnel past the entrance. Four kills in five drop a charm, but only two or three novices spawn, so you may wait out their three-minute respawn. They throw frostbolts from range; the Troll Whelps at the cave mouth jump anyone who passes. With the charms, your hearthstone takes you straight back: a new character's is set to {area:132}."] = "Los novicios Peloescarcha (nivel 3-4) están al fondo de la cueva trol al sur de {area:77}, cerca de Grek'nir el Frío, junto a la poza helada: toma el túnel de la izquierda pasando la entrada. Cuatro de cada cinco sueltan un amuleto, pero solo aparecen dos o tres novicios, así que puede que tengas que esperar sus tres minutos de reaparición. Lanzan descargas de escarcha a distancia; las crías de trol de la entrada saltan sobre quien pase. Con los amuletos, tu piedra de hogar te lleva directo de vuelta: la de un personaje nuevo está vinculada a {area:132}.",
		["The {object:83763}"] = "{object:83763}",
		["Your first demon at level 1-4: the imp, from your start zone's warlock trainer."] = "Tu primer demonio, a nivel 1-4: el diablillo, del instructor de brujos de tu zona inicial.",
		["Your first letter ({item:9576}, from {npc:197} after Kobold Camp Cleanup) points you to {npc:459}, the warlock trainer in the little graveyard beside {area:24}. She asks for a book the Defias stole."] = "Tu primera carta ({item:9576}, de {npc:197} después de Limpieza del campamento kóbold) te lleva con {npc:459}, la instructora de brujos en el cementerito junto a {area:24}. Te pide un libro que robaron los Defias.",
		["Your first letter ({item:9577}, from {npc:658} after Dwarven Outfitters) points you to {npc:460}, the warlock trainer upstairs inside {area:77}. He asks for three Feather Charms."] = "Tu primera carta ({item:9577}, de {npc:658} después de Pertrechos enanos) te lleva con {npc:460}, el instructor de brujos en el piso de arriba dentro de {area:77}. Te pide tres Amuletos de plumas.",
		["{item:6785}, from the {object:83763}"] = "{item:6785}, de {object:83763}",
		["{npc:459} (Humans)"] = "{npc:459} (humanos)",
		["{npc:459} teaches you {spell:688} at the hand-in: summon it right away, it costs nothing and fights beside you."] = "{npc:459} te enseña {spell:688} al entregar: invócalo enseguida, no cuesta nada y pelea a tu lado.",
		["{npc:460} (Gnomes)"] = "{npc:460} (gnomos)",
		["{npc:460} teaches you {spell:688} at the hand-in: summon it right away, it costs nothing and fights beside you."] = "{npc:460} te enseña {spell:688} al entregar: invócalo enseguida, no cuesta nada y pelea a tu lado.",
} end)()
t.guides["forever/class/warlock/imp-horde"] = (function() return {
		["Imp (Horde)"] = "Diablillo (Horda)",
		["Rattlecage Skulls"] = "Cráneos Jaularraída",
		["The Rattlecage Skeletons (level 2-3) stand around the old smithy buildings just north of {area:154}, often right against the walls. Four kills in five drop a skull, so plan on about five; twenty of them spawn there and each comes back after five minutes."] = "Los esqueletos Jaularraída (nivel 2-3) están alrededor de los viejos edificios de la herrería, justo al norte de {area:154}, muchas veces pegados a las paredes. Cuatro de cada cinco sueltan un cráneo, así que cuenta con unos cinco; aparecen veinte ahí y cada uno vuelve a los cinco minutos.",
		["The {quest:1485} (level 3-4) swarm the {area:365}, the cave north of the Den, inside and around its mouth. Almost every kill drops a head (80%), so about eight kills does it; they throw small fireballs, so pull them one at a time. They respawn in just over three minutes. Other classes hunt the same imps for their own {quest:1485} quest."] = "{quest:1485} (nivel 3-4) pululan en {area:365}, la cueva al norte de la Guarida, adentro y alrededor de la entrada. Casi todas las muertes sueltan una cabeza (80 %), así que con unas ocho alcanza; lanzan bolitas de fuego, así que atráelos de a uno. Reaparecen en poco más de tres minutos. Otras clases cazan los mismos diablillos para su propia misión {quest:1485}.",
		["Vile Familiar Heads"] = "Cabezas de familiar vil",
		["Your first demon at level 1-4: the imp, with a starter blade or staff for Orcs and Trolls."] = "Tu primer demonio, a nivel 1-4: el diablillo, con una hoja o bastón inicial para orcos y trols.",
		["Your first letter ({item:9578}, from {npc:1569} after The Mindless Ones) points you to Maximillion, the warlock trainer in {area:154}. {npc:5667} waits inside the building beside him and asks for three Rattlecage Skulls."] = "Tu primera carta ({item:9578}, de {npc:1569} después de Los descerebrados) te lleva con Maximillion, el instructor de brujos en {area:154}. {npc:5667} espera dentro del edificio a su lado y te pide tres Cráneos Jaularraída.",
		["Your first letter ({item:9579} for Orcs, {item:282346} for Trolls, from Gornek after Cutting Teeth) points you to Nartok, the warlock trainer in the Den. {npc:5765} stands just outside the Den in the {area:363} and asks for six Vile Familiar Heads."] = "Tu primera carta ({item:9579} para orcos, {item:282346} para trols, de Gornek después de Probar los dientes) te lleva con Nartok, el instructor de brujos en la Guarida. {npc:5765} está justo afuera de la Guarida en {area:363} y te pide seis Cabezas de familiar vil.",
		["{npc:5667} (Undead)"] = "{npc:5667} (no-muertos)",
		["{npc:5667} teaches you {spell:688} when you hand in the skulls: summon it right away, it costs nothing and fights beside you."] = "{npc:5667} te enseña {spell:688} cuando entregas los cráneos: invócalo enseguida, no cuesta nada y pelea a tu lado.",
		["{npc:5765} (Orcs and Trolls)"] = "{npc:5765} (orcos y trols)",
		["{npc:5765} teaches you {spell:688} when you hand in the heads: summon it right away, it costs nothing and fights beside you. Then speak with {npc:3145} a few steps away for a starter weapon."] = "{npc:5765} te enseña {spell:688} cuando entregas las cabezas: invócalo enseguida, no cuesta nada y pelea a tu lado. Luego habla con {npc:3145}, a pocos pasos, para un arma inicial.",
} end)()
t.guides["forever/class/warlock/impsys-request"] = (function() return {
		["A staff, off-hand or robe for your 50s; {npc:14470}'s own errand, not a step of the Dreadsteed chain."] = "Un bastón, una pieza de mano izquierda o una toga para los 50; un encargo propio de {npc:14470}, no un paso de la cadena del Corcelorror.",
		["Amber Voodoo Feathers: Gasher, {npc:5716}"] = "Plumas vudú ámbar: Gasher, {npc:5716}",
		["At 50 {npc:3326} in the {object:172960} sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "A nivel 50, {npc:3326} en {object:172960} te manda con {npc:14470} en {zone:1448} con una pieza de {item:14256}.",
		["At 50 {npc:4563} in the {object:36082} sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "A nivel 50, {npc:4563} en {object:36082} te manda con {npc:14470} en {zone:1448} con una pieza de {item:14256}.",
		["At 50 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "A nivel 50, {npc:461}, en {object:2164}, en {object:2101}, te manda con {npc:14470} en {zone:1448} con una pieza de {item:14256}.",
		["At 50 {npc:5172} in {zone:1455} sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "A nivel 50, {npc:5172} en {zone:1455} te manda con {npc:14470} en {zone:1448} con una pieza de {item:14256}.",
		["Blue Voodoo Feathers: Hukku, Mijan"] = "Plumas vudú azules: Hukku, Mijan",
		["Choose the {item:20536} (staff), the {item:20534} (off-hand) or the {item:20530}."] = "Elige {item:20536} (bastón), {item:20534} (mano izquierda) o {item:20530}.",
		["Green Voodoo Feathers: Zolo, Loro"] = "Plumas vudú verdes: Zolo, Loro",
		["One {item:14256}: the Jadefire satyrs of {zone:1448} drop it about one kill in fourteen, and so do the Legashi satyrs and the Felguard Sentries you hunt for Niby's essences. Quicker: buy one at the Auction House. You need it for the trainer's {quest:8419} or for {npc:14470}'s own {quest:8420}, the same errand: whichever you hold."] = "Una {item:14256}: los sátiros Fuego de Jade de {zone:1448} la sueltan más o menos una vez de cada catorce, igual que los sátiros Legashi y los centinelas guardia vil que cazas por las esencias de Niby. Más rápido: compra una en la casa de subastas. La necesitas para {quest:8419} del instructor o para {quest:8420} del propio {npc:14470}, el mismo encargo: la que tengas.",
		["The Irontree treants (level 52) of {area:1767}, in northern {zone:1448} west of {area:1998}, drop {item:20613} one time in four; the big {npc:7149} (55) often drops three at once but hits hard and dazes. The Tainted Oozes (51) around {npc:14470} and along the Bloodvenom drop the essence one time in five."] = "Los antárboles Bosque de Hierro (nivel 52) de {area:1767}, en el norte de {zone:1448} al oeste de {area:1998}, sueltan {item:20613} una vez de cada cuatro; el gran {npc:7149} (55) suele soltar tres de una vez, pero pega fuerte y aturde. Los mocos contaminados (51) alrededor de {npc:14470} y a lo largo del Sangrevenenosa sueltan la esencia una vez de cada cinco.",
		["The {area:1417}"] = "{area:1417}",
		["The {area:1417} ({area:1477}, level 50-56, a group of five) stands in the middle of the {area:74}: swim down into the temple and take the stairs to the entrance. The six troll guardians (level 51-52, elite) stand on the balconies around the central pit, each with adds; each drops his feather every time: Gasher and {npc:5716} the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green. Not soloable at 52."] = "{area:1417} ({area:1477}, nivel 50-56, un grupo de cinco) está en el centro de {area:74}: nada hacia abajo dentro del templo y toma la escalera hasta la entrada. Los seis guardianes trol (nivel 51-52, élite) están en los balcones alrededor del foso central, cada uno con refuerzos; cada uno suelta su pluma siempre: Gasher y {npc:5716} la ámbar, Hukku y Mijan la azul, Zolo y Loro la verde. No se puede hacer solo a nivel 52.",
		["{item:20613} and Bloodvenom"] = "{item:20613} y veneno de sangre",
		["{npc:14470} again"] = "{npc:14470} de nuevo",
		["{npc:14470} now wants six {item:20609} from the {area:1417}: a dungeon run."] = "{npc:14470} ahora quiere seis {item:20609} de {area:1417}: una salida a mazmorra.",
		["{npc:14470} waits beside {npc:14469} on a rise just north-east of {area:1997}: coming north over the {area:1765} bridge, they stand off the road to the east, past a few oozes. Hand him the trainer's {quest:8419} with the cloth. Next he wants ten {item:20613} and four {item:20614}."] = "{npc:14470} espera junto a {npc:14469} en una elevación justo al noreste de {area:1997}: viniendo al norte por el puente de {area:1765}, están fuera del camino hacia el este, pasando unos mocos. Entrégale {quest:8419} del instructor con la tela. Después quiere diez {item:20613} y cuatro {item:20614}.",
		["{npc:14470} waits beside {npc:14469} on a rise just north-east of {area:1997}: coming north over the {area:1765} bridge, they stand off the road to the east, past a few oozes. Take his own {quest:8420} and hand him the cloth at once. Next he wants ten {item:20613} and four {item:20614}."] = "{npc:14470} espera junto a {npc:14469} en una elevación justo al noreste de {area:1997}: viniendo al norte por el puente de {area:1765}, están fuera del camino hacia el este, pasando unos mocos. Toma su propia {quest:8420} y dale la tela enseguida. Después quiere diez {item:20613} y cuatro {item:20614}.",
} end)()
t.guides["forever/class/warlock/incubus-alliance"] = (function() return {
		["At 20 {npc:6120}, the warlock trainer in {zone:1455}'s {object:32383}, sends you to {npc:6122} in {zone:1453}. Take the {area:2257}."] = "A nivel 20, {npc:6120}, el instructor de brujos en {object:32383} de {zone:1455}, te manda con {npc:6122} en {zone:1453}. Toma {area:2257}.",
		["At 20 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6244} in the {zone:1413}: a long trip for the Alliance. Take the boat from {area:150} to Theramore and head west through {zone:1445}, or the boat from {area:35} to {area:392}."] = "A nivel 20, {npc:6122}, en el sótano de {object:2164} en {object:2101}, te manda con {npc:6244} en {zone:1413}: un viaje largo para la Alianza. Toma el barco de {area:150} a Theramore y ve al oeste por {zone:1445}, o el barco de {area:35} a {area:392}.",
		["At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards."] = "A nivel 20: la súcubo y el íncubo de Forever, su gemelo masculino, cada uno con una bolsa de almas para tus fragmentos.",
		["Back to {npc:6122} with the {quest:1738}. He hands you the {item:6913}: take the stairs behind him down to the crypt; part way along the lowest corridor a side stair on the left leads to the room with the purple circle. Stand on it and use the core. Summon your voidwalker first and keep the succubus (level 20, not elite) on the circle, or the guards may kill her and the kill does not count. If she wins, use the core again; keep it, {npc:6122} takes it back."] = "De vuelta con {npc:6122} con {quest:1738}. Te da {item:6913}: baja por la escalera detrás de él hasta la cripta; a mitad del pasillo más bajo, una escalera lateral a la izquierda lleva a la sala del círculo morado. Párate en él y usa el núcleo. Invoca antes a tu abisario y mantén a la súcubo (nivel 20, no élite) en el círculo, o los guardias pueden matarla y esa muerte no cuenta. Si gana ella, usa el núcleo otra vez; guárdalo, {npc:6122} lo recupera.",
		["Give Gakin the figurine, then use the {item:190309} at the middle of the same circle and defeat the incubus it calls (level 20, not elite; it can charm you) with your voidwalker tanking. Keep the figurine: {npc:6122} takes it back."] = "Dale a Gakin la figurilla, luego usa {item:190309} en el centro del mismo círculo y derrota al íncubo que llama (nivel 20, no élite; puede hechizarte) con tu abisario como tanque. Guarda la figurilla: {npc:6122} la recupera.",
		["Ordil'Aran lies in north-west {zone:1440}, north of {area:415} along the road toward {zone:1439}. About twenty Dark Strand cultists hold the ruins around the great tree: keep to the outer wall, and click the {quest:1738} from as far away as it lets you. It is turned in to {npc:6122}, not to Takar."] = "Ordil'Aran está en el noroeste de {zone:1440}, al norte de {area:415} por el camino hacia {zone:1439}. Unos veinte sectarios de la Hebra Oscura ocupan las ruinas alrededor del gran árbol: mantente junto al muro exterior y haz clic en {quest:1738} desde lo más lejos que te deje. Se entrega a {npc:6122}, no a Takar.",
		["Succubus and Incubus (Alliance)"] = "Súcubo e íncubo (Alianza)",
		["The house stands alone in the trees of north-western {zone:1440}, north-west of Ordil'Aran and well north of {area:413}: do it on the same trip as the {quest:1738}. Take the {item:190307} from the table outside, light it at a campfire (a {object:29784} of your own, or Talen's fire on {area:414}), and go straight back: the {item:190308} burns out after five minutes, so a fire of your own beside the house is quickest. Without it the figure in the house stops you. The figurine is upstairs."] = "La casa está sola entre los árboles del noroeste de {zone:1440}, al noroeste de Ordil'Aran y bastante al norte de {area:413}: hazlo en el mismo viaje que {quest:1738}. Toma {item:190307} de la mesa de afuera, enciéndela en una fogata (una {object:29784} tuya o la fogata de Talen en {area:414}) y vuelve directo: {item:190308} se apaga a los cinco minutos, así que una fogata propia junto a la casa es lo más rápido. Sin ella, la figura de la casa te detiene. La figurilla está en el piso de arriba.",
		["The {item:190309}"] = "{item:190309}",
		["the incubus"] = "el íncubo",
		["the succubus"] = "la súcubo",
		["{item:190307}, on the table outside"] = "{item:190307}, en la mesa de afuera",
		["{item:190309}, upstairs"] = "{item:190309}, en el piso de arriba",
		["{item:6913}, on the circle in the crypt"] = "{item:6913}, sobre el círculo de la cripta",
		["{npc:185335}, at the circle in the crypt"] = "{npc:185335}, en el círculo de la cripta",
		["{npc:6244} camps at a tent with a campfire just north-east of {area:378}, by a fork in the road: Horde ground, so come in from the east and keep clear of the Taurajo guards. {npc:6247} beside him starts the {item:6898}. Takar offers both branches: take both."] = "{npc:6244} acampa en una tienda con fogata, justo al noreste de {area:378}, junto a una bifurcación del camino: es terreno de la Horda, así que llega desde el este y no te acerques a los guardias de Taurajo. {npc:6247}, a su lado, inicia {item:6898}. Takar ofrece las dos ramas: toma ambas.",
		["{quest:1717} (Gnomes)"] = "{quest:1717} (gnomos)",
		["{quest:1739}: succubus"] = "{quest:1739}: súcubo",
		["{quest:65603}: incubus"] = "{quest:65603}: íncubo",
} end)()
t.guides["forever/class/warlock/incubus-horde"] = (function() return {
		["At 20 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:5909} a few steps away. Two trainers start these demons, {npc:5875} here and {npc:5675} in the {zone:1458}, and you can take only one; this guide follows whichever {quest:1507} you took. {npc:5909} offers both of {zone:1454}'s branches: take both."] = "A nivel 20, {npc:5875}, en {object:172960} debajo de {object:172982}, te manda con {npc:5909}, a pocos pasos. Dos instructores inician estos demonios, {npc:5875} aquí y {npc:5675} en {zone:1458}, y solo puedes tomar uno; esta guía sigue la {quest:1507} que hayas tomado. {npc:5909} ofrece las dos ramas de {zone:1454}: toma ambas.",
		["At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards."] = "A nivel 20: la súcubo y el íncubo de Forever, su gemelo masculino, cada uno con una bolsa de almas para tus fragmentos.",
		["Back to {npc:5675} with Dalin's and Corma's hearts. He hands you the {item:6286}: go down to the summoning circle below him, stand on it and use them. Summon your voidwalker first and keep the fight on the circle, or the guards may kill her and the kill does not count. If she wins, use the hearts again; keep them, {npc:5675} takes them back."] = "De vuelta con {npc:5675} con los corazones de Dalin y Corma. Te da {item:6286}: baja al círculo de invocación debajo de él, párate en él y úsalos. Invoca antes a tu abisario y mantén la pelea en el círculo, o los guardias pueden matarla y esa muerte no cuenta. Si gana ella, usa los corazones otra vez; guárdalos, {npc:5675} los recupera.",
		["Back to {npc:5675} with the lovers' hearts, then place the {item:190181} on the same circle and defeat the incubus they call (level 20, not elite; it can charm you). Keep the hearts: {npc:5675} takes them back."] = "De vuelta con {npc:5675} con los corazones de los amantes, luego pon {item:190181} sobre el mismo círculo y derrota al íncubo que llaman (nivel 20, no élite; puede hechizarte). Guarda los corazones: {npc:5675} los recupera.",
		["Back to {npc:5875} with the pendant. He hands you {item:6626}: take it across the {object:172960} to {npc:3216}'s tent, stand on the purple circle and use it. Summon your voidwalker first and let it tank: the succubus (level 20, not elite) charms and lashes; keep your damage over time on her. If she wins, use the pendant again. Keep the pendant: {npc:5875} takes it back."] = "De vuelta con {npc:5875} con el colgante. Te da {item:6626}: llévalo cruzando {object:172960} hasta la tienda de {npc:3216}, párate en el círculo morado y úsalo. Invoca antes a tu abisario y deja que aguante: la súcubo (nivel 20, no élite) hechiza y azota; mantén tu daño en el tiempo sobre ella. Si gana ella, usa el colgante otra vez. Guarda el colgante: {npc:5875} lo recupera.",
		["Back to {npc:5875} with the scarf, then use the {item:190232} on the same circle in Neeru's tent and defeat the incubus it calls (level 20, not elite) with your voidwalker tanking. Keep the scarf: {npc:5875} takes it back."] = "De vuelta con {npc:5875} con la bufanda, luego usa {item:190232} sobre el mismo círculo de la tienda de Neeru y derrota al íncubo que llama (nivel 20, no élite) con tu abisario como tanque. Guarda la bufanda: {npc:5875} la recupera.",
		["Corma Villard"] = "Corma Villard",
		["Corma Villard (level 22, not elite; Comar in older records) wanders the north of the {zone:1437} just past the {area:881}, to the right as you come off the bridge. From the {zone:1458} head through {area:287} and {zone:1417}, where the mobs are 30 and up. Attacking her flags you for PvP."] = "Corma Villard (nivel 22, no élite; Comar en registros más viejos) deambula por el norte de {zone:1437}, justo pasando {area:881}, a la derecha al bajar del puente. Desde {zone:1458} ve por {area:287} y {zone:1417}, donde los enemigos son de nivel 30 o más. Atacarla te activa el JcJ.",
		["Silverpine hearts"] = "Corazones de Bosque de Argénteos",
		["Succubus and Incubus (Horde)"] = "Súcubo e íncubo (Horda)",
		["Take the road west from the Crossroads into {zone:1442} and, just past the border, the faint trail up to the left (south): {area:2539} cannot be reached from the main road. {npc:4197} hands you her draught for {npc:5911}."] = "Toma el camino al oeste desde el Cruce hasta {zone:1442} y, justo pasando la frontera, el sendero tenue que sube a la izquierda (al sur): a {area:2539} no se llega por el camino principal. {npc:4197} te da su brebaje para {npc:5911}.",
		["the incubus"] = "el íncubo",
		["the succubus"] = "la súcubo",
		["{area:422} lies in southern {zone:1440}, south-west of {area:431}. The Shadethicket Stone Movers and Bark Rippers (level 25-27) around the lake drop the {item:190232} about one time in twenty, and the lone {npc:3931} (30) can drop it too: plan on a good number of kills, so the guide waits for level 27 first (Forever made this quest level 27); with the succubus already bound you can leave it for your 20s leveling in {zone:1440}. They respawn in five minutes."] = "{area:422} está en el sur de {zone:1440}, al suroeste de {area:431}. Los Muevepiedras y Destripacortezas Sombramatorral (nivel 25-27) de alrededor del lago sueltan la {item:190232} aproximadamente una de cada veinte veces, y el {npc:3931} solitario (30) también puede soltarla: cuenta con bastantes muertes, por eso la guía espera primero al nivel 27 (Forever subió esta misión a nivel 27); con la súcubo ya vinculada, puedes dejarla para cuando subas de nivel en {zone:1440} entre los niveles 20 y 30. Reaparecen en cinco minutos.",
		["{item:6286}, on the circle below {npc:5675}"] = "{item:6286}, sobre el círculo debajo de {npc:5675}",
		["{item:6626}, on the circle in Neeru's tent"] = "{item:6626}, sobre el círculo de la tienda de Neeru",
		["{npc:185333} (level 22) works as a tailor for the {area:279} wizards at {area:233}, in eastern Silverpine: the wizards around her are hostile. {npc:5682} (level 20, not elite) patrols near the {area:230} in the far south. Both are Alliance-friendly humans: attacking them can flag you for PvP. Each drops her or his heart."] = "{npc:185333} (nivel 22) trabaja de sastre para los magos de {area:279} en {area:233}, en el este de Bosque de Argénteos: los magos a su alrededor son hostiles. {npc:5682} (nivel 20, no élite) patrulla cerca de {area:230}, en el extremo sur. Ambos son humanos amistosos con la Alianza: atacarlos puede activarte el JcJ. Cada uno suelta su corazón.",
		["{npc:185334} (level 22) works in {area:392}, on the {zone:1413} coast, at one of two spots in town: take the zeppelin to {zone:1411} and head south, or fly from {zone:1454}. He is an Alliance-friendly human: attacking him can flag you for PvP."] = "{npc:185334} (nivel 22) trabaja en {area:392}, en la costa de {zone:1413}, en uno de dos lugares del pueblo: toma el zepelín a {zone:1411} y ve al sur, o vuela desde {zone:1454}. Es un humano amistoso con la Alianza: atacarlo puede activarte el JcJ.",
		["{npc:185335}, at the circle below {npc:5675}"] = "{npc:185335}, en el círculo debajo de {npc:5675}",
		["{npc:185335}, at the circle in Neeru's tent"] = "{npc:185335}, en el círculo de la tienda de Neeru",
		["{npc:3363} keeps {object:173018} on the main street east of the {object:172960}. He asks you to look for his mate Krilge in {zone:1440}."] = "{npc:3363} atiende {object:173018} en la calle principal al este de {object:172960}. Te pide que busques a su pareja Krilge en {zone:1440}.",
		["{npc:3464} waits in front of the inn at the Crossroads. He sends you on to {npc:4197} at {area:2539}, in {zone:1442}."] = "{npc:3464} espera frente a la posada del Cruce. Te manda con {npc:4197} en {area:2539}, en {zone:1442}.",
		["{npc:5910} lives in a hut up on the cliffs on the west side of the city, above the {object:172982}: climb the wind rider tower, cross the bridge at its top to the west and turn right off it. She sends you to the Crossroads."] = "{npc:5910} vive en una choza en lo alto de los acantilados del lado oeste de la ciudad, sobre {object:172982}: sube a la torre de los jinetes del viento, cruza el puente de arriba hacia el oeste y dobla a la derecha al salir. Te manda al Cruce.",
		["{npc:5911} stands at {area:378}, south down the road from the Crossroads. He sends you north to the quilboar camp where Dogran is held: the camp with two huts side by side, north-west of a decoy camp whose huts stand apart. A rare level 22 elite quilboar sometimes guards the huts: send your voidwalker in, sacrifice it if you must, and talk to Dogran. He gives you a pendant for {npc:5875}. Keep it."] = "{npc:5911} está en {area:378}, al sur por el camino desde el Cruce. Te manda al norte, al campamento de jabaespines donde tienen a Dogran: el campamento con dos chozas una al lado de la otra, al noroeste de un campamento señuelo cuyas chozas están separadas. A veces un jabaespín élite raro de nivel 22 custodia las chozas: manda a tu abisario, sacrifícalo si hace falta, y habla con Dogran. Te da un colgante para {npc:5875}. Guárdalo.",
		["{object:1661}'s version, for warlocks who took {npc:5675}'s {quest:1472} instead of {npc:5875}'s. At 20 {npc:5675}, in the {object:36082}, sends you to {npc:5693} close by. {npc:5693} shows you an image of each quarry and offers both branches: take both."] = "La versión de {object:1661}, para los brujos que tomaron {quest:1472} de {npc:5675} en vez de la de {npc:5875}. A nivel 20, {npc:5675}, en {object:36082}, te manda con {npc:5693}, cerca. {npc:5693} te muestra una imagen de cada presa y ofrece las dos ramas: toma ambas.",
		["{quest:1474}: succubus ({zone:1458})"] = "{quest:1474}: súcubo ({zone:1458})",
		["{quest:1513}: succubus ({zone:1454})"] = "{quest:1513}: súcubo ({zone:1454})",
		["{quest:65597}: incubus ({zone:1458})"] = "{quest:65597}: íncubo ({zone:1458})",
		["{quest:65604}: incubus ({zone:1454})"] = "{quest:65604}: íncubo ({zone:1454})",
} end)()
t.guides["forever/class/warlock/orb-of-orahil"] = (function() return {
		["An off-hand orb or a staff for your late 30s, down the felhound's or the infernal's path, your pick."] = "Un orbe de mano izquierda o un bastón para el final de tus 30, por el camino del can manáfago o del infernal, a tu elección.",
		["At 35 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}."] = "A nivel 35, {npc:3326}, en {object:172960}, te envía con {npc:6266} en {area:392}.",
		["At 35 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}."] = "A nivel 35, {npc:4563}, en {object:36082}, te envía con {npc:6266} en {area:392}. El zepelín de {zone:1420} vuela a {zone:1411}.",
		["At 35 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}."] = "A nivel 35, {npc:461}, en {object:2164} en {object:2101}, te envía con {npc:6266} en {area:392}.",
		["At 35 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}."] = "A nivel 35, {npc:5172}, en {zone:1455}, te envía con {npc:6266} en {area:392}.",
		["Back to {npc:6266} in the tower above {area:392} with the cleansed orb. On the felhound path, accept her last quest and wait beside her while she completes the {item:15108} (do not attack her: the quest log calls it a kill), then speak to her again and pick the off-hand orb or the staff."] = "De vuelta con {npc:6266}, en la torre sobre {area:392}, con el orbe purificado. En el camino del can vil, acepta su última misión y espera a su lado mientras completa {item:15108} (no la ataques: el registro de misiones lo llama matar), luego vuelve a hablarle y elige el orbe de mano izquierda o el bastón.",
		["Back to {npc:6266} in the tower above {area:392} with the spirit and the gem first: her orb follows from it."] = "De vuelta con {npc:6266}, en la torre sobre {area:392}, primero con el espíritu y la gema: su orbe viene después.",
		["Choose an acolyte"] = "Elige un acólito",
		["On the infernal path, accept her last quest and wait beside {npc:6266} while she completes the {item:15107}, then speak to her again and pick the off-hand orb or the staff."] = "En el camino del infernal, acepta su última misión y espera junto a {npc:6266} mientras completa {item:15107}, luego vuelve a hablarle y elige el orbe de mano izquierda o el bastón.",
		["Orb of Orahil"] = "Orbe de Orahil",
		["Pick one acolyte: you can take only one of their quests. {npc:6254}'s felhound path ends with the Orb or {item:15106}, the shadow versions; {npc:6252}'s infernal path with the Orb or {item:15105}, much the same items on the fire side. Most warlocks lean on shadow, but compare the four in their tooltips first. The guide follows the one you take. Keep the ruby or the emerald: it is handed back."] = "Elige un acólito: solo puedes tomar una de sus misiones. El camino del can vil de {npc:6254} termina con el Orbe o {item:15106}, las versiones de sombras; el camino del infernal de {npc:6252}, con el Orbe o {item:15105}, casi los mismos objetos del lado del fuego. La mayoría de los brujos se apoya en las sombras, pero compara primero los cuatro en sus descripciones. La guía sigue el que tomes. Guarda el rubí o la esmeralda: se devuelve.",
		["The demon's spirit"] = "El espíritu del demonio",
		["The {item:15107}"] = "{item:15107}",
		["The {item:15108}"] = "{item:15108}",
		["Wait beside {npc:6266} while she makes the orb"] = "Espera junto a {npc:6266} mientras hace el orbe",
		["{area:602} fills south-central {zone:1443}, east of {area:2408}. The Burning Blade Summoners (level 38-39, warlocks with imps) carry the {item:7291} every time. For the spirit, bring your demon to low health with your damage over time, then channel the ruby or the emerald on it and keep channelling while it dies, as with {spell:1120}: the gem does no damage of its own. The ruby works on the coven's felhounds: the two Mana Eaters (37-38) in the north, and the Mage Hunters (38) and Ley Hunters (39) further south. The emerald works on the Lesser Infernals (36-37, sixteen of them, fire-resistant)."] = "{area:602} ocupa el centro-sur de {zone:1443}, al este de {area:2408}. Los invocadores del Filo Ardiente (nivel 38-39, brujos con diablillos) llevan {item:7291} siempre. Para el espíritu, baja la salud de tu demonio con tu daño en el tiempo, luego canaliza el rubí o la esmeralda sobre él y sigue canalizando mientras muere, como con {spell:1120}: la gema no hace daño por sí misma. El rubí sirve con los canes viles del aquelarre: los dos devoradores de maná (37-38) del norte, y los cazamagos (38) y cazadores de líneas ley (39) más al sur. La esmeralda sirve con los infernales menores (36-37, son dieciséis, resistentes al fuego).",
		["{item:12648}, from a {npc:4678}, {npc:4681} or {npc:4685}"] = "{item:12648}, de un {npc:4678}, {npc:4681} o {npc:4685}",
		["{item:12649}, from a {npc:4676}"] = "{item:12649}, de un {npc:4676}",
		["{item:7291}, from the Burning Blade Summoners"] = "{item:7291}, de los Invocadores Filo Ardiente",
		["{npc:6252}: he gives you the {item:12646}"] = "{npc:6252}: te da {item:12646}",
		["{npc:6254}: she gives you the {item:12647}"] = "{npc:6254}: te da {item:12647}",
		["{npc:6266} and her two acolytes stand in {npc:6251}'s tower on the hill above {area:392}."] = "{npc:6266} y sus dos acólitos están en la torre de {npc:6251}, en la colina sobre {area:392}.",
		["{npc:6546} lives at her farm in the middle of {zone:1445}, south of the road from the {zone:1413} and south-west of Theramore; a spirit healer stands beside it. Deadmire, a level 45 crocolisk, patrols the creeks just north-east. Hand in the orb now; Cleansing waits for level 40. Before you accept it, clear the spiders and crocolisks around her paddock. Accepting starts a 3-minute timer: she walks to the paddock and lets the {npc:6549} out. It is elite (level 40): grouping up is encouraged; a warlock of about 40 can solo it with Fear or {spell:710} and damage over time, a level 38 one brings a friend. The timer keeps running after the kill, so hand in at once. If time runs out, abandon the quest and take it from {npc:6546} again."] = "{npc:6546} vive en su granja, en el centro de {zone:1445}, al sur del camino que viene de {zone:1413} y al suroeste de Theramore; a su lado hay un Ángel de la Resurrección. Lodomuerto, un crocolisco de nivel 45, patrulla los arroyos justo al noreste. Entrega ahora el orbe; “La purificación” espera al nivel 40. Antes de tomarla, limpia las arañas y los crocoliscos de alrededor de su corral. Al tomarla empieza un temporizador de 3 minutos: ella va al corral y suelta al {npc:6549}. Es élite (nivel 40): se recomienda ir en grupo; un brujo de nivel 40 aproximadamente puede hacerlo solo con Miedo o {spell:710} y daño periódico; uno de nivel 38 debería llevar a un amigo. El temporizador sigue corriendo después de la muerte, así que entrega de inmediato. Si se acaba el tiempo, abandona la misión y vuelve a tomarla de {npc:6546}.",
} end)()
t.guides["forever/class/warlock/orb-of-soranruk"] = (function() return {
		["A rare off-hand orb or staff for your 20s, for fragments from two dungeons."] = "Un orbe de mano izquierda o un bastón raros para tus veintes, a cambio de fragmentos de dos mazmorras.",
		["Back to {npc:6247}"] = "Regresa con {npc:6247}",
		["Choose the off-hand {item:6898} or the two-handed {item:15109}."] = "Elige {item:6898} de mano izquierda o {item:15109} de dos manos.",
		["Soran'ruk Fragments, from the Twilight Acolytes inside"] = "Fragmentos de Soran'ruk, de los acólitos del Crepúsculo de adentro",
		["{area:236} (level 22-30, a group of five) stands on the hill south of the {area:228}. Free the prisoner in the cells right of the entrance and he opens the way into the courtyard. The Shadowfang Darksouls (level 20-21, elite) are not in the courtyard: they walk the halls past it, up the ramp that curves left and in the building after. About twelve stand in a run and one in five drops the Large Fragment, so clear every Darksoul and run it again if it does not drop."] = "{area:236} (nivel 22-30, un grupo de cinco) está en la colina al sur de {area:228}. Libera al prisionero de las celdas a la derecha de la entrada y te abre el camino al patio. Los almanegras Colmillo Oscuro (nivel 20-21, élite) no están en el patio: recorren los pasillos más allá, subiendo la rampa que dobla a la izquierda y en el edificio siguiente. Hay unos doce por salida y uno de cada cinco suelta el fragmento grande, así que despeja a todos los almanegras y vuelve a hacerla si no cae.",
		["{area:2797} (level 24-32, a group of five) opens in the ruins on the north-west coast of {zone:1440}, under the water at {area:414}. The Twilight Acolytes (level 24-25, elite, healers) stand in the last halls, around {npc:4832} and the altar before {npc:4829}; each one drops a fragment, but only three spawn in a run and they do not come back for two hours, so one run covers one warlock: kill them first, before they heal the rest."] = "{area:2797} (nivel 24-32, un grupo de cinco) se abre en las ruinas de la costa noroeste de {zone:1440}, bajo el agua en {area:414}. Los acólitos del Crepúsculo (nivel 24-25, élite, sanadores) están en las últimas salas, alrededor de {npc:4832} y del altar antes de {npc:4829}; cada uno suelta un fragmento, pero solo aparecen tres por salida y no vuelven en dos horas, así que una salida alcanza para un brujo: mátalos primero, antes de que curen al resto.",
		["{item:6915}, from the Shadowfang Darksouls inside"] = "{item:6915}, de los almanegras Colmillo Oscuro de adentro",
		["{npc:6247} camps beside {npc:6244}, at a tent just north-east of {area:378} in the southern {zone:1413}. Alliance warlocks reach him from {area:392} or Theramore; Horde ones head south from the Crossroads. He wants fragments from two dungeons: take the quest before your {area:2797} and {area:236} runs."] = "{npc:6247} acampa junto a {npc:6244}, en una tienda justo al noreste de {area:378}, en el sur de {zone:1413}. Los brujos de la Alianza llegan desde {area:392} o Theramore; los de la Horda bajan al sur desde el Cruce. Quiere fragmentos de dos mazmorras: toma la misión antes de tus salidas a {area:2797} y {area:236}.",
} end)()
t.guides["forever/class/warlock/shard-of-the-green-flame"] = (function() return {
		["A rare off-hand for your 50s from {npc:14469} and {npc:14470} in {zone:1448}, the camp that also offers An Imp's Request."] = "Un objeto de mano izquierda raro para tus 50 de {npc:14469} y {npc:14470} en {zone:1448}, el campamento que también ofrece Pedido de un diablillo.",
		["At 50 {npc:14469} and his imp {npc:14470} wait on a rise in central {zone:1448} just north-east of {area:1997}: coming north over the {area:1765} bridge, they stand off the road to the east, past a few oozes. {npc:14469} sends you to {npc:14470}, beside him, who wants three Flawless Fel Essences from three places."] = "A nivel 50, {npc:14469} y su diablillo {npc:14470} esperan en una elevación en el centro de {zone:1448}, justo al noreste de {area:1997}: viniendo al norte por el puente de {area:1765}, están fuera del camino hacia el este, pasando unos mocos. {npc:14469} te manda con {npc:14470}, a su lado, que quiere tres Esencias viles impecables de tres lugares.",
		["Back to {npc:14469}"] = "Regresa con {npc:14469}",
		["Back to {npc:14470}. He hands you the {item:18626}: keep it, it wakes the infernal {npc:14467}."] = "De vuelta con {npc:14470}. Te da {item:18626}: guárdalo, despierta al infernal {npc:14467}.",
		["The Felguard Sentries (level 54) walk around the {area:72} in the south of the {zone:1419}, each with a felhunter. Leave the level 57 Servants of Razelikh alone: they cannot be killed without their own quest."] = "Los centinelas guardia vil (nivel 54) caminan alrededor de {area:72}, en el sur de {zone:1419}, cada uno con un manáfago. Deja en paz a los siervos de Razelikh de nivel 57: no se pueden matar sin su propia misión.",
		["The Legashi satyrs (level 51-53) hold the Legash Encampment on {zone:1447}'s northern coast. Every kind drops the essence three times in four; the satyrs burn mana and the Hellcallers rain fire, so pull them singly."] = "Los sátiros Legashi (nivel 51-53) ocupan el Campamento Legashi en la costa norte de {zone:1447}. Todos los tipos sueltan la esencia tres de cada cuatro veces; los sátiros queman maná y los clamainfiernos hacen llover fuego, así que atráelos de a uno.",
		["{area:1763} lies just south of {area:1997}, west of the road. The guide waits for level 54 first: its Legionnaires are 55. Of its two caves, {area:1770} is the northern one, further up the hill; the other has no Legionnaires. {area:1770}'s tunnels run north under the hills, and the Jaedenar Legionnaires (level 55) stand in its deeper halls, from the first ramps on toward {npc:9516}'s chamber; they Uppercut anyone in melee. Three kills in four give the essence, but only about eleven spawn: clear your way in and wait out a five-minute respawn if you must. The cultists of {area:1763} and {area:1770} are all hostile."] = "{area:1763} está justo al sur de {area:1997}, al oeste del camino. La guía espera primero al nivel 54: sus Legionarios son de nivel 55. De sus dos cuevas, {area:1770} es la del norte, más arriba en la colina; la otra no tiene Legionarios. Los túneles de {area:1770} van hacia el norte bajo las colinas, y los Legionarios Jaedenar (nivel 55) están en sus salas más profundas, desde las primeras rampas hasta la cámara de {npc:9516}; usan Gancho contra quien esté cuerpo a cuerpo. Tres de cada cuatro muertes dan la esencia, pero solo aparecen unos once: abre camino hacia adentro y espera a que reaparezcan (cinco minutos) si hace falta. Todos los sectarios de {area:1763} y {area:1770} son hostiles.",
		["{item:18626}, at {object:179677}"] = "{item:18626}, en {object:179677}",
		["{npc:14467}' remains lie in {area:1766}, the burnt crater north of {npc:14469}: follow the road north from his camp; the remains lie a little east of it. Use the {item:18626} beside them and wait for him to rise. {npc:14467} is elite (level 55): grouping up is encouraged; a warlock of 55 or more can solo him with Fear and damage over time, or with Enslave Demon, but fire spells do nothing to him and he knocks you back. If you die he heals to full; he rises again three minutes after he dies. An elite infernal patrols the pool south of the remains: pull {npc:14467} away from it. He always drops his core. Lost the {item:18626}? Abandon the quest and take it again from {npc:14470}."] = "Los restos de {npc:14467} están en {area:1766}, el cráter quemado al norte de {npc:14469}: sigue el camino al norte desde su campamento; los restos están un poco al este. Usa {item:18626} a su lado y espera a que se levante. {npc:14467} es élite (nivel 55): se recomienda agruparse; un brujo de nivel 55 o más puede hacerlo solo con Miedo y daño en el tiempo, o con Esclavizar demonio, pero los hechizos de fuego no le hacen nada y te empuja. Si mueres, se cura por completo; vuelve a levantarse tres minutos después de morir. Un infernal élite patrulla la poza al sur de los restos: aleja a {npc:14467} de ella. Siempre suelta su núcleo. ¿Perdiste {item:18626}? Abandona la misión y vuelve a tomarla con {npc:14470}.",
} end)()
t.guides["forever/class/warlock/tome-of-sacrifice"] = (function() return {
		["A rare off-hand at 60, {npc:14463}'s payment for capturing a {npc:12396} in the {zone:1419}."] = "Una pieza rara de mano izquierda a nivel 60, el pago de {npc:14463} por capturar a un {npc:12396} en {zone:1419}.",
		["At 60 {npc:14463} waits in the {area:73}, the demon-filled hollow in the west of the {zone:1419}. The Scar is full of hard-hitting elites: Soulstone yourself first, then keep to the right-hand wall going in, or ride through mounted. {npc:14463} gives you two errands at once."] = "A nivel 60, {npc:14463} espera en {area:73}, la hondonada llena de demonios en el oeste de {zone:1419}. La Cicatriz está llena de élites que pegan fuerte: ponte antes una piedra de alma y mantente pegado a la pared derecha al entrar, o pasa montado. {npc:14463} te da dos encargos a la vez.",
		["Back to {npc:14463}"] = "Vuelve con {npc:14463}",
		["Hand both in to {npc:14463} and take the {item:18601}. Find a {npc:12396} (level 61, elite) standing alone in the {area:73}, open from about 30 yards with your voidwalker on him, and channel the prison on him for about 20 seconds: he attacks you to break free, and his {spell:45} can interrupt the channel, so sacrifice the voidwalker for its shield if you must. Grouping up is encouraged: a second player to tank makes it easy. When the channel finishes he becomes the {item:18605}: click it. If the channel breaks, kill him or run, and try another."] = "Entrégale ambas a {npc:14463} y toma {item:18601}. Busca un {npc:12396} (nivel 61, élite) solo en {area:73}, empieza desde unos 30 m con tu abisario sobre él y canaliza la prisión sobre él unos 20 segundos: te ataca para liberarse, y su {spell:45} puede interrumpir la canalización, así que sacrifica al abisario por su escudo si hace falta. Se recomienda agruparse: un segundo jugador como tanque lo hace fácil. Cuando termina la canalización, se convierte en {item:18605}: haz clic en él. Si la canalización se rompe, mátalo o huye, y prueba con otro.",
		["The Hederine demons (level 57-60, elite) hold {area:2256} in the far south of {zone:1452}: grouping up is encouraged. Two Slayers guard the gorge past the bridge; the western tunnel leads to more Initiates, the easiest of them (watch for their {spell:7645}). A warlock can solo them one at a time with Fear or {spell:710} and damage over time, but slowly. Any of them can drop the Tears, four kills in five."] = "Los demonios Hederine (nivel 57-60, élite) ocupan {area:2256}, en el extremo sur de {zone:1452}: se recomienda agruparse. Dos destripadores custodian la garganta pasando el puente; el túnel del oeste lleva a más iniciados, los más fáciles (cuidado con su {spell:7645}). Un brujo puede hacerlos solo de a uno con Miedo o {spell:710} y daño en el tiempo, pero despacio. Cualquiera puede soltar las Lágrimas, cuatro de cada cinco veces.",
		["The Wildspawn satyrs (level 55-57, elite) fill the Warpwood Quarter, {area:2577}'s eastern wing: bring a group of five. Four in five drop a blood, but they do not come back for two hours and one full clear may come up short of fifteen; reset and run it again. The back door at {area:2518} needs the {item:18249}, which drops inside this wing; until someone has it, go in by {area:2577}'s main gate in central {zone:1444}."] = "Los sátiros Engendro Salvaje (nivel 55-57, élite) llenan el Barrio Madeguerra, el ala este de {area:2577}: lleva un grupo de cinco. Cuatro de cada cinco sueltan una sangre, pero no vuelven en dos horas y una limpieza completa puede quedarse corta de quince; reinicia y vuelve a hacerla. La puerta trasera de {area:2518} necesita {item:18249}, que cae dentro de esta ala; hasta que alguien la tenga, entra por la puerta principal de {area:2577}, en el centro de {zone:1444}.",
		["{item:18601}, on a {npc:12396}"] = "{item:18601}, sobre un {npc:12396}",
		["{item:18603}, from the Wildspawn inside"] = "{item:18603}, de los Engendro Salvaje de adentro",
		["{item:18605}, click it"] = "{item:18605}, haz clic en él",
} end)()
t.guides["forever/class/warlock/voidwalker-alliance"] = (function() return {
		["At 10 {npc:6120}, the warlock trainer in {zone:1455}'s {object:32383}, sends you to {npc:6122} in {zone:1453}. Take the {area:2257} from {object:171524}. If {npc:6120} does not offer it, go to {npc:6122} anyway: he still gives you the next quest."] = "A nivel 10, {npc:6120}, el instructor de brujos en {object:32383} de {zone:1455}, te manda con {npc:6122} en {zone:1453}. Toma {area:2257} desde {object:171524}. Si {npc:6120} no te la ofrece, ve con {npc:6122} igual: te da la siguiente misión de todos modos.",
		["At 10 {npc:6121}, in the cellar of the Lion's Pride Inn in {area:87} (the stairs down are in the back room past the butcher's table), sends you to {npc:6122} in {zone:1453}."] = "A nivel 10, {npc:6121}, en el sótano de la Posada Orgullo de León en {area:87} (la escalera de bajada está en la sala del fondo, pasando la mesa del carnicero), te manda con {npc:6122} en {zone:1453}.",
		["Back to {npc:6122}. He hands you the {item:6928}. The circle is hard to find: take the stairs behind {npc:6122} down; part way along the lowest corridor a side stair on the left leads into a room with a glowing purple circle in the middle. Stand on it and use the choker. The voidwalker (level 10, not elite) gets dangerous below 30% health: {spell:14868}, Corruption and {spell:348} with your imp on it, Fear when it gets close. If it beats you, use the choker again. Keep the choker: {npc:6122} takes it back."] = "De vuelta con {npc:6122}. Te da {item:6928}. El círculo cuesta encontrarlo: baja por la escalera detrás de {npc:6122}; a mitad del pasillo más bajo, una escalera lateral a la izquierda lleva a una sala con un círculo morado brillante en el centro. Párate en él y usa el collar. El abisario (nivel 10, no élite) se vuelve peligroso por debajo del 30 % de salud: {spell:14868}, Corrupción y {spell:348} con tu diablillo encima, y Miedo cuando se acerque. Si te gana, usa el collar otra vez. Guarda el collar: {npc:6122} lo recupera.",
		["Voidwalker (Alliance)"] = "Abisario (Alianza)",
		["Your tank demon at 10: the voidwalker, after a dark sorceress's choker and a fight in {npc:6122}'s crypt."] = "Tu demonio tanque a nivel 10: el abisario, después del collar de una hechicera oscura y una pelea en la cripta de {npc:6122}.",
		["{item:6928}, on the circle in the crypt"] = "{item:6928}, sobre el círculo de la cripta",
		["{npc:6121}, Lion's Pride Inn cellar"] = "{npc:6121}, sótano de la Posada Orgullo de León",
		["{npc:881} (level 9) is inside the farmhouse at the {area:62}, south-east Elwynn near the Redridge road. {npc:473} (level 10) and a warrior stand with her and join the fight; Morgan gouges and goes for your imp, so keep him Feared. Put your damage over time on {npc:881} first, Fear the others, and loot her choker before you finish them: it stays yours even if you die after. She throws fireballs from range and is back three minutes after she dies. Have the quest before you kill her, or the choker does not drop."] = "{npc:881} (nivel 9) está dentro de la granja de {area:62}, en el sureste de Elwynn, cerca del camino a Crestagrana. {npc:473} (nivel 10) y un guerrero están con ella y se unen a la pelea; Morgan da golpes bajos y va por tu diablillo, así que mantenlo aterrado. Pon primero tu daño en el tiempo sobre {npc:881}, aterra a los otros y saquea su collar antes de rematarlos: sigue siendo tuyo aunque mueras después. Lanza bolas de fuego a distancia y vuelve tres minutos después de morir. Ten la misión antes de matarla, o el collar no cae.",
		["{quest:1685} (Humans)"] = "{quest:1685} (humanos)",
		["{quest:1715} (Gnomes)"] = "{quest:1715} (gnomos)",
		["{quest:1715} is the tavern in the {object:2101}; {npc:6122} is in its cellar, down the stairs inside."] = "{quest:1715} es la taberna de {object:2101}; {npc:6122} está en su sótano, bajando la escalera de adentro.",
} end)()
t.guides["forever/class/warlock/voidwalker-horde"] = (function() return {
		["At 10 {npc:3294} sends you to {npc:5875}. He stands outside at the back of {area:362}'s barracks, the big building on the east side of town (not the inn), a few steps from {npc:3172}, the warlock trainer. {npc:5875} stands with the senior warlocks in the {object:172960}, the cavern under {zone:1454}'s {object:172982}. An Orc or Troll leveling in {zone:1420} can take the {zone:1458} version from {npc:5724} in {area:159} instead (the {zone:1458} steps below): you can do only one of the two."] = "A nivel 10, {npc:3294} te manda con {npc:5875}. Está afuera, en la parte de atrás del cuartel de {area:362}, el edificio grande del lado este del pueblo (no la posada), a pocos pasos de {npc:3172}, el instructor de brujos. {npc:5875} está con los brujos veteranos en {object:172960}, la caverna debajo de {object:172982} de {zone:1454}. Un orco o trol que sube de nivel en {zone:1420} puede tomar en su lugar la versión de {zone:1458} con {npc:5724} en {area:159} (los pasos de {zone:1458}, más abajo): solo puedes hacer una de las dos.",
		["At 10 {npc:5724}, upstairs in the {area:2119} in {area:159}, sends you to {npc:5675}: the version for the Undead, and for Orcs and Trolls who level in {zone:1420} instead of taking {npc:5875}'s. {npc:5675} stands in the {zone:1458}'s {object:36082}, by the Temple of the Damned."] = "A nivel 10, {npc:5724}, en el piso de arriba de {area:2119} en {area:159}, te manda con {npc:5675}: la versión para los no-muertos, y para los orcos y trols que suben de nivel en {zone:1420} en vez de tomar la de {npc:5875}. {npc:5675} está en {object:36082} de {zone:1458}, junto al Templo de los Malditos.",
		["Back to {npc:5675}. He hands you the {item:6284}: go down the stairs from him to the summoning circle and use them while standing on it. Fight the voidwalker (level 10, not elite) on the circle: if it wanders off, the city guards may kill it and the kill does not count. {spell:14868}, Corruption and {spell:348} with your imp tanking bring it down; it hits harder below 30%. If you lose, use the runes again. Keep the runes: {npc:5675} takes them back."] = "De vuelta con {npc:5675}. Te da {item:6284}: baja la escalera desde donde está él hasta el círculo de invocación y úsalas parado en él. Pelea con el abisario (nivel 10, no élite) en el círculo: si se aleja, los guardias de la ciudad pueden matarlo y esa muerte no cuenta. {spell:14868}, Corrupción y {spell:348} con tu diablillo como tanque lo bajan; pega más fuerte por debajo del 30 %. Si pierdes, usa las runas otra vez. Guarda las runas: {npc:5675} las recupera.",
		["Back to {npc:5875}. He hands you the {item:7464}: take them across the {object:172960} to {npc:3216}'s tent, stand on the purple circle on its floor and use them. The voidwalker (level 10, not elite) hits hard at 30% health and leaves after three minutes, so start at once: {spell:14868}, Corruption and {spell:348}, send your imp in, and Fear it when you need a breather. If it beats you or leaves, the glyphs are not used up: use them again on the circle. Keep the glyphs: {npc:5875} takes them back."] = "De vuelta con {npc:5875}. Te da {item:7464}: llévalos cruzando {object:172960} hasta la tienda de {npc:3216}, párate en el círculo morado del suelo y úsalos. El abisario (nivel 10, no élite) pega fuerte al 30 % de salud y se va a los tres minutos, así que empieza enseguida: {spell:14868}, Corrupción y {spell:348}, manda a tu diablillo y aterralo cuando necesites un respiro. Si te gana o se va, los glifos no se gastan: úsalos otra vez sobre el círculo. Guarda los glifos: {npc:5875} los recupera.",
		["The Scarlet tower stands in the fields west of the {zone:1458}'s ruins (not the tower near {area:154}). The grimoire is in the small chest on the ground floor, under the stairs; ignore the chest upstairs. {npc:1662} (level 9) and a {npc:1537} guard it: kill them, or Fear the zealot while you deal with Perrine. Scarlet Missionaries and Zealots (level 7-9) walk the fields around the tower. The chest is back three seconds after anyone opens it."] = "La torre Escarlata está en los campos al oeste de las ruinas de {zone:1458} (no la torre cerca de {area:154}). El grimorio está en el cofrecito de la planta baja, debajo de la escalera; ignora el cofre de arriba. {npc:1662} (nivel 9) y un {npc:1537} lo custodian: mátalos, o aterra al fanático mientras te encargas de Perrine. Los misioneros y fanáticos Escarlata (nivel 7-9) recorren los campos alrededor de la torre. El cofre vuelve tres segundos después de que alguien lo abre.",
		["Voidwalker (Horde)"] = "Abisario (Horda)",
		["Your tank demon at 10: the voidwalker, after a stolen book and a fight at a summoning circle."] = "Tu demonio tanque a nivel 10: el abisario, después de un libro robado y una pelea en un círculo de invocación.",
		["{area:817} is the cave in the cliffs just east of {zone:1454}'s gate. Inside, take the right-hand ramp up and follow it to the top: the {object:58595} sits on that upper ledge, which cannot be reached from the lower floor. The cave is packed with Burning Blade Apprentices and Fanatics (level 9-11, many with voidwalkers) that respawn quickly, and {npc:3204}, a level 14 Burning Blade warlock, stands near the stash. Old notes call him elite; Forever's data lists him as normal. At 10 it is hard alone: pull one pack at a time and Fear the extra, wait for 11, or go with a friend. The stash always holds the tablet."] = "{area:817} es la cueva en los acantilados justo al este de la puerta de {zone:1454}. Adentro, toma la rampa de la derecha y síguela hasta arriba: {object:58595} está en esa cornisa superior, a la que no se llega desde el piso de abajo. La cueva está llena de aprendices y fanáticos del Filo Ardiente (nivel 9-11, muchos con abisarios) que reaparecen rápido, y {npc:3204}, un brujo del Filo Ardiente de nivel 14, está cerca del alijo. Notas viejas dicen que es élite; los datos de Forever lo listan como normal. A nivel 10 es difícil solo: atrae un grupo a la vez y aterra al que sobre, espera al nivel 11 o ve con un amigo. El alijo siempre tiene la tablilla.",
		["{item:6284}, on the circle below {npc:5675}"] = "{item:6284}, sobre el círculo debajo de {npc:5675}",
		["{item:6285}, in {object:37098}"] = "{item:6285}, en {object:37098}",
		["{item:6535}, in the {object:58595}"] = "{item:6535}, en {object:58595}",
		["{item:7464}, on the circle in Neeru's tent"] = "{item:7464}, sobre el círculo de la tienda de Neeru",
		["{npc:5724}, upstairs in the {area:159} inn"] = "{npc:5724}, en el piso de arriba de la posada de {area:159}",
		["{quest:1506} (Orcs and Trolls)"] = "{quest:1506} (orcos y trols)",
} end)()
t.guides["forever/class/warrior/brutal-armor"] = (function() return {
		["At 20, {npc:3041}, the warrior trainer of {zone:1456}, sends you to {npc:6394} in {area:378}."] = "A nivel 20, {npc:3041}, el instructor de guerreros de {zone:1456}, te manda con {npc:6394} en {area:378}.",
		["At 20, {npc:3354} in the {object:172958} sends you to {npc:6394} in {area:378}."] = "A nivel 20, {npc:3354} en {object:172958} te manda con {npc:6394} en {area:378}.",
		["At 20, {npc:4595}, a warrior trainer of the {zone:1458}, sends you to {npc:6394} in {area:378}."] = "A nivel 20, {npc:4595}, un instructor de guerreros de {zone:1458}, te manda con {npc:6394} en {area:378}.",
		["Back to {npc:5878} on {area:1699}. {quest:1848} is the first piece; he then sends you to three crafters, one per piece: take all three."] = "De vuelta con {npc:5878} en {area:1699}. {quest:1848} es la primera pieza; después te manda con tres artesanos, uno por pieza: toma las tres.",
		["Fly to {area:378}. {npc:6394} stands in the hut with the leatherworking and tailoring trainers."] = "Vuela a {area:378}. {npc:6394} está en la choza con los instructores de peletería y sastrería.",
		["Hillsbrad Miners"] = "Mineros de Trabalomas ({npc:2269})",
		["Iron Bars"] = "Barras de hierro",
		["Iron Bars: {npc:8673}"] = "Barras de hierro: {npc:8673}",
		["Roogug in {area:1717}"] = "Roogug en {area:1717}",
		["Roogug is an elite quilboar (level 28) inside {area:1717}, the dungeon at the south end of the {zone:1413}; a five-player dungeon: needs a group of five, his guards come with him. The guide waits for level 30 first. Inside take the left path at the first fork, cross the vine bridge over the pig pens, go past the room with the big cauldron: he waits in the room on the right. He casts {spell:403} and calls Earth Rumblers. The vial always drops."] = "Roogug es un jabaespín élite (nivel 28) dentro de {area:1717}, el calabozo del extremo sur de {zone:1413}; un calabozo para cinco jugadores: requiere un grupo de cinco, sus guardias vienen con él. La guía espera primero al nivel 30. Adentro, toma el camino de la izquierda en la primera bifurcación, cruza el puente de lianas sobre los chiqueros y pasa la sala del gran caldero: espera en la sala de la derecha. Lanza {spell:403} e invoca estruendores de tierra. El vial siempre cae.",
		["Starts now at 20 at your trainer; four armor pieces at 30 (hauberk, helm, gauntlets, legguards), a shield on the way."] = "Empieza ahora, a nivel 20, con tu instructor; cuatro piezas de armadura a nivel 30 (cota, yelmo, guanteletes y musleras) y un escudo en el camino.",
		["Take the zeppelin from {zone:1454} to {zone:1420}; {npc:6411} works in the {zone:1458}'s {object:36078}. She wants 8 Sturdy Dragonmaw Shinbones."] = "Toma el zepelín de {zone:1454} a {zone:1420}; {npc:6411} trabaja en {object:36078} de {zone:1458}. Quiere 8 Espinillas Faucedraco robustas.",
		["The Dragonmaw orcs (level 26-30) camp in the middle of the {zone:1437}; from {area:321} in Arathi head south over the {area:881} ({area:150} is Alliance). With {quest:1846} from {npc:6411} in your log, every Raider, Swamprunner, Centurion, Shadowwarder and Bonewarder drops a {item:7131} (without the quest they drop none): right-click it to test it, and about one in four comes out sturdy, the rest break, so expect 30 or more kills for 8. You can test while moving or fighting. The orcs run for help at 15%; Raiders net you, Centurions shield-bash, Shadowwarders cast {spell:686}, Bonewarders raise skeletons."] = "Los orcos Faucedraco (nivel 26-30) acampan en medio de {zone:1437}; desde {area:321} en Arathi, ve al sur por {area:881} ({area:150} es de la Alianza). Con {quest:1846} de {npc:6411} en tu registro, cada Asaltante, Correpantanos, Centurión, Depositario de sombras y Guardahuesos suelta una {item:7131} (sin la misión no sueltan ninguna): haz clic derecho en ella para probarla; más o menos una de cada cuatro sale robusta y las demás se rompen, así que cuenta con 30 muertes o más para conseguir 8. Puedes probarlas mientras te mueves o peleas. Los orcos huyen en busca de ayuda al 15%; los Asaltantes te lanzan redes, los Centuriones golpean con el escudo, los Depositarios de sombras lanzan {spell:686} y los Guardahuesos alzan esqueletos.",
		["The satyrs of {area:430}, north-east of {area:431} ({area:429}, level 28-30), and the Felmusk satyrs north-west of the post (25-27) drop a hoof four kills in five. A {area:429} satyr at 15% health may cast {spell:6925} and heal to full: finish it fast or stun it. Hellcallers throw Fireballs from 40 yards; Felmusk satyrs reek in melee and run for help at 15%."] = "Los sátiros de {area:430}, al noreste de {area:431} ({area:429}, nivel 28-30), y los sátiros Almizcle Vil al noroeste del puesto (25-27) sueltan una pezuña cuatro de cada cinco veces. Un sátiro de {area:429} al 15 % de salud puede lanzar {spell:6925} y curarse por completo: remátalo rápido o atúrdelo. Los clamainfiernos lanzan bolas de fuego desde 40 m; los sátiros Almizcle Vil apestan cuerpo a cuerpo y huyen a pedir ayuda al 15 %.",
		["The {npc:6167} (level 28, not elite, larger than the young ones around her) roams the south edge of the {area:465} in south-west Stonetalon, near the road to {zone:1443}. She is the only one: she returns 5 minutes after dying and drops the {item:6840} four kills in five. She spits {spell:3396} from 30 yards."] = "La {npc:6167} (nivel 28, no élite, más grande que las jóvenes que la rodean) recorre el borde sur de {area:465}, en el suroeste de Sierra Espolón, cerca del camino a {zone:1443}. Es la única: vuelve 5 minutos después de morir y suelta {item:6840} cuatro de cada cinco veces. Escupe {spell:3396} desde 30 m.",
		["You have 30 minutes, and each {item:7119} rots 15 minutes after you loot it, so take the quest only when ready (logging out does not stop the clock). The Silithid Mounds dot the {area:390} south of {area:378}; every silithid drops an antenna. Creepers (level 20-21) and Grubs are the easiest: Swarmers (21-22) call small swarms and Creepers lay eggs that hatch adds. The eastern part of the field has plenty of Creepers. {item:7120}, a shield, is the reward."] = "Tienes 30 minutos, y cada {item:7119} se pudre 15 minutos después de saquearla, así que toma la misión solo cuando estés listo (desconectarte no detiene el reloj). Los montículos de silítidos salpican {area:390} al sur de {area:378}; todos los silítidos sueltan una antena. Los reptadores (nivel 20-21) y las larvas son los más fáciles: los enjambradores (21-22) llaman pequeños enjambres y los reptadores ponen huevos de los que salen refuerzos. La parte este del campo tiene muchos reptadores. La recompensa es {item:7120}, un escudo.",
		["You need 10 Iron Bars. Miners smelt them from {item:2772} (one ore a bar, {spell:3307} at {skill:186} 125); everyone else buys them at the auction house in {zone:1454}."] = "Necesitas 10 Barras de hierro. Los mineros las funden con {item:2772} (un mineral por barra, {spell:3307} con {skill:186} 125); los demás las compran en la casa de subastas de {zone:1454}.",
		["You need 10 {item:7127}. The guide waits for level 30 first ({quest:1838} is a level 30 quest). The Hillsbrad Miners (level 26-27) work the mine in the hills west of {area:271} and drop the azurite four kills in five; they fight in {spell:71}, sunder your armor and run for help at 30% health. Fly to {area:272} and head south-west."] = "Necesitas 10 {item:7127}. La guía espera primero al nivel 30 ({quest:1838} es una misión de nivel 30). Los Mineros de Trabalomas (nivel 26-27) trabajan en la mina de las colinas al oeste de {area:271} y sueltan la azurita en cuatro de cada cinco muertes; pelean en {spell:71}, te hienden la armadura y huyen en busca de ayuda al 30% de salud. Vuela a {area:272} y dirígete al suroeste.",
		["You need 15 Smoky Iron Ingots. The {area:2160} lies at the east end of {area:461}, east of {area:460}; every Windshear kobold (level 19-23) drops an ingot four kills in five. Stonecutters, Geomancers and Overlords run for help when low; Geomancers cast {spell:116}."] = "Necesitas 15 Lingotes de hierro humeante. {area:2160} está en el extremo este de {area:461}, al este de {area:460}; los kóbolds Cizalla (nivel 19-23) sueltan un lingote cuatro de cada cinco veces. Los picapedreros, geomantes y señores supremos huyen a pedir ayuda con poca salud; los geomantes lanzan {spell:116}.",
		["from the Dragonmaw orcs: right-click to test it"] = "de los orcos Faucedraco: haz clic derecho para probarla",
		["{item:6840}, from the {npc:6167}"] = "{item:6840}, de la {npc:6167}",
		["{item:6841}, from Roogug"] = "{item:6841}, de Roogug",
		["{item:7119}, from the silithid"] = "{item:7119}, de los silítidos",
		["{item:7126}, from the Windshear kobolds"] = "{item:7126}, de los kóbolds Cizalla",
		["{item:7127}, from the Hillsbrad Miners"] = "{item:7127}, de los mineros de Trabalomas",
		["{npc:5878}'s hut sits on top of {area:1699}, east of the Crossroads: climb the broad ridge on the north or east side. {quest:1838} is a level 30 quest, so the guide waits for level 29 before you take it. {item:7587} list where each material comes from."] = "La choza de {npc:5878} está en lo alto de {area:1699}, al este del Cruce: sube por la cresta ancha del lado norte o este. {quest:1838} es una misión de nivel 30, así que la guía espera al nivel 29 antes de que la tomes. {item:7587} dice de dónde sale cada material.",
		["{npc:6408} is in {area:367} on the {zone:1411} coast. He wants 7 Uncloven Satyr Hooves."] = "{npc:6408} está en {area:367}, en la costa de {zone:1411}. Quiere 7 Pezuñas de sátiro sin hender.",
		["{npc:6410} works on {zone:1456}'s lowest level, close to the blacksmith."] = "{npc:6410} trabaja en el nivel más bajo de {zone:1456}, cerca del herrero.",
} end)()
t.guides["forever/class/warrior/fire-hardened-armor"] = (function() return {
		["At 20, {npc:5113}, the warrior trainer of {zone:1455}, sends you to {quest:1698} in Redridge."] = "A nivel 20, {npc:5113}, el instructor de guerreros de {zone:1455}, te envía con {quest:1698} en las Montañas Crestagrana.",
		["At 20, {npc:5479}, beside {npc:5480} in the warrior trainers' building of {object:2100}, sends you to {quest:1698} in Redridge."] = "A nivel 20, {npc:5479}, junto a {npc:5480} en el edificio de los instructores de guerreros de {object:2100}, te manda con {quest:1698} en Montañas Crestagrana.",
		["At 20, {npc:7315}, the warrior trainer of {zone:1457}, sends you to {quest:1698} in Redridge."] = "A nivel 20, {npc:7315}, el instructor de guerreros de {zone:1457}, te envía con {quest:1698} en las Montañas Crestagrana.",
		["Back to {npc:5413} in the {object:28027} for the hauberk. He then sends you to the smith of your race; the other two smiths' pieces are open to you as well: talk to them directly."] = "De vuelta con {npc:5413} en {object:28027} para la cota. Después te manda con el herrero de tu raza; las piezas de los otros dos herreros también están disponibles: habla con ellos directamente.",
		["Charred and Galvanized Horns"] = "Cuernos carbonizados y galvanizados",
		["Enter the {area:98} and come back; below ground, at the first fork"] = "Entra en {area:98} y vuelve; bajo tierra, en la primera bifurcación",
		["Fire Hardened Armor"] = "Armadura endurecida al fuego",
		["Ride the {area:2257} from {zone:1453} to {zone:1455}. {quest:1704}, a gnome smith, works in {object:171524} near the engineering trainers. He wants 20 {item:6848}."] = "Toma {area:2257} de {zone:1453} a {zone:1455}. {quest:1704}, un herrero gnomo, trabaja en {object:171524}, cerca de los instructores de ingeniería. Quiere 20 {item:6848}.",
		["Roogug in {area:1717}"] = "Roogug en {area:1717}",
		["Roogug is an elite quilboar (level 28) inside {area:1717}, the dungeon at the south end of the {zone:1413}; a five-player dungeon: needs a group of five, and his guards come with him. The guide waits for level 28 first. Inside take the left path at the first fork, cross the root bridge, go past the big empty cauldron: he is in a dead end on the right, with about ten elites on the way. He casts {spell:403} and calls Earth Rumblers. The vial always drops."] = "Roogug es un jabaespín élite (nivel 28) dentro de {area:1717}, el calabozo en el extremo sur de {zone:1413}; es un calabozo de cinco jugadores: necesita un grupo de cinco, y sus guardias vienen con él. La guía espera primero al nivel 28. Adentro, toma el camino de la izquierda en la primera bifurcación, cruza el puente de raíces y pasa el gran caldero vacío: está en un callejón sin salida a la derecha, con unos diez élites en el camino. Lanza {spell:403} y llama a retumbadores de tierra. El vial siempre cae.",
		["Scorched Spider Fangs"] = "Colmillos de araña agostados",
		["Starts now at 20 with a shield; a hauberk at 28, then a coif, leggings and gauntlets from three smiths."] = "Empieza ahora, a nivel 20, con un escudo; una cota a nivel 28, y luego una cofia, unas calzas y unos guanteletes de tres herreros.",
		["The Nightbane worgen of {zone:1431} (Dark Runners, Vile Fangs, Shadow Weavers, Worgen and Tainted Ones, level 26-31) south and west of {area:42} drop the {quest:1705} four kills in five; the guide waits for level 28 first. The Tainted Ones poison and howl; Vile Fangs cause {spell:3427}."] = "Los huargen Penumbría de {zone:1431} (Sombracechadores, Colmilloviles, Tejesombras, Huargen y Corruptos, nivel 26-31) al sur y al oeste de {area:42} sueltan la {quest:1705} en cuatro de cada cinco muertes; la guía espera primero al nivel 28. Los Corruptos envenenan y aúllan; los Colmilloviles causan {spell:3427}.",
		["The chimaeras live south-west of {area:460} in the {area:465}; the guide waits for level 28 first. You need 12 Charred Horns from the Fledgling (level 25-27) and Young Chimaeras (23-25), four kills in five, and the {item:6840} from the {npc:6167} (28, the big one), also four in five. Only three Fledglings, two Young and one Matriarch live there, each back in 5 minutes, so expect to wait. Fledglings and the Matriarch spit {spell:3396}, the Young cast {spell:403}. Alliance: fly to {area:467} and head south."] = "Las quimeras viven al suroeste de {area:460}, en {area:465}; la guía espera primero al nivel 28. Necesitas 12 Cuernos carbonizados de las Quimeras volantonas (nivel 25-27) y las Quimeras jóvenes (23-25), en cuatro de cada cinco muertes, y el {item:6840} de la {npc:6167} (28, la grande), también en cuatro de cada cinco. Ahí solo viven tres volantonas, dos jóvenes y una matriarca, y cada una vuelve en 5 minutos, así que prepárate para esperar. Las volantonas y la matriarca escupen {spell:3396}; las jóvenes lanzan {spell:403}. Alianza: vuela a {area:467} y dirígete al sur.",
		["The shells lie on the ground under the wyvern nests at {area:482} in western {zone:1441}, deeper into the gorge. Only nine exist and each returns 3 minutes after you pick it, so you will wait; some shell-like things there cannot be looted. Highperch Wyverns (level 28-31) guard them and sometimes come several at once: the guide waits for level 30 first."] = "Los caparazones están en el suelo debajo de los nidos de dracoleones en {area:482}, al oeste de {zone:1441}, más adentro de la garganta. Solo hay nueve y cada uno vuelve 3 minutos después de recogerlo, así que vas a esperar; algunas cosas parecidas a caparazones no se pueden saquear. Los Dracoleones Nido Alto (nivel 28-31) los custodian y a veces vienen varios a la vez: la guía espera primero al nivel 30.",
		["The {area:98}"] = "{area:98}",
		["The {quest:1708} grows on the sea floor just south of {area:150}, by the murloc huts and a wrecked boat: eight there and two south-east of the harbor, each back in 3 minutes, so you will wait for respawns to reach 20. The murlocs can net you underwater: watch your breath, and a {item:5996} removes the risk."] = "{quest:1708} crece en el fondo del mar justo al sur de {area:150}, junto a las chozas múrloc y un barco hundido: ocho ahí y dos al sureste del puerto, cada uno vuelve en 3 minutos, así que vas a esperar a que reaparezcan hasta llegar a 20. Los múrlocs pueden atraparte con una red bajo el agua: cuida tu aliento; un {item:5996} elimina el riesgo.",
		["You have one hour, and {npc:6166}'s {spell:8553} leaves you drunk for 8-10 minutes. Run north-west into the {area:98}, keeping close to the cliff wall to miss most gnoll packs, and go in as far as the first fork; then come back to {npc:6166} (from the ridge you can jump down into {area:69}). Dying and releasing your spirit fails the quest: abandon it and {npc:6166} gives it again."] = "Tienes una hora, y {spell:8553} de {npc:6166} te deja borracho de 8 a 10 minutos. Corre al noroeste hacia {area:98}, pegado a la pared del acantilado para evitar la mayoría de los grupos de gnolls, y entra hasta la primera bifurcación; luego vuelve con {npc:6166} (desde la cresta puedes saltar hasta {area:69}). Morir y liberar tu espíritu hace fracasar la misión: abandónala y {npc:6166} te la vuelve a dar.",
		["You need 50 fangs. The Leech Stalkers and Cave Stalkers (level 21-22) crawl in the middle of the {zone:1437}, north of {area:836}; every one drops a fang, but the Highland Horrors and Lurkers (elites, 28-29) roam the same ground, so the guide waits for level 28. The spiders poison; back in 5 minutes."] = "Necesitas 50 colmillos. Los Acechadores sanguijuela y Acechadores de cuevas (nivel 21-22) se arrastran por el centro de {zone:1437}, al norte de {area:836}; todos sueltan un colmillo, pero los Horrores de las Tierras Altas y los Merodeadores (élites, 28-29) rondan la misma zona, así que la guía espera al nivel 28. Las arañas envenenan; vuelven en 5 minutos.",
		["{item:6839}, from the young chimaeras"] = "{item:6839}, de las quimeras jóvenes",
		["{item:6840}, from the {npc:6167}"] = "{item:6840}, de la {npc:6167}",
		["{item:6841}, from Roogug"] = "{item:6841}, de Roogug",
		["{item:6845}, from {npc:6170}"] = "{item:6845}, de {npc:6170}",
		["{item:6848}, from {quest:1708}"] = "{item:6848}, de {quest:1708}",
		["{npc:1416} keeps the weapon shop in the north-west of the {object:28027}, a short walk from {npc:5413}. He wants 20 {quest:1705} and the {item:6845}."] = "{npc:1416} tiene la tienda de armas en el noroeste de {object:28027}, a poca distancia de {npc:5413}. Quiere 20 {quest:1705} y {item:6845}.",
		["{npc:5413} works in the Dwarven District of Stormwind. He takes the {item:6843} (lost it? abandon the quest and {npc:6166} gives a new one) and gives you {item:6970}, a shield."] = "{npc:5413} trabaja en el Distrito de los Enanos de Ventormenta. Recibe {item:6843} (¿lo perdiste? abandona la misión y {npc:6166} te da uno nuevo) y te da {item:6970}, un escudo.",
		["{npc:5413}'s next task, {quest:1701}, is a level 28 quest: its chimaeras and Roogug are level 28, so the guide waits for level 27 before you take it. Come back to {npc:5413} in the {object:28027} then; {item:6842} list what it needs."] = "La siguiente tarea de {npc:5413}, {quest:1701}, es una misión de nivel 28: sus quimeras y Roogug son de nivel 28, así que la guía espera al nivel 27 antes de que la tomes. Vuelve entonces con {npc:5413} en {object:28027}; {item:6842} dice lo que necesita.",
		["{npc:6170} (level 32, not elite) carries the {item:6845}, four kills in five; the guide waits for level 32 first. He walks between the inside and the mouth of the {area:2161} mine south-east of {area:42}, so wait at the entrance and pull him outside. He poisons and howls."] = "{npc:6170} (nivel 32, no élite) lleva la {item:6845}, en cuatro de cada cinco muertes; la guía espera primero al nivel 32. Camina entre el interior y la boca de la mina de {area:2161}, al sureste de {area:42}, así que espera en la entrada y atráelo afuera. Envenena y aúlla.",
		["{quest:1698} sits in the inn at {area:69}. His test is timed, and it is a level 22 quest, so the guide waits for level 21 before you take it: before that, clear the Redridge gnolls on the path to the {area:98} in the hills north-west of {area:69}, including the two on the rock by the cave mouth (climb it from its right side)."] = "{quest:1698} está en la posada de {area:69}. Su prueba tiene tiempo límite y es una misión de nivel 22, así que la guía espera al nivel 21 antes de que la aceptes: antes, despeja los gnolls Crestagrana del camino a {area:98}, en las colinas al noroeste de {area:69}, incluidos los dos de la roca junto a la entrada de la cueva (súbela por su lado derecho).",
		["{quest:1703} works on the south side of the {area:1660} in {zone:1457}. He wants 20 {quest:1710}."] = "{quest:1703} trabaja en el lado sur de {area:1660} en {zone:1457}. Quiere 20 {quest:1710}.",
		["{quest:1705}, from the Nightbane worgen"] = "{quest:1705}, de los huargos Pesadumbre",
} end)()
t.guides["forever/class/warrior/haggards-weapons"] = (function() return {
		["At 10, {npc:1229}, the warrior trainer in {area:131}, sends you to {quest:1679} in {zone:1455}. Any Alliance warrior may take one of the three roads, never two: in {zone:1453} at 10 anyway? {npc:5480}'s {quest:1638} is the quickest stance (one fight in a tavern), with a Haggard's weapon after it."] = "A nivel 10, {npc:1229}, el instructor de guerreros en {area:131}, te manda con {quest:1679} en {zone:1455}. Cualquier guerrero de la Alianza puede tomar uno de los tres caminos, nunca dos: ¿igual vas a estar en {zone:1453} a nivel 10? {quest:1638} de {npc:5480} es la actitud más rápida (una pelea en una taberna), con un arma de Haggard después.",
		["At 10, {npc:252377} stands with the trainers by {area:16638}'s west gate. A cultist, {npc:257196}, holds her family's shield at the {area:16629}."] = "A nivel 10, {npc:252377} está con los instructores junto a la puerta oeste de {area:16638}. Un sectario, {npc:257196}, tiene el escudo de su familia en {area:16629}.",
		["At 10, {npc:3598}, the warrior trainer in {area:186}, or {npc:2151}, who patrols the road west of {area:186}, sends you to {quest:1684} on the {area:1660} in {zone:1457}. Any Alliance warrior may take one of the three roads, never two: in {zone:1453} at 10 anyway? {npc:5480}'s {quest:1638} teaches the same stance after one fight in a tavern."] = "A nivel 10, {npc:3598}, la instructora de guerreros en {area:186}, o {npc:2151}, que patrulla el camino al oeste de {area:186}, te manda con {quest:1684} en {area:1660}, en {zone:1457}. Cualquier guerrero de la Alianza puede tomar uno de los tres caminos, nunca dos: ¿igual vas a estar en {zone:1453} a nivel 10? {quest:1638} de {npc:5480} enseña la misma actitud después de una pelea en una taberna.",
		["At 10, {npc:913}, the warrior trainer by the inn in {area:87}, sends you to {npc:6089} in {zone:1453}; {npc:5480}, the warrior trainer in {zone:1453}'s {object:2100}, offers it too."] = "A nivel 10, {npc:913}, la instructora de guerreros junto a la posada de {area:87}, te manda con {npc:6089} en {zone:1453}; {npc:5480}, la instructora de guerreros en {object:2100} de {zone:1453}, también la ofrece.",
		["Back on the {area:1660}: {npc:4088} hands you the {item:6812}; {npc:6142} works on the far, south side of the same terrace, easy to miss."] = "De vuelta en {area:1660}: {npc:4088} te da {item:6812}; {npc:6142} trabaja en el lado sur, al otro extremo de la misma terraza, fácil de pasar por alto.",
		["Back to {npc:252377} in {area:16638}. She teaches {spell:71} and gives you the {item:275290}, a shield to use it with. {npc:6090}'s road below still gives a weapon, once you reach {zone:1453}."] = "De vuelta con {npc:252377} en {area:16638}. Te enseña {spell:71} y te da {item:275290}, un escudo para usarla. El camino de {npc:6090}, más abajo, igual te da un arma cuando llegues a {zone:1453}.",
		["Back to {npc:294}"] = "Vuelve con {npc:294}",
		["Back to {npc:6114} for {spell:71}, then to {quest:1680} at the {object:32372} in the middle of {zone:1455}."] = "De vuelta con {npc:6114} para {spell:71}, y luego con {quest:1680} en {object:32372}, en el centro de {zone:1455}.",
		["Elunite under {area:442}"] = "Elunita debajo de {area:442}",
		["Head north-west from {area:16638} to the {area:16629}. {npc:257196} stands west of the shrine's approach, among the cult's Guardians, Spiritcallers and Blademasters: pull them one at a time before you take him. He drops the {item:263993}."] = "Ve al noroeste desde {area:16638} hasta {area:16629}. {npc:257196} está al oeste de la subida al santuario, entre los guardianes, clamaespíritus y maestros de espadas del culto: atráelos de a uno antes de enfrentarlo. Suelta {item:263993}.",
		["Take the boat from {area:702} to {area:442}. The wreck lies underwater just south of {area:442}'s southern pier, where the Menethil boat docks. Open Crates of Elunite on the sea floor around the wreck, by a huge sunken turtle, toward the beach and under the pier until you have eight; every crate holds ore and comes back in 3-5 minutes. The grey {npc:6133} (level 11) drifts around the middle of the wreck and always drops the medallion: target it when you see it, so you can find it after surfacing for air. Watch your breath; Threshers can join in."] = "Toma el barco de {area:702} a {area:442}. El naufragio está bajo el agua justo al sur del muelle sur de {area:442}, donde atraca el barco de Menethil. Abre las Cajas de elunita del fondo del mar alrededor del naufragio, junto a una enorme tortuga hundida, hacia la playa y debajo del muelle, hasta tener ocho; cada caja tiene mineral y vuelve en 3-5 minutos. La {npc:6133} gris (nivel 11) flota por el centro del naufragio y siempre suelta el medallón: selecciónala cuando la veas para poder encontrarla después de salir a respirar. Cuida tu aliento; los trilladores pueden unirse.",
		["from {npc:6093}"] = "de {npc:6093}",
		["{item:263993}, from {npc:257196}"] = "{item:263993}, de {npc:257196}",
		["{item:6782}, from {object:85563}"] = "{item:6782}, de {object:85563}",
		["{item:6800}, from {object:85562}"] = "{item:6800}, de {object:85562}",
		["{item:6808}, from Crates of Elunite"] = "{item:6808}, de las Cajas de elunita",
		["{item:6809}, from the {npc:6133}"] = "{item:6809}, de la {npc:6133}",
		["{npc:252377} in {area:16638}"] = "{npc:252377} en {area:16638}",
		["{npc:294}'s manor stands at the south-east edge of the {area:88} in eastern Elwynn, at the end of a short road that does not join the main one."] = "La mansión de {npc:294} está en el borde sureste de {area:88}, en el este de Elwynn, al final de un camino corto que no se une al principal.",
		["{npc:6089} and {npc:6090} are in the Pig and Whistle tavern in {object:2100}; {npc:6090} is the drunk at the far end of the bar. {npc:6090} (level 10) hits harder than his level, so start at full health; he gives up at low health instead of dying. If he wins, he disappears for about three minutes: keep the quest and talk to him again when he is back. A Dwarf, Gnome or Night Elf who took {quest:1638} from {npc:5480} instead of their home road is led through {zone:1453} from here."] = "{npc:6089} y {npc:6090} están en la taberna El Cerdo y el Silbato, en {object:2100}; {npc:6090} es el borracho al fondo de la barra. {npc:6090} (nivel 10) pega más fuerte de lo que dice su nivel, así que empieza con la salud al máximo; se rinde con poca salud en vez de morir. Si gana, desaparece unos tres minutos: quédate con la misión y vuelve a hablarle cuando regrese. Un enano, gnomo o elfo de la noche que tomó {quest:1638} de {npc:5480} en vez de su camino de origen sigue por {zone:1453} desde aquí.",
		["{npc:6093} (level 11) camps in the far south-east of Elwynn. A guard stands beside him and Defias and wolves are spread around the camp (now and then a rarer guard too): clear them one at a time, then kill Jack. He always drops {item:6783}; open {object:85563} in the crates by him for {item:6782}. Jack returns 3 minutes after dying, the box 1 minute after opening."] = "{npc:6093} (nivel 11) acampa en el extremo sureste de Elwynn. Un guardia está a su lado y hay Defias y lobos repartidos por el campamento (a veces también un guardia más raro): despéjalos de a uno y luego mata a Jack. Siempre suelta {item:6783}; abre {object:85563} entre las cajas a su lado para conseguir {item:6782}. Jack vuelve 3 minutos después de morir, y la caja 1 minuto después de abrirla.",
		["{quest:1678} (level 11, a lone troll) waits at his hut on a hill south of {area:135}, near the mountains at the top of a short ramp, with no other trolls around; the hut at the front of {area:135} is the wrong one. He fights in {spell:71} and sunders your armor; {spell:6343} slows him. His head always drops; he returns about 8 minutes after dying."] = "{quest:1678} (nivel 11, un trol solitario) espera en su choza en una colina al sur de {area:135}, cerca de las montañas, al final de una rampa corta, sin otros trols alrededor; la choza del frente de {area:135} no es. Pelea en {spell:71} y te hiende la armadura; {spell:6343} lo ralentiza. Su cabeza siempre cae; vuelve unos 8 minutos después de morir.",
		["{quest:1679} in {zone:1455}"] = "{quest:1679} en {zone:1455}",
		["{quest:1679} stands in the {object:32390} in the {object:32359}."] = "{quest:1679} está en {object:32390}, en {object:32359}.",
		["{quest:1681} lies in eastern {zone:1426}, below {area:212} on its south side. Dark Iron Spies (level 8-10) stand along the way, far enough apart to pull one at a time. {object:85562} is in the basement of the southernmost house; {npc:6124} (level 11) stands by it and charges on sight. The box always holds the ore and refills 15 minutes after opening."] = "{quest:1681} está en el este de {zone:1426}, debajo de {area:212} por su lado sur. Hay espías Hierro Negro (nivel 8-10) a lo largo del camino, lo bastante separados para atraerlos de a uno. {object:85562} está en el sótano de la casa más al sur; {npc:6124} (nivel 11) está a su lado y carga en cuanto te ve. La caja siempre tiene el mineral y se rellena 15 minutos después de abrirla.",
		["{quest:1683} (level 10, a satyr) stands at a hidden moonwell up a hillside west of {area:186}. The trail is hard to spot: it starts behind a Gnarlpine camp and climbs in switchbacks lined with lamp posts. The furbolgs below can come in groups. His horn always drops; he returns 5 minutes after dying."] = "{quest:1683} (nivel 10, un sátiro) está en un pozo de luna escondido, subiendo una ladera al oeste de {area:186}. El sendero cuesta verlo: empieza detrás de un campamento Tuercepino y sube en zigzag con faroles a los lados. Los fúrbolgs de abajo pueden venir en grupo. Su cuerno siempre cae; vuelve 5 minutos después de morir.",
		["{quest:1684} in {zone:1457}"] = "{quest:1684} en {zone:1457}",
		["{quest:1684} stands on the {area:1660}."] = "{quest:1684} está en {area:1660}.",
		["{spell:71} and a Weapon (Alliance)"] = "{spell:71} y un arma (Alianza)",
		["{spell:71} at 10 and a one-hand weapon of your choice from {zone:1453}, {zone:1455} or {zone:1457}."] = "{spell:71} a nivel 10 y un arma de una mano a elección de {zone:1453}, {zone:1455} o {zone:1457}.",
} end)()
t.guides["forever/class/warrior/heirloom-weapon"] = (function() return {
		["At 10, {npc:2131}, the warrior trainer inside the inn of {area:159}, sends you to {npc:1496} by the graveyard on {area:159}'s west edge. This road and {npc:5810}'s exclude each other: drop {quest:1505} or {quest:1498} from your log if you hold one."] = "A nivel 10, {npc:2131}, el instructor de guerreros dentro de la posada de {area:159}, te manda con {npc:1496}, junto al cementerio del borde oeste de {area:159}. Este camino y el de {npc:5810} se excluyen: quita {quest:1505} o {quest:1498} de tu registro si tienes alguna.",
		["At 10, {npc:252377} stands with the trainers by {area:16638}'s west gate. A cultist, {npc:257196}, holds her family's shield at the {area:16629}."] = "A nivel 10, {npc:252377} está con los instructores junto a la puerta oeste de {area:16638}. Un sectario, {npc:257196}, tiene el escudo de su familia en {area:16629}.",
		["At 10, {npc:3063}, the warrior trainer of {area:222}, sends you to {npc:5810} in the {zone:1413}. {npc:3041} in {zone:1456} offers it too."] = "A nivel 10, {npc:3063}, el instructor de guerreros de {area:222}, te manda con {npc:5810} en {zone:1413}. {npc:3041}, en {zone:1456}, también la ofrece.",
		["At 10, {npc:3169}, the warrior trainer in the barracks of {area:362}, sends you to {npc:5810} in the {zone:1413}. Sorek in {zone:1454}'s {object:172958} offers it too. Any Horde warrior may take one of the two roads, never both: heading to {zone:1420} at 10 anyway? {npc:2131} in {area:159}'s inn offers the other: one fight by {area:159}'s graveyard for the same stance, then the Agamand crypt for an heirloom weapon."] = "A nivel 10, {npc:3169}, el instructor de guerreros en el cuartel de {area:362}, te manda con {npc:5810} en {zone:1413}. Sorek, en {object:172958} de {zone:1454}, también la ofrece. Cualquier guerrero de la Horda puede tomar uno de los dos caminos, nunca ambos: ¿igual vas a ir a {zone:1420} a nivel 10? {npc:2131}, en la posada de {area:159}, ofrece el otro: una pelea junto al cementerio de {area:159} para la misma actitud, y después la cripta Agamand para un arma reliquia.",
		["Back to {npc:1500}"] = "Regresa con {npc:1500}",
		["Back to {npc:252377} in {area:16638}. She teaches {spell:71} and gives you the {item:275290}, a shield to use it with. {npc:5810}'s road below still gives a weapon later, once you reach Kalimdor."] = "De vuelta con {npc:252377} en {area:16638}. Te enseña {spell:71} y te da {item:275290}, un escudo para usarla. El camino de {npc:5810}, más abajo, igual te da un arma más adelante, cuando llegues a Kalimdor.",
		["Back to {npc:5810} under his tree west of {area:379}."] = "De vuelta con {npc:5810}, bajo su árbol al oeste de {area:379}.",
		["Dillinger stands by the graveyard on {area:159}'s west edge. An Orc, Troll, Tauren or Skyborne who took {quest:1818} from {npc:2131} instead of {npc:5810}'s road is led through {area:159} from here."] = "Dillinger está junto al cementerio del borde oeste de {area:159}. Un orco, trol, tauren o Skyborne que tomó {quest:1818} de {npc:2131} en vez del camino de {npc:5810} sigue por {area:159} desde aquí.",
		["Head north-west from {area:16638} to the {area:16629}. {npc:257196} stands west of the shrine's approach, among the cult's Guardians, Spiritcallers and Blademasters: pull them one at a time before you take him. He drops the {item:263993}."] = "Ve al noroeste desde {area:16638} hasta {area:16629}. {npc:257196} está al oeste de la subida al santuario, entre los guardianes, clamaespíritus y maestros de espadas del culto: atráelos de a uno antes de enfrentarlo. Suelta {item:263993}.",
		["Singed Scales in {area:369}"] = "Escamas chamuscadas en {area:369}",
		["The four Agamand Weapon Racks are inside the {area:158} at the north end of {area:157}, north of {area:159}, one rack per room: one in the lowest room, two in the pair of rooms up the stairs, one in the room above those. The axe rack stands in a dark corner. The crypt's undead come in packs of three or more and return quickly; the ones in the top room are not linked. The axe, dagger and mace racks take 15 minutes to refill after someone loots them."] = "Los cuatro Armeros Agamand están dentro de {area:158}, en el extremo norte de {area:157}, al norte de {area:159}, uno por sala: uno en la sala más baja, dos en el par de salas subiendo la escalera y uno en la sala de arriba de esas. El armero del hacha está en un rincón oscuro. Los no-muertos de la cripta vienen en grupos de tres o más y reaparecen rápido; los de la sala de arriba no están vinculados. Los armeros del hacha, la daga y la maza tardan 15 minutos en rellenarse después de que alguien los saquea.",
		["The {area:158}"] = "{area:158}",
		["The {object:58369} stands by a broken wagon in the Razormane camp north-west of {npc:5878}, north-east of the Crossroads. Two Razormanes guard it and their hunters pull more quilboar: clear them one at a time, then open the chest (it refills within seconds, so a friend can loot it too)."] = "{object:58369} está junto a una carreta rota en el campamento Crines de Acero al noroeste de {npc:5878}, al noreste del Cruce. Dos Crines de Acero la custodian y sus cazadores atraen más jabaespines: despéjalos de a uno y luego abre el cofre (se rellena en segundos, así que un amigo también puede saquearlo).",
		["You need five Singed Scales. Thunder Lizards (level 9-10) and Lightning Hides (10-11) live down in the {area:369} crevasse in north-west {zone:1411}, south of {zone:1454}: from the {zone:1413} bridge turn left and follow the river north into it. Both drop a scale about four kills in five; both cast {spell:5401}."] = "Necesitas cinco Escamas chamuscadas. Los truenagartos (nivel 9-10) y los pielrrelámpago (10-11) viven abajo, en la grieta de {area:369}, en el noroeste de {zone:1411}, al sur de {zone:1454}: desde el puente de {zone:1413}, dobla a la izquierda y sigue el río al norte hasta entrar. Ambos sueltan una escama más o menos cuatro de cada cinco veces; ambos lanzan {spell:5401}.",
		["{item:263993}, from {npc:257196}"] = "{item:263993}, de {npc:257196}",
		["{item:6486}, from the lizards"] = "{item:6486}, de los lagartos",
		["{item:6534}, from the {object:58369}"] = "{item:6534}, de {object:58369}",
		["{npc:1500} is in the {area:2119}, the inn on {area:159}'s east side."] = "{npc:1500} está en {area:2119}, la posada del lado este de {area:159}.",
		["{npc:252377} in {area:16638}"] = "{npc:252377} en {area:16638}",
		["{npc:5810} at {area:379}"] = "{npc:5810} en {area:379}",
		["{npc:5810} is easy to miss: he stands under a small canopy by a large tree just west of {area:379}, below the road's south side, with the post in sight to his east. Going straight south from the post does not lead to him. From {zone:1411} cross the bridge west; from {zone:1412} head north past the Crossroads."] = "{npc:5810} es fácil de pasar por alto: está bajo un pequeño toldo junto a un árbol grande, justo al oeste de {area:379}, debajo del lado sur del camino, con el puesto a la vista hacia el este. Ir derecho al sur desde el puesto no lleva hasta él. Desde {zone:1411}, cruza el puente hacia el oeste; desde {zone:1412}, ve al norte pasando el Cruce.",
		["{npc:5878}'s hut sits on top of {area:1699}, east of the Crossroads. Most slopes are too steep: climb the broad ridge on the north or east side."] = "La choza de {npc:5878} está en lo alto de {area:1699}, al este del Cruce. La mayoría de las laderas son demasiado empinadas: sube por la cresta ancha del lado norte o este.",
		["{npc:6390} sleeps in the mausoleum in the graveyard just north of Dillinger. To wake him, click the flat skull plaque on the ground, left of the path to the mausoleum door; the seal lifts and {npc:6390} (level 11, not elite) walks out. Start at full health."] = "{npc:6390} duerme en el mausoleo del cementerio, justo al norte de Dillinger. Para despertarlo, haz clic en la placa plana con forma de cráneo en el suelo, a la izquierda del camino a la puerta del mausoleo; el sello se levanta y {npc:6390} (nivel 11, no élite) sale. Empieza con la salud al máximo.",
		["{spell:71} and a Weapon (Horde)"] = "{spell:71} y un arma (Horda)",
		["{spell:71} at 10 and a one-hand weapon of your choice: {npc:5810}'s road, {area:159}'s crypt, or the Skybreaker shield."] = "{spell:71} a nivel 10 y un arma de una mano a elección: el camino de {npc:5810}, la cripta de {area:159} o el escudo Rompecielos.",
} end)()
t.guides["forever/class/warrior/quelserrar"] = (function() return {
		["A tank sword at 60: a {area:2577} book, then {npc:10184}'s breath tempers the blade (the sword is not in Forever's items yet)."] = "Una espada de tanque a nivel 60: un libro de {area:2577}, y luego el aliento de {npc:10184} templa la hoja (la espada todavía no está entre los objetos de Forever).",
		["Back to {npc:14368} in the Athenaeum of Dire Maul West: through the West door with the {item:18249} again, and a group to reach the library."] = "De vuelta con {npc:14368} en el Athenaeum de La Masacre Oeste: otra vez por la puerta del Oeste con {item:18249}, y con un grupo para llegar a la biblioteca.",
		["Kill {npc:10184}, then target her corpse and use the {item:18488} on it before the 20 minutes run out. It becomes the {item:18492}, with no time limit."] = "Mata a {npc:10184}, luego selecciona su cadáver y usa {item:18488} sobre él antes de que pasen los 20 minutos. Se convierte en {item:18492}, sin límite de tiempo.",
		["Shen'dralar reputation"] = "Reputación con Shen'dralar",
		["The book is a rare random drop from the bosses of all three {area:2577} wings (Alzzin, Hydrospawn and the rest of the East, Tendris, Illyanna, Kalendris, {npc:11496} and the West, {npc:11501} and the North's guards) and very rarely from the tribute chest; it can be traded, so the auction house may have one. {area:2577} is a five-player dungeon in the ruins of central {zone:1444}: needs a group of five. Right-click the book to start the quest; it stays in your bags."] = "El libro es un botín raro al azar de los jefes de las tres alas de {area:2577} (Alzzin, Hidroengendro y el resto del Este; Tendris, Illyanna, Kalendris, {npc:11496} y el Oeste; {npc:11501} y los guardias del Norte) y muy rara vez del cofre del tributo; se puede comerciar, así que puede haber uno en la casa de subastas. {area:2577} es una mazmorra de cinco jugadores en las ruinas del centro de {zone:1444}: necesita un grupo de cinco. Haz clic derecho en el libro para empezar la misión; se queda en tus bolsas.",
		["click the heated blade on the ground"] = "haz clic en la hoja caliente en el suelo",
		["from {item:18401}"] = "de {item:18401}",
		["{item:18488}, on her corpse"] = "{item:18488}, sobre su cadáver",
		["{item:18489}: plant it in her breath"] = "{item:18489}: clávala en su aliento",
		["{npc:10184} is the 40-player raid boss of {area:2159}, a cave in the {area:511} of southern {zone:1445}; she returns once a week. Tell the raid first. Late in the fight (around 10-15% health, when she has landed again) use the {item:18489} to plant it in the path of her fire breath, usually by the main tank's feet. When her breath has heated it, click the {object:179562} to take the {item:18488}: from then you have 20 minutes. Her breath can kill you while you plant or pick up the blade; if you die and nobody brings you back before she dies, wait for next week. Planted in the wrong place? Abandon the quest, take it again from Lydros for a new blade."] = "{npc:10184} es la jefa de banda de 40 jugadores de {area:2159}, una cueva en {area:511}, en el sur de {zone:1445}; reaparece una vez por semana. Avísale primero a la banda. Al final de la pelea (alrededor del 10-15 % de salud, cuando ya volvió a aterrizar) usa {item:18489} para clavarla en el camino de su aliento de fuego, normalmente a los pies del tanque principal. Cuando su aliento la haya calentado, haz clic en {object:179562} para tomar {item:18488}: desde ahí tienes 20 minutos. Su aliento puede matarte mientras clavas o recoges la hoja; si mueres y nadie te revive antes de que ella muera, espera a la semana siguiente. ¿La clavaste en el lugar equivocado? Abandona la misión y vuelve a tomarla con Lydros para una hoja nueva.",
		["{npc:10184}'s breath"] = "El aliento de {npc:10184}",
		["{npc:10184}'s corpse"] = "El cadáver de {npc:10184}",
		["{npc:14368} stands in the Athenaeum, the library at the far end of Dire Maul West, past the Court of the Highborne and the Prison of Immol'thar. The West door needs the {item:18249}, which Pusillin drops in Dire Maul East (he runs; chase him), or a rogue to pick it. Clearing to the library needs your group of five. He takes the book, hands you {item:18513} to give straight back, then the {item:18489}. Keep that blade: lose it, and you must abandon the quest and take it again."] = "{npc:14368} está en el Athenaeum, la biblioteca al fondo de La Masacre Oeste, pasando la Corte de los Altonatos y la Prisión de Immol'thar. La puerta del Oeste necesita {item:18249}, que suelta Pusillin en La Masacre Este (huye; persíguelo), o un pícaro que la abra. Despejar hasta la biblioteca necesita tu grupo de cinco. Recibe el libro, te da {item:18513} para que se lo devuelvas enseguida y luego {item:18489}. Guarda esa hoja: si la pierdes, tienes que abandonar la misión y volver a tomarla.",
		["{npc:14368}, in the Athenaeum"] = "{npc:14368}, en el Athenaeum",
		["{npc:14368}: hand back the Dull and Flat Elven Blade"] = "{npc:14368}: devuélvele la hoja élfica roma y plana",
} end)()
t.guides["forever/class/warrior/voodoo-feathers"] = (function() return {
		["At 50, {npc:3041}, the warrior trainer of {zone:1456}, sends you to the {npc:7572} in the {zone:1435}."] = "A nivel 50, {npc:3041}, el instructor de guerreros de {zone:1456}, te envía con {npc:7572} en {zone:1435}.",
		["At 50, {npc:3354} in the {object:172958} sends you to the {npc:7572} in the {zone:1435}."] = "A nivel 50, {npc:3354}, en {object:172958}, te envía con {npc:7572} en {zone:1435}.",
		["At 50, {npc:4593}, a warrior trainer of the {zone:1458}, sends you to the {npc:7572} in the {zone:1435}."] = "A nivel 50, {npc:4593}, un instructor de guerreros de {zone:1458}, te envía con {npc:7572} en {zone:1435}.",
		["At 50, {npc:5113}, the warrior trainer of {zone:1455}, sends you to the {npc:7572} in the {zone:1435}."] = "A nivel 50, {npc:5113}, el instructor de guerreros de {zone:1455}, te envía con {npc:7572} en {zone:1435}.",
		["At 50, {npc:5479}, beside {npc:5480} in the warrior trainers' building of {object:2100}, sends you to the {npc:7572} in the {zone:1435}."] = "A nivel 50, {npc:5479}, junto a {npc:5480} en el edificio de los instructores de guerreros de {object:2100}, te manda con el {npc:7572} en {zone:1435}.",
		["At 50, {npc:7315}, the warrior trainer of {zone:1457}, sends you to the {npc:7572} in the {zone:1435}."] = "A nivel 50, {npc:7315}, el instructor de guerreros de {zone:1457}, te envía con {npc:7572} en {zone:1435}.",
		["Back to the {npc:10996}"] = "De vuelta con {npc:10996}",
		["Experience"] = "Experiencia",
		["Experience at 50, ending in the {area:1417}; Classic's item choice may be gone on Forever."] = "Experiencia a nivel 50, terminando en {area:1417}; puede que en Forever ya no esté la elección de objeto de Classic.",
		["Helboars"] = "Jabinfernos",
		["In Classic the {npc:10996} let you choose the {item:20130}, the {item:20521} or the {item:20517} here. Forever's change notes say the choice is gone, though its quest page still lists three unnamed rewards: look at the reward window before you hand in."] = "En Classic, el {npc:10996} te dejaba elegir aquí {item:20130}, {item:20521} o {item:20517}. Las notas de cambios de Forever dicen que la elección ya no está, aunque su página de misión todavía muestra tres recompensas sin nombre: mira la ventana de recompensas antes de entregar.",
		["Seven Helboars (level 52-53, not elite) roam the north-west of the {zone:1419}, south-west of {area:1438}; some stand near the ogres on the mountainside by the road. They charge from 25 yards and cast {spell:8349}. They share spawn points with the Felbeasts and scorpids: if no boars are around, kill those and boars may appear instead. Back in 5 minutes."] = "Siete jabalíes infernales (nivel 52-53, no élite) recorren el noroeste de {zone:1419}, al suroeste de {area:1438}; algunos están cerca de los ogros en la ladera junto al camino. Cargan desde 25 m y lanzan {spell:8349}. Comparten puntos de aparición con las bestias viles y los escórpidos: si no hay jabalíes, mata a esos y pueden aparecer jabalíes en su lugar. Vuelven en 5 minutos.",
		["Shadowsworn camps"] = "Campamentos Sombraída",
		["The Shadowsworn camp around the mouth of the {area:1440} cave, south of {area:1438} on the way to the {area:72}. You need 20 Adepts (level 52-53, they leech blood and heal hurt allies: kill them first), 10 Cultists (51-52, they throw from range, so close in) and 20 Thugs (52-53, Thrash and {spell:1766}). Thugs can run short before the others: kill every Shadowsworn you pass."] = "El campamento de los Juramentados de las Sombras alrededor de la entrada de la cueva de {area:1440}, al sur de {area:1438}, de camino a {area:72}. Necesitas 20 adeptos (nivel 52-53, drenan sangre y curan a los aliados heridos: mátalos primero), 10 sectarios (51-52, atacan a distancia, así que acércate) y 20 matones (52-53, Vapulear y {spell:1766}). Los matones pueden escasear antes que los demás: mata a todos los Juramentados de las Sombras que encuentres.",
		["The {area:1417}"] = "{area:1417}",
		["The {npc:7572}"] = "{npc:7572}",
		["The {npc:7572}, a ghost, stands in the south-west of the {zone:1435}, at the pass into the {zone:1419}, a short ride south-west of {area:75}. Horde: fly to {area:75}. Alliance: fly to {area:1438} in the {zone:1419} and ride north through the pass. High-level beasts roam the way."] = "El {npc:7572}, un fantasma, está en el suroeste de {zone:1435}, en el paso hacia {zone:1419}, a poca distancia al suroeste de {area:75}. Horda: vuela a {area:75}. Alianza: vuela a {area:1438} en {zone:1419} y ve al norte por el paso. En el camino rondan bestias de nivel alto.",
		["You need two feathers of each colour from the six Atal'ai troll guardians (level 51-52, elite) on the {area:1417}'s balcony, who hold the barrier in front of {npc:5710}: Gasher and {npc:5716} drop the amber, Hukku and Mijan the blue, Zolo and Loro the green, every kill; each player on the quest loots their own set. The {area:1417} is a five-player dungeon: needs a group of five. It lies in the {area:74} in eastern {zone:1435}: climb the temple's outer steps, dive into the flooded hall and follow the stairs down to the entrance. Inside, reach the balcony by the stairs or the path on the right, not the spiral stairs. Hukku calls guardians and casts {spell:9081} and {spell:8282}; Mijan heals the others ({spell:139}, a {npc:3560}, {spell:331} below half health): kill her or her ward fast; {npc:5716} cleaves."] = "Necesitas dos plumas de cada color de los seis guardianes trol Atal'ai (nivel 51-52, élite) del balcón de {area:1417}, que mantienen la barrera frente a {npc:5710}: Gasher y {npc:5716} sueltan la ámbar, Hukku y Mijan la azul, Zolo y Loro la verde, en cada muerte; cada jugador con la misión saquea su propio juego. {area:1417} es una mazmorra de cinco jugadores: necesita un grupo de cinco. Está en {area:74}, en el este de {zone:1435}: sube los escalones exteriores del templo, zambúllete en la sala inundada y sigue la escalera hacia abajo hasta la entrada. Adentro, llega al balcón por la escalera o el camino de la derecha, no por la escalera de caracol. Hukku llama guardianes y lanza {spell:9081} y {spell:8282}; Mijan cura a los demás ({spell:139}, un {npc:3560}, {spell:331} por debajo de la mitad de salud): mátala a ella o a su guarda rápido; {npc:5716} da tajos.",
		["{item:20606}, from Gasher and {npc:5716}"] = "{item:20606}, de Gasher y {npc:5716}",
		["{item:20607}, from Hukku and Mijan"] = "{item:20607}, de Hukku y Mijan",
		["{item:20608}, from Zolo and Loro"] = "{item:20608}, de Zolo y Loro",
} end)()
t.guides["forever/class/warrior/whirlwind-weapon"] = (function() return {
		["At 30, {npc:3041}, the warrior trainer of {zone:1456}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "A nivel 30, {npc:3041}, el instructor de guerreros de {zone:1456}, te envía con {npc:6236} en {area:720} en {zone:1413}.",
		["At 30, {npc:3354} in the {object:172958} sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "A nivel 30, {npc:3354}, en {object:172958}, te envía con {npc:6236} en {area:720} en {zone:1413}.",
		["At 30, {npc:4595}, a warrior trainer of the {zone:1458}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "A nivel 30, {npc:4595}, un instructor de guerreros de {zone:1458}, te envía con {npc:6236} en {area:720} en {zone:1413}.",
		["At 30, {npc:5113}, the warrior trainer of {zone:1455}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "A nivel 30, {npc:5113}, el instructor de guerreros de {zone:1455}, te envía con {npc:6236} en {area:720} en {zone:1413}.",
		["At 30, {npc:5479}, beside {npc:5480} in the warrior trainers' building of {object:2100}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "A nivel 30, {npc:5479}, junto a {npc:5480} en el edificio de los instructores de guerreros de {object:2100}, te manda con {npc:6236} en {area:720}, en {zone:1413}.",
		["Back to {npc:6176}. Accepting {quest:1713} starts his ritual, and {quest:1712} appears just north of his camp. {quest:1712} is elite (level 40): grouping up is encouraged; it needs a group of two or three around level 40. It deals nature damage (a {item:6052} soaks it), whirls, and {spell:10101} throws you far while it heals itself as you run back: fight with your back to a slope or rock. The {item:6894} always drops. If the fight fails {npc:6176} stops answering: abandon {quest:1713} and take it again for a new summon; the earlier items are not needed again."] = "De vuelta con {npc:6176}. Aceptar {quest:1713} empieza su ritual, y {quest:1712} aparece justo al norte de su campamento. {quest:1712} es élite (nivel 40): se recomienda agruparse; necesita un grupo de dos o tres cerca del nivel 40. Hace daño de naturaleza (un {item:6052} lo absorbe), gira, y {spell:10101} te lanza lejos mientras se cura mientras vuelves corriendo: pelea de espaldas a una pendiente o roca. {item:6894} siempre cae. Si la pelea falla, {npc:6176} deja de responder: abandona {quest:1713} y vuelve a tomarla para una nueva invocación; los objetos anteriores no hacen falta de nuevo.",
		["Bloodscalp Tusks"] = "Colmillos Sangrapellejo",
		["Click {object:89931} with the 24 charms in your bags and {quest:1712} in your log. Its window asks for the charms straight away, with nothing to accept: Continue, then Complete, and it hands you the {quest:1714}."] = "Haz clic en {object:89931} con los 24 talismanes en tus bolsas y {quest:1712} en tu registro. Su ventana pide los talismanes directamente, sin nada que aceptar: Continuar y luego Completar, y te entrega la {quest:1714}.",
		["Fly to {area:392} and go south along the {area:391}. {area:720} lies offshore to the south-east: wade across on the shallow sand bar; off it the water is deep and fatigue sets in. {npc:6236} stands by the arena."] = "Vuela a {area:392} y ve al sur por {area:391}. {area:720} está frente a la costa, al sureste: cruza a pie por el banco de arena poco profundo; fuera de él el agua es profunda y aparece la fatiga. {npc:6236} está junto a la arena.",
		["The cauldron wants 8 of each charm, 24 in all, and each exile drops its charm about one kill in three, so plan on some 70 kills. All are level 38-39, not elite: the guide waits for level 38 first, and a friend helps. Burning Exiles (fire) by the {area:334} in the north-west, north-west of {area:320}; Thundering Exiles (air) by the {area:336} south-east of {area:320}, casting {spell:403} from 40 yards; Cresting Exiles (water) by the {area:333}, north-west of {area:321}, with {spell:122}. About a dozen of each, back in under 7 minutes. The charms trade and sell on the auction house; using one banishes another kind of exile for a while (Burning on Thundering, Thundering on Cresting, Cresting on Burning)."] = "El caldero pide 8 talismanes de cada tipo, 24 en total, y cada exiliado suelta su talismán aproximadamente una de cada tres veces, así que cuenta con unas 70 muertes. Todos son de nivel 38-39, no élites: la guía espera primero al nivel 38, y un amigo ayuda. Exiliados ardientes (fuego) junto a {area:334}, en el noroeste, al noroeste de {area:320}; Exiliados tronadores (aire) junto a {area:336}, al sureste de {area:320}, que lanzan {spell:403} desde 40 metros; Éxilus coronadores (agua) junto a {area:333}, al noroeste de {area:321}, con {spell:122}. Hay más o menos una docena de cada uno, y reaparecen en menos de 7 minutos. Los talismanes se pueden intercambiar y vender en la casa de subastas; usar uno destierra por un rato a otro tipo de exiliado (el ardiente al tronador, el tronador al coronador, el coronador al ardiente).",
		["The exiles of Arathi"] = "Los exiliados de Arathi",
		["You have 10 minutes. Eat and drink to full, then step onto the grate in the middle of the crowd: {npc:6248} announces the challengers (level 26-27), who come one at a time, 15-20 seconds apart, and only while you stand near the grate. After each kill, step off the grate to eat or bandage; step back on when ready for the next. Six of them, then {npc:6238} (level 33, not elite) walks out; he stays neutral until you attack him, so bandage or eat first. Do not use {spell:1160}: it sends the challengers running and more of them pile in at once. If nothing starts, step off and on the grate again, or abandon the quest and take it again."] = "Tienes 10 minutos. Come y bebe hasta llenarte y luego súbete a la rejilla en medio de la multitud: {npc:6248} anuncia a los retadores (nivel 26-27), que llegan de a uno, con 15-20 segundos entre cada uno, y solo mientras estés cerca de la rejilla. Después de cada muerte, bájate de la rejilla para comer o vendarte; vuelve a subir cuando estés listo para el siguiente. Son seis, y luego sale {npc:6238} (nivel 33, no élite); se queda neutral hasta que lo atacas, así que véndate o come antes. No uses {spell:1160}: hace huir a los retadores y entran más a la vez. Si no empieza nada, bájate y vuelve a subir a la rejilla, o abandona la misión y vuelve a tomarla.",
		["You need 30 tusks. Every Bloodscalp troll (level 33-37) of north-west Stranglethorn drops one about one kill in three, so plan on some 80 kills: the camps and ruins north and north-west of {area:117} and around the {area:123} on the coast. They enrage below 30% health and the Warriors disarm; back in 5 minutes."] = "Necesitas 30 colmillos. Cualquier trol Sangrapellejo (nivel 33-37) del noroeste de Tuercespina suelta uno más o menos una vez de cada tres, así que cuenta con unas 80 muertes: los campamentos y ruinas al norte y noroeste de {area:117} y alrededor de {area:123}, en la costa. Se enfurecen por debajo del 30 % de salud y los guerreros desarman; vuelven en 5 minutos.",
		["You need 8 {item:3357}. Herbalists pick it by rivers and lakes in the {zone:1437}, {zone:1417} and {zone:1434}; otherwise the auction house. Herb vendors keep only one at a time and restock every two hours: {npc:1302} and {npc:1313} in {zone:1453}, {npc:844} on the road in eastern Elwynn, Jeeda at {area:460} in Stonetalon, Montarr in {zone:1441}. Kurzen Medicine Men in northern Stranglethorn drop one about one kill in twelve."] = "Necesitas 8 {item:3357}. Los herboristas la recogen junto a ríos y lagos en {zone:1437}, {zone:1417} y {zone:1434}; si no, la casa de subastas. Los vendedores de hierbas tienen solo una a la vez y reponen cada dos horas: {npc:1302} y {npc:1313} en {zone:1453}, {npc:844} en el camino del este de Elwynn, Jeeda en {area:460}, en Sierra Espolón, y Montarr en {zone:1441}. Los curanderos Kurzen del norte de Tuercespina sueltan una más o menos una vez de cada doce.",
		["{item:4479}, from Burning Exiles"] = "{item:4479}, de los exiliados ardientes",
		["{item:4480}, from Thundering Exiles"] = "{item:4480}, de los exiliados atronadores",
		["{item:4481}, from Cresting Exiles"] = "{item:4481}, de los exiliados de cresta",
		["{item:6894}, from {quest:1712}"] = "{item:6894}, de {quest:1712}",
		["{npc:6176} camps by ruins on the east bank of the river that runs past {area:272}, a short walk north-east of the town, just over the border in {zone:1416}; his cauldron stands beside him. Horde: fly to {area:272}. Alliance: fly to {area:271} and go north along the river; {area:272}'s guards are level 42 elites, so keep away from the town. Accepting {quest:1712} gives you {item:6929}, the list of what he needs: 8 {item:3357}, 30 Bloodscalp Tusks and the {item:6851} from his cauldron. The cauldron's {item:6851} is not a quest you take: it never shows in your quest log. Come back with its charms and hand them in at the cauldron."] = "{npc:6176} acampa junto a unas ruinas en la orilla este del río que pasa por {area:272}, a una caminata corta al noreste del pueblo, justo pasando la frontera de {zone:1416}; su caldero está a su lado. Horda: vuela a {area:272}. Alianza: vuela a {area:271} y ve al norte siguiendo el río; los guardias de {area:272} son élites de nivel 42, así que mantente lejos del pueblo. Al tomar {quest:1712} recibes {item:6929}, la lista de lo que necesita: 8 {item:3357}, 30 Colmillos Sangrapellejo y la {item:6851} de su caldero. La {item:6851} del caldero no es una misión que se tome: nunca aparece en tu registro de misiones. Regresa con sus talismanes y entrégalos en el caldero.",
		["{npc:6176}: {item:6975}, Sword or Warhammer"] = "{npc:6176}: {item:6975}, espada o martillo de guerra",
		["{quest:1714}, from the cauldron by {npc:6176}"] = "{quest:1714}, del caldero junto a {npc:6176}",
		["{spell:2458} at 30 and a {spell:1680} axe, sword or warhammer at 40."] = "{spell:2458} a nivel 30 y un hacha, espada o martillo de guerra de {spell:1680} a nivel 40.",
} end)()
t.guides["forever/collectibles/mounts/alliance/black-war-mounts"] = (function() return {
		["Black War Mounts"] = "Monturas de guerra negras",
		["PvP rank 11"] = "Rango JcJ 11",
		["{item:18243}, {spell:10907}, 100g"] = "{item:18243}, {spell:10907}, 100 de oro",
		["{item:18244}, {spell:826}, 100g"] = "{item:18244}, {spell:826}, 100 de oro",
		["{npc:12783} sells the mounts in {zone:1453}'s {object:2100} by the {area:2918}, beside the other honor quartermasters. The Forever client lists each at 100g. Each one also needs its kind's riding: Humans ride the steed, Night Elves the tiger, Gnomes the battlestrider, Dwarves the ram. A Skyborne, or anyone choosing another race's mount, first needs that riding from its trainer (Exalted with the race's city)."] = "{npc:12783} vende las monturas en {object:2100} de {zone:1453}, junto a {area:2918}, al lado de los otros intendentes de honor. El cliente de Forever las lista a 100 de oro cada una. Cada una también pide la equitación de su tipo: los humanos montan el corcel, los elfos de la noche el tigre, los gnomos el zancudo de batalla y los enanos el carnero. Un Cielonato, o quien elija la montura de otra raza, primero necesita esa equitación de su instructor (Exaltado con la ciudad de esa raza).",
		["{npc:14332}, {spell:824}, 100g"] = "{npc:14332}, {spell:824}, 100 de oro",
		["{spell:1299382} come from battlegrounds, PvP quests and the season's weekly tasks, with a weekly cap; Commander (rank 11) unlocks the Black War mounts. The Player vs. Player tab of your character pane shows your rank and what you may buy. {skill:762} one at full speed needs Journeyman {skill:762} (level 60). Polestar cannot read your rank, so this step waits for level 60 and Journeyman {skill:762}."] = "Los {spell:1299382} salen de los campos de batalla, las misiones JcJ y las tareas semanales de la temporada, con un tope semanal; Comandante (rango 11) desbloquea las monturas de guerra negras. La pestaña Jugador contra Jugador del panel de personaje muestra tu rango y lo que puedes comprar. Usar {skill:762} con una a toda velocidad requiere {skill:762} de oficial (nivel 60). Polestar no puede leer tu rango, así que este paso espera al nivel 60 y a {skill:762} de oficial.",
		["{spell:22723}, {spell:828}, 100g"] = "{spell:22723}, {spell:828}, 100 de oro",
} end)()
t.guides["forever/collectibles/mounts/alliance/horse"] = (function() return {
		["Any Alliance race can buy these horses, but riding one also takes {spell:824}, which only Humans get with {skill:762}. {npc:4732} teaches it to other races once they are Exalted with {faction:72} (the Stormwind Reputation guide shows the way). Until then, don't buy a horse for this character."] = "Cualquier raza de la Alianza puede comprar estos caballos, pero para montar uno también hace falta {spell:824}, que solo los humanos reciben con {skill:762}. {npc:4732} se la enseña a las demás razas una vez que están en Exaltado con {faction:72} (la guía de reputación de Ventormenta muestra el camino). Hasta entonces, no le compres un caballo a este personaje.",
		["Horse"] = "Caballo",
		["Learn to ride"] = "Aprende a montar",
		["Pick a colour"] = "Elige un color",
		["The {npc:5404} is not at {npc:384}: {npc:1460} sells it, at the stables of {area:150} in the {zone:1437} (20g in the Forever client). Skip this unless you want that colour."] = "El {npc:5404} no lo tiene {npc:384}: lo vende {npc:1460}, en los establos de {area:150} en {zone:1437} (20 de oro en el cliente de Forever). Sáltate esto salvo que quieras ese color.",
		["{item:2411}, 20g, {npc:1460}"] = "{item:2411}, 20 de oro, {npc:1460}",
		["{item:2414}, 20g"] = "{item:2414}, 20 o",
		["{item:5655}, 20g"] = "{item:5655}, 20 o",
		["{item:5656}, 20g"] = "{item:5656}, 20 o",
		["{npc:384} sells the other colours (20g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:384} vende los otros colores (20 o cada uno en el cliente de Forever). Compra los que quieras, o ninguno si te gusta la montura que te dieron.",
		["{npc:4732} and {npc:384}'s horse pen are at {area:88} in eastern {zone:1429}. At 40 {npc:4732} teaches {skill:762} to Humans for 100g (10% less at Honored with {faction:72}), and it comes with a horse. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "El corral de caballos de {npc:4732} y {npc:384} está en {area:88}, en el este de {zone:1429}. A nivel 40 {npc:4732} enseña {skill:762} a los humanos por 100 de oro (10% menos en Honorable con {faction:72}), y viene con un caballo. Las demás razas aprenden {skill:762}, con su propia primera montura, con el instructor de equitación de su raza.",
		["{npc:4732}, riding trainer"] = "{npc:4732}, instructor de equitación",
		["{npc:5404} in {area:150}"] = "{npc:5404} en {area:150}",
		["{spell:824} for other races"] = "{spell:824} para otras razas",
} end)()
t.guides["forever/collectibles/mounts/alliance/mechanostrider"] = (function() return {
		["Any Alliance race can buy these mechanostriders, but riding one also takes {spell:10907}, which only Gnomes get with {skill:762}. {npc:7954} teaches it to other races once they are Exalted with {faction:54} (the Gnomeregan Exiles Reputation guide shows the way). Until then, don't buy a mechanostrider for this character."] = "Cualquier raza de la Alianza puede comprar estos mecazancudos, pero para montar uno también hace falta {spell:10907}, que solo los gnomos reciben con {skill:762}. {npc:7954} se la enseña a las demás razas una vez que están en Exaltado con {faction:54} (la guía de reputación de los Exiliados de Gnomeregan muestra el camino). Hasta entonces, no le compres un mecazancudo a este personaje.",
		["In Classic only Dwarves and Gnomes could ride mechanostriders; in Forever every Alliance race can learn {spell:10907}."] = "En Classic solo los enanos y los gnomos podían montar mecazancudos; en Forever todas las razas de la Alianza pueden aprender {spell:10907}.",
		["Learn to ride"] = "Aprende a montar",
		["Mechanostrider"] = "Mecazancudo",
		["Pick a colour"] = "Elige un color",
		["{area:189} is just east of {area:131}; {npc:7954} stands beside {npc:7955}'s mechanostriders. At 40 {npc:7954} teaches {skill:762} to Gnomes for 100g (10% less at Honored with {faction:54}), and it comes with a mechanostrider. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{area:189} está justo al este de {area:131}; {npc:7954} está junto a los mecazancudos de {npc:7955}. A nivel 40 {npc:7954} enseña {skill:762} a los gnomos por 100 de oro (10% menos en Honorable con {faction:54}), y viene con un mecazancudo. Las demás razas aprenden {skill:762}, con su propia primera montura, con el instructor de equitación de su raza.",
		["{item:13321}, 20g"] = "{item:13321}, 20 o",
		["{item:13322}, 20g"] = "{item:13322}, 20 o",
		["{item:8563}, 20g"] = "{item:8563}, 20 o",
		["{item:8595}, 20g"] = "{item:8595}, 20 o",
		["{npc:7954}, riding trainer"] = "{npc:7954}, instructor de equitación",
		["{npc:7955} sells the other colours (20g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:7955} vende los otros colores (20 o cada uno en el cliente de Forever). Compra los que quieras, o ninguno si te gusta la montura que te dieron.",
		["{spell:10907} for other races"] = "{spell:10907} para otras razas",
} end)()
t.guides["forever/collectibles/mounts/alliance/pack-kodo"] = (function() return {
		["6,000 Merchant's Favor"] = "6,000 de Merchant's Favor",
		["The camp is at {area:1002} in western {zone:1433}, where the roads from {zone:1429}, {zone:1431} and {area:69} meet. {npc:256736} sells the {npc:10636} only once you are Exalted with the {faction:2586}, and it costs 6,000 Merchant's Favor. Crates pay only Favor (about 15 a crate return); the reputation comes from Craftsman's Writs and the one-time {item:280179}, so follow the Supply Factions Reputation guide and keep 6,000 Favor aside."] = "El campamento está en {area:1002}, en el oeste de {zone:1433}, donde se juntan los caminos de {zone:1429}, {zone:1431} y {area:69}. {npc:256736} vende el {npc:10636} solo cuando estás en Exaltado con {faction:2586}, y cuesta 6.000 de Favor del mercader. Los cajones pagan solo Favor (unos 15 por cajón entregado); la reputación sale de los encargos de Artesano y del {item:280179} único, así que sigue la guía de reputación de las facciones de suministros y guarda 6.000 de Favor.",
		["The reins need level 60 and Journeyman Riding to ride (Forever client); you can buy them earlier."] = "Las riendas requieren nivel 60 y Equitación de oficial para montar (cliente de Forever); puedes comprarlas antes.",
		["{faction:2586} camp"] = "Campamento de la {faction:2586}",
} end)()
t.guides["forever/collectibles/mounts/alliance/paladin-charger"] = (function() return {
		["An {item:12800} comes from Thorium veins and obsidian, about one vein in a hundred; a {item:18335} drops rarely from elites of level 59 and up (Revanchion and {npc:14695} about one kill in nine and one in a hundred). The Auction House is the usual source of both."] = "Un {item:12800} sale de vetas de torio y de obsidiana, más o menos una veta de cada cien; un {item:18335} lo sueltan muy de vez en cuando los élites de nivel 59 o más (Revanchion y {npc:14695}, más o menos una muerte de cada nueve y una de cada cien). La casa de subastas es la fuente habitual de ambos.",
		["Arcanite Bars x6: an alchemist, or the Trade District Auction House"] = "Barras de arcanita x6: un alquimista, o la casa de subastas del Distrito de Mercaderes",
		["At 60 {npc:5149} in the {object:32362} sends you to {quest:7670} in {zone:1453}'s Cathedral of Light."] = "A nivel 60, {npc:5149} en {object:32362} te manda con {quest:7670} en la Catedral de la Luz de {zone:1453}.",
		["Back to Lord Grayson"] = "Vuelve con Lord Grisillo",
		["Bring the materials and 150 gold, taken at the hand-in. {npc:1416} walks to his forge and hands you the {item:18753}."] = "Lleva los materiales y 150 de oro, que se cobran al entregar. {npc:1416} camina a su forja y te da la {item:18753}.",
		["Dire Maul West's door"] = "La puerta de La Masacre Oeste",
		["Enriched Manna Biscuits"] = "Galletas enriquecidas con maná",
		["Enriched Manna Biscuits: {npc:10857}, {area:3197}"] = "Galletas enriquecidas con maná: {npc:10857}, {area:3197}",
		["Lord Grayson blesses the censer into the {item:18752} for {area:2627}."] = "Lord Grayson bendice el incensario y lo convierte en el {item:18752} para {area:2627}.",
		["Lord Grayson hands you {item:18804}: open it for the {item:18746} and the {item:18792}. Keep both."] = "Lord Grayson te da la {item:18804}: ábrela para sacar el {item:18746} y la {item:18792}. Guarda los dos.",
		["Lord Grayson keeps the barding for now: you get it back with the next quest."] = "Lord Grayson se queda con la barda por ahora: la recuperas con la siguiente misión.",
		["Lord Grayson takes the censer back."] = "Lord Grayson recupera el incensario.",
		["Paladin Charger"] = "Destrero de paladín",
		["Stratholme Supply Crates, inside"] = "Cajas de suministros de Stratholme, adentro",
		["Terrordale Spirits x25"] = "Espíritus de Valle del Terror x25",
		["The {spell:23214} chain is long: {area:2279}, Dire Maul West and {area:2057} with a group, 350 gold in donations, and materials worth several hundred more (6 Arcanite Bars, 40 {item:14047}, 10 {item:8836}, two diamonds). Start saving early. Lord Grayson stands in the Cathedral of Light, {npc:6171} nearby."] = "La cadena de {spell:23214} es larga: {area:2279}, La Masacre Oeste y {area:2057} en grupo, 350 de oro en donaciones y materiales por varios cientos más (6 barras de arcanita, 40 {item:14047}, 10 {item:8836}, dos diamantes). Empieza a ahorrar temprano. Lord Grayson está en la Catedral de la Luz, y {npc:6171} cerca.",
		["Two diamonds"] = "Dos diamantes",
		["Your epic mount at 60, summoned at will: the faster step up from the Warhorse."] = "Tu montura épica a nivel 60, invocada a voluntad: el paso más rápido tras el caballo de guerra.",
		["{area:2057} lies under {area:2298}, the island town in the south-east of the {zone:1422}; the door needs the {item:13704} (The Key to {area:2057}). Clear the {object:179746}, Rattlegore's room in the basement, then use the {item:18746} at its centre. Four waves of spirits come, each ending with an Aspect: players judge them with {spell:1105}, Justice, Righteousness and then Light, which stuns them. {npc:14516} (level 62 elite) comes after the last; he mind-controls players. Loot the {item:18749}, use it inside the Ossuary to redeem it, and give it and the {item:18792} to {npc:14568}. If the group wipes, the gates lock and the scryer is gone: abandon the quest and take it again from Lord Grayson for a new satchel. A group of five at 60. Again Into the {object:179746}, after the mount, lets you fight him again."] = "{area:2057} está debajo de {area:2298}, el pueblo isleño del sureste de {zone:1422}; la puerta necesita la {item:13704} (La llave de {area:2057}). Despeja {object:179746}, la sala de Traquesangre en el sótano, y usa el {item:18746} en su centro. Llegan cuatro oleadas de espíritus, cada una terminada por un Aspecto: los jugadores los juzgan con {spell:1105}, Justicia, Rectitud y luego Luz, que los aturde. {npc:14516} (élite de nivel 62) llega después del último; controla mentalmente a los jugadores. Saquea el {item:18749}, úsala dentro del Osario para redimirla, y dásela con la {item:18792} a {npc:14568}. Si el grupo muere entero, las puertas se cierran y el visor desaparece: abandona la misión y tómala otra vez con Lord Grayson para recibir otra cartera. Un grupo de cinco a nivel 60. Otra vez a {object:179746}, después de la montura, te deja pelear contra él otra vez.",
		["{area:2279} is a dungeon for a group of five at 58-60, at the north end of the {zone:1423}. Stratholme Supply Crates along the streets of both halves hold the Holy Water, one to three each; they come back after three minutes. Some crates let out a swarm of plagued rats or maggots: be ready. The main gate (the Scarlet half) needs no key."] = "{area:2279} es una mazmorra para un grupo de cinco de nivel 58-60, en el extremo norte de {zone:1423}. Las cajas de suministros de Stratholme a lo largo de las calles de las dos mitades tienen el agua bendita, de una a tres cada una; vuelven a los tres minutos. Algunas cajas sueltan un enjambre de ratas o larvas apestadas: prepárate. La puerta principal (la mitad Escarlata) no necesita llave.",
		["{area:2577} lies in central {zone:1444}. From the gate at the foot of the ruins, walk up through the outer courtyards to the West wing's door at their north end; it needs a {item:18249} (from Pusillin in Dire Maul East) or a rogue's lockpicking. {npc:11489} (level 60 elite) stands at the far end of the West wing's first courtyard. Once attacked he calls every {npc:11459} still alive in the courtyard: kill them first. His death frees the {quest:7643}: talk to it to give it the horse feed and the {item:18753}, and it blesses the barding. A group of five at 60."] = "{area:2577} está en el centro de {zone:1444}. Desde la puerta al pie de las ruinas, sube por los patios exteriores hasta la puerta del ala Oeste, en su extremo norte; necesita una {item:18249} (de Pusillin, en La Masacre Este) o la ganzúa de un pícaro. {npc:11489} (élite de nivel 60) está al fondo del primer patio del ala Oeste. Cuando lo atacas llama a todos los {npc:11459} que sigan vivos en el patio: mátalos primero. Su muerte libera al {quest:7643}: háblale para darle el forraje y la {item:18753}, y bendice la barda. Un grupo de cinco a nivel 60.",
		["{area:2627} lies in the far north-west of the {zone:1423}, west of the {area:2279} gates. Stand inside a green glowing patch on the ground (a {object:179747}; some are inside the ruined houses) and use the {item:18752}: up to three Terrordale Spirits (level 59-60) rise and attack. Their {spell:7713} lowers all your stats by 30%: fight them one at a time and use {spell:2878}. The patches come back quickly; several paladins can work side by side."] = "{area:2627} está en el extremo noroeste de {zone:1423}, al oeste de las puertas de {area:2279}. Párate dentro de una mancha verde brillante en el suelo (un {object:179747}; algunas están dentro de las casas en ruinas) y usa el {item:18752}: se levantan hasta tres espíritus de Valle del Terror (nivel 59-60) y atacan. Su {spell:7713} baja todas tus estadísticas un 30%: pelea contra ellos de uno en uno y usa {spell:2878}. Las manchas vuelven rápido; varios paladines pueden trabajar uno al lado del otro.",
		["{item:14047} drops from humanoids of level 50 and up ({area:2255}'s Bruisers, the Scarlet Crusade in the Plaguelands, the {area:2577} ogres). {item:8836} is a Plaguelands herb ({skill:182} 220), common around {area:3197}. An {item:12360} is an alchemist's transmute from a {item:12359} and an {item:12363}, once every two days per alchemist: ask a guild alchemist early, or buy the bars. The Auction House sells all three."] = "El {item:14047} lo sueltan los humanoides de nivel 50 o más (los matones de {area:2255}, la Cruzada Escarlata de las Tierras de la Peste, los ogros de {area:2577}). Las {item:8836} son una hierba de las Tierras de la Peste ({skill:182} 220), común alrededor de {area:3197}. Una {item:12360} es una transmutación de alquimista a partir de una {item:12359} y un {item:12363}, una vez cada dos días por alquimista: pídeselo temprano a un alquimista de la hermandad, o compra las barras. La casa de subastas vende los tres.",
		["{item:14047} x40"] = "{item:14047} x40",
		["{item:18749}, inside the {object:179746}"] = "{item:18749}, dentro de {object:179746}",
		["{item:18752}, inside a green patch"] = "{item:18752}, dentro de una mancha verde",
		["{item:18792}, from the satchel"] = "{item:18792}, de la cartera",
		["{item:8836} x10"] = "{item:8836} x10",
		["{npc:11406}, the priest trainer, walks about the {object:32386} in {zone:1455}'s {object:32362}. He gives you his censer for a donation of 150 gold, taken at the hand-in. Keep the censer."] = "{npc:11406}, el instructor de sacerdotes, camina por {object:32386} en {object:32362} de {zone:1455}. Te da su incensario por una donación de 150 de oro, que se cobra al entregar. Guarda el incensario.",
		["{npc:11406}: 150 gold"] = "{npc:11406}: 150 de oro",
		["{npc:11489}, inside the West wing"] = "{npc:11489}, dentro del ala oeste",
		["{npc:1416} works in {zone:1453}'s {object:28027}. He forges the {item:18753} from your materials and 150 gold."] = "{npc:1416} trabaja en {object:28027} de {zone:1453}. Forja la {item:18753} con tus materiales y 150 de oro.",
		["{npc:1416}'s materials"] = "Materiales de {npc:1416}",
		["{npc:1416}: 150 gold"] = "{npc:1416}: 150 de oro",
		["{npc:2357} breeds horses in {area:271}'s stable. She makes the {quest:7645} from the 20 biscuits and 50 gold, taken at the hand-in."] = "{npc:2357} cría caballos en el establo de {area:271}. Prepara el {quest:7645} con las 20 galletas y 50 de oro, que se cobran al entregar.",
		["{npc:6171}, Cathedral of Light"] = "{npc:6171}, Catedral de la Luz",
		["{npc:928}: the {item:18753}"] = "{npc:928}: la {item:18753}",
		["{object:2160} quartermasters sell Enriched Manna Biscuits, five for 60 silver, once the {object:92525} is Friendly with you: {npc:10857} at {area:3197} or {npc:11536} at {area:2268}. Scourgestones and the Plaguelands quests raise the standing."] = "Los intendentes de {object:2160} venden galletas de maná enriquecidas, cinco por 60 de plata, una vez que estás en Amistoso con {object:92525}: {npc:10857} en {area:3197} o {npc:11536} en {area:2268}. Las piedras de la Plaga y las misiones de las Tierras de la Peste suben la reputación.",
} end)()
t.guides["forever/collectibles/mounts/alliance/paladin-warhorse"] = (function() return {
		["At 40 {npc:6179}, upstairs in the {object:32386}, sends you to {npc:6171} in {zone:1453} ({npc:5149} downstairs gives the same errand; take one). Take the {area:2257} to {zone:1453}."] = "A nivel 40 {npc:6179}, arriba en {object:32386}, te manda con {npc:6171} en {zone:1453} ({npc:5149}, abajo, da el mismo encargo; toma uno). Toma {area:2257} hasta {zone:1453}.",
		["Paladin Warhorse"] = "Caballo de guerra de paladín",
		["Your first mount at 40, summoned at will: a paladin buys no horse."] = "Tu primera montura a nivel 40, invocada a voluntad: un paladín no compra caballo.",
		["{npc:6171} stands in the Cathedral of Light. At 40 he offers {quest:1661}: accept it and hand it straight back to learn {spell:13819}. Paladins do not buy a horse."] = "{npc:6171} está en la Catedral de la Luz. A nivel 40 ofrece {quest:1661}: acéptala y entrégala enseguida para aprender {spell:13819}. Los paladines no compran caballo.",
} end)()
t.guides["forever/collectibles/mounts/alliance/ram"] = (function() return {
		["Any Alliance race can buy these rams, but riding one also takes {spell:826}, which only Dwarves get with {skill:762}. {npc:4772} teaches it to other races once they are Exalted with {faction:47} (the Ironforge Reputation guide shows the way). Until then, don't buy a ram for this character."] = "Cualquier raza de la Alianza puede comprar estos carneros, pero para montar uno también hace falta {spell:826}, que solo los enanos reciben con {skill:762}. {npc:4772} se la enseña a las demás razas una vez que están en Exaltado con {faction:47} (la guía de reputación de Forjaz muestra el camino). Hasta entonces, no le compres un carnero a este personaje.",
		["Learn to ride"] = "Aprende a montar",
		["Pick a colour"] = "Elige un color",
		["Ram"] = "Carnero",
		["{area:803} is east of {area:131} on the road to {zone:1432}; {npc:4772} stands beside {npc:1261}'s rams. At 40 {npc:4772} teaches {skill:762} to Dwarves for 100g (10% less at Honored with {faction:47}), and it comes with a ram. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{area:803} está al este de {area:131}, en el camino a {zone:1432}; {npc:4772} está junto a los carneros de {npc:1261}. A nivel 40 {npc:4772} enseña {skill:762} a los enanos por 100 de oro (10% menos en Honorable con {faction:47}), y viene con un carnero. Las demás razas aprenden {skill:762}, con su propia primera montura, con el instructor de equitación de su raza.",
		["{item:5864}, 20g"] = "{item:5864}, 20 o",
		["{item:5872}, 20g"] = "{item:5872}, 20 o",
		["{item:5873}, 20g"] = "{item:5873}, 20 o",
		["{npc:1261} sells the other colours (20g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:1261} vende los otros colores (20 o cada uno en el cliente de Forever). Compra los que quieras, o ninguno si te gusta la montura que te dieron.",
		["{npc:4772}, riding trainer"] = "{npc:4772}, instructor de equitación",
		["{spell:826} for other races"] = "{spell:826} para otras razas",
} end)()
t.guides["forever/collectibles/mounts/alliance/saber"] = (function() return {
		["Any Alliance race can buy these sabers, but riding one also takes {spell:828}, which only Night Elves get with {skill:762}. {npc:4753} teaches it to other races once they are Exalted with {faction:69} (the Darnassus Reputation guide shows the way). Until then, don't buy a saber for this character."] = "Cualquier raza de la Alianza puede comprar estos sables, pero para montar uno también hace falta {spell:828}, que solo los elfos de la noche reciben con {skill:762}. {npc:4753} se la enseña a las demás razas una vez que están en Exaltado con {faction:69} (la guía de reputación de Darnassus muestra el camino). Hasta entonces, no le compres un sable a este personaje.",
		["Learn to ride"] = "Aprende a montar",
		["Pick a colour"] = "Elige un color",
		["Saber"] = "Sable",
		["new in Forever, 20g; beta players found it here"] = "nuevo en Forever, 20 de oro; los jugadores de la beta lo encontraron aquí",
		["{item:8629}, 20g"] = "{item:8629}, 20g",
		["{item:8631}, 20g"] = "{item:8631}, 20g",
		["{item:8632}, 20g"] = "{item:8632}, 20g",
		["{npc:4730} sells the other colours (20g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:4730} vende los demás colores (20g cada uno en el cliente de Forever). Compra los que quieras, o ninguno si te gusta la montura que te dieron.",
		["{npc:4753} and {npc:4730}'s sabers are in the {area:1658}'s riding grounds in {faction:69}. At 40 {npc:4753} teaches {skill:762} to Night Elves for 100g (10% less at Honored with {faction:69}), and it comes with a saber. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "Los sables de {npc:4753} y {npc:4730} están en el campo de equitación de {area:1658}, en {faction:69}. A nivel 40 {npc:4753} enseña {skill:762} a los elfos de la noche por 100 de oro (10% menos en Honorable con {faction:69}), y viene con un sable. Las demás razas aprenden {skill:762}, con su propia primera montura, con el instructor de equitación de su raza.",
		["{npc:4753}, riding trainer"] = "{npc:4753}, instructor de equitación",
		["{spell:828} for other races"] = "{spell:828} para otras razas",
} end)()
t.guides["forever/collectibles/mounts/alliance/stormpike-battle-charger"] = (function() return {
		["The Forever client lists it at 200g and level 60. It runs at full speed, so riding it needs Journeyman {skill:762}; any Alliance race can ride it."] = "El cliente de Forever la lista a 200 de oro y nivel 60. Corre a toda velocidad, así que para montarla necesitas {skill:762} de oficial; cualquier raza de la Alianza puede montarla.",
		["{area:2839} (level 51+) raises {faction:730}: win, capture towers and graveyards, and hand in the battleground's turn-ins; the Alterac Valley Reputation guide shows the fastest way. {npc:13217} waits outside the battleground on the {zone:1416} border above {area:287}; {npc:13216} inside {area:2839} sells the same mount."] = "{area:2839} (nivel 51+) sube {faction:730}: gana, captura torres y cementerios, y entrega las misiones del campo de batalla; la guía de reputación del Valle de Alterac muestra el camino más rápido. {npc:13217} espera afuera del campo de batalla, en el borde de {zone:1416} arriba de {area:287}; {npc:13216}, dentro de {area:2839}, vende la misma montura.",
		["{npc:13217}, 200g"] = "{npc:13217}, 200 o",
} end)()
t.guides["forever/collectibles/mounts/alliance/swift-horse"] = (function() return {
		["Any Alliance race can buy these horses, but riding one also takes {spell:824}, which only Humans get with {skill:762}. {npc:4732} teaches it to other races once they are Exalted with {faction:72} (the Stormwind Reputation guide shows the way). Until then, don't buy a horse for this character."] = "Cualquier raza de la Alianza puede comprar estos caballos, pero para montar uno también hace falta {spell:824}, que solo los humanos reciben con {skill:762}. {npc:4732} se la enseña a las demás razas una vez que están en Exaltado con {faction:72} (la guía de reputación de Ventormenta muestra el camino). Hasta entonces, no le compres un caballo a este personaje.",
		["Journeyman {skill:762}"] = "{skill:762} de oficial",
		["Pick a colour"] = "Elige un color",
		["Swift Horse"] = "Caballo presto",
		["{item:18776}, 200g"] = "{item:18776}, 200g",
		["{item:18777}, 200g"] = "{item:18777}, 200g",
		["{item:18778}, 200g"] = "{item:18778}, 200g",
		["{npc:384} sells the other colours (200g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:384} vende los demás colores (200g cada uno en el cliente de Forever). Compra los que quieras, o ninguno si te gusta la montura que te dieron.",
