		["{npc:15350}: {quest:98887} again, 100 for 3 marks"] = "{npc:15350}: {quest:98887} otra vez, 100 por 3 marcas",
		["{npc:15351}: 100 for 3 marks"] = "{npc:15351}: 100 por 3 marcas",
		["{npc:15351}: {quest:98895} again, 100 for 3 marks"] = "{npc:15351}: {quest:98895} otra vez, 100 por 3 marcas",
